#[tauri::command]
async fn get_cached_steam_artwork(
    app: AppHandle,
    steam_app_id: String,
    variant: String,
) -> Result<Option<String>, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let root = store_root(&app)?;
        cached_steam_artwork_data_url(&root, &steam_app_id, &variant)
    })
    .await
    .map_err(error_to_string)?
}

fn cached_steam_artwork_data_url(
    store_root: &Path,
    steam_app_id: &str,
    variant: &str,
) -> Result<Option<String>, String> {
    let steam_app_id = steam_app_id.trim();
    if steam_app_id.is_empty()
        || !steam_app_id
            .chars()
            .all(|character| character.is_ascii_digit())
    {
        return Ok(None);
    }
    if !matches!(variant, "hero" | "poster") {
        return Err("Unsupported Steam artwork variant.".to_string());
    }

    let cache_path = steam_artwork_cache_path(store_root, steam_app_id, variant);
    if let Some(data_url) = read_cached_steam_artwork(&cache_path)? {
        return Ok(Some(data_url));
    }

    let client = Client::builder()
        .user_agent(format!("Mod Garrison/{}", env!("CARGO_PKG_VERSION")))
        .connect_timeout(Duration::from_secs(3))
        .timeout(Duration::from_secs(8))
        .build()
        .map_err(error_to_string)?;

    for source_url in steam_artwork_source_urls(steam_app_id, variant) {
        let Ok(mut response) = client.get(&source_url).send() else {
            continue;
        };
        if !response.status().is_success()
            || response
                .content_length()
                .is_some_and(|size| size == 0 || size > MAX_STEAM_ARTWORK_BYTES)
        {
            continue;
        }

        let mut bytes = Vec::new();
        if copy_with_limit(&mut response, &mut bytes, MAX_STEAM_ARTWORK_BYTES).is_err() {
            continue;
        }
        let Some(mime_type) = steam_artwork_mime_type(&bytes) else {
            continue;
        };

        atomic_write(&cache_path, &bytes).map_err(error_to_string)?;
        return Ok(Some(steam_artwork_data_url(mime_type, &bytes)));
    }

    Ok(None)
}

fn steam_artwork_cache_path(store_root: &Path, steam_app_id: &str, variant: &str) -> PathBuf {
    store_root
        .join("cache")
        .join("steam-artwork")
        .join(steam_app_id)
        .join(format!("{variant}.image"))
}

fn read_cached_steam_artwork(path: &Path) -> Result<Option<String>, String> {
    if !path.is_file() {
        return Ok(None);
    }

    let bytes = fs::read(path).map_err(error_to_string)?;
    if bytes.is_empty() || bytes.len() as u64 > MAX_STEAM_ARTWORK_BYTES {
        let _ = fs::remove_file(path);
        return Ok(None);
    }
    let Some(mime_type) = steam_artwork_mime_type(&bytes) else {
        let _ = fs::remove_file(path);
        return Ok(None);
    };

    Ok(Some(steam_artwork_data_url(mime_type, &bytes)))
}

fn steam_artwork_mime_type(bytes: &[u8]) -> Option<&'static str> {
    if bytes.starts_with(&[0xff, 0xd8, 0xff]) {
        Some("image/jpeg")
    } else if bytes.starts_with(b"\x89PNG\r\n\x1a\n") {
        Some("image/png")
    } else if bytes.len() >= 12 && bytes.starts_with(b"RIFF") && &bytes[8..12] == b"WEBP" {
        Some("image/webp")
    } else {
        None
    }
}

fn steam_artwork_data_url(mime_type: &str, bytes: &[u8]) -> String {
    format!("data:{mime_type};base64,{}", BASE64_STANDARD.encode(bytes))
}

fn steam_artwork_source_urls(steam_app_id: &str, variant: &str) -> Vec<String> {
    let wide = [
        format!("https://shared.cloudflare.steamstatic.com/store_item_assets/steam/apps/{steam_app_id}/library_hero.jpg"),
        format!("https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/{steam_app_id}/library_hero.jpg"),
        format!("https://shared.cloudflare.steamstatic.com/store_item_assets/steam/apps/{steam_app_id}/header.jpg"),
        format!("https://cdn.cloudflare.steamstatic.com/steam/apps/{steam_app_id}/header.jpg"),
    ];
    if variant == "hero" {
        return wide.into_iter().collect();
    }

    [
        format!("https://shared.cloudflare.steamstatic.com/store_item_assets/steam/apps/{steam_app_id}/library_600x900.jpg"),
        format!("https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/{steam_app_id}/library_600x900.jpg"),
        format!("https://shared.cloudflare.steamstatic.com/store_item_assets/steam/apps/{steam_app_id}/library_600x900_2x.jpg"),
        format!("https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/{steam_app_id}/library_600x900_2x.jpg"),
        format!("https://cdn.cloudflare.steamstatic.com/steam/apps/{steam_app_id}/capsule_231x87.jpg"),
    ]
    .into_iter()
    .chain(wide)
    .collect()
}

#[tauri::command]
async fn create_steam_profile(
    app: AppHandle,
    game: SteamGameRecord,
) -> Result<GameProfile, String> {
    tauri::async_runtime::spawn_blocking(move || create_steam_profile_sync(app, game))
        .await
        .map_err(error_to_string)?
}

fn create_steam_profile_sync(app: AppHandle, game: SteamGameRecord) -> Result<GameProfile, String> {
    let root = store_root(&app)?;
    let game = verify_installed_steam_game(&game)?;
    let detection =
        detect_game_setup_with_steam_app_id(Path::new(&game.install_dir), Some(&game.app_id))?;
    let mut profile = {
        let _commit = lock_mutations()?;
        let existing_profiles =
            read_store::<GameProfile>(&profiles_path(&root)).map_err(error_to_string)?;
        if existing_profiles.items.iter().any(|profile| {
            profile.steam_app_id.as_deref() == Some(game.app_id.as_str())
                || normalize_filesystem_identity(&profile.game_path)
                    == normalize_filesystem_identity(&game.install_dir)
        }) {
            return Err(format!("{} already has a Mod Garrison profile.", game.name));
        }
        create_profile_in_store(
            &root,
            CreateProfileInput {
                name: game.name,
                game_path: game.install_dir,
                game_id: detection.game_id,
                steam_app_id: Some(game.app_id),
                engine: detection.engine,
                loader: detection.loader,
            },
        )?
    };
    let profile_operation = operation::profile_lock(&profile.id)?;
    let _profile_operation = operation::lock_profile(&profile_operation)?;
    let mut setup_warnings = match game_process_running(Path::new(&profile.game_path)) {
        Ok(false) => {
            let runtime_inference =
                enrich_profile_with_provider_runtime(&root, &mut profile, true);
            if runtime_inference.inference.is_some() {
                persist_profile(&root, &profile)?;
            }
            let mut warnings = runtime_inference.warnings;
            warnings.extend(install_profile_bootstrap_dependencies(&root, &profile));
            warnings
        }
        Ok(true) => vec![format!(
            "Automatic runtime detection and setup needs {} to be closed. Close the game and refresh this profile to finish setup; no runtime files were changed.",
            profile_game_label(&profile)
        )],
        Err(error) => vec![format!(
            "Automatic runtime detection and setup could not verify whether {} is running, so it was postponed and no runtime files were changed: {error}",
            profile_game_label(&profile)
        )],
    };
    let route_outcome = ensure_profile_route_knowledge(&root, &profile, true);
    setup_warnings.extend(route_outcome.warnings);
    apply_profile_setup_outcome(&mut profile, setup_warnings);
    persist_profile(&root, &profile)?;
    let discovered_config_files = discover_profile_config_files(&profile);
    let mut installed_store =
        read_store::<InstalledModRecord>(&installed_mods_path(&root)).map_err(error_to_string)?;
    adopt_existing_profile_mods(&root, &profile, &mut installed_store)?;
    ensure_visible_runtime_records(&root, &profile, &mut installed_store)?;
    for record in installed_store
        .items
        .iter_mut()
        .filter(|record| record.profile_id == profile.id)
    {
        record.display_name = record
            .display_name
            .as_deref()
            .map(humanize_mod_display_name);
    }
    let config_records = installed_store
        .items
        .iter()
        .filter(|record| record.profile_id == profile.id)
        .cloned()
        .collect::<Vec<_>>();
    let mut config_files_by_record =
        resolved_profile_config_files(&profile, &config_records, &discovered_config_files);
    for record in installed_store
        .items
        .iter_mut()
        .filter(|record| record.profile_id == profile.id)
    {
        record.config_files = config_files_by_record
            .remove(&record.id)
            .unwrap_or_default();
    }
    let profile_records = installed_store
        .items
        .iter()
        .filter(|record| record.profile_id == profile.id)
        .cloned()
        .collect::<Vec<_>>();
    commit_installed_mod_records(&root, &profile, &profile_records, &[])?;
    Ok(profile)
}

fn verify_installed_steam_game(requested: &SteamGameRecord) -> Result<SteamGameRecord, String> {
    let requested_path = normalize_filesystem_identity(
        normalize_profile_game_path(&requested.install_dir).trim_end_matches(['/', '\\']),
    );

    scan_steam_games_cached()
        .into_iter()
        .find(|installed| {
            installed.app_id == requested.app_id
                && normalize_filesystem_identity(
                    normalize_profile_game_path(&installed.install_dir)
                        .trim_end_matches(['/', '\\']),
                ) == requested_path
        })
        .ok_or_else(|| {
            "Steam could not verify this installed game. Rescan your Steam library and select it again."
                .to_string()
        })
}

fn ensure_verified_steam_profile(profile: &GameProfile) -> Result<(), String> {
    verified_steam_game_for_profile(profile).map(|_| ())
}

fn verified_steam_game_for_profile(profile: &GameProfile) -> Result<SteamGameRecord, String> {
    let app_id = profile
        .steam_app_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "Only verified Steam profiles can install mods.".to_string())?;

    verify_installed_steam_game(&SteamGameRecord {
        app_id: app_id.to_string(),
        name: profile.name.clone(),
        install_dir: profile.game_path.clone(),
        library_path: String::new(),
    })
}

#[tauri::command]
async fn launch_profile_game(
    app: AppHandle,
    profile_id: String,
    mods_enabled: bool,
) -> Result<(), String> {
    let operation_profile_id = profile_id.clone();
    let task_app = app.clone();
    operation::run_blocking(
        app,
        "launch_profile_game",
        Some(operation_profile_id),
        move || {
            let profile_operation = operation::profile_lock(&profile_id)?;
            let _profile_operation = operation::lock_profile(&profile_operation)?;
            let root = store_root(&task_app)?;
            let profile = get_profile(&root, &profile_id)?;
            let steam_app_id = profile
                .steam_app_id
                .as_deref()
                .map(str::trim)
                .filter(|app_id| !app_id.is_empty())
                .ok_or_else(|| {
                    "This profile does not have a Steam App ID yet. Add it through Steam scan to launch it from Mod Garrison.".to_string()
                })?;

            prepare_profile_mod_launch(&root, &profile, mods_enabled)?;
            persist_profile_launch_mode(&root, &profile_id, mods_enabled)?;
            open_url_in_shell(&format!("steam://run/{steam_app_id}"))
        },
    )
    .await
}

#[tauri::command]
async fn set_profile_mod_launch_mode(
    app: AppHandle,
    profile_id: String,
    mods_enabled: bool,
) -> Result<ProfileLaunchModeResult, String> {
    let operation_profile_id = profile_id.clone();
    let task_app = app.clone();
    operation::run_blocking(
        app,
        "set_profile_mod_launch_mode",
        Some(operation_profile_id),
        move || {
            let profile_operation = operation::profile_lock(&profile_id)?;
            let _profile_operation = operation::lock_profile(&profile_operation)?;
            let root = store_root(&task_app)?;
            let profile = get_profile(&root, &profile_id)?;
            ensure_game_files_mutable(&profile, "change the clean-launch mod state")?;
            let changed_components = prepare_profile_mod_launch(&root, &profile, mods_enabled)?;
            persist_profile_launch_mode(&root, &profile_id, mods_enabled)?;
            Ok(ProfileLaunchModeResult {
                profile_id,
                mods_enabled,
                changed_components,
            })
        },
    )
    .await
}

#[tauri::command]
async fn profile_game_running(app: AppHandle, profile_id: String) -> Result<bool, String> {
    let operation_profile_id = profile_id.clone();
    let task_app = app.clone();
    operation::run_blocking(
        app,
        "profile_game_running",
        Some(operation_profile_id),
        move || {
            let root = store_root(&task_app)?;
            let profile = get_profile(&root, &profile_id)?;
            if profile
                .steam_app_id
                .as_deref()
                .map(str::trim)
                .is_none_or(str::is_empty)
            {
                return Ok(false);
            }

            game_process_running(Path::new(&profile.game_path))
        },
    )
    .await
}

#[cfg(target_os = "windows")]
fn game_process_running(game_path: &Path) -> Result<bool, String> {
    use windows_sys::Win32::Foundation::{CloseHandle, INVALID_HANDLE_VALUE};
    use windows_sys::Win32::System::Diagnostics::ToolHelp::{
        CreateToolhelp32Snapshot, Process32FirstW, Process32NextW, PROCESSENTRY32W,
        TH32CS_SNAPPROCESS,
    };

    let game_root = fs::canonicalize(game_path).unwrap_or_else(|_| game_path.to_path_buf());
    if !game_root.is_dir() {
        return Ok(false);
    }

    // SAFETY: Toolhelp returns an owned snapshot handle that is closed before this function exits.
    let snapshot = unsafe { CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0) };
    if snapshot == INVALID_HANDLE_VALUE {
        return Err(format!(
            "Could not inspect running games: {}",
            io::Error::last_os_error()
        ));
    }

    let mut process = PROCESSENTRY32W {
        dwSize: std::mem::size_of::<PROCESSENTRY32W>() as u32,
        ..Default::default()
    };
    // SAFETY: `process` is correctly sized and remains valid throughout enumeration.
    let mut has_process = unsafe { Process32FirstW(snapshot, &mut process) } != 0;
    let mut found = false;

    while has_process {
        if process.th32ProcessID != 0
            && process.th32ProcessID != std::process::id()
            && process_executable_path(process.th32ProcessID)
                .is_some_and(|executable| path_is_within_directory(&executable, &game_root))
        {
            found = true;
            break;
        }

        // SAFETY: `process` remains a valid, correctly sized output buffer for the snapshot.
        has_process = unsafe { Process32NextW(snapshot, &mut process) } != 0;
    }

    // SAFETY: `snapshot` is a valid owned Toolhelp handle and is closed exactly once.
    unsafe {
        CloseHandle(snapshot);
    }
    Ok(found)
}

#[cfg(target_os = "windows")]
fn process_executable_path(process_id: u32) -> Option<PathBuf> {
    use std::ffi::OsString;
    use std::os::windows::ffi::OsStringExt;
    use windows_sys::Win32::Foundation::CloseHandle;
    use windows_sys::Win32::System::Threading::{
        OpenProcess, QueryFullProcessImageNameW, PROCESS_QUERY_LIMITED_INFORMATION,
    };

    // SAFETY: OpenProcess is called with query-only access for the supplied process ID.
    let handle = unsafe { OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, 0, process_id) };
    if handle.is_null() {
        return None;
    }

    let mut buffer = vec![0u16; 32_768];
    let mut length = buffer.len() as u32;
    // SAFETY: `buffer` is writable for `length` UTF-16 units and the handle is valid.
    let queried =
        unsafe { QueryFullProcessImageNameW(handle, 0, buffer.as_mut_ptr(), &mut length) } != 0;
    // SAFETY: `handle` was returned by OpenProcess and is closed exactly once.
    unsafe {
        CloseHandle(handle);
    }

    queried.then(|| PathBuf::from(OsString::from_wide(&buffer[..length as usize])))
}

#[cfg(not(target_os = "windows"))]
fn game_process_running(_game_path: &Path) -> Result<bool, String> {
    Ok(false)
}

fn ensure_game_files_mutable(profile: &GameProfile, action: &str) -> Result<(), String> {
    ensure_game_path_files_mutable(
        Path::new(&profile.game_path),
        &profile_game_label(profile),
        action,
    )
}

fn ensure_game_path_files_mutable(
    game_path: &Path,
    game_label: &str,
    action: &str,
) -> Result<(), String> {
    match game_process_running(game_path) {
        Ok(false) => Ok(()),
        Ok(true) => Err(format!(
            "Close {} before Mod Garrison can {}. No files were changed.",
            game_label, action
        )),
        Err(error) => Err(format!(
            "Mod Garrison could not verify whether {} is running, so it refused to {}: {error}",
            game_label, action
        )),
    }
}

fn path_is_within_directory(path: &Path, directory: &Path) -> bool {
    let normalized_path = normalize_process_path(path);
    let normalized_directory = normalize_process_path(directory);
    let directory_prefix = format!("{}/", normalized_directory.trim_end_matches('/'));
    normalized_path.starts_with(&directory_prefix)
}

fn normalize_process_path(path: &Path) -> String {
    let normalized = normalize_filesystem_identity(path.to_string_lossy().as_ref());
    normalized
        .strip_prefix("//?/")
        .unwrap_or(&normalized)
        .to_string()
}

fn scan_steam_games_impl() -> Vec<SteamGameRecord> {
    let mut games = Vec::new();
    let mut seen_app_ids = HashSet::new();

    for library_path in steam_library_roots() {
        let steamapps_path = library_path.join("steamapps");
        let Ok(entries) = fs::read_dir(&steamapps_path) else {
            continue;
        };

        for entry in entries.flatten() {
            let path = entry.path();
            let Some(file_name) = path.file_name().and_then(|value| value.to_str()) else {
                continue;
            };

            if !file_name.starts_with("appmanifest_") || !file_name.ends_with(".acf") {
                continue;
            }

            let Some(game) = parse_steam_app_manifest(&path, &library_path) else {
                continue;
            };

            if is_user_steam_game(&game) && seen_app_ids.insert(game.app_id.clone()) {
                games.push(game);
            }
        }
    }

    games.sort_by(|first, second| {
        first
            .name
            .to_lowercase()
            .cmp(&second.name.to_lowercase())
            .then_with(|| first.app_id.cmp(&second.app_id))
    });
    games
}

fn scan_steam_games_cached() -> Vec<SteamGameRecord> {
    if let Ok(cache) = STEAM_GAMES_CACHE.get_or_init(|| Mutex::new(None)).lock() {
        if let Some(entry) = cache.as_ref() {
            if entry.fetched_at.elapsed() <= STEAM_GAMES_CACHE_TTL {
                return entry.games.clone();
            }
        }
    }

    let games = scan_steam_games_impl();
    update_steam_games_cache(&games);
    games
}

fn update_steam_games_cache(games: &[SteamGameRecord]) {
    if let Ok(mut cache) = STEAM_GAMES_CACHE.get_or_init(|| Mutex::new(None)).lock() {
        *cache = Some(SteamGamesCacheEntry {
            fetched_at: Instant::now(),
            games: games.to_vec(),
        });
    }
}

fn is_user_steam_game(game: &SteamGameRecord) -> bool {
    let lower_name = game.name.to_lowercase();
    Path::new(&game.install_dir).is_dir()
        && game.app_id != "228980"
        && !lower_name.contains("steamworks common redistributables")
        && !lower_name.starts_with("steam linux runtime")
        && !lower_name.contains("proton ")
        && !lower_name.ends_with(" dedicated server")
}

fn steam_library_roots() -> Vec<PathBuf> {
    let mut roots = Vec::new();
    let mut seen = HashSet::new();

    for steam_root in steam_install_roots() {
        push_unique_path(&mut roots, &mut seen, steam_root.clone());

        let library_file = steam_root.join("steamapps").join("libraryfolders.vdf");
        let Ok(content) = fs::read_to_string(&library_file) else {
            continue;
        };

        for library_path in parse_steam_library_paths(&content) {
            push_unique_path(&mut roots, &mut seen, library_path);
        }
    }

    roots
}

fn steam_install_roots() -> Vec<PathBuf> {
    let mut roots = Vec::new();
    let mut seen = HashSet::new();

    for root in steam_registry_roots() {
        push_unique_path(&mut roots, &mut seen, root);
    }

    if let Ok(program_files_x86) = std::env::var("ProgramFiles(x86)") {
        push_unique_path(
            &mut roots,
            &mut seen,
            PathBuf::from(program_files_x86).join("Steam"),
        );
    }

    if let Ok(program_files) = std::env::var("ProgramFiles") {
        push_unique_path(
            &mut roots,
            &mut seen,
            PathBuf::from(program_files).join("Steam"),
        );
    }

    push_unique_path(
        &mut roots,
        &mut seen,
        PathBuf::from(r"C:\Program Files (x86)\Steam"),
    );
    roots
        .into_iter()
        .filter(|root| root.join("steamapps").is_dir())
        .collect()
}

#[cfg(windows)]
fn steam_registry_roots() -> Vec<PathBuf> {
    use winreg::enums::{HKEY_CURRENT_USER, HKEY_LOCAL_MACHINE};
    use winreg::RegKey;

    let mut roots = Vec::new();

    for (hive, key_path, value_name) in [
        (
            RegKey::predef(HKEY_CURRENT_USER),
            r"Software\Valve\Steam",
            "SteamPath",
        ),
        (
            RegKey::predef(HKEY_LOCAL_MACHINE),
            r"SOFTWARE\WOW6432Node\Valve\Steam",
            "InstallPath",
        ),
        (
            RegKey::predef(HKEY_LOCAL_MACHINE),
            r"SOFTWARE\Valve\Steam",
            "InstallPath",
        ),
    ] {
        if let Ok(key) = hive.open_subkey(key_path) {
            if let Ok(path) = key.get_value::<String, _>(value_name) {
                let path = path.trim();
                if !path.is_empty() {
                    roots.push(PathBuf::from(path));
                }
            }
        }
    }

    roots
}

#[cfg(not(windows))]
fn steam_registry_roots() -> Vec<PathBuf> {
    Vec::new()
}

fn parse_steam_library_paths(content: &str) -> Vec<PathBuf> {
    let mut paths = Vec::new();

    for line in content.lines() {
        let tokens = quoted_values(line);
        if tokens.len() < 2 {
            continue;
        }

        let key = tokens[0].trim();
        let value = tokens[1].trim();
        if key.eq_ignore_ascii_case("path")
            || (key.chars().all(|ch| ch.is_ascii_digit()) && looks_like_path(value))
        {
            paths.push(PathBuf::from(value));
        }
    }

    paths
}

fn parse_steam_app_manifest(path: &Path, library_path: &Path) -> Option<SteamGameRecord> {
    let content = fs::read_to_string(path).ok()?;
    let mut values: HashMap<String, String> = HashMap::new();

    for line in content.lines() {
        let tokens = quoted_values(line);
        if tokens.len() >= 2 {
            values.insert(tokens[0].to_lowercase(), tokens[1].clone());
        }
    }

    let app_id = values.get("appid")?.trim().to_string();
    let name = values.get("name")?.trim().to_string();
    let install_dir_name = values
        .get("installdir")
        .map(String::as_str)
        .unwrap_or(name.as_str());
    let install_dir = steam_install_dir_from_manifest(library_path, install_dir_name)?;

    Some(SteamGameRecord {
        app_id,
        name,
        install_dir: install_dir.to_string_lossy().to_string(),
        library_path: library_path.to_string_lossy().to_string(),
    })
}

fn steam_install_dir_from_manifest(library_path: &Path, install_dir_name: &str) -> Option<PathBuf> {
    if install_dir_name != install_dir_name.trim() {
        return None;
    }
    let install_dir_name = install_dir_name.trim();
    if install_dir_name.is_empty()
        || install_dir_name == "."
        || install_dir_name == ".."
        || install_dir_name.contains(['/', '\\', ':', '\0'])
        || validate_archive_relative_path(install_dir_name).is_err()
    {
        return None;
    }

    let mut components = Path::new(install_dir_name).components();
    if !matches!(components.next(), Some(Component::Normal(_))) || components.next().is_some() {
        return None;
    }

    let common_root = library_path.join("steamapps").join("common");
    let install_dir = common_root.join(install_dir_name);
    let mut relative_components = install_dir.strip_prefix(&common_root).ok()?.components();
    if !matches!(relative_components.next(), Some(Component::Normal(_)))
        || relative_components.next().is_some()
        || install_dir.parent() != Some(common_root.as_path())
    {
        return None;
    }

    Some(install_dir)
}

fn infer_steam_app_id_for_game_path(game_path: &Path) -> Option<String> {
    let common_path = game_path.parent()?;
    if !common_path
        .file_name()
        .and_then(|value| value.to_str())
        .is_some_and(|value| value.eq_ignore_ascii_case("common"))
    {
        return None;
    }

    let steamapps_path = common_path.parent()?;
    if !steamapps_path
        .file_name()
        .and_then(|value| value.to_str())
        .is_some_and(|value| value.eq_ignore_ascii_case("steamapps"))
    {
        return None;
    }

    let library_path = steamapps_path.parent()?;
    let target_identity = normalize_filesystem_identity(&game_path.to_string_lossy());
    let entries = fs::read_dir(steamapps_path).ok()?;

    for entry in entries.flatten() {
        let manifest_path = entry.path();
        let Some(file_name) = manifest_path.file_name().and_then(|value| value.to_str()) else {
            continue;
        };
        if !file_name.starts_with("appmanifest_") || !file_name.ends_with(".acf") {
            continue;
        }

        let Some(game) = parse_steam_app_manifest(&manifest_path, library_path) else {
            continue;
        };
        if normalize_filesystem_identity(&game.install_dir) == target_identity {
            return Some(game.app_id);
        }
    }

    None
}

fn quoted_values(line: &str) -> Vec<String> {
    let mut values = Vec::new();
    let mut chars = line.chars().peekable();

    while let Some(ch) = chars.next() {
        if ch != '"' {
            continue;
        }

        let mut value = String::new();
        let mut escaped = false;

        for next_ch in chars.by_ref() {
            if escaped {
                value.push(next_ch);
                escaped = false;
                continue;
            }

            if next_ch == '\\' {
                escaped = true;
                continue;
            }

            if next_ch == '"' {
                break;
            }

            value.push(next_ch);
        }

        values.push(value);
    }

    values
}

fn looks_like_path(value: &str) -> bool {
    value.contains(":\\") || value.contains(":/") || value.contains('\\') || value.contains('/')
}

fn push_unique_path(paths: &mut Vec<PathBuf>, seen: &mut HashSet<String>, path: PathBuf) {
    let key = path.to_string_lossy().replace('/', "\\").to_lowercase();
    if seen.insert(key) {
        paths.push(path);
    }
}

#[tauri::command]
fn rename_profile(app: AppHandle, profile_id: String, name: String) -> Result<GameProfile, String> {
    let trimmed_name = name.trim().to_string();
    if trimmed_name.is_empty() {
        return Err("Profile name is required.".to_string());
    }

    let profile_operation = operation::profile_lock(&profile_id)?;
    let _profile_operation = operation::lock_profile(&profile_operation)?;
    let _commit = lock_mutations()?;
    let root = store_root(&app)?;
    let path = profiles_path(&root);
    let mut store = read_store::<GameProfile>(&path).map_err(error_to_string)?;
    let profile = store
        .items
        .iter_mut()
        .find(|profile| profile.id == profile_id)
        .ok_or_else(|| format!("Profile not found: {}", profile_id))?;

    profile.name = trimmed_name;
    profile.updated_at = now_string();
    let updated_profile = profile.clone();
    write_store(&path, &store).map_err(error_to_string)?;
    Ok(updated_profile)
}

#[tauri::command]
fn remove_profile(
    app: AppHandle,
    profile_id: String,
    force_forget_modified: Option<bool>,
) -> Result<ProfileActionResult, String> {
    let force_forget_modified = force_forget_modified.unwrap_or(false);
    let profile_operation = operation::profile_lock(&profile_id)?;
    let _profile_operation = operation::lock_profile(&profile_operation)?;
    let root = store_root(&app)?;
    let profile = get_profile(&root, &profile_id)?;
    ensure_game_files_mutable(&profile, "remove this profile")?;

    let installed_mods =
        read_store::<InstalledModRecord>(&installed_mods_path(&root)).map_err(error_to_string)?;
    let profile_mods = installed_mods
        .items
        .iter()
        .filter(|record| record.profile_id == profile.id)
        .cloned()
        .collect::<Vec<_>>();
    let launch_suspension = read_profile_launch_suspension(&root, &profile.id)?;
    let suspended_ids = launch_suspension
        .mods
        .iter()
        .map(|suspended| suspended.mod_id.as_str())
        .collect::<HashSet<_>>();
    let mut deactivated: Vec<InstalledModRecord> = Vec::new();
    let mut warnings = Vec::new();
    let mut preserved_modified_files = false;
    for record in profile_mods.iter().filter(|record| {
        record.enabled
            && record_is_mod_garrison_owned(record)
            && !suspended_ids.contains(record.id.as_str())
    }) {
        let policy = if force_forget_modified {
            ModifiedFilePolicy::Preserve
        } else {
            ModifiedFilePolicy::RequireRemovalConfirmation
        };
        let deactivation = deactivate_mod_files_with_policy(&root, &profile, record, policy);
        let deactivation = match deactivation {
            Ok(deactivation) => deactivation,
            Err(error) => {
                for previous in deactivated.iter().rev() {
                    let mut previous = previous.clone();
                    if let Some(plan) = previous.plan.clone() {
                        let install_id = previous.id.clone();
                        let archive_path = previous.archive_path.clone();
                        let _ = deploy_mod_files(
                            &root,
                            &profile,
                            &install_id,
                            &archive_path,
                            &plan,
                            &mut previous,
                        );
                    }
                }
                return Err(format!(
                    "Profile removal was cancelled because its mod files could not be safely removed: {error}"
                ));
            }
        };
        preserved_modified_files |= !deactivation.preserved_files.is_empty();
        warnings.extend(deactivation.warnings);
        deactivated.push(record.clone());
    }

    let removed_mod_records = profile_mods.len();
    if let Err(error) = commit_removed_profile_state(&root, &profile.id) {
        if !preserved_modified_files {
            for previous in deactivated.iter().rev() {
                let mut previous = previous.clone();
                if let Some(plan) = previous.plan.clone() {
                    let install_id = previous.id.clone();
                    let archive_path = previous.archive_path.clone();
                    let _ = deploy_mod_files(
                        &root,
                        &profile,
                        &install_id,
                        &archive_path,
                        &plan,
                        &mut previous,
                    );
                }
            }
        }
        return Err(error);
    }

    if let Err(error) = remove_pending_nexus_downloads_for_profile(&root, &profile.id) {
        warnings.push(format!(
            "Profile was removed, but Mod Garrison could not clear its pending Nexus downloads: {error}"
        ));
    }
    let profile_data_dir = profile_dir(&root, &profile.id);
    if profile_data_dir.exists() {
        if let Err(error) = fs::remove_dir_all(&profile_data_dir) {
            warnings.push(format!(
                "Profile was removed, but Mod Garrison could not remove its local data folder: {}.",
                error
            ));
        }
    }

    Ok(ProfileActionResult {
        profile_id: profile.id,
        name: profile.name,
        removed_mod_records,
        warnings,
    })
}

#[tauri::command]
async fn refresh_profile(
    app: AppHandle,
    profile_id: String,
) -> Result<ProfileRefreshResult, String> {
    tauri::async_runtime::spawn_blocking(move || refresh_profile_sync(app, profile_id))
        .await
        .map_err(error_to_string)?
}

fn refresh_profile_sync(
    app: AppHandle,
    profile_id: String,
) -> Result<ProfileRefreshResult, String> {
    let profile_operation = operation::profile_lock(&profile_id)?;
    let _profile_operation = operation::lock_profile(&profile_operation)?;
    let root = store_root(&app)?;
    let mut profile = get_profile(&root, &profile_id)?;
    ensure_verified_steam_profile(&profile)?;
    let mut detection = detect_game_setup_with_steam_app_id(
        Path::new(&profile.game_path),
        profile.steam_app_id.as_deref(),
    )?;

    profile.game_id = detection.game_id.clone().or(profile.game_id);
    if detection.engine != "unknown" || profile.engine == "unknown" {
        profile.engine = detection.engine.clone();
    }
    if detection.loader != "none" || runtime_definition_by_id(&profile.loader).is_none() {
        profile.loader = detection.loader.clone();
    }
    let runtime_inference_outcome = enrich_profile_with_provider_runtime(&root, &mut profile, true);
    let runtime_inference = runtime_inference_outcome.inference;
    let runtime_inference_warnings = runtime_inference_outcome.warnings;
    profile.updated_at = now_string();

    let launch_suspension = read_profile_launch_suspension(&root, &profile.id)?;
    let mut bootstrap_warnings = Vec::new();
    let mut runtime_refresh = RuntimeRefreshOutcome::default();
    let mut can_repair_managed_folders = false;
    if !launch_suspension.mods.is_empty() {
        runtime_refresh.notes.push(
            "Runtime updates are postponed while Mods OFF clean-launch mode is active.".to_string(),
        );
    } else {
        match game_process_running(Path::new(&profile.game_path)) {
            Ok(true) => runtime_refresh.notes.push(
                "Runtime updates are postponed until the game is closed.".to_string(),
            ),
            Ok(false) => {
                can_repair_managed_folders = true;
                runtime_refresh = refresh_profile_runtime_updates(&root, &profile);
                bootstrap_warnings = install_profile_bootstrap_dependencies(&root, &profile);
            }
            Err(error) => runtime_refresh.warnings.push(format!(
                "Runtime updates were skipped because Mod Garrison could not verify whether the game is running: {error}"
            )),
        }
    }
    let route_outcome = ensure_profile_route_knowledge(&root, &profile, false);
    for route in &route_outcome.expected_routes {
        push_unique_route(&mut detection.expected_mod_folders, route);
    }
    for route in &route_outcome.created_routes {
        push_unique_route(&mut detection.created_mod_folders, route);
    }
    apply_profile_identity_to_detection(&profile, &mut detection, runtime_inference.as_ref());
    let managed_folder_migration = if can_repair_managed_folders {
        migrate_legacy_generated_mod_folders(&root, &profile)?
    } else {
        ManagedFolderMigrationOutcome::default()
    };
    if managed_folder_migration.migrated_records > 0 {
        runtime_refresh.notes.push(format!(
            "Renamed legacy generated folders for {} managed mod(s) ({} file(s)).",
            managed_folder_migration.migrated_records, managed_folder_migration.migrated_files
        ));
    }
    let mut setup_warnings = bootstrap_warnings.clone();
    setup_warnings.extend(runtime_inference_warnings);
    setup_warnings.extend(runtime_refresh.warnings.clone());
    setup_warnings.extend(route_outcome.warnings.clone());
    setup_warnings.extend(managed_folder_migration.warnings.clone());
    apply_profile_setup_outcome(&mut profile, setup_warnings);

    let discovered_config_files = discover_profile_config_files(&profile);
    let mut installed_store =
        read_store::<InstalledModRecord>(&installed_mods_path(&root)).map_err(error_to_string)?;
    let adopted_native_script_mods =
        adopt_existing_profile_mods(&root, &profile, &mut installed_store)?;
    ensure_visible_runtime_records(&root, &profile, &mut installed_store)?;
    for record in installed_store
        .items
        .iter_mut()
        .filter(|record| record.profile_id == profile_id)
    {
        record.display_name = record
            .display_name
            .as_deref()
            .map(humanize_mod_display_name);
    }
    let config_records = installed_store
        .items
        .iter()
        .filter(|record| record.profile_id == profile_id)
        .cloned()
        .collect::<Vec<_>>();
    let mut config_files_by_record =
        resolved_profile_config_files(&profile, &config_records, &discovered_config_files);
    let mut mod_file_health = Vec::new();
    let mut missing_dependencies = Vec::new();
    let mut dependency_keys = HashSet::new();

    for dependency in profile_bootstrap_dependencies(&profile) {
        let dependency = refresh_dependency_status(&root, &profile, &dependency);
        push_missing_dependency(
            &mut missing_dependencies,
            &mut dependency_keys,
            dependency,
            None,
        );
    }

    for record in installed_store
        .items
        .iter_mut()
        .filter(|record| record.profile_id == profile_id)
    {
        record.config_files = config_files_by_record
            .remove(&record.id)
            .unwrap_or_default();
        let selected_target = installed_record_selected_target(record).cloned();
        record.dependencies = record
            .dependencies
            .iter()
            .map(|dependency| {
                refresh_dependency_status_for_target(
                    &root,
                    &profile,
                    dependency,
                    selected_target.as_ref(),
                )
            })
            .collect();

        for dependency in &record.dependencies {
            push_missing_dependency(
                &mut missing_dependencies,
                &mut dependency_keys,
                dependency.clone(),
                selected_target.as_ref(),
            );
        }

        mod_file_health.push(mod_file_health_for_record(record, &launch_suspension));
    }

    let installed_mods = installed_store
        .items
        .iter()
        .filter(|record| record.profile_id == profile_id)
        .cloned()
        .collect::<Vec<_>>();
    commit_refreshed_profile_state(&root, &profile, &installed_mods)?;
    let mut warnings =
        profile_refresh_warnings(&detection, &mod_file_health, &missing_dependencies);
    warnings.extend(bootstrap_warnings);
    warnings.extend(runtime_refresh.warnings.clone());
    warnings.extend(route_outcome.warnings);
    warnings.extend(managed_folder_migration.warnings);

    Ok(ProfileRefreshResult {
        profile,
        detection,
        installed_mods,
        mod_file_health,
        missing_dependencies,
        adopted_native_script_mods,
        runtime_updates: runtime_refresh.updates,
        runtime_update_notes: runtime_refresh.notes,
        warnings,
    })
}

