#[tauri::command]
async fn bootstrap_profile_dependencies(
    app: AppHandle,
    profile_id: String,
) -> Result<ProfileDependencyBootstrapResult, String> {
    tauri::async_runtime::spawn_blocking(move || {
        bootstrap_profile_dependencies_sync(app, profile_id)
    })
    .await
    .map_err(error_to_string)?
}

fn bootstrap_profile_dependencies_sync(
    app: AppHandle,
    profile_id: String,
) -> Result<ProfileDependencyBootstrapResult, String> {
    let profile_operation = operation::profile_lock(&profile_id)?;
    let _profile_operation = operation::lock_profile(&profile_operation)?;
    let root = store_root(&app)?;
    let mut profile = get_profile(&root, &profile_id)?;
    ensure_verified_steam_profile(&profile)?;
    repair_profile_identity_from_steam_app_id(&root, &mut profile)?;
    let launch_suspension = read_profile_launch_suspension(&root, &profile.id)?;
    let mutation_block = if !launch_suspension.mods.is_empty() {
        Some(
            "Dependency installation is postponed while Mods OFF clean-launch mode is active."
                .to_string(),
        )
    } else {
        match game_process_running(Path::new(&profile.game_path)) {
            Ok(true) => Some("Dependency installation is postponed until the game is closed.".to_string()),
            Ok(false) => None,
            Err(error) => Some(format!(
                "Dependency installation was skipped because Mod Garrison could not verify whether the game is running: {error}"
            )),
        }
    };
    if let Some(message) = mutation_block {
        return Ok(ProfileDependencyBootstrapResult {
            profile_id,
            installed_dependencies: Vec::new(),
            skipped_dependencies: profile_bootstrap_dependencies(&profile)
                .into_iter()
                .map(|dependency| dependency.name)
                .collect(),
            warnings: vec![message],
        });
    }
    let mut visited_dependencies = HashSet::new();
    let mut installed_dependencies = Vec::new();
    let mut skipped_dependencies = Vec::new();
    let mut warnings = Vec::new();
    let mut seen_dependencies = HashSet::new();

    for (dependency, target) in profile_dependency_candidates(&root, &profile)? {
        if !seen_dependencies.insert(dependency_key_for_target(&dependency, target.as_ref())) {
            continue;
        }
        if dependency.status == "already-installed" {
            skipped_dependencies.push(dependency.name.clone());
            continue;
        }

        let install_result = install_dependency_by_provider_for_target(
            &root,
            &profile,
            &dependency,
            &mut visited_dependencies,
            0,
            target.as_ref(),
        );

        match install_result {
            Ok(mut dependency_warnings) => {
                let verified = refresh_dependency_status_for_target(
                    &root,
                    &profile,
                    &dependency,
                    target.as_ref(),
                );
                if verified.status == "already-installed" {
                    installed_dependencies.push(dependency.name.clone());
                    warnings.append(&mut dependency_warnings);
                } else {
                    warnings.push(format!(
                        "{} was downloaded, but its required runtime files were not detected in the game folder after installation.",
                        dependency.name
                    ));
                }
            }
            Err(error) => warnings.push(format!(
                "Could not install {} automatically: {}",
                dependency.name, error
            )),
        }
    }

    apply_profile_setup_outcome(&mut profile, warnings.clone());
    persist_profile(&root, &profile)?;

    Ok(ProfileDependencyBootstrapResult {
        profile_id,
        installed_dependencies,
        skipped_dependencies,
        warnings,
    })
}

