fn progressive_discovery_fetch_count(
    snapshot: Option<&DiscoveryProviderCacheEntry>,
    required_count: usize,
    warm_cache: bool,
    warm_batch_size: usize,
) -> usize {
    let current_count = snapshot.map_or(0, |entry| entry.records.len());
    let requested_count = if warm_cache {
        required_count.max(current_count.saturating_add(warm_batch_size))
    } else {
        required_count
    };
    requested_count.min(DISCOVERY_PROVIDER_CACHE_MAX_RECORDS)
}

fn remember_discovery_provider_batch(
    key: &str,
    batch: DiscoveryProviderBatch,
) -> DiscoveryProviderCacheEntry {
    let cache = DISCOVERY_PROVIDER_CACHE.get_or_init(|| Mutex::new(HashMap::new()));
    let mut cache = cache
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let now = Instant::now();
    cache.retain(|_, entry| {
        now.duration_since(entry.fetched_at)
            <= Duration::from_secs(DISCOVERY_PROVIDER_CACHE_MINUTES * 60)
    });

    if batch.start_offset > 0 {
        if let Some(existing) = cache.get_mut(key) {
            if batch.start_offset == existing.next_offset {
                let mut seen = existing
                    .records
                    .iter()
                    .map(discovery_record_cache_key)
                    .collect::<HashSet<_>>();
                for record in batch.records {
                    if existing.records.len() >= DISCOVERY_PROVIDER_CACHE_MAX_RECORDS {
                        break;
                    }
                    if seen.insert(discovery_record_cache_key(&record)) {
                        existing.records.push(record);
                    }
                }
                existing.next_offset = batch.next_offset;
                existing.filtered_out = existing.filtered_out.saturating_add(batch.filtered_out);
                existing.complete = batch.complete;
                existing.total = discovery_provider_visible_total(
                    existing.records.len(),
                    batch.raw_total,
                    existing.filtered_out,
                    existing.complete,
                );
                existing.fetched_at = Instant::now();
                let updated = existing.clone();
                prune_discovery_provider_cache(&mut cache, key);
                return cache.get(key).cloned().unwrap_or(updated);
            }
            // Never replace a verified prefix with an overlapping, stale, or
            // gapped continuation from a superseded request.
            return existing.clone();
        }
    }

    let records = batch
        .records
        .into_iter()
        .take(DISCOVERY_PROVIDER_CACHE_MAX_RECORDS)
        .collect::<Vec<_>>();
    let entry = DiscoveryProviderCacheEntry {
        fetched_at: Instant::now(),
        total: discovery_provider_visible_total(
            records.len(),
            batch.raw_total,
            batch.filtered_out,
            batch.complete,
        ),
        records,
        next_offset: batch.next_offset,
        filtered_out: batch.filtered_out,
        complete: batch.complete,
    };
    cache.insert(key.to_string(), entry.clone());
    prune_discovery_provider_cache(&mut cache, key);
    cache.get(key).cloned().unwrap_or(entry)
}

fn prune_discovery_provider_cache(
    cache: &mut HashMap<String, DiscoveryProviderCacheEntry>,
    preserve_key: &str,
) {
    loop {
        let total_records = cache
            .values()
            .map(|entry| entry.records.len())
            .sum::<usize>();
        if cache.len() <= DISCOVERY_PROVIDER_CACHE_MAX_ENTRIES
            && total_records <= DISCOVERY_PROVIDER_CACHE_MAX_TOTAL_RECORDS
        {
            break;
        }
        let Some(oldest) = cache
            .iter()
            .filter(|(key, _)| key.as_str() != preserve_key)
            .min_by_key(|(_, entry)| entry.fetched_at)
            .map(|(key, _)| key.clone())
        else {
            break;
        };
        cache.remove(&oldest);
    }
}

fn discovery_record_cache_key(record: &OnlineModRecord) -> String {
    format!(
        "{}:{}",
        record.provider.to_ascii_lowercase(),
        record.id.to_ascii_lowercase()
    )
}

fn discovery_provider_visible_total(
    record_count: usize,
    raw_total: usize,
    filtered_out: usize,
    complete: bool,
) -> usize {
    if complete {
        record_count
    } else {
        raw_total
            .saturating_sub(filtered_out)
            .max(record_count)
            .min(DISCOVERY_PROVIDER_CACHE_MAX_RECORDS)
    }
}

fn cached_discovery_provider_snapshot(key: &str) -> Option<DiscoveryProviderCacheEntry> {
    let cache = DISCOVERY_PROVIDER_CACHE.get_or_init(|| Mutex::new(HashMap::new()));
    let mut cache = cache.lock().ok()?;
    let entry = cache.get(key)?;
    if entry.fetched_at.elapsed() > Duration::from_secs(DISCOVERY_PROVIDER_CACHE_MINUTES * 60) {
        cache.remove(key);
        return None;
    }
    Some(entry.clone())
}

fn clear_discovery_provider_cache_for_provider(profile_id: &str, provider: &str) {
    let prefix = format!("{}:{profile_id}:", provider.to_ascii_lowercase());
    if let Ok(mut cache) = DISCOVERY_PROVIDER_CACHE
        .get_or_init(|| Mutex::new(HashMap::new()))
        .lock()
    {
        cache.retain(|key, _| !key.starts_with(&prefix));
    }
}

fn ensure_discovery_is_current(profile_id: &str, request_id: u64) -> Result<(), String> {
    if operation::discovery_is_current(profile_id, request_id) {
        Ok(())
    } else {
        Err(DISCOVERY_CANCELLED_ERROR.to_string())
    }
}

fn is_external_mod_manager_listing(record: &OnlineModRecord) -> bool {
    let name = record.name.to_lowercase();
    let description = record.description.to_lowercase();
    let combined = format!("{name} {description}");

    let external_name_markers = [
        "gale mod manager",
        "nexus mod manager",
        "mod organizer 2",
        "r2modman",
        "thunderstore mod manager",
        "thunderstore app",
        "vortex mod manager",
        "vortex extension",
        "vortex support",
    ];
    if external_name_markers
        .iter()
        .any(|marker| name.contains(marker))
    {
        return true;
    }

    let in_game_markers = [
        "in-game mod manager",
        "in game mod manager",
        "ingame mod manager",
        "configuration manager",
        "config manager",
        "configuration menu",
        "config menu",
        "mod browser",
        "mod menu",
        "mod viewer",
    ];
    if in_game_markers
        .iter()
        .any(|marker| combined.contains(marker))
    {
        return false;
    }

    let external_listing_markers = [
        "thunderstore mod manager",
        "thunderstore manager",
        "thunderstore app",
        "r2modman",
        "r2modmanplus",
        "nexus mod manager",
        "mod organizer 2",
        "vortex mod manager",
        "vortex extension",
        "vortex support",
        "support for vortex",
        "support for thunderstore",
        "overwolf app",
        "curseforge app",
        "desktop mod manager",
        "external mod manager",
        "mod manager for thunderstore",
        "manager for nexus mods",
    ];
    if external_listing_markers
        .iter()
        .any(|marker| combined.contains(marker))
    {
        return true;
    }

    let describes_manager = combined.contains("mod manager")
        || combined.contains("mod-manager")
        || combined.contains("modmanager");
    let external_ecosystem = combined.contains("thunderstore")
        || combined.contains("nexus mods")
        || combined.contains("r2modman")
        || combined.contains("vortex")
        || combined.contains("overwolf")
        || combined.contains("curseforge");

    describes_manager && external_ecosystem
}

fn online_mod_matches_query(record: &OnlineModRecord, query: &str) -> bool {
    record.name.to_lowercase().contains(query)
}

fn sort_online_mods(records: &mut [OnlineModRecord], sort: &str) {
    records.sort_by(|first, second| match sort {
        "newest" => online_mod_timestamp(second)
            .cmp(&online_mod_timestamp(first))
            .then_with(|| second.downloads.cmp(&first.downloads))
            .then_with(|| first.provider.cmp(&second.provider))
            .then_with(|| first.id.cmp(&second.id)),
        "oldest" => online_mod_timestamp(first)
            .cmp(&online_mod_timestamp(second))
            .then_with(|| second.downloads.cmp(&first.downloads))
            .then_with(|| first.provider.cmp(&second.provider))
            .then_with(|| first.id.cmp(&second.id)),
        _ => second
            .downloads
            .cmp(&first.downloads)
            .then_with(|| second.rating_score.cmp(&first.rating_score))
            .then_with(|| first.name.to_lowercase().cmp(&second.name.to_lowercase()))
            .then_with(|| first.provider.cmp(&second.provider))
            .then_with(|| first.id.cmp(&second.id)),
    });
}

fn online_mod_timestamp(record: &OnlineModRecord) -> i64 {
    record
        .updated_at
        .as_deref()
        .or(record.created_at.as_deref())
        .and_then(|value| chrono::DateTime::parse_from_rfc3339(value).ok())
        .map(|value| value.timestamp())
        .unwrap_or(0)
}

fn thunderstore_community_for_profile(profile: &GameProfile) -> Option<String> {
    thunderstore_community_for_profile_with_refresh(profile, false)
}

fn thunderstore_community_for_profile_with_refresh(
    profile: &GameProfile,
    force_refresh: bool,
) -> Option<String> {
    if let Some(community) = bundled_thunderstore_community_for_profile(profile) {
        return Some(community);
    }

    auto_detect_thunderstore_community(profile, force_refresh)
}

fn bundled_thunderstore_community_for_profile(profile: &GameProfile) -> Option<String> {
    profile
        .game_id
        .as_deref()
        .and_then(game_definition_by_id)
        .and_then(|definition| definition.thunderstore_community.clone())
}

fn nexus_domain_for_profile(profile: &GameProfile) -> Option<String> {
    nexus_domain_for_profile_with_refresh(profile, false)
}

fn nexus_domain_for_profile_with_refresh(
    profile: &GameProfile,
    force_refresh: bool,
) -> Option<String> {
    if let Some(domain) = bundled_nexus_domain_for_profile(profile) {
        return Some(domain);
    }

    auto_detect_nexus_mapping(profile, force_refresh)
        .ok()
        .flatten()
        .map(|mapping| mapping.provider_game_id)
}

fn bundled_nexus_domain_for_profile(profile: &GameProfile) -> Option<String> {
    profile
        .game_id
        .as_deref()
        .and_then(game_definition_by_id)
        .and_then(|definition| definition.nexus_game_domain.clone())
}

fn verified_discovery_provider_game(
    store_root: &Path,
    profile: &GameProfile,
    provider: &str,
    supplied_provider_game_id: Option<&str>,
    package_provider_game_id: Option<&str>,
) -> Result<String, String> {
    let expected = match provider {
        "thunderstore" => thunderstore_community_for_profile(profile),
        "nexus" => bundled_nexus_domain_for_profile(profile)
            .or_else(|| {
                persisted_provider_game_mapping(store_root, "nexus", profile)
                    .ok()
                    .flatten()
                    .map(|mapping| mapping.provider_game_id)
            })
            .or_else(|| nexus_domain_for_profile(profile)),
        "steam-workshop" => steam_workshop::verified_app_id(profile).ok(),
        "modio" => persisted_provider_game_mapping(store_root, "modio", profile)
            .ok()
            .flatten()
            .map(|mapping| mapping.provider_game_id),
        _ => None,
    }
    .ok_or_else(|| {
        format!(
            "Mod Garrison could not verify the {} game catalogue for {}.",
            provider_label(provider),
            profile_game_label(profile)
        )
    })?;
    let actual = package_provider_game_id
        .or(supplied_provider_game_id)
        .unwrap_or(expected.as_str());

    if let Some(supplied) = supplied_provider_game_id {
        if compact_provider_slug(supplied) != compact_provider_slug(actual) {
            return Err(format!(
                "The selected {} result no longer matches its provider game catalogue. Refresh Discovery and try again.",
                provider_label(provider)
            ));
        }
    }
    if compact_provider_slug(actual) != compact_provider_slug(&expected) {
        return Err(format!(
            "This {} mod belongs to '{}', but the selected profile is linked to '{}'. No files were installed.",
            provider_label(provider),
            actual,
            expected
        ));
    }

    Ok(expected)
}

fn auto_detect_thunderstore_community(
    profile: &GameProfile,
    force_refresh: bool,
) -> Option<String> {
    cached_provider_mapping("thunderstore", profile, force_refresh, || {
        let client = provider_client().ok()?;
        let candidates = provider_slug_candidates(profile);
        parallel_first_map(&candidates, &|candidate| {
            thunderstore_community_available(&client, candidate).then(|| candidate.to_string())
        })
    })
}

fn thunderstore_community_available(client: &Client, community: &str) -> bool {
    let url = format!(
        "{}/{}/api/v1/package/",
        THUNDERSTORE_COMMUNITY_API_BASE,
        sanitize_url_path_segment(community)
    );
    client
        .get(url)
        .send()
        .map(|response| response.status().is_success())
        .unwrap_or(false)
}

fn auto_detect_nexus_mapping(
    profile: &GameProfile,
    force_refresh: bool,
) -> Result<Option<ProviderGameMapping>, String> {
    let canonical_game = verified_steam_game_for_profile(profile)?;
    let canonical_name = canonical_game.name;
    let steam_app_id = profile
        .steam_app_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| {
            "Automatic Nexus catalogue matching requires a verified Steam App ID.".to_string()
        })?
        .to_string();
    let mut resolved_node = None;
    let mut resolution = "catalog-exact-name".to_string();
    let mut resolution_error = None;
    let domain = cached_provider_mapping("nexus", profile, force_refresh, || {
        let client = match provider_client() {
            Ok(client) => client,
            Err(error) => {
                resolution_error = Some(error);
                return None;
            }
        };
        match resolve_nexus_game_node(&client, &canonical_name) {
            Ok(Some((node, source))) => {
                let domain = node.domain_name.clone();
                resolution = source;
                resolved_node = Some(node);
                Some(domain)
            }
            Ok(None) => None,
            Err(error) => {
                resolution_error = Some(error);
                None
            }
        }
    });

    if domain.is_none() {
        if let Some(error) = resolution_error {
            return Err(error);
        }
        return Ok(None);
    }
    let domain = domain.expect("checked above");
    let provider_catalogue_id = resolved_node
        .as_ref()
        .and_then(|node| node.id)
        .map(|id| id.to_string());
    Ok(Some(ProviderGameMapping {
        provider: "nexus".to_string(),
        steam_app_id,
        canonical_game_name: canonical_name,
        provider_game_id: domain,
        provider_catalogue_id,
        resolution,
        verified_at: now_string(),
    }))
}

fn cached_provider_mapping<F>(
    provider: &str,
    profile: &GameProfile,
    force_refresh: bool,
    resolve: F,
) -> Option<String>
where
    F: FnOnce() -> Option<String>,
{
    cached_provider_mapping_result(provider, profile, force_refresh, || Ok(resolve()))
        .unwrap_or_default()
}

fn cached_provider_mapping_result<F>(
    provider: &str,
    profile: &GameProfile,
    force_refresh: bool,
    resolve: F,
) -> Result<Option<String>, String>
where
    F: FnOnce() -> Result<Option<String>, String>,
{
    let cache_key = provider_mapping_cache_key(provider, profile);
    if force_refresh {
        clear_cached_provider_mapping(provider, profile);
    } else {
        if let Ok(cache) = PROVIDER_MAPPING_CACHE
            .get_or_init(|| Mutex::new(HashMap::new()))
            .lock()
        {
            if let Some(entry) = cache.get(&cache_key) {
                let ttl = if entry.value.is_some() {
                    Duration::from_secs(PROVIDER_MAPPING_CACHE_HOURS * 60 * 60)
                } else {
                    Duration::from_secs(PROVIDER_MAPPING_NEGATIVE_CACHE_MINUTES * 60)
                };
                if entry.fetched_at.elapsed() < ttl {
                    return Ok(entry.value.clone());
                }
            }
        }
    }

    // A failed request is not evidence that this game has no catalogue.
    let value = resolve()?;
    if let Ok(mut cache) = PROVIDER_MAPPING_CACHE
        .get_or_init(|| Mutex::new(HashMap::new()))
        .lock()
    {
        let now = Instant::now();
        cache.retain(|_, entry| {
            let ttl = if entry.value.is_some() {
                Duration::from_secs(PROVIDER_MAPPING_CACHE_HOURS * 60 * 60)
            } else {
                Duration::from_secs(PROVIDER_MAPPING_NEGATIVE_CACHE_MINUTES * 60)
            };
            now.duration_since(entry.fetched_at) < ttl
        });
        evict_oldest_provider_mapping_entry(
            &mut cache,
            PROVIDER_MAPPING_CACHE_MAX_ENTRIES,
            &cache_key,
        );
        cache.insert(
            cache_key,
            ProviderMappingCacheEntry {
                fetched_at: now,
                value: value.clone(),
            },
        );
    }
    Ok(value)
}

fn provider_mapping_cache_key(provider: &str, profile: &GameProfile) -> String {
    if let Some(app_id) = profile
        .steam_app_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        return format!("{provider}:steam:{}", app_id.to_ascii_lowercase());
    }

    let game_identity = Path::new(&profile.game_path)
        .canonicalize()
        .unwrap_or_else(|_| PathBuf::from(&profile.game_path))
        .to_string_lossy()
        .replace('\\', "/")
        .to_lowercase();
    format!("{provider}:path:{game_identity}")
}

fn clear_cached_provider_mapping(provider: &str, profile: &GameProfile) {
    let cache_key = provider_mapping_cache_key(provider, profile);
    if let Ok(mut cache) = PROVIDER_MAPPING_CACHE
        .get_or_init(|| Mutex::new(HashMap::new()))
        .lock()
    {
        cache.remove(&cache_key);
    }
}

fn known_nexus_mapping_for_discovery(
    store_root: &Path,
    profile: &GameProfile,
) -> ProviderGameResolution {
    if let Some(domain) = bundled_nexus_domain_for_profile(profile) {
        return ProviderGameResolution {
            mapping: Some(ProviderGameMapping {
                provider: "nexus".to_string(),
                steam_app_id: profile.steam_app_id.clone().unwrap_or_default(),
                canonical_game_name: canonical_game_name_for_profile(profile),
                provider_game_id: domain,
                provider_catalogue_id: None,
                resolution: "bundled".to_string(),
                verified_at: now_string(),
            }),
            warning: None,
        };
    }
    known_persisted_provider_mapping(store_root, "nexus", profile)
}

fn known_persisted_provider_mapping(
    store_root: &Path,
    provider: &str,
    profile: &GameProfile,
) -> ProviderGameResolution {
    match persisted_provider_game_mapping(store_root, provider, profile) {
        Ok(mapping) => ProviderGameResolution {
            mapping,
            warning: None,
        },
        Err(error) => ProviderGameResolution {
            mapping: None,
            warning: Some(format!(
                "Mod Garrison could not read its saved {provider} catalogue mapping: {error}"
            )),
        },
    }
}

fn resolve_nexus_mapping_for_discovery(
    store_root: &Path,
    profile: &GameProfile,
    force_refresh: bool,
) -> ProviderGameResolution {
    if let Some(domain) = bundled_nexus_domain_for_profile(profile) {
        return ProviderGameResolution {
            mapping: Some(ProviderGameMapping {
                provider: "nexus".to_string(),
                steam_app_id: profile.steam_app_id.clone().unwrap_or_default(),
                canonical_game_name: canonical_game_name_for_profile(profile),
                provider_game_id: domain,
                provider_catalogue_id: None,
                resolution: "bundled".to_string(),
                verified_at: now_string(),
            }),
            warning: None,
        };
    }

    let saved = match persisted_provider_game_mapping(store_root, "nexus", profile) {
        Ok(mapping) => mapping,
        Err(error) => {
            return ProviderGameResolution {
                mapping: auto_detect_nexus_mapping(profile, true)
                    .ok()
                    .flatten(),
                warning: Some(format!(
                    "Nexus Mods catalogue matching is available, but Mod Garrison could not read its saved provider mapping: {error}"
                )),
            };
        }
    };
    if !force_refresh {
        if let Some(mapping) = saved {
            return ProviderGameResolution {
                mapping: Some(mapping),
                warning: None,
            };
        }
    }

    clear_cached_provider_mapping("nexus", profile);
    match auto_detect_nexus_mapping(profile, true) {
        Ok(Some(mapping)) => {
            let warning = remember_provider_game_mapping(store_root, mapping.clone())
                .err()
                .map(|error| {
                    format!(
                        "Nexus Mods was linked automatically, but Mod Garrison could not remember the verified mapping: {error}"
                    )
                });
            ProviderGameResolution {
                mapping: Some(mapping),
                warning,
            }
        }
        Ok(None) => {
            let forget_warning = forget_provider_game_mapping(store_root, "nexus", profile)
                .err()
                .map(|error| format!(" The obsolete saved mapping could not be removed: {error}"))
                .unwrap_or_default();
            ProviderGameResolution {
                mapping: None,
                warning: Some(format!(
                    "{}{}",
                    unlinked_nexus_catalogue_message(profile),
                    forget_warning
                )),
            }
        }
        Err(error) => {
            if let Some(mapping) = saved {
                return ProviderGameResolution {
                    mapping: Some(mapping),
                    warning: Some(format!(
                        "Nexus Mods could not refresh its catalogue mapping ({error}). Mod Garrison kept the last verified mapping."
                    )),
                };
            }
            ProviderGameResolution {
                mapping: None,
                warning: Some(format!(
                    "{} Nexus Mods could not be reached while matching the catalogue: {error}",
                    unlinked_nexus_catalogue_message(profile)
                )),
            }
        }
    }
}

fn resolve_modio_mapping_for_discovery(
    store_root: &Path,
    profile: &GameProfile,
    api_key: &str,
    force_refresh: bool,
) -> ProviderGameResolution {
    resolve_modio_mapping_for_discovery_with(store_root, profile, force_refresh, || {
        modio::resolve_mapping(profile, api_key, force_refresh)
    })
}

fn resolve_modio_mapping_for_discovery_with<F>(
    store_root: &Path,
    profile: &GameProfile,
    force_refresh: bool,
    resolve: F,
) -> ProviderGameResolution
where
    F: FnOnce() -> Result<Option<ProviderGameMapping>, String>,
{
    let saved = persisted_provider_game_mapping(store_root, "modio", profile);
    if !force_refresh {
        if let Ok(Some(mapping)) = saved.as_ref() {
            return ProviderGameResolution {
                mapping: Some(mapping.clone()),
                warning: None,
            };
        }
    }
    let persisted_mapping_warning = saved.err().map(|error| {
        format!("Mod Garrison could not read its saved mod.io provider mapping: {error}")
    });
    if force_refresh {
        clear_cached_provider_mapping("modio", profile);
    }
    match resolve() {
        Ok(Some(mapping)) => {
            let remember_warning = remember_provider_game_mapping(store_root, mapping.clone())
                .err()
                .map(|error| {
                    format!(
                        "mod.io was linked automatically, but Mod Garrison could not remember the verified mapping: {error}"
                    )
                });
            ProviderGameResolution {
                mapping: Some(mapping),
                warning: remember_warning.or(persisted_mapping_warning),
            }
        }
        Ok(None) => {
            let forget_warning = forget_provider_game_mapping(store_root, "modio", profile)
                .err()
                .map(|error| {
                    format!("The obsolete saved mod.io mapping could not be removed: {error}")
                });
            let warnings = persisted_mapping_warning
                .into_iter()
                .chain(forget_warning)
                .collect::<Vec<_>>();
            ProviderGameResolution {
                mapping: None,
                // An optional provider with no matching catalogue is a normal
                // result. Storage and actual request failures remain visible.
                warning: (!warnings.is_empty()).then(|| warnings.join(" ")),
            }
        }
        Err(error) => ProviderGameResolution {
            mapping: None,
            warning: Some(format!(
                "mod.io could not verify a catalogue match for {}: {error}",
                profile_game_label(profile)
            )),
        },
    }
}

fn modio_discovery_warning(
    profile: &GameProfile,
    resolution: &ProviderGameResolution,
    explicitly_selected: bool,
) -> Option<String> {
    resolution.warning.clone().or_else(|| {
        (explicitly_selected && resolution.mapping.is_none()).then(|| {
            format!(
                "mod.io has no verified catalogue for {}.",
                profile_game_label(profile)
            )
        })
    })
}

fn unlinked_nexus_catalogue_message(profile: &GameProfile) -> String {
    let canonical_name = canonical_game_name_for_profile(profile);
    let steam_suffix = profile
        .steam_app_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|app_id| format!(" (Steam App ID {app_id})"))
        .unwrap_or_default();
    format!(
        "Nexus Mods catalogue could not be linked automatically for {canonical_name}{steam_suffix}."
    )
}

fn canonical_game_name_for_profile(profile: &GameProfile) -> String {
    verified_steam_game_for_profile(profile)
        .ok()
        .map(|game| game.name)
        .or_else(|| {
            profile
                .game_id
                .as_deref()
                .and_then(game_definition_by_id)
                .map(|definition| definition.display_name.clone())
        })
        .unwrap_or_else(|| profile_game_label(profile))
}

fn persisted_provider_game_mapping(
    store_root: &Path,
    provider: &str,
    profile: &GameProfile,
) -> Result<Option<ProviderGameMapping>, String> {
    let Some(steam_app_id) = profile
        .steam_app_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return Ok(None);
    };
    let store = read_store::<ProviderGameMapping>(&provider_game_mappings_path(store_root))
        .map_err(error_to_string)?;
    let mapping = store.items.into_iter().find(|mapping| {
        mapping.provider.eq_ignore_ascii_case(provider)
            && mapping.steam_app_id == steam_app_id
            && valid_provider_game_id(&mapping.provider_game_id)
    });
    if let Some(mapping) = mapping
        .as_ref()
        .filter(|mapping| mapping.provider.eq_ignore_ascii_case("nexus"))
    {
        if let Some(game_id) = mapping
            .provider_catalogue_id
            .as_deref()
            .and_then(|id| id.parse::<u64>().ok())
        {
            cache_nexus_game_id(&compact_provider_slug(&mapping.provider_game_id), game_id);
        }
    }
    Ok(mapping)
}

fn remember_provider_game_mapping(
    store_root: &Path,
    mapping: ProviderGameMapping,
) -> Result<(), String> {
    if mapping.steam_app_id.trim().is_empty()
        || !mapping
            .steam_app_id
            .chars()
            .all(|character| character.is_ascii_digit())
        || !valid_provider_game_id(&mapping.provider_game_id)
    {
        return Err("The verified provider mapping contains an invalid game identity.".to_string());
    }
    let _mapping_guard = PROVIDER_GAME_MAPPING_LOCK
        .get_or_init(|| Mutex::new(()))
        .lock()
        .map_err(|_| "The provider mapping store is unavailable.".to_string())?;
    let path = provider_game_mappings_path(store_root);
    let mut store = read_store::<ProviderGameMapping>(&path).map_err(error_to_string)?;
    store.items.retain(|existing| {
        !(existing.provider.eq_ignore_ascii_case(&mapping.provider)
            && existing.steam_app_id == mapping.steam_app_id)
    });
    store.items.push(mapping);
    if store.items.len() > PROVIDER_GAME_MAPPING_MAX_ENTRIES {
        store.items.sort_by(|first, second| {
            first
                .verified_at
                .cmp(&second.verified_at)
                .then_with(|| first.provider.cmp(&second.provider))
                .then_with(|| first.steam_app_id.cmp(&second.steam_app_id))
        });
        let remove_count = store
            .items
            .len()
            .saturating_sub(PROVIDER_GAME_MAPPING_MAX_ENTRIES);
        store.items.drain(0..remove_count);
    }
    write_store(&path, &store).map_err(error_to_string)
}

fn forget_provider_game_mapping(
    store_root: &Path,
    provider: &str,
    profile: &GameProfile,
) -> Result<(), String> {
    let Some(steam_app_id) = profile
        .steam_app_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return Ok(());
    };
    let _mapping_guard = PROVIDER_GAME_MAPPING_LOCK
        .get_or_init(|| Mutex::new(()))
        .lock()
        .map_err(|_| "The provider mapping store is unavailable.".to_string())?;
    let path = provider_game_mappings_path(store_root);
    let mut store = read_store::<ProviderGameMapping>(&path).map_err(error_to_string)?;
    let previous_len = store.items.len();
    store.items.retain(|mapping| {
        !(mapping.provider.eq_ignore_ascii_case(provider) && mapping.steam_app_id == steam_app_id)
    });
    if store.items.len() != previous_len {
        write_store(&path, &store).map_err(error_to_string)?;
    }
    Ok(())
}

fn valid_provider_game_id(value: &str) -> bool {
    let value = value.trim();
    (1..=128).contains(&value.len())
        && value
            .chars()
            .all(|character| character.is_ascii_alphanumeric() || matches!(character, '-' | '_'))
}

fn evict_oldest_provider_mapping_entry(
    cache: &mut HashMap<String, ProviderMappingCacheEntry>,
    max_entries: usize,
    incoming_key: &str,
) {
    if cache.len() < max_entries || cache.contains_key(incoming_key) {
        return;
    }
    if let Some(oldest) = cache
        .iter()
        .min_by_key(|(_, entry)| entry.fetched_at)
        .map(|(key, _)| key.clone())
    {
        cache.remove(&oldest);
    }
}

fn parallel_first_map<T, F>(items: &[String], mapper: &F) -> Option<T>
where
    T: Send,
    F: Fn(&str) -> Option<T> + Sync,
{
    if items.is_empty() {
        return None;
    }
    let worker_count = items.len().min(4);
    std::thread::scope(|scope| {
        let handles = (0..worker_count)
            .map(|worker_index| {
                scope.spawn(move || {
                    items
                        .iter()
                        .enumerate()
                        .filter(|(index, _)| index % worker_count == worker_index)
                        .find_map(|(index, item)| mapper(item).map(|value| (index, value)))
                })
            })
            .collect::<Vec<_>>();

        handles
            .into_iter()
            .filter_map(|handle| handle.join().ok().flatten())
            .min_by_key(|(index, _)| *index)
            .map(|(_, value)| value)
    })
}

fn resolve_nexus_game_node(
    client: &Client,
    canonical_name: &str,
) -> Result<Option<(NexusGameNode, String)>, String> {
    if canonical_name.trim().is_empty() {
        return Ok(None);
    }
    let primary_nodes = fetch_nexus_games_by_name_result(client, canonical_name)?;
    if let Some((node, match_kind)) = select_nexus_game_match(canonical_name, &primary_nodes) {
        return Ok(Some((node, format!("catalog-{match_kind}-name"))));
    }

    let Some(editionless_name) = editionless_provider_name_variant(canonical_name) else {
        return Ok(None);
    };
    let nodes = fetch_nexus_games_by_name_result(client, &editionless_name)?;
    Ok(select_nexus_game_match(canonical_name, &nodes)
        .map(|(node, match_kind)| (node, format!("catalog-{match_kind}-edition-alias"))))
}

fn select_nexus_game_match(
    requested_name: &str,
    nodes: &[NexusGameNode],
) -> Option<(NexusGameNode, &'static str)> {
    let requested_compact = compact_provider_slug(requested_name);
    let exact = unique_nexus_game_match(nodes.iter().filter(|node| {
        compact_provider_slug(&node.name) == requested_compact
            || compact_provider_slug(&node.domain_name) == requested_compact
    }));
    if let Some(node) = exact {
        return Some((node, "exact"));
    }

    let requested_editionless = editionless_provider_title(requested_name);
    if requested_editionless.is_empty() || requested_editionless == requested_compact {
        return None;
    }
    unique_nexus_game_match(
        nodes
            .iter()
            .filter(|node| editionless_provider_title(&node.name) == requested_editionless),
    )
    .map(|node| (node, "edition"))
}

fn unique_nexus_game_match<'a>(
    nodes: impl Iterator<Item = &'a NexusGameNode>,
) -> Option<NexusGameNode> {
    let mut matches = Vec::new();
    let mut seen_domains = HashSet::new();
    for node in nodes {
        if !valid_provider_game_id(&node.domain_name) {
            continue;
        }
        let key = compact_provider_slug(&node.domain_name);
        if seen_domains.insert(key) {
            matches.push(node.clone());
        }
    }
    (matches.len() == 1).then(|| matches.remove(0))
}

fn editionless_provider_title(value: &str) -> String {
    let readable = readable_provider_text(value);
    let mut words = readable
        .split_whitespace()
        .map(|word| word.to_ascii_lowercase())
        .collect::<Vec<_>>();
    const SUFFIXES: &[&[&str]] = &[
        &["game", "of", "the", "year", "edition"],
        &["definitive", "edition"],
        &["complete", "edition"],
        &["ultimate", "edition"],
        &["deluxe", "edition"],
        &["enhanced", "edition"],
        &["remastered", "edition"],
        &["goty", "edition"],
        &["definitive"],
        &["complete"],
        &["ultimate"],
        &["deluxe"],
        &["enhanced"],
        &["remastered"],
        &["goty"],
    ];
    if let Some(suffix) = SUFFIXES
        .iter()
        .find(|suffix| provider_words_end_with(&words, suffix))
    {
        words.truncate(words.len().saturating_sub(suffix.len()));
    }
    compact_provider_slug(&words.join(" "))
}

fn provider_words_end_with(words: &[String], suffix: &[&str]) -> bool {
    words.len() >= suffix.len()
        && words[words.len() - suffix.len()..]
            .iter()
            .map(String::as_str)
            .eq(suffix.iter().copied())
}

fn provider_name_candidates(profile: &GameProfile) -> Vec<String> {
    let mut names = Vec::new();
    let mut seen = HashSet::new();

    for text in provider_candidate_texts(profile) {
        push_unique_string(&mut names, &mut seen, text.clone());
        let readable = readable_provider_text(&text);
        push_unique_string(&mut names, &mut seen, readable);
    }

    for slug in provider_slug_candidates(profile) {
        for alias in provider_name_aliases(&slug) {
            push_unique_string(&mut names, &mut seen, alias);
        }
    }

    names.truncate(MAX_PROVIDER_CANDIDATES);
    names
}

fn provider_slug_candidates(profile: &GameProfile) -> Vec<String> {
    let mut candidates = Vec::new();
    let mut seen = HashSet::new();

    for text in provider_candidate_texts(profile) {
        let readable = readable_provider_text(&text);
        for source in [text.as_str(), readable.as_str()] {
            let compact = compact_provider_slug(source);
            let hyphenated = hyphenated_provider_slug(source);
            push_provider_slug(&mut candidates, &mut seen, compact.clone());
            push_provider_slug(&mut candidates, &mut seen, hyphenated);

            for alias in provider_slug_aliases(&compact) {
                push_provider_slug(&mut candidates, &mut seen, alias);
            }
        }
    }

    candidates.truncate(MAX_PROVIDER_CANDIDATES);
    candidates
}

fn provider_candidate_texts(profile: &GameProfile) -> Vec<String> {
    let canonical_steam_name = verified_steam_game_for_profile(profile)
        .ok()
        .map(|game| game.name);
    provider_candidate_texts_with_canonical_name(profile, canonical_steam_name.as_deref())
}

fn provider_candidate_texts_with_canonical_name(
    profile: &GameProfile,
    canonical_steam_name: Option<&str>,
) -> Vec<String> {
    let mut texts = Vec::new();
    let mut seen = HashSet::new();

    if let Some(canonical_name) = canonical_steam_name {
        push_unique_string(&mut texts, &mut seen, canonical_name.to_string());
        if let Some(editionless) = editionless_provider_name_variant(canonical_name) {
            push_unique_string(&mut texts, &mut seen, editionless);
        }
    }

    if let Some(folder_name) = Path::new(&profile.game_path)
        .file_name()
        .and_then(|name| name.to_str())
    {
        push_unique_string(&mut texts, &mut seen, folder_name.to_string());
    }

    let normalized_path = normalize_archive_path(&profile.game_path);
    push_unique_string(&mut texts, &mut seen, basename(&normalized_path));

    if let Some(game_id) = &profile.game_id {
        push_unique_string(&mut texts, &mut seen, game_id.clone());
        if let Some(definition) = game_definition_by_id(game_id) {
            push_unique_string(&mut texts, &mut seen, definition.display_name.clone());
        }
    }

    texts
}

fn editionless_provider_name_variant(value: &str) -> Option<String> {
    let readable = readable_provider_text(value);
    let mut words = readable
        .split_whitespace()
        .map(str::to_string)
        .collect::<Vec<_>>();
    const SUFFIXES: &[&[&str]] = &[
        &["game", "of", "the", "year", "edition"],
        &["definitive", "edition"],
        &["complete", "edition"],
        &["ultimate", "edition"],
        &["deluxe", "edition"],
        &["enhanced", "edition"],
        &["remastered", "edition"],
        &["goty", "edition"],
        &["definitive"],
        &["complete"],
        &["ultimate"],
        &["deluxe"],
        &["enhanced"],
        &["remastered"],
        &["goty"],
    ];
    let lower_words = words
        .iter()
        .map(|word| word.to_ascii_lowercase())
        .collect::<Vec<_>>();
    let suffix = SUFFIXES
        .iter()
        .find(|suffix| provider_words_end_with(&lower_words, suffix))?;
    words.truncate(words.len().saturating_sub(suffix.len()));
    (!words.is_empty()).then(|| words.join(" "))
}

fn infer_profile_foundation_runtime(
    root: &Path,
    profile: &GameProfile,
    force_refresh: bool,
) -> RuntimeInferenceOutcome {
    // Enshrouded has multiple independent loader families. Provision the selected
    // package's actual dependencies instead of installing a catalogue majority.
    if profile.game_id.as_deref() == Some("enshrouded") {
        return RuntimeInferenceOutcome::default();
    }
    if !profile_bootstrap_dependencies(profile).is_empty() {
        return RuntimeInferenceOutcome::default();
    }
    if !profile_supports_any_inferred_runtime(profile) {
        return RuntimeInferenceOutcome::default();
    }

    let mut warnings = Vec::new();

    if force_refresh {
        clear_cached_provider_mapping("thunderstore", profile);
        clear_cached_provider_mapping("nexus", profile);
        clear_cached_provider_mapping("gamebanana", profile);
        clear_cached_provider_mapping("modio", profile);
    }

    let thunderstore_community =
        thunderstore_community_for_profile_with_refresh(profile, force_refresh);
    let nexus_domain = nexus_domain_for_profile_with_refresh(profile, force_refresh);
    let modio_api_key = match read_app_settings(root) {
        Ok(settings) => settings.modio_api_key().map(str::to_string),
        Err(error) => {
            warnings.push(format!(
                "Provider settings were unavailable during automatic runtime detection: {error}"
            ));
            None
        }
    };
    let mut supplemental_mappings = resolve_supplemental_provider_mappings(
        root,
        profile,
        modio_api_key.as_deref(),
        force_refresh,
    );
    warnings.append(&mut supplemental_mappings.warnings);
    if thunderstore_community.is_none()
        && nexus_domain.is_none()
        && supplemental_mappings.gamebanana.is_none()
        && supplemental_mappings.modio.is_none()
    {
        return RuntimeInferenceOutcome {
            inference: None,
            warnings,
        };
    }
    if force_refresh {
        if let Some(community) = thunderstore_community.as_deref() {
            clear_thunderstore_community_cache(community);
        }
    }

    let cache_key = format!(
        "{}|{}|{}|{}|{}|{}|{}|{}",
        profile.steam_app_id.as_deref().unwrap_or_default(),
        profile.game_id.as_deref().unwrap_or_default(),
        profile.engine.to_lowercase(),
        profile.loader.to_lowercase(),
        thunderstore_community.as_deref().unwrap_or_default(),
        nexus_domain.as_deref().unwrap_or_default(),
        supplemental_mappings
            .gamebanana
            .as_ref()
            .map(|mapping| mapping.provider_game_id.as_str())
            .unwrap_or_default(),
        supplemental_mappings
            .modio
            .as_ref()
            .map(|mapping| mapping.provider_game_id.as_str())
            .unwrap_or_default()
    );
    let cache = PROFILE_RUNTIME_INFERENCE_CACHE.get_or_init(|| Mutex::new(HashMap::new()));
    if let Ok(cache) = cache.lock() {
        if let Some(value) =
            cached_profile_runtime_inference_value(&cache, &cache_key, force_refresh)
        {
            return RuntimeInferenceOutcome {
                inference: value,
                warnings,
            };
        }
    }

    let mut supporters = HashMap::<String, HashSet<String>>::new();
    let mut providers = HashMap::<String, HashSet<String>>::new();
    let mut sampled_mods = 0usize;

    if let Some(community) = thunderstore_community.as_deref() {
        match fetch_thunderstore_community_packages(community) {
            Ok(packages) => {
                sampled_mods = sampled_mods.saturating_add(collect_thunderstore_runtime_votes(
                    profile,
                    community,
                    &packages,
                    &mut supporters,
                    &mut providers,
                ));
            }
            Err(error) => warnings.push(format!(
                "Thunderstore runtime metadata was unavailable: {error}"
            )),
        }
    }

    if let Some(domain) = nexus_domain.as_deref() {
        match provider_client().and_then(|client| {
            fetch_nexus_mod_page(&client, domain, 0, PROFILE_RUNTIME_SAMPLE_SIZE)
        }) {
            Ok(page) => {
                sampled_mods = sampled_mods.saturating_add(collect_nexus_runtime_votes(
                    profile,
                    domain,
                    &page.nodes,
                    &mut supporters,
                    &mut providers,
                ));
            }
            Err(error) => warnings.push(format!(
                "Nexus Mods runtime metadata was unavailable: {error}"
            )),
        }
    }

    if let Some(mapping) = supplemental_mappings.gamebanana.as_ref() {
        match gamebanana::available_mod_documents(profile, mapping, PROFILE_RUNTIME_SAMPLE_SIZE) {
            Ok(documents) => {
                sampled_mods = sampled_mods.saturating_add(collect_document_runtime_votes(
                    profile,
                    &documents,
                    &mut supporters,
                    &mut providers,
                ));
            }
            Err(error) => warnings.push(format!(
                "GameBanana runtime metadata was unavailable: {error}"
            )),
        }
    }

    if let (Some(api_key), Some(mapping)) = (
        modio_api_key.as_deref(),
        supplemental_mappings.modio.as_ref(),
    ) {
        match modio::available_mod_documents(profile, api_key, mapping, PROFILE_RUNTIME_SAMPLE_SIZE)
        {
            Ok(documents) => {
                sampled_mods = sampled_mods.saturating_add(collect_document_runtime_votes(
                    profile,
                    &documents,
                    &mut supporters,
                    &mut providers,
                ));
            }
            Err(error) => {
                warnings.push(format!("mod.io runtime metadata was unavailable: {error}"))
            }
        }
    }

    retain_supported_runtime_inference_votes(profile, &mut supporters, &mut providers);
    let value = choose_runtime_inference(supporters, providers, sampled_mods);
    if let Ok(mut cache) = cache.lock() {
        let now = Instant::now();
        cache.retain(|_, entry| {
            now.duration_since(entry.fetched_at) < runtime_inference_cache_ttl(&entry.value)
        });
        if cache.len() >= PROFILE_RUNTIME_CACHE_MAX_ENTRIES && !cache.contains_key(&cache_key) {
            if let Some(oldest) = cache
                .iter()
                .min_by_key(|(_, entry)| entry.fetched_at)
                .map(|(key, _)| key.clone())
            {
                cache.remove(&oldest);
            }
        }
        cache.insert(
            cache_key,
            RuntimeInferenceCacheEntry {
                fetched_at: now,
                value: value.clone(),
            },
        );
    }
    RuntimeInferenceOutcome {
        inference: value,
        warnings,
    }
}

fn runtime_inference_cache_ttl(value: &Option<ProviderRuntimeInference>) -> Duration {
    if value.is_some() {
        Duration::from_secs(PROVIDER_MAPPING_CACHE_HOURS * 60 * 60)
    } else {
        Duration::from_secs(PROVIDER_MAPPING_NEGATIVE_CACHE_MINUTES * 60)
    }
}

fn cached_profile_runtime_inference_value(
    cache: &HashMap<String, RuntimeInferenceCacheEntry>,
    cache_key: &str,
    force_refresh: bool,
) -> Option<Option<ProviderRuntimeInference>> {
    if force_refresh {
        return None;
    }
    let entry = cache.get(cache_key)?;
    (entry.fetched_at.elapsed() < runtime_inference_cache_ttl(&entry.value))
        .then(|| entry.value.clone())
}

fn retain_supported_runtime_inference_votes(
    profile: &GameProfile,
    supporters: &mut HashMap<String, HashSet<String>>,
    providers: &mut HashMap<String, HashSet<String>>,
) {
    supporters.retain(|runtime, _| profile_supports_inferred_runtime(profile, runtime.as_str()));
    providers.retain(|runtime, _| supporters.contains_key(runtime));
}

fn profile_supports_inferred_runtime(profile: &GameProfile, runtime: &str) -> bool {
    let Some(definition) = profile.game_id.as_deref().and_then(game_definition_by_id) else {
        return true;
    };
    let adapter = runtime_adapter_id(runtime);
    definition
        .supported_adapters
        .iter()
        .any(|supported| supported.eq_ignore_ascii_case(adapter))
}

fn profile_supports_any_inferred_runtime(profile: &GameProfile) -> bool {
    let Some(definition) = profile.game_id.as_deref().and_then(game_definition_by_id) else {
        return true;
    };
    runtime_definitions().iter().any(|runtime| {
        let adapter = runtime_adapter_id(&runtime.id);
        definition
            .supported_adapters
            .iter()
            .any(|supported| supported.eq_ignore_ascii_case(adapter))
    })
}

fn collect_thunderstore_runtime_votes(
    profile: &GameProfile,
    community: &str,
    packages: &[ThunderstoreCommunityPackage],
    supporters: &mut HashMap<String, HashSet<String>>,
    providers: &mut HashMap<String, HashSet<String>>,
) -> usize {
    let package_index = packages
        .iter()
        .map(|package| {
            (
                format!(
                    "{}/{}",
                    package.owner.to_lowercase(),
                    package.name.to_lowercase()
                ),
                package,
            )
        })
        .collect::<HashMap<_, _>>();
    let dependency_package_keys = packages
        .iter()
        .filter_map(latest_active_thunderstore_version)
        .flat_map(|version| version.dependencies.iter())
        .filter_map(|dependency| parse_thunderstore_token(dependency, None))
        .map(|package_ref| {
            format!(
                "{}/{}",
                package_ref.namespace.to_lowercase(),
                package_ref.name.to_lowercase()
            )
        })
        .collect::<HashSet<_>>();
    let mut sampled = packages
        .iter()
        .filter(|package| {
            is_discoverable_thunderstore_package(package)
                && !dependency_package_keys.contains(&format!(
                    "{}/{}",
                    package.owner.to_lowercase(),
                    package.name.to_lowercase()
                ))
        })
        .collect::<Vec<_>>();
    sampled.sort_by_key(|package| {
        std::cmp::Reverse(
            latest_active_thunderstore_version(package)
                .map(|version| version.downloads)
                .unwrap_or_default(),
        )
    });
    sampled.truncate(PROFILE_RUNTIME_SAMPLE_SIZE);

    for package in &sampled {
        let root_key = format!(
            "thunderstore:{community}:{}/{}",
            package.owner.to_lowercase(),
            package.name.to_lowercase()
        );
        let Some(version) = latest_active_thunderstore_version(package) else {
            continue;
        };
        let mut queue = version
            .dependencies
            .iter()
            .cloned()
            .map(|dependency| (dependency, 1usize))
            .collect::<VecDeque<_>>();
        let mut visited = HashSet::new();
        let mut root_runtimes = HashSet::new();

        while let Some((dependency, depth)) = queue.pop_front() {
            if depth > PROFILE_RUNTIME_MAX_DEPENDENCY_DEPTH {
                continue;
            }
            let Some(package_ref) = parse_thunderstore_token(&dependency, None) else {
                continue;
            };
            let dependency_key = format!(
                "{}/{}",
                package_ref.namespace.to_lowercase(),
                package_ref.name.to_lowercase()
            );
            if !visited.insert(dependency_key.clone()) {
                continue;
            }

            if let Some(runtime_id) = runtime_id_for_provider_package(
                profile,
                "thunderstore",
                Some(&package_ref.namespace),
                &package_ref.name,
            ) {
                root_runtimes.insert(runtime_id);
            }

            if let Some(dependency_package) = package_index.get(&dependency_key) {
                if let Some(dependency_version) =
                    latest_active_thunderstore_version(dependency_package)
                {
                    queue.extend(
                        dependency_version
                            .dependencies
                            .iter()
                            .cloned()
                            .map(|nested| (nested, depth + 1)),
                    );
                }
            }
        }

        for runtime_id in root_runtimes {
            supporters
                .entry(runtime_id.clone())
                .or_default()
                .insert(root_key.clone());
            providers
                .entry(runtime_id)
                .or_default()
                .insert("Thunderstore".to_string());
        }
    }

    sampled.len()
}

fn collect_nexus_runtime_votes(
    profile: &GameProfile,
    domain: &str,
    nodes: &[NexusModNode],
    supporters: &mut HashMap<String, HashSet<String>>,
    providers: &mut HashMap<String, HashSet<String>>,
) -> usize {
    for node in nodes {
        let Some(mod_id) = node.mod_id else {
            continue;
        };
        let root_key = format!("nexus:{domain}/{mod_id}");
        let mut root_runtimes = HashSet::new();
        for requirement in node
            .mod_requirements
            .as_ref()
            .map(|requirements| requirements.nexus_requirements.nodes.as_slice())
            .unwrap_or_default()
        {
            if let Some(runtime_id) = runtime_id_for_nexus_requirement(profile, requirement) {
                root_runtimes.insert(runtime_id);
            }
        }
        for runtime_id in root_runtimes {
            supporters
                .entry(runtime_id.clone())
                .or_default()
                .insert(root_key.clone());
            providers
                .entry(runtime_id)
                .or_default()
                .insert("Nexus Mods".to_string());
        }
    }
    nodes.len()
}

fn collect_document_runtime_votes(
    profile: &GameProfile,
    documents: &[ProviderRouteDocument],
    supporters: &mut HashMap<String, HashSet<String>>,
    providers: &mut HashMap<String, HashSet<String>>,
) -> usize {
    let mut sampled_mods = 0usize;
    for document in documents {
        let provider_id = match document.provider.to_ascii_lowercase().as_str() {
            "gamebanana" => "gamebanana",
            "mod.io" | "modio" => "modio",
            _ => continue,
        };
        // Runtime packages are deliberately excluded by each catalogue sampler.
        // Keep this defense here as well so a future provider parser cannot turn
        // the runtime itself into a normal discoverable-mod vote.
        if is_known_runtime_provider_package(provider_id, None, &document.mod_name) {
            continue;
        }
        sampled_mods = sampled_mods.saturating_add(1);

        let root_key = document.mod_id.to_ascii_lowercase();
        let mut root_runtimes = HashSet::new();
        for dependency in description_runtime_dependencies(profile, &document.text, None) {
            if let Some(runtime_id) = dependency.id.strip_prefix("runtime:") {
                root_runtimes.insert(runtime_id.to_string());
            }
        }
        for runtime_id in root_runtimes {
            supporters
                .entry(runtime_id.clone())
                .or_default()
                .insert(root_key.clone());
            providers
                .entry(runtime_id)
                .or_default()
                .insert(document.provider.clone());
        }
    }
    sampled_mods
}

fn choose_runtime_inference(
    supporters: HashMap<String, HashSet<String>>,
    providers: HashMap<String, HashSet<String>>,
    sampled_mods: usize,
) -> Option<ProviderRuntimeInference> {
    let mut ranked = supporters
        .into_iter()
        .map(|(runtime_id, mods)| (runtime_id, mods.len()))
        .collect::<Vec<_>>();
    ranked.sort_by(|first, second| second.1.cmp(&first.1).then_with(|| first.0.cmp(&second.0)));
    let (runtime_id, supporting_mods) = ranked.first()?.clone();
    if supporting_mods < PROFILE_RUNTIME_MIN_SUPPORT
        || ranked
            .get(1)
            .is_some_and(|second| second.1 >= supporting_mods)
    {
        return None;
    }

    let mut provider_names = providers
        .get(&runtime_id)
        .cloned()
        .unwrap_or_default()
        .into_iter()
        .collect::<Vec<_>>();
    provider_names.sort();
    Some(ProviderRuntimeInference {
        runtime_id,
        providers: provider_names,
        supporting_mods,
        sampled_mods,
    })
}

fn ensure_profile_route_knowledge(
    root: &Path,
    profile: &GameProfile,
    force_refresh: bool,
) -> RouteKnowledgeOutcome {
    let existing = read_profile_route_knowledge(root, &profile.id)
        .ok()
        .flatten();
    let mut knowledge = if !force_refresh
        && existing
            .as_ref()
            .is_some_and(profile_route_knowledge_is_fresh)
    {
        existing.unwrap()
    } else {
        learn_profile_route_knowledge(root, profile, existing.as_ref())
    };

    let mut outcome = apply_profile_route_knowledge(profile, &mut knowledge);
    for warning in &knowledge.warnings {
        if !outcome.warnings.contains(warning) {
            outcome.warnings.push(warning.clone());
        }
    }
    if let Err(error) = write_profile_route_knowledge(root, &knowledge) {
        outcome
            .warnings
            .push(format!("Could not save learned install routes: {error}"));
        return outcome;
    }
    outcome
}

fn profile_route_knowledge_is_fresh(knowledge: &ProfileRouteKnowledge) -> bool {
    if knowledge.version != PROFILE_ROUTE_KNOWLEDGE_VERSION {
        return false;
    }
    let Ok(learned_at) = chrono::DateTime::parse_from_rfc3339(&knowledge.learned_at) else {
        return false;
    };
    let age = Utc::now().signed_duration_since(learned_at.with_timezone(&Utc));
    let maximum_age = if knowledge.sampled_mods == 0 {
        chrono::Duration::minutes(PROFILE_ROUTE_NEGATIVE_CACHE_MINUTES)
    } else {
        chrono::Duration::hours(PROFILE_ROUTE_CACHE_HOURS)
    };
    age >= chrono::Duration::zero() && age <= maximum_age
}

fn learn_profile_route_knowledge(
    root: &Path,
    profile: &GameProfile,
    previous: Option<&ProfileRouteKnowledge>,
) -> ProfileRouteKnowledge {
    let (nexus_api_key, modio_api_key, mut settings_warnings) = match read_app_settings(root) {
        Ok(settings) => (
            settings.nexus_api_key().map(str::to_string),
            settings.modio_api_key().map(str::to_string),
            Vec::new(),
        ),
        Err(error) => (
            None,
            None,
            vec![format!(
                "Provider settings were unavailable while learning install routes: {error}"
            )],
        ),
    };
    let (documents, mut warnings) = collect_profile_route_documents(
        root,
        profile,
        nexus_api_key.as_deref(),
        modio_api_key.as_deref(),
    );
    settings_warnings.append(&mut warnings);
    let mut knowledge = build_profile_route_knowledge(profile, &documents, settings_warnings);

    if let Some(previous) = previous {
        for retained in previous
            .routes
            .iter()
            .filter(|route| route.package_verified)
        {
            merge_learned_route(&mut knowledge.routes, retained.clone());
        }
    }

    knowledge.routes.sort_by(|first, second| {
        first
            .relative_path
            .to_lowercase()
            .cmp(&second.relative_path.to_lowercase())
    });
    knowledge.routes.truncate(32);
    knowledge
}

fn collect_profile_route_documents(
    root: &Path,
    profile: &GameProfile,
    nexus_api_key: Option<&str>,
    modio_api_key: Option<&str>,
) -> (Vec<ProviderRouteDocument>, Vec<String>) {
    let mut documents = Vec::new();
    let mut warnings = Vec::new();

    if let Some(community) = thunderstore_community_for_profile(profile) {
        match fetch_thunderstore_route_documents(&community) {
            Ok(mut provider_documents) => documents.append(&mut provider_documents),
            Err(error) => warnings.push(format!(
                "Thunderstore route metadata was unavailable: {error}"
            )),
        }
    }

    if let Some(domain) = nexus_domain_for_profile(profile) {
        match fetch_nexus_route_documents(&domain, nexus_api_key) {
            Ok(mut provider_documents) => documents.append(&mut provider_documents),
            Err(error) => warnings.push(format!("Nexus route metadata was unavailable: {error}")),
        }
    }

    let supplemental = resolve_supplemental_provider_mappings(root, profile, modio_api_key, false);
    warnings.extend(supplemental.warnings);

    if let Some(mapping) = supplemental.gamebanana.as_ref() {
        match gamebanana::available_mod_documents(profile, mapping, PROFILE_ROUTE_SAMPLE_SIZE) {
            Ok(mut provider_documents) => documents.append(&mut provider_documents),
            Err(error) => warnings.push(format!(
                "GameBanana route metadata was unavailable: {error}"
            )),
        }
    }

    if let (Some(api_key), Some(mapping)) = (modio_api_key, supplemental.modio.as_ref()) {
        match modio::available_mod_documents(profile, api_key, mapping, PROFILE_ROUTE_SAMPLE_SIZE) {
            Ok(mut provider_documents) => documents.append(&mut provider_documents),
            Err(error) => warnings.push(format!("mod.io route metadata was unavailable: {error}")),
        }
    }

    (documents, warnings)
}

fn resolve_supplemental_provider_mappings(
    root: &Path,
    profile: &GameProfile,
    modio_api_key: Option<&str>,
    force_refresh: bool,
) -> SupplementalProviderMappings {
    let mut resolved = SupplementalProviderMappings::default();

    let gamebanana_resolution = gamebanana::resolve_mapping(root, profile, force_refresh);
    resolved.gamebanana = gamebanana_resolution.mapping;
    if let Some(warning) = gamebanana_resolution.warning {
        resolved.warnings.push(warning);
    }

    if let Some(api_key) = modio_api_key.filter(|key| !key.trim().is_empty()) {
        let modio_resolution =
            resolve_modio_mapping_for_discovery(root, profile, api_key, force_refresh);
        resolved.modio = modio_resolution.mapping;
        if let Some(warning) = modio_resolution.warning {
            resolved.warnings.push(warning);
        }
    }

    resolved
}

fn fetch_thunderstore_route_documents(
    community: &str,
) -> Result<Vec<ProviderRouteDocument>, String> {
    let packages = fetch_thunderstore_community_packages(community)?;
    let mut sampled = packages
        .into_iter()
        .filter(is_discoverable_thunderstore_package)
        .filter_map(|package| {
            let version = latest_active_thunderstore_version(&package)?.clone();
            Some((package, version))
        })
        .collect::<Vec<_>>();
    sampled.sort_by_key(|(_, version)| std::cmp::Reverse(version.downloads));
    sampled.truncate(PROFILE_ROUTE_SAMPLE_SIZE);

    let client = thunderstore_client()?;
    let mut documents = Vec::new();
    for (batch_index, chunk) in sampled.chunks(PROFILE_ROUTE_FETCH_CONCURRENCY).enumerate() {
        let include_readme =
            batch_index * PROFILE_ROUTE_FETCH_CONCURRENCY < PROFILE_ROUTE_FULL_TEXT_SAMPLE_SIZE;
        let batch_documents = std::thread::scope(|scope| {
            let handles = chunk
                .iter()
                .cloned()
                .enumerate()
                .map(|(index, (package, version))| {
                    let client = client.clone();
                    let fetch_readme = include_readme
                        && batch_index * PROFILE_ROUTE_FETCH_CONCURRENCY + index
                            < PROFILE_ROUTE_FULL_TEXT_SAMPLE_SIZE;
                    let community = community.to_string();
                    scope.spawn(move || {
                        let package_ref = ThunderstorePackageRef {
                            namespace: package.owner.clone(),
                            name: package.name.clone(),
                            version: Some(version.version_number.clone()),
                        };
                        let readme = fetch_readme
                            .then(|| {
                                fetch_thunderstore_package_readme_with_client(
                                    &client,
                                    &package_ref,
                                    &version.version_number,
                                )
                                .ok()
                            })
                            .flatten()
                            .unwrap_or_default();
                        let text = [version.description.as_str(), readme.as_str()]
                            .into_iter()
                            .filter(|value| !value.trim().is_empty())
                            .collect::<Vec<_>>()
                            .join("\n");
                        ProviderRouteDocument {
                            provider: "Thunderstore".to_string(),
                            mod_id: format!(
                                "thunderstore:{community}:{}/{}",
                                package.owner, package.name
                            ),
                            mod_name: humanize_mod_display_name(&package.full_name),
                            text,
                        }
                    })
                })
                .collect::<Vec<_>>();
            handles
                .into_iter()
                .filter_map(|handle| handle.join().ok())
                .collect::<Vec<_>>()
        });
        documents.extend(batch_documents);
    }
    Ok(documents)
}

fn fetch_thunderstore_package_readme_with_client(
    client: &Client,
    package_ref: &ThunderstorePackageRef,
    version: &str,
) -> Result<String, String> {
    let url = format!(
        "{}readme/",
        thunderstore_package_version_url(package_ref, version)
    );
    client
        .get(url)
        .send()
        .map_err(error_to_string)?
        .error_for_status()
        .map_err(error_to_string)?
        .json::<ThunderstoreMarkdownResponse>()
        .map(|response| response.markdown)
        .map_err(error_to_string)
}

fn thunderstore_route_document(
    package_ref: &ThunderstorePackageRef,
    version: &ThunderstoreVersion,
) -> ProviderRouteDocument {
    let readme = thunderstore_client()
        .and_then(|client| {
            fetch_thunderstore_package_readme_with_client(
                &client,
                package_ref,
                &version.version_number,
            )
        })
        .unwrap_or_default();
    ProviderRouteDocument {
        provider: "Thunderstore".to_string(),
        mod_id: thunderstore_package_id(package_ref),
        mod_name: humanize_mod_display_name(&version.full_name),
        text: [version.description.as_str(), readme.as_str()]
            .into_iter()
            .filter(|value| !value.trim().is_empty())
            .collect::<Vec<_>>()
            .join("\n"),
    }
}

fn fetch_nexus_route_documents(
    domain: &str,
    api_key: Option<&str>,
) -> Result<Vec<ProviderRouteDocument>, String> {
    let client = provider_client()?;
    let page = fetch_nexus_mod_page(&client, domain, 0, PROFILE_ROUTE_SAMPLE_SIZE)?;
    let nodes = page
        .nodes
        .into_iter()
        .filter(|node| node.mod_id.is_some())
        .collect::<Vec<_>>();
    let mut details_by_id = HashMap::<u64, NexusModDetails>::new();

    if let Some(api_key) = api_key.filter(|value| !value.trim().is_empty()) {
        for chunk in nodes[..nodes.len().min(PROFILE_ROUTE_FULL_TEXT_SAMPLE_SIZE)]
            .chunks(PROFILE_ROUTE_FETCH_CONCURRENCY)
        {
            let batch_details = std::thread::scope(|scope| {
                let handles = chunk
                    .iter()
                    .filter_map(|node| node.mod_id)
                    .map(|mod_id| {
                        let client = client.clone();
                        let api_key = api_key.to_string();
                        let domain = domain.to_string();
                        scope.spawn(move || {
                            fetch_nexus_mod_details(&client, &api_key, &domain, mod_id)
                                .ok()
                                .map(|details| (mod_id, details))
                        })
                    })
                    .collect::<Vec<_>>();
                handles
                    .into_iter()
                    .filter_map(|handle| handle.join().ok().flatten())
                    .collect::<Vec<_>>()
            });
            details_by_id.extend(batch_details);
        }
    }

    Ok(nodes
        .into_iter()
        .filter_map(|node| {
            let mod_id = node.mod_id?;
            let details = details_by_id.remove(&mod_id).unwrap_or_default();
            let name = non_empty_string(details.name.trim())
                .or(node.name)
                .unwrap_or_else(|| format!("Nexus mod {mod_id}"));
            let summary = node.summary.unwrap_or_default();
            let text = [
                summary.as_str(),
                details.summary.as_str(),
                details.description.as_str(),
            ]
            .into_iter()
            .filter(|value| !value.trim().is_empty())
            .collect::<Vec<_>>()
            .join("\n");
            Some(ProviderRouteDocument {
                provider: "Nexus Mods".to_string(),
                mod_id: format!("nexus:{domain}/{mod_id}"),
                mod_name: name,
                text,
            })
        })
        .collect())
}

fn fetch_nexus_mod_details(
    client: &Client,
    api_key: &str,
    domain: &str,
    mod_id: u64,
) -> Result<NexusModDetails, String> {
    let url = format!(
        "https://api.nexusmods.com/v1/games/{}/mods/{}.json",
        sanitize_url_path_segment(domain),
        mod_id
    );
    nexus_api_get(client, &url, api_key)
        .send()
        .map_err(error_to_string)?
        .error_for_status()
        .map_err(error_to_string)?
        .json::<NexusModDetails>()
        .map_err(error_to_string)
}

fn nexus_mod_details_icon_url(details: &NexusModDetails) -> Option<String> {
    [
        details.thumbnail_large_url.as_deref(),
        details.picture_url.as_deref(),
        details.thumbnail_url.as_deref(),
    ]
    .into_iter()
    .find_map(|value| value.and_then(|value| non_empty_string(value.trim())))
}

fn nexus_mod_node_icon_url(node: &NexusModNode) -> Option<String> {
    [
        node.thumbnail_large_url.as_deref(),
        node.picture_url.as_deref(),
        node.thumbnail_url.as_deref(),
    ]
    .into_iter()
    .find_map(|value| value.and_then(|value| non_empty_string(value.trim())))
}

fn backfill_installed_mod_artwork(
    profile: &GameProfile,
    settings: Option<&AppSettings>,
    store: &mut StoreFile<InstalledModRecord>,
) -> usize {
    if !store.items.iter().any(|record| {
        record.profile_id == profile.id
            && record.last_status != "removed"
            && record.runtime_id.is_none()
            && record.icon_url.is_none()
    }) {
        return 0;
    }

    let Ok(client) = provider_client() else {
        return 0;
    };
    let nexus_api_key = settings.and_then(AppSettings::nexus_api_key);
    let nexus_domain = nexus_domain_for_profile(profile);
    let mut changed = 0;

    for record in store.items.iter_mut().filter(|record| {
        record.profile_id == profile.id
            && record.last_status != "removed"
            && record.runtime_id.is_none()
            && record.icon_url.is_none()
    }) {
        let mut recovered_package_id = None;
        let icon_url = record
            .package_id
            .as_deref()
            .and_then(|package_id| installed_provider_artwork(&client, nexus_api_key, package_id))
            .or_else(|| {
                recover_legacy_nexus_artwork(
                    &client,
                    nexus_api_key,
                    nexus_domain.as_deref(),
                    record,
                )
                .map(|(package_id, icon_url)| {
                    recovered_package_id = Some(package_id);
                    icon_url
                })
            });

        let Some(icon_url) = icon_url else {
            continue;
        };
        record.icon_url = Some(icon_url);
        if record.package_id.is_none() {
            record.package_id = recovered_package_id;
        }
        changed += 1;
    }

    changed
}

fn installed_provider_artwork(
    client: &Client,
    nexus_api_key: Option<&str>,
    package_id: &str,
) -> Option<String> {
    if package_id.starts_with("nexus:") {
        let api_key = nexus_api_key?;
        let (domain, mod_id) = parse_nexus_online_mod_id(package_id).ok()?;
        return fetch_nexus_mod_details(client, api_key, &domain, mod_id)
            .ok()
            .and_then(|details| nexus_mod_details_icon_url(&details));
    }

    let raw_id = package_id.strip_prefix("thunderstore:")?;
    let package_ref = parse_thunderstore_token(raw_id, None)?;
    fetch_thunderstore_package_version(&package_ref)
        .ok()
        .and_then(|version| version.icon)
        .and_then(|icon| non_empty_string(icon.trim()))
}

fn recover_legacy_nexus_artwork(
    client: &Client,
    nexus_api_key: Option<&str>,
    domain: Option<&str>,
    record: &InstalledModRecord,
) -> Option<(String, String)> {
    let domain = domain?;

    if let (Some(api_key), Some(mod_id)) = (
        nexus_api_key,
        nexus_mod_id_from_download_name(&record.archive_name),
    ) {
        if let Ok(details) = fetch_nexus_mod_details(client, api_key, domain, mod_id) {
            if let Some(icon_url) = nexus_mod_details_icon_url(&details) {
                return Some((format!("nexus:{domain}/{mod_id}"), icon_url));
            }
        }
    }

    let display_name = record
        .display_name
        .as_deref()
        .unwrap_or(&record.archive_name);
    let search_term = legacy_mod_artwork_search_term(display_name)?;
    let expected_key = legacy_mod_artwork_match_key(&search_term);
    if expected_key.len() < 5 {
        return None;
    }

    let matches = fetch_nexus_mods_by_name(client, domain, &search_term)
        .ok()?
        .into_iter()
        .filter(|node| {
            node.name
                .as_deref()
                .map(legacy_mod_artwork_match_key)
                .as_deref()
                == Some(expected_key.as_str())
        })
        .collect::<Vec<_>>();
    if matches.len() != 1 {
        return None;
    }

    let node = matches.into_iter().next()?;
    let mod_id = node.mod_id?;
    let icon_url = nexus_mod_node_icon_url(&node)?;
    Some((format!("nexus:{domain}/{mod_id}"), icon_url))
}

fn fetch_nexus_mods_by_name(
    client: &Client,
    domain: &str,
    name: &str,
) -> Result<Vec<NexusModNode>, String> {
    const NEXUS_NAME_QUERY: &str = r#"
        query ModGarrisonFindModArtwork(
          $filter: ModsFilter,
          $offset: Int,
          $count: Int
        ) {
          mods(filter: $filter, offset: $offset, count: $count) {
            totalCount
            nodes {
              modId
              name
              pictureUrl
              thumbnailUrl
              thumbnailLargeUrl
            }
          }
        }
    "#;
    let body = serde_json::json!({
        "query": NEXUS_NAME_QUERY,
        "variables": {
            "filter": {
                "op": "AND",
                "gameDomainName": [{ "value": domain, "op": "EQUALS" }],
                "name": [{ "value": name, "op": "WILDCARD" }],
                "adultContent": [{ "value": false, "op": "EQUALS" }],
                "status": [{ "value": "published", "op": "EQUALS" }]
            },
            "offset": 0,
            "count": 20
        }
    });
    let response = client
        .post(NEXUS_GRAPHQL_API_BASE)
        .json(&body)
        .send()
        .map_err(error_to_string)?
        .error_for_status()
        .map_err(error_to_string)?
        .json::<NexusGraphqlResponse>()
        .map_err(error_to_string)?;

    if !response.errors.is_empty() {
        return Err(response
            .errors
            .into_iter()
            .map(|error| error.message)
            .collect::<Vec<_>>()
            .join("; "));
    }
    response
        .data
        .map(|data| data.mods.nodes)
        .ok_or_else(|| "Nexus Mods returned no artwork data.".to_string())
}

fn nexus_mod_id_from_download_name(archive_name: &str) -> Option<u64> {
    let file_name = basename(&normalize_archive_path(archive_name));
    let lower = file_name.to_ascii_lowercase();
    let stem = [".zip", ".7z", ".rar"]
        .iter()
        .find_map(|extension| {
            lower
                .ends_with(extension)
                .then(|| file_name[..file_name.len().saturating_sub(extension.len())].to_string())
        })
        .unwrap_or(file_name);
    let segments = stem.split('-').collect::<Vec<_>>();

    segments.windows(3).find_map(|window| {
        let mod_id = window[0].parse::<u64>().ok()?;
        window[1].parse::<u64>().ok()?;
        let timestamp = window[2];
        (timestamp.len() >= 9
            && timestamp
                .chars()
                .all(|character| character.is_ascii_digit()))
        .then_some(mod_id)
    })
}

fn legacy_mod_artwork_search_term(value: &str) -> Option<String> {
    let humanized = humanize_mod_display_name(value);
    let mut words = humanized
        .split_whitespace()
        .map(str::to_string)
        .collect::<Vec<_>>();
    while words
        .last()
        .map(|word| is_mod_variant_suffix(word))
        .unwrap_or(false)
    {
        words.pop();
    }
    non_empty_string(words.join(" ").trim())
}

fn legacy_mod_artwork_match_key(value: &str) -> String {
    legacy_mod_artwork_search_term(value)
        .unwrap_or_default()
        .chars()
        .filter(|character| character.is_ascii_alphanumeric())
        .flat_map(|character| character.to_lowercase())
        .collect()
}

fn is_mod_variant_suffix(value: &str) -> bool {
    let lower = value.to_ascii_lowercase();
    let without_prefix = lower.strip_prefix('x').unwrap_or(&lower);
    let without_suffix = without_prefix.strip_suffix('x').unwrap_or(without_prefix);
    without_suffix
        .chars()
        .all(|character| character.is_ascii_digit())
        || lower
            .strip_suffix('h')
            .map(|number| number.chars().all(|character| character.is_ascii_digit()))
            .unwrap_or(false)
}

fn build_profile_route_knowledge(
    profile: &GameProfile,
    documents: &[ProviderRouteDocument],
    warnings: Vec<String>,
) -> ProfileRouteKnowledge {
    #[derive(Default)]
    struct RouteAggregate {
        relative_path: String,
        adapter_id: String,
        scopes: HashSet<String>,
        supporters: HashSet<String>,
        providers: HashSet<String>,
        evidence: Vec<RouteEvidence>,
    }

    let mut aggregates = HashMap::<String, RouteAggregate>::new();
    for document in documents {
        let mut document_routes = HashSet::new();
        for candidate in extract_install_route_candidates(profile, &document.text) {
            let key = install_route_key(&candidate.adapter_id, &candidate.relative_path);
            if !document_routes.insert(key.clone()) {
                continue;
            }
            let aggregate = aggregates.entry(key).or_default();
            aggregate.relative_path = candidate.relative_path;
            aggregate.adapter_id = candidate.adapter_id;
            aggregate.scopes.extend(candidate.scopes);
            aggregate.supporters.insert(document.mod_id.clone());
            aggregate.providers.insert(document.provider.clone());
            if aggregate.evidence.len() < PROFILE_ROUTE_MAX_EVIDENCE {
                aggregate.evidence.push(RouteEvidence {
                    provider: document.provider.clone(),
                    mod_id: document.mod_id.clone(),
                    mod_name: document.mod_name.clone(),
                    excerpt: candidate.excerpt,
                });
            }
        }
    }

    let mut routes = aggregates
        .into_values()
        .filter_map(|aggregate| {
            if !validate_learned_route_shape(&aggregate.adapter_id, &aggregate.relative_path) {
                return None;
            }
            let supporting_mods = aggregate.supporters.len();
            let route_exists = safe_join(Path::new(&profile.game_path), &aggregate.relative_path)
                .map(|path| path.is_dir())
                .unwrap_or(false);
            let compatible = route_adapter_compatible(profile, &aggregate.adapter_id);
            let trusted = supporting_mods >= PROFILE_ROUTE_MIN_SUPPORT
                && (compatible || route_exists || profile.engine == "unknown");
            let confidence = (0.58
                + 0.1 * supporting_mods.min(4) as f64
                + if aggregate.providers.len() > 1 {
                    0.08
                } else {
                    0.0
                }
                + if route_exists { 0.05 } else { 0.0 })
            .min(0.98);
            let mut scopes = aggregate.scopes.into_iter().collect::<Vec<_>>();
            scopes.sort();
            let mut providers = aggregate.providers.into_iter().collect::<Vec<_>>();
            providers.sort();
            Some(LearnedInstallRoute {
                relative_path: aggregate.relative_path,
                adapter_id: aggregate.adapter_id,
                scopes,
                confidence,
                supporting_mods,
                providers,
                evidence: aggregate.evidence,
                trusted,
                package_verified: false,
                created: false,
            })
        })
        .collect::<Vec<_>>();
    routes.sort_by(|first, second| {
        second
            .trusted
            .cmp(&first.trusted)
            .then_with(|| {
                second
                    .confidence
                    .partial_cmp(&first.confidence)
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
            .then_with(|| first.relative_path.cmp(&second.relative_path))
    });

    let mut providers = documents
        .iter()
        .map(|document| document.provider.clone())
        .collect::<HashSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    providers.sort();
    let sampled_mods = documents
        .iter()
        .map(|document| document.mod_id.to_lowercase())
        .collect::<HashSet<_>>()
        .len();

    ProfileRouteKnowledge {
        version: PROFILE_ROUTE_KNOWLEDGE_VERSION,
        profile_id: profile.id.clone(),
        learned_at: now_string(),
        sampled_mods,
        providers,
        routes,
        warnings,
    }
}

fn merge_learned_route(routes: &mut Vec<LearnedInstallRoute>, incoming: LearnedInstallRoute) {
    let key = install_route_key(&incoming.adapter_id, &incoming.relative_path);
    if let Some(existing) = routes
        .iter_mut()
        .find(|route| install_route_key(&route.adapter_id, &route.relative_path) == key)
    {
        for scope in incoming.scopes {
            push_unique_string_value(&mut existing.scopes, &scope);
        }
        for provider in incoming.providers {
            push_unique_string_value(&mut existing.providers, &provider);
        }
        for evidence in incoming.evidence {
            if existing.evidence.len() >= PROFILE_ROUTE_MAX_EVIDENCE {
                break;
            }
            if !existing.evidence.iter().any(|item| {
                item.mod_id.eq_ignore_ascii_case(&evidence.mod_id)
                    && item.provider.eq_ignore_ascii_case(&evidence.provider)
            }) {
                existing.evidence.push(evidence);
            }
        }
        existing.supporting_mods = existing.supporting_mods.max(incoming.supporting_mods).max(
            existing
                .evidence
                .iter()
                .map(|evidence| evidence.mod_id.to_lowercase())
                .collect::<HashSet<_>>()
                .len(),
        );
        existing.confidence = existing.confidence.max(incoming.confidence);
        existing.trusted |= incoming.trusted;
        existing.package_verified |= incoming.package_verified;
        existing.created |= incoming.created;
    } else {
        routes.push(incoming);
    }
}

fn install_route_key(adapter_id: &str, relative_path: &str) -> String {
    format!(
        "{}|{}",
        adapter_id.to_lowercase(),
        normalize_archive_path(relative_path).to_lowercase()
    )
}

fn extract_install_route_candidates(
    profile: &GameProfile,
    text: &str,
) -> Vec<InstallRouteCandidate> {
    let scan_text = provider_text_for_route_scan(text);
    let mut candidates = Vec::new();
    let mut seen = HashSet::new();

    for line in scan_text.lines() {
        let context = line.trim();
        if context.is_empty() {
            continue;
        }
        for token in provider_route_token_candidates(context) {
            let Some((relative_path, adapter_id)) =
                normalize_install_route_candidate(profile, &token)
            else {
                continue;
            };
            let key = install_route_key(&adapter_id, &relative_path);
            if !seen.insert(key) {
                continue;
            }
            candidates.push(InstallRouteCandidate {
                relative_path,
                adapter_id,
                scopes: install_route_scopes(context),
                excerpt: compact_route_excerpt(context),
            });
        }
    }

    candidates
}

fn provider_route_token_candidates(context: &str) -> Vec<String> {
    let mut segments = Vec::new();
    let mut current = String::new();
    let mut quote = None;
    let flush = |current: &mut String, segments: &mut Vec<String>| {
        let candidate = current.trim();
        if !candidate.is_empty() {
            segments.push(candidate.to_string());
        }
        current.clear();
    };

    for character in context.chars() {
        if let Some(active_quote) = quote {
            if character == active_quote {
                flush(&mut current, &mut segments);
                quote = None;
            } else {
                current.push(character);
            }
            continue;
        }
        if matches!(character, '\'' | '"' | '`') {
            flush(&mut current, &mut segments);
            quote = Some(character);
        } else if matches!(
            character,
            '=' | '(' | ')' | '[' | ']' | '{' | '}' | ',' | ';' | '|'
        ) {
            flush(&mut current, &mut segments);
        } else {
            current.push(character);
        }
    }
    flush(&mut current, &mut segments);

    let mut candidates = Vec::new();
    let mut seen = HashSet::new();
    for segment in segments {
        let words = segment.split_whitespace().take(64).collect::<Vec<_>>();
        if words.is_empty() {
            continue;
        }
        for start in 0..words.len() {
            for end in start + 1..=words.len().min(start + 12) {
                let candidate = words[start..end].join(" ");
                if !(candidate.contains('/') || candidate.contains('\\') || candidate.contains('<'))
                {
                    continue;
                }
                let key = candidate.to_ascii_lowercase();
                if seen.insert(key) {
                    candidates.push(candidate);
                    if candidates.len() >= 256 {
                        return candidates;
                    }
                }
            }
        }
    }
    candidates
}

fn provider_install_target_options(
    store_root: &Path,
    profile: &GameProfile,
    document: &ProviderRouteDocument,
) -> Vec<InstallTargetOption> {
    let learned = read_profile_route_knowledge(store_root, &profile.id)
        .ok()
        .flatten();
    let mut options = Vec::new();
    let mut seen = HashSet::new();

    for candidate in extract_install_route_candidates(profile, &document.text) {
        if !validate_learned_route_shape(&candidate.adapter_id, &candidate.relative_path)
            || !route_has_safe_internal_root(
                profile,
                &candidate.relative_path,
                &candidate.adapter_id,
            )
            || !(route_adapter_compatible(profile, &candidate.adapter_id)
                || profile.engine == "unknown")
        {
            continue;
        }

        let key = install_route_key(&candidate.adapter_id, &candidate.relative_path);
        if !seen.insert(key.clone()) {
            continue;
        }
        let route_exists = safe_join(Path::new(&profile.game_path), &candidate.relative_path)
            .map(|path| path.is_dir())
            .unwrap_or(false);
        let route_is_learned = learned.as_ref().is_some_and(|knowledge| {
            knowledge.routes.iter().any(|route| {
                install_route_key(&route.adapter_id, &route.relative_path) == key
                    && (route.trusted || route.package_verified || route.created)
            })
        });
        if !route_exists && !route_is_learned {
            continue;
        }

        let scope = preferred_install_target_scope(&candidate.scopes);
        let label = format!(
            "{} ({})",
            install_target_scope_label(&scope),
            candidate.relative_path.replace('/', "\\")
        );
        options.push(InstallTargetOption {
            id: key,
            label,
            relative_path: candidate.relative_path,
            recommended: matches!(scope.as_str(), "client" | "general"),
            scope,
        });
    }

    options.sort_by(|first, second| {
        second
            .recommended
            .cmp(&first.recommended)
            .then_with(|| first.label.to_lowercase().cmp(&second.label.to_lowercase()))
    });
    if !options.is_empty() && !options.iter().any(|option| option.recommended) {
        options[0].recommended = true;
    }
    options
}

fn preferred_install_target_scope(scopes: &[String]) -> String {
    for preferred in ["client", "hosted-server", "dedicated-server", "general"] {
        if scopes.iter().any(|scope| scope == preferred) {
            return preferred.to_string();
        }
    }
    "general".to_string()
}

fn install_target_scope_label(scope: &str) -> &'static str {
    match scope {
        "client" => "Game Mods",
        "hosted-server" => "Local Server Mods",
        "dedicated-server" => "Dedicated Server Mods",
        _ => "Game Mods",
    }
}

fn provider_plan_install_target_options(
    store_root: &Path,
    profile: &GameProfile,
    document: &ProviderRouteDocument,
    plan: &InstallPlan,
) -> Vec<InstallTargetOption> {
    let mut derived = plan_install_target_options(profile, plan);
    let described = provider_install_target_options(store_root, profile, document);
    if derived.len() >= 2 {
        for option in &mut derived {
            if let Some(description_option) = described.iter().find(|described| {
                install_target_routes_overlap(&option.relative_path, &described.relative_path)
            }) {
                // Destination paths are the execution authority for client/server
                // partitioning. Provider prose may improve presentation, but must
                // never rewrite the canonical scope used to filter files.
                let equivalent_scope = option.scope == description_option.scope
                    || (matches!(option.scope.as_str(), "client" | "general")
                        && matches!(description_option.scope.as_str(), "client" | "general"));
                if equivalent_scope {
                    option.recommended = description_option.recommended;
                    option.label = description_option.label.clone();
                }
            }
        }
        sort_install_target_options(&mut derived);
        return derived;
    }

    let verified_routes = verified_install_target_routes(profile, &plan.adapter_id);
    let mut described = described
        .into_iter()
        .filter(|target| target.id == install_route_key(&plan.adapter_id, &target.relative_path))
        .flat_map(|target| {
            // Provider instructions often name a payload directory such as
            // BepInEx/plugins. The executable's verified loader root remains
            // authoritative, including when there is only one destination.
            verified_routes
                .iter()
                .filter(move |route| install_target_routes_overlap(route, &target.relative_path))
                .map(move |route| {
                    let scope = install_target_scope_from_path(route);
                    InstallTargetOption {
                        id: install_route_key(&plan.adapter_id, route),
                        label: format!(
                            "{} ({})",
                            install_target_scope_label(&scope),
                            route.replace('/', "\\")
                        ),
                        relative_path: route.clone(),
                        recommended: matches!(scope.as_str(), "client" | "general"),
                        scope,
                    }
                })
        })
        .filter(|target| install_target_has_mappings(plan, target))
        .collect::<Vec<_>>();
    described.sort_by(|first, second| first.id.cmp(&second.id));
    described.dedup_by(|first, second| first.id == second.id);
    if described.len() > 1 && !install_target_options_are_exclusive(plan, &described) {
        return Vec::new();
    }
    sort_install_target_options(&mut described);
    described
}

fn provider_selected_install_target_id(
    store_root: &Path,
    profile: &GameProfile,
    document: &ProviderRouteDocument,
    options: &[InstallTargetOption],
    selected_target_id: Option<&str>,
) -> Option<String> {
    let described = provider_install_target_options(store_root, profile, document);
    if let Some(selected_target_id) = selected_target_id.filter(|value| !value.trim().is_empty()) {
        if let Some(option) = options
            .iter()
            .find(|option| option.id == selected_target_id)
        {
            return Some(option.id.clone());
        }
        let described = described
            .iter()
            .find(|option| option.id == selected_target_id);
        if let Some(described) = described {
            let overlapping = options
                .iter()
                .filter(|option| {
                    install_target_routes_overlap(&option.relative_path, &described.relative_path)
                })
                .collect::<Vec<_>>();
            if overlapping.len() == 1 {
                return Some(overlapping[0].id.clone());
            }
            if let Some(option) = overlapping.into_iter().find(|option| {
                option.scope == described.scope
                    || (matches!(option.scope.as_str(), "client" | "general")
                        && matches!(described.scope.as_str(), "client" | "general"))
            }) {
                return Some(option.id.clone());
            }
        }
        // Preserve the invalid identifier so the canonical selector fails closed
        // instead of silently installing to a different destination.
        return Some(selected_target_id.to_string());
    }

    // If a provider describes exactly one route and explicitly says it is
    // server-only, choose the sole overlapping canonical server destination.
    // All other multi-route packages retain the normal client-first default.
    if described.len() == 1
        && matches!(
            described[0].scope.as_str(),
            "hosted-server" | "dedicated-server"
        )
    {
        let matching = options
            .iter()
            .filter(|option| {
                matches!(option.scope.as_str(), "hosted-server" | "dedicated-server")
                    && install_target_routes_overlap(
                        &option.relative_path,
                        &described[0].relative_path,
                    )
            })
            .collect::<Vec<_>>();
        if matching.len() == 1 {
            return Some(matching[0].id.clone());
        }
    }
    None
}

fn plan_install_target_options(
    profile: &GameProfile,
    plan: &InstallPlan,
) -> Vec<InstallTargetOption> {
    let mut routes = verified_install_target_routes(profile, &plan.adapter_id);
    let verified_route_ids = routes
        .iter()
        .map(|route| install_route_key(&plan.adapter_id, route))
        .collect::<HashSet<_>>();
    for mapping in plan
        .mappings
        .iter()
        .filter(|mapping| mapping.target_root.eq_ignore_ascii_case("game"))
    {
        let derived = match plan.adapter_id.as_str() {
            "unreal-pak" => Some(install_route_parent(&mapping.target_relative_path)),
            "ue4ss" => {
                install_route_prefix_through(&mapping.target_relative_path, &["binaries", "win64"])
            }
            "bepinex" => install_route_prefix_through(&mapping.target_relative_path, &["bepinex"]),
            "reframework" => {
                install_route_prefix_through(&mapping.target_relative_path, &["reframework"])
            }
            _ => None,
        };
        if let Some(derived) = derived.filter(|route| !route.is_empty()) {
            if !verified_route_ids.contains(&install_route_key(&plan.adapter_id, &derived)) {
                continue;
            }
            push_unique_route(&mut routes, &derived);
        }
    }
    let mut seen = HashSet::new();
    let mut options = routes
        .into_iter()
        .filter_map(|relative_path| {
            let relative_path = normalize_archive_path(&relative_path);
            let id = install_route_key(&plan.adapter_id, &relative_path);
            if !seen.insert(id.clone()) {
                return None;
            }
            let scope = install_target_scope_from_path(&relative_path);
            let option = InstallTargetOption {
                id,
                label: format!(
                    "{} ({})",
                    install_target_scope_label(&scope),
                    relative_path.replace('/', "\\")
                ),
                relative_path,
                recommended: matches!(scope.as_str(), "client" | "general"),
                scope,
            };
            install_target_has_mappings(plan, &option).then_some(option)
        })
        .collect::<Vec<_>>();
    if plan_has_mixed_unreal_payload(plan) {
        let mut seen_scopes = HashSet::new();
        options.retain(|option| seen_scopes.insert(option.scope.clone()));
    }
    if options.len() < 2 || !install_target_options_are_exclusive(plan, &options) {
        return Vec::new();
    }
    sort_install_target_options(&mut options);
    options
}

fn verified_install_target_routes(profile: &GameProfile, adapter_id: &str) -> Vec<String> {
    if !(route_adapter_compatible(profile, adapter_id) || profile.engine == "unknown") {
        return Vec::new();
    }
    let mut routes = match adapter_id {
        "unreal-pak" => unreal_pak_target_dirs(profile),
        "ue4ss" => ue4ss_install_targets(profile).0,
        "script-files" => native_script_target_dirs(profile),
        "bepinex" => bepinex_target_roots(profile),
        "reframework" => reframework_target_roots(profile),
        _ => Vec::new(),
    };
    routes = routes
        .into_iter()
        .map(|route| normalize_archive_path(&route))
        .filter(|route| !route.is_empty())
        .filter(|route| {
            let Ok(target_path) = safe_join(Path::new(&profile.game_path), route) else {
                return false;
            };
            if validate_deployment_containment(Path::new(&profile.game_path), &target_path).is_err()
            {
                return false;
            }
            target_path.is_dir()
                || (adapter_id == "unreal-pak"
                    && basename(route).eq_ignore_ascii_case("~mods")
                    && target_path.parent().is_some_and(Path::is_dir))
                || (adapter_id == "script-files"
                    && basename(route).eq_ignore_ascii_case("mods")
                    && target_path.parent().is_some_and(Path::is_dir))
                || (matches!(adapter_id, "bepinex" | "reframework")
                    && target_path.parent().is_some_and(Path::is_dir))
        })
        .collect();
    routes.sort_by_key(|route| route.to_ascii_lowercase());
    routes.dedup_by(|first, second| first.eq_ignore_ascii_case(second));
    routes
}

fn canonicalize_supplied_install_targets(
    profile: &GameProfile,
    plan: &InstallPlan,
    supplied: &[InstallTargetOption],
) -> Result<Vec<InstallTargetOption>, String> {
    let verified_routes = verified_install_target_routes(profile, &plan.adapter_id);
    let mut canonical = Vec::new();
    let mut seen = HashSet::new();

    for supplied_target in supplied {
        let route = verified_routes
            .iter()
            .find(|route| route.eq_ignore_ascii_case(&supplied_target.relative_path))
            .ok_or_else(|| {
                format!(
                    "The requested install target is not a verified directory in this game build: {}.",
                    supplied_target.relative_path
                )
            })?
            .clone();
        let id = install_route_key(&plan.adapter_id, &route);
        if supplied_target.id != id {
            return Err("The requested install target failed its integrity check.".to_string());
        }
        if !seen.insert(id.clone()) {
            continue;
        }
        let scope = install_target_scope_from_path(&route);
        let target = InstallTargetOption {
            id,
            label: if supplied_target.label.trim().is_empty() {
                format!(
                    "{} ({})",
                    install_target_scope_label(&scope),
                    route.replace('/', "\\")
                )
            } else {
                supplied_target.label.clone()
            },
            relative_path: route,
            recommended: matches!(scope.as_str(), "client" | "general"),
            scope,
        };
        if !install_target_has_mappings(plan, &target) {
            return Err(format!(
                "The requested install target has no verified payload mapping: {}.",
                target.relative_path
            ));
        }
        validate_persisted_install_target(profile, plan, &target)?;
        canonical.push(target);
    }

    if canonical.len() > 1 && !install_target_options_are_exclusive(plan, &canonical) {
        return Err(
            "The requested install targets are not mutually exclusive package variants."
                .to_string(),
        );
    }
    sort_install_target_options(&mut canonical);
    Ok(canonical)
}

fn install_target_options_are_exclusive(
    plan: &InstallPlan,
    options: &[InstallTargetOption],
) -> bool {
    let mixed_unreal_payload = plan_has_mixed_unreal_payload(plan);
    let source_sets = options
        .iter()
        .map(|target| {
            plan.mappings
                .iter()
                .filter(|mapping| {
                    mapping.target_root.eq_ignore_ascii_case("game")
                        && mapping_matches_install_target(
                            &plan.adapter_id,
                            mapping,
                            target,
                            mixed_unreal_payload,
                        )
                })
                .map(|mapping| normalize_archive_path(&mapping.source_path).to_ascii_lowercase())
                .collect::<HashSet<_>>()
        })
        .collect::<Vec<_>>();
    let Some(first) = source_sets.first() else {
        return false;
    };
    if first.is_empty() || source_sets.iter().any(HashSet::is_empty) {
        return false;
    }
    if source_sets.iter().skip(1).all(|set| set == first) {
        return true;
    }

    let common_sources = source_sets
        .iter()
        .skip(1)
        .fold(first.clone(), |common, sources| {
            common.intersection(sources).cloned().collect()
        });
    let mut found_partitioned_source = false;
    for (target, sources) in options.iter().zip(&source_sets) {
        for source in sources.difference(&common_sources) {
            let Some(source_scope) = source_install_target_scope(source) else {
                return false;
            };
            if !source_scope_matches_target_scope(Some(source_scope), &target.scope) {
                return false;
            }
            found_partitioned_source = true;
        }
    }
    found_partitioned_source
}

fn install_route_prefix_through(path: &str, suffix: &[&str]) -> Option<String> {
    let parts = normalize_archive_path(path)
        .split('/')
        .filter(|part| !part.is_empty())
        .map(str::to_string)
        .collect::<Vec<_>>();
    let index = parts.windows(suffix.len()).position(|window| {
        window
            .iter()
            .zip(suffix)
            .all(|(part, expected)| part.eq_ignore_ascii_case(expected))
    })?;
    Some(parts[..index + suffix.len()].join("/"))
}

fn install_target_scope_from_path(relative_path: &str) -> String {
    let parts = normalize_archive_path(relative_path)
        .split('/')
        .filter(|part| !part.is_empty())
        .map(|part| part.to_ascii_lowercase())
        .collect::<Vec<_>>();
    if parts
        .iter()
        .any(|part| matches!(part.as_str(), "dedicatedserver" | "dedicated-server"))
    {
        "dedicated-server".to_string()
    } else if parts.iter().any(|part| {
        matches!(
            part.as_str(),
            "windowsserver"
                | "windows-server"
                | "hostedserver"
                | "hosted-server"
                | "localserver"
                | "local-server"
                | "server"
        )
    }) {
        "hosted-server".to_string()
    } else {
        "client".to_string()
    }
}

fn source_install_target_variant(path: &str) -> Option<(usize, &'static str)> {
    let normalized = normalize_archive_path(path);
    let parts = normalized
        .split('/')
        .filter(|part| !part.is_empty())
        .collect::<Vec<_>>();
    let directory_count = parts.len().saturating_sub(1);
    // Canonical server build roots are structural, not prose-like variant names.
    // They remain authoritative at any depth (for example
    // Package/R5/Builds/WindowsServer/R5/Content/Paks), while generic Client or
    // Server folders stay deliberately limited to the shallow package edge.
    if let Some((index, _)) = parts
        .iter()
        .take(directory_count)
        .enumerate()
        .find(|(_, part)| {
            matches!(
                compact_provider_slug(part).as_str(),
                "dedicatedserver" | "dedicatedserverfiles" | "dedicatedserveronly"
            )
        })
    {
        return Some((index, "dedicated-server"));
    }
    if let Some((index, _)) = parts
        .iter()
        .take(directory_count)
        .enumerate()
        .find(|(_, part)| {
            matches!(
                compact_provider_slug(part).as_str(),
                "windowsserver" | "windowsserverfiles"
            )
        })
    {
        return Some((index, "hosted-server"));
    }
    for (index, part) in parts.iter().take(directory_count).enumerate() {
        // Variant folders are expected at the package edge, optionally under one
        // or two wrapper folders. Deeper "Client" or "Server" directories may be
        // legitimate mod data, so they are deliberately not inferred.
        if index > 2 {
            break;
        }
        let compact = compact_provider_slug(part);
        let scope = match compact.as_str() {
            "client"
            | "clientfile"
            | "clientfiles"
            | "clientside"
            | "clientsidefiles"
            | "clientonly"
            | "clientversion"
            | "singleplayer"
            | "singleplayerfiles"
            | "singleplayeronly"
            | "singleplayerversion"
            | "solo"
            | "solofiles" => Some("client"),
            "server" | "serverfile" | "serverfiles" | "serverside" | "serversidefiles"
            | "serveronly" | "serverversion" | "localserver" | "localserverfiles"
            | "hostedserver" | "hostedserverfiles" | "windowsserver" => Some("hosted-server"),
            "dedicatedserver"
            | "dedicatedserverfile"
            | "dedicatedserverfiles"
            | "dedicatedserveronly"
            | "dedicatedserverversion" => Some("dedicated-server"),
            _ => None,
        };
        if let Some(scope) = scope {
            return Some((index, scope));
        }
        if matches!(
            compact.as_str(),
            "ue4ss"
                | "mods"
                | "mod"
                | "scripts"
                | "script"
                | "content"
                | "paks"
                | "binaries"
                | "plugins"
                | "plugin"
        ) {
            break;
        }
    }
    None
}

fn source_install_target_scope(path: &str) -> Option<&'static str> {
    source_install_target_variant(path).map(|(_, scope)| scope)
}

fn source_payload_path_for_install_target(file: &ArchiveEntry) -> String {
    let normalized_source = normalize_archive_path(&file.path);
    if let Some((variant_index, _)) = source_install_target_variant(&normalized_source) {
        let remaining = normalized_source
            .split('/')
            .filter(|part| !part.is_empty())
            .skip(variant_index + 1)
            .collect::<Vec<_>>()
            .join("/");
        if !remaining.is_empty() {
            return remaining;
        }
    }
    normalize_archive_path(&file.logical_path)
}

fn source_scope_matches_target_scope(source_scope: Option<&str>, target_scope: &str) -> bool {
    match source_scope {
        None => true,
        Some("client") => matches!(target_scope, "client" | "general"),
        Some("hosted-server") => target_scope == "hosted-server",
        Some("dedicated-server") => target_scope == "dedicated-server",
        Some(_) => false,
    }
}

fn source_scope_matches_target_route(source_scope: Option<&str>, target_route: &str) -> bool {
    source_scope_matches_target_scope(source_scope, &install_target_scope_from_path(target_route))
}

fn sort_install_target_options(options: &mut [InstallTargetOption]) {
    options.sort_by(|first, second| {
        second
            .recommended
            .cmp(&first.recommended)
            .then_with(|| first.label.to_lowercase().cmp(&second.label.to_lowercase()))
            .then_with(|| first.id.cmp(&second.id))
    });
    if !options.is_empty() && !options.iter().any(|option| option.recommended) {
        options[0].recommended = true;
    }
}

fn install_target_routes_overlap(first: &str, second: &str) -> bool {
    let first = normalize_archive_path(first).to_ascii_lowercase();
    let second = normalize_archive_path(second).to_ascii_lowercase();
    first == second
        || first.starts_with(&format!("{second}/"))
        || second.starts_with(&format!("{first}/"))
}

fn install_target_has_mappings(plan: &InstallPlan, target: &InstallTargetOption) -> bool {
    let mixed_unreal_payload = plan_has_mixed_unreal_payload(plan);
    plan.mappings.iter().any(|mapping| {
        mapping.target_root.eq_ignore_ascii_case("game")
            && mapping_matches_install_target(
                &plan.adapter_id,
                mapping,
                target,
                mixed_unreal_payload,
            )
    })
}

fn plan_has_mixed_unreal_payload(plan: &InstallPlan) -> bool {
    plan.adapter_id == "ue4ss"
        && plan.mappings.iter().any(|mapping| {
            matches!(
                Path::new(&mapping.target_relative_path)
                    .extension()
                    .and_then(|extension| extension.to_str())
                    .map(str::to_ascii_lowercase)
                    .as_deref(),
                Some("pak" | "ucas" | "utoc")
            )
        })
}

fn mapping_matches_install_target(
    adapter_id: &str,
    mapping: &InstallMapping,
    target: &InstallTargetOption,
    mixed_unreal_payload: bool,
) -> bool {
    let target_path = normalize_archive_path(&target.relative_path).to_lowercase();
    let target_prefix = format!("{target_path}/");
    let mapping_path = normalize_archive_path(&mapping.target_relative_path).to_lowercase();
    if mapping_path == target_path || mapping_path.starts_with(&target_prefix) {
        return true;
    }
    if mixed_unreal_payload {
        let mapping_scope = install_target_scope_from_path(&mapping_path);
        return match target.scope.as_str() {
            "dedicated-server" => mapping_scope == "dedicated-server",
            "hosted-server" => mapping_scope == "hosted-server",
            _ => matches!(mapping_scope.as_str(), "client" | "general"),
        };
    }

    if !matches!(adapter_id, "bepinex" | "reframework") {
        return false;
    }
    let target_parent = install_route_parent(&target_path);
    if target_parent.is_empty() {
        return !mapping_path.contains('/');
    }
    mapping_path
        .strip_prefix(&format!("{target_parent}/"))
        .is_some_and(|remaining| !remaining.contains('/'))
}

fn select_install_target_id(
    options: &[InstallTargetOption],
    selected_target_id: Option<&str>,
) -> Result<Option<String>, String> {
    if let Some(selected_target_id) = selected_target_id.filter(|value| !value.trim().is_empty()) {
        return options
            .iter()
            .find(|target| target.id == selected_target_id)
            .map(|target| Some(target.id.clone()))
            .ok_or_else(|| {
                "The selected install target is no longer verified for this game. Refresh Discovery and try again."
                    .to_string()
            });
    }

    Ok(options
        .iter()
        .find(|target| target.recommended)
        .or_else(|| {
            options
                .iter()
                .find(|target| matches!(target.scope.as_str(), "client" | "general"))
        })
        .or_else(|| options.first())
        .map(|target| target.id.clone()))
}

fn select_dependency_install_target_id(
    plan: &InstallPlan,
    options: &[InstallTargetOption],
    parent_target: Option<&InstallTargetOption>,
) -> Result<Option<String>, String> {
    let Some(parent_target) = parent_target else {
        return select_install_target_id(options, None);
    };
    let parent_family = install_target_route_family(&parent_target.relative_path);
    let matching = options
        .iter()
        .filter(|target| install_target_route_family(&target.relative_path) == parent_family)
        .collect::<Vec<_>>();
    match matching.as_slice() {
        [target] => Ok(Some(target.id.clone())),
        [] if options.is_empty() && plan_payload_covers_install_target(plan, parent_target) => {
            Ok(None)
        }
        [] => Err(format!(
            "The dependency has no verified install target in the same game-root family as {}.",
            parent_target.label
        )),
        _ => Err(format!(
            "The dependency has multiple ambiguous install targets in the same game-root family as {}.",
            parent_target.label
        )),
    }
}

fn apply_install_target_option(
    plan: &mut InstallPlan,
    target: &InstallTargetOption,
) -> Result<(), String> {
    let adapter_id = plan.adapter_id.clone();
    let mixed_unreal_payload = plan_has_mixed_unreal_payload(plan);
    let selected_mapping_count = plan
        .mappings
        .iter()
        .filter(|mapping| {
            mapping.target_root.eq_ignore_ascii_case("game")
                && mapping_matches_install_target(
                    &adapter_id,
                    mapping,
                    target,
                    mixed_unreal_payload,
                )
        })
        .count();
    if selected_mapping_count == 0 {
        return Err(format!(
            "The selected target '{}' does not match this package's verified install layout. No files were changed.",
            target.label
        ));
    }

    plan.mappings.retain(|mapping| {
        if !mapping.target_root.eq_ignore_ascii_case("game") {
            return true;
        }
        mapping_matches_install_target(&adapter_id, mapping, target, mixed_unreal_payload)
    });
    Ok(())
}

fn provider_text_for_route_scan(text: &str) -> String {
    let decoded = decode_provider_html_entities(text);
    let characters = decoded.chars().collect::<Vec<_>>();
    let mut output = String::with_capacity(decoded.len());
    let mut index = 0usize;

    while index < characters.len() {
        if characters[index] != '<' {
            output.push(characters[index]);
            index += 1;
            continue;
        }
        let Some(relative_end) = characters[index + 1..]
            .iter()
            .position(|character| *character == '>')
        else {
            output.push('<');
            index += 1;
            continue;
        };
        let end = index + 1 + relative_end;
        let content = characters[index + 1..end].iter().collect::<String>();
        let tag_name = content
            .trim()
            .trim_start_matches('/')
            .split_whitespace()
            .next()
            .unwrap_or_default()
            .trim_end_matches('/')
            .to_lowercase();
        if is_provider_html_tag(&tag_name) {
            if matches!(
                tag_name.as_str(),
                "br" | "p" | "div" | "li" | "tr" | "h1" | "h2" | "h3" | "h4" | "pre"
            ) {
                output.push('\n');
            } else {
                output.push(' ');
            }
        } else {
            output.push('<');
            for character in content.chars() {
                output.push(if character.is_whitespace() {
                    '_'
                } else {
                    character
                });
            }
            output.push('>');
        }
        index = end + 1;
    }
    output
}

fn decode_provider_html_entities(value: &str) -> String {
    let mut decoded = String::with_capacity(value.len());
    let mut cursor = 0usize;

    while let Some(relative_start) = value[cursor..].find('&') {
        let start = cursor + relative_start;
        decoded.push_str(&value[cursor..start]);
        let Some(relative_end) = value[start + 1..].find(';') else {
            decoded.push_str(&value[start..]);
            return decoded;
        };
        let end = start + 1 + relative_end;
        let entity = &value[start + 1..end];
        if entity.len() <= 16 {
            if let Some(character) = decode_provider_html_entity(entity) {
                decoded.push(character);
                cursor = end + 1;
                continue;
            }
        }

        decoded.push('&');
        cursor = start + 1;
    }

    decoded.push_str(&value[cursor..]);
    decoded
}

fn decode_provider_html_entity(entity: &str) -> Option<char> {
    match entity.to_ascii_lowercase().as_str() {
        "amp" => Some('&'),
        "quot" => Some('"'),
        "apos" => Some('\''),
        "lt" => Some('<'),
        "gt" => Some('>'),
        "nbsp" => Some(' '),
        numeric if numeric.starts_with("#x") => u32::from_str_radix(&numeric[2..], 16)
            .ok()
            .and_then(char::from_u32),
        numeric if numeric.starts_with('#') => {
            numeric[1..].parse::<u32>().ok().and_then(char::from_u32)
        }
        _ => None,
    }
}

fn is_provider_html_tag(tag_name: &str) -> bool {
    matches!(
        tag_name,
        "a" | "b"
            | "blockquote"
            | "br"
            | "code"
            | "div"
            | "em"
            | "h1"
            | "h2"
            | "h3"
            | "h4"
            | "h5"
            | "h6"
            | "i"
            | "img"
            | "li"
            | "ol"
            | "p"
            | "pre"
            | "span"
            | "strong"
            | "table"
            | "tbody"
            | "td"
            | "th"
            | "thead"
            | "tr"
            | "ul"
    )
}

fn normalize_install_route_candidate(
    profile: &GameProfile,
    raw_token: &str,
) -> Option<(String, String)> {
    let mut token = raw_token.trim_matches(|character: char| {
        !(character.is_ascii_alphanumeric()
            || matches!(
                character,
                '/' | '\\' | '.' | '_' | '-' | '~' | '<' | '>' | ':'
            ))
    });
    if token.is_empty()
        || token.to_lowercase().contains("://")
        || token.to_lowercase().starts_with("www.")
    {
        return None;
    }
    if let Some(colon_index) = token.rfind(':') {
        if colon_index == 1
            && token
                .chars()
                .next()
                .is_some_and(|character| character.is_ascii_alphabetic())
        {
            return None;
        }
        token = &token[colon_index + 1..];
    }

    let mut normalized = token.replace('\\', "/");
    while normalized.contains("//") {
        normalized = normalized.replace("//", "/");
    }
    normalized = normalized
        .trim_matches(|character: char| {
            !(character.is_ascii_alphanumeric()
                || matches!(character, '/' | '.' | '_' | '-' | '~' | '<' | '>'))
        })
        .trim_start_matches("./")
        .trim_start_matches('/')
        .trim_end_matches('.')
        .to_string();

    if normalized.starts_with('<') {
        let placeholder_end = normalized.find('>')?;
        let placeholder = &normalized[1..placeholder_end];
        if !profile_route_placeholder_matches(profile, placeholder) {
            return None;
        }
        normalized = normalized[placeholder_end + 1..]
            .trim_start_matches('/')
            .to_string();
    }

    let aliases = profile_route_root_aliases(profile);
    let mut parts = normalized
        .split('/')
        .filter(|part| !part.trim().is_empty())
        .map(|part| part.trim().to_string())
        .collect::<Vec<_>>();

    while parts
        .first()
        .is_some_and(|part| part.chars().all(|character| character == '.'))
    {
        parts.remove(0);
    }
    if let Some(alias_index) = parts
        .iter()
        .position(|part| aliases.contains(&compact_provider_slug(part)))
    {
        parts.drain(..=alias_index);
    }
    if parts.is_empty() || parts.len() > 12 {
        return None;
    }
    if parts.iter().any(|part| !safe_install_route_component(part)) {
        return None;
    }

    let (relative_path, adapter_id) = canonical_install_route(&parts)?;
    if relative_path.len() > 260
        || !validate_learned_route_shape(&adapter_id, &relative_path)
        || !route_has_safe_internal_root(profile, &relative_path, &adapter_id)
    {
        return None;
    }
    safe_join(Path::new(&profile.game_path), &relative_path).ok()?;
    Some((relative_path, adapter_id))
}

fn profile_route_placeholder_matches(profile: &GameProfile, placeholder: &str) -> bool {
    let compact = compact_provider_slug(placeholder);
    if matches!(
        compact.as_str(),
        "game" | "gamefolder" | "gamedirectory" | "gameroot" | "installfolder" | "steamlocation"
    ) {
        return true;
    }
    profile_route_root_aliases(profile).contains(&compact)
}

fn profile_route_root_aliases(profile: &GameProfile) -> HashSet<String> {
    let mut aliases = HashSet::new();
    aliases.insert(compact_provider_slug(&profile.name));
    if let Some(folder_name) = Path::new(&profile.game_path)
        .file_name()
        .and_then(|name| name.to_str())
    {
        aliases.insert(compact_provider_slug(folder_name));
    }
    if let Some(definition) = profile.game_id.as_deref().and_then(game_definition_by_id) {
        aliases.insert(compact_provider_slug(&definition.display_name));
        aliases.insert(compact_provider_slug(&definition.id));
    }
    aliases.retain(|alias| !alias.is_empty());
    aliases
}

fn safe_install_route_component(component: &str) -> bool {
    let trimmed = component.trim();
    let windows_trimmed = trimmed.trim_end_matches(['.', ' ']);
    if trimmed.is_empty()
        || matches!(trimmed, "." | "..")
        || windows_trimmed.is_empty()
        || windows_trimmed != trimmed
        || trimmed.len() > 80
        || trimmed.chars().any(|character| {
            character.is_control()
                || matches!(
                    character,
                    ':' | '*' | '?' | '"' | '<' | '>' | '|' | '$' | '%'
                )
        })
    {
        return false;
    }
    !is_windows_reserved_folder_name(trimmed)
}

fn canonical_install_route(parts: &[String]) -> Option<(String, String)> {
    let lower = parts
        .iter()
        .map(|part| part.to_lowercase())
        .collect::<Vec<_>>();
    if let Some(index) = lower
        .windows(2)
        .position(|parts| parts[0] == "content" && parts[1] == "paks")
    {
        let mut route = parts[..=index + 1].to_vec();
        route.push("~mods".to_string());
        return Some((route.join("/"), "unreal-pak".to_string()));
    }
    if let Some(index) = lower
        .windows(2)
        .position(|parts| matches!(parts[0].as_str(), "script" | "scripts") && parts[1] == "mods")
    {
        return Some((parts[..=index + 1].join("/"), "script-files".to_string()));
    }
    if let Some(index) = lower.windows(4).position(|parts| {
        parts[0] == "binaries" && parts[1] == "win64" && parts[2] == "ue4ss" && parts[3] == "mods"
    }) {
        return Some((parts[..=index + 3].join("/"), "ue4ss".to_string()));
    }
    if let Some(index) = lower
        .windows(3)
        .position(|parts| parts[0] == "binaries" && parts[1] == "win64" && parts[2] == "mods")
    {
        return Some((parts[..=index + 2].join("/"), "ue4ss".to_string()));
    }
    if let Some(index) = lower.windows(2).position(|parts| {
        parts[0] == "bepinex" && matches!(parts[1].as_str(), "plugins" | "config")
    }) {
        return Some((parts[..=index + 1].join("/"), "bepinex".to_string()));
    }
    if let Some(index) = lower.windows(2).position(|parts| {
        parts[0] == "reframework" && matches!(parts[1].as_str(), "autorun" | "plugins")
    }) {
        return Some((parts[..=index + 1].join("/"), "reframework".to_string()));
    }
    None
}

fn validate_learned_route_shape(adapter_id: &str, relative_path: &str) -> bool {
    let parts = normalize_archive_path(relative_path)
        .split('/')
        .filter(|part| !part.is_empty())
        .map(|part| part.to_lowercase())
        .collect::<Vec<_>>();
    if parts.is_empty() || parts.len() > 12 || parts.iter().any(|part| part == "..") {
        return false;
    }
    match adapter_id {
        "unreal-pak" => {
            parts.len() >= 3
                && parts[parts.len() - 3] == "content"
                && parts[parts.len() - 2] == "paks"
                && parts[parts.len() - 1] == "~mods"
        }
        "script-files" => {
            parts.len() >= 2
                && matches!(parts[parts.len() - 2].as_str(), "script" | "scripts")
                && parts[parts.len() - 1] == "mods"
        }
        "ue4ss" => {
            let legacy = parts.len() >= 3
                && parts[parts.len() - 3] == "binaries"
                && parts[parts.len() - 2] == "win64"
                && parts[parts.len() - 1] == "mods";
            let nested = parts.len() >= 4
                && parts[parts.len() - 4] == "binaries"
                && parts[parts.len() - 3] == "win64"
                && parts[parts.len() - 2] == "ue4ss"
                && parts[parts.len() - 1] == "mods";
            legacy || nested
        }
        "bepinex" => {
            parts.len() >= 2
                && parts[parts.len() - 2] == "bepinex"
                && matches!(parts[parts.len() - 1].as_str(), "plugins" | "config")
        }
        "reframework" => {
            parts.len() >= 2
                && parts[parts.len() - 2] == "reframework"
                && matches!(parts[parts.len() - 1].as_str(), "autorun" | "plugins")
        }
        _ => false,
    }
}

fn route_has_safe_internal_root(
    profile: &GameProfile,
    relative_path: &str,
    adapter_id: &str,
) -> bool {
    let Some(first) = normalize_archive_path(relative_path)
        .split('/')
        .find(|part| !part.is_empty())
        .map(str::to_string)
    else {
        return false;
    };
    let lower = first.to_lowercase();
    if matches!(
        lower.as_str(),
        "users"
            | "windows"
            | "programdata"
            | "appdata"
            | "documents"
            | "desktop"
            | "downloads"
            | "steamapps"
    ) {
        return false;
    }
    if Path::new(&profile.game_path).join(&first).exists() {
        return true;
    }
    matches!(
        (adapter_id, lower.as_str()),
        ("unreal-pak", "content")
            | ("script-files", "script")
            | ("script-files", "scripts")
            | ("ue4ss", "binaries")
            | ("bepinex", "bepinex")
            | ("reframework", "reframework")
    )
}

fn install_route_scopes(context: &str) -> Vec<String> {
    let lower = context.to_lowercase();
    let mut scopes = Vec::new();
    if lower.contains("single player") || lower.contains("single-player") || lower.contains("solo")
    {
        scopes.push("client".to_string());
    }
    if lower.contains("multiplayer")
        || lower.contains("local server")
        || lower.contains("hosting")
        || lower.contains("windowsserver")
    {
        scopes.push("hosted-server".to_string());
    }
    if lower.contains("dedicated server") || lower.contains("dedicated-server") {
        scopes.push("dedicated-server".to_string());
    }
    if scopes.is_empty() {
        scopes.push("general".to_string());
    }
    scopes
}

fn compact_route_excerpt(context: &str) -> String {
    context
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .chars()
        .take(240)
        .collect()
}

fn route_adapter_compatible(profile: &GameProfile, adapter_id: &str) -> bool {
    if let Some(definition) = profile.game_id.as_deref().and_then(game_definition_by_id) {
        return definition
            .supported_adapters
            .iter()
            .any(|adapter| adapter.eq_ignore_ascii_case(adapter_id));
    }
    match adapter_id {
        "bepinex" => profile.engine.starts_with("unity") || profile.loader.starts_with("bepinex"),
        "unreal-pak" | "script-files" | "ue4ss" => {
            profile.engine == "unreal" || profile.loader == "ue4ss"
        }
        "reframework" => profile.engine == "re-engine" || profile.loader == "reframework",
        _ => false,
    }
}

fn apply_profile_route_knowledge(
    profile: &GameProfile,
    knowledge: &mut ProfileRouteKnowledge,
) -> RouteKnowledgeOutcome {
    let mut outcome = RouteKnowledgeOutcome::default();
    let mut normalized_routes = Vec::new();
    for mut route in std::mem::take(&mut knowledge.routes) {
        let Some((relative_path, adapter_id)) =
            normalize_install_route_candidate(profile, &route.relative_path)
        else {
            outcome.warnings.push(format!(
                "Skipped an unsafe or unrecognized learned route: {}.",
                route.relative_path
            ));
            continue;
        };
        route.relative_path = relative_path;
        route.adapter_id = adapter_id;
        merge_learned_route(&mut normalized_routes, route);
    }
    knowledge.routes = normalized_routes;

    for route in knowledge.routes.iter_mut().filter(|route| route.trusted) {
        if !validate_learned_route_shape(&route.adapter_id, &route.relative_path)
            || !route_has_safe_internal_root(profile, &route.relative_path, &route.adapter_id)
            || !(route_adapter_compatible(profile, &route.adapter_id)
                || profile.engine == "unknown")
        {
            outcome.warnings.push(format!(
                "Skipped an unsafe or incompatible learned route: {}.",
                route.relative_path
            ));
            continue;
        }
        push_unique_route(&mut outcome.expected_routes, &route.relative_path);
        // Provider prose is discovery evidence, not filesystem authority. Creating
        // this directory here would make the next archive scan mistake our own
        // mutation for a genuine game route. A verified install plan creates its
        // destination parents later inside the deployment transaction.
        route.created = safe_join(Path::new(&profile.game_path), &route.relative_path)
            .is_ok_and(|path| path.is_dir());
    }
    outcome
}

fn prepare_package_install_routes(
    root: &Path,
    profile: &GameProfile,
    scanned: &ScannedArchive,
    document: &ProviderRouteDocument,
    verified_plan: &mut InstallPlan,
) -> RouteKnowledgeOutcome {
    let candidates = extract_install_route_candidates(profile, &document.text)
        .into_iter()
        .filter(|candidate| {
            candidate
                .adapter_id
                .eq_ignore_ascii_case(&verified_plan.adapter_id)
                && archive_supports_adapter(scanned, &candidate.adapter_id)
        })
        .filter(|candidate| {
            route_adapter_compatible(profile, &candidate.adapter_id) || profile.engine == "unknown"
        })
        .collect::<Vec<_>>();
    if candidates.is_empty() {
        return RouteKnowledgeOutcome::default();
    }
    let candidate_keys = candidates
        .iter()
        .map(|candidate| install_route_key(&candidate.adapter_id, &candidate.relative_path))
        .collect::<HashSet<_>>();

    let mut knowledge = read_profile_route_knowledge(root, &profile.id)
        .ok()
        .flatten()
        .unwrap_or_else(|| ProfileRouteKnowledge {
            version: PROFILE_ROUTE_KNOWLEDGE_VERSION,
            profile_id: profile.id.clone(),
            learned_at: now_string(),
            sampled_mods: 0,
            providers: Vec::new(),
            routes: Vec::new(),
            warnings: Vec::new(),
        });
    push_unique_string_value(&mut knowledge.providers, &document.provider);

    for candidate in candidates {
        let strong_evidence = package_route_has_strong_evidence(profile, scanned, &candidate);
        if !strong_evidence {
            knowledge.warnings.push(format!(
                "Learned install route {} from {}, but it is waiting for game-folder or multi-source corroboration.",
                candidate.relative_path, document.mod_name
            ));
        }
        merge_learned_route(
            &mut knowledge.routes,
            LearnedInstallRoute {
                relative_path: candidate.relative_path,
                adapter_id: candidate.adapter_id,
                scopes: candidate.scopes,
                confidence: if strong_evidence { 0.9 } else { 0.68 },
                supporting_mods: 1,
                providers: vec![document.provider.clone()],
                evidence: vec![RouteEvidence {
                    provider: document.provider.clone(),
                    mod_id: document.mod_id.clone(),
                    mod_name: document.mod_name.clone(),
                    excerpt: candidate.excerpt,
                }],
                trusted: strong_evidence,
                package_verified: true,
                created: false,
            },
        );
    }
    knowledge.learned_at = now_string();
    let mut outcome = apply_profile_route_knowledge(profile, &mut knowledge);
    let current_package_routes = knowledge
        .routes
        .iter()
        .filter(|route| {
            candidate_keys.contains(&install_route_key(&route.adapter_id, &route.relative_path))
        })
        .cloned()
        .collect::<Vec<_>>();
    apply_verified_provider_routes_to_plan(
        profile,
        scanned,
        &current_package_routes,
        verified_plan,
        &mut outcome.warnings,
    );
    if let Err(error) = write_profile_route_knowledge(root, &knowledge) {
        outcome.warnings.push(format!(
            "Could not remember this package's install route: {error}"
        ));
    }
    outcome
}

fn apply_verified_provider_routes_to_plan(
    profile: &GameProfile,
    scanned: &ScannedArchive,
    routes: &[LearnedInstallRoute],
    plan: &mut InstallPlan,
    warnings: &mut Vec<String>,
) {
    if plan.adapter_id != "unreal-pak" {
        return;
    }

    // Provider prose may describe which verified root a package belongs to, but
    // it can never create install authority for a path that the game does not
    // actually expose.
    let canonical_routes = verified_install_target_routes(profile, &plan.adapter_id);
    if canonical_routes.is_empty() {
        return;
    }

    let mut verified_routes = routes
        .iter()
        .filter(|route| route.adapter_id.eq_ignore_ascii_case(&plan.adapter_id))
        .filter(|route| route.package_verified && route.trusted)
        .filter(|route| {
            validate_learned_route_shape(&route.adapter_id, &route.relative_path)
                && route_has_safe_internal_root(profile, &route.relative_path, &route.adapter_id)
                && archive_supports_adapter(scanned, &route.adapter_id)
                && canonical_routes
                    .iter()
                    .any(|canonical| canonical.eq_ignore_ascii_case(&route.relative_path))
        })
        .map(|route| route.relative_path.clone())
        .collect::<Vec<_>>();
    verified_routes.sort_by(|left, right| {
        install_target_scope_from_path(left)
            .cmp(&install_target_scope_from_path(right))
            .then_with(|| left.to_ascii_lowercase().cmp(&right.to_ascii_lowercase()))
    });
    verified_routes.dedup_by(|left, right| left.eq_ignore_ascii_case(right));
    if verified_routes.is_empty() {
        return;
    }

    let original_game_sources = plan
        .mappings
        .iter()
        .filter(|mapping| {
            mapping.generated_content.is_none() && mapping.target_root.eq_ignore_ascii_case("game")
        })
        .map(|mapping| normalize_archive_path(&mapping.source_path).to_ascii_lowercase())
        .collect::<HashSet<_>>();
    let mut remapped = plan
        .mappings
        .iter()
        .filter(|mapping| !mapping.target_root.eq_ignore_ascii_case("game"))
        .cloned()
        .collect::<Vec<_>>();

    for mapping in plan
        .mappings
        .iter()
        .filter(|mapping| mapping.target_root.eq_ignore_ascii_case("game"))
    {
        let source_scope = source_install_target_scope(&mapping.source_path);
        for route in &verified_routes {
            if !source_scope_matches_target_route(source_scope, route) {
                continue;
            }
            let mut routed = mapping.clone();
            routed.target_relative_path =
                join_install_route(route, &basename(&mapping.target_relative_path));
            routed.reason =
                "Provider route accepted after the archive install layout was verified."
                    .to_string();
            push_unique_mapping(&mut remapped, routed);
        }
    }

    let remapped_sources = remapped
        .iter()
        .filter(|mapping| {
            mapping.generated_content.is_none() && mapping.target_root.eq_ignore_ascii_case("game")
        })
        .map(|mapping| normalize_archive_path(&mapping.source_path).to_ascii_lowercase())
        .collect::<HashSet<_>>();
    if !original_game_sources.is_subset(&remapped_sources) {
        plan.requires_confirmation = true;
        push_unique_string_value(
            warnings,
            "Provider routes did not cover every verified package payload scope. Automatic installation was blocked.",
        );
        push_unique_string_value(
            &mut plan.warnings,
            "Provider routes did not cover every verified package payload scope. Automatic installation was blocked.",
        );
        return;
    }

    plan.mappings = remapped;
    plan.summary = format!(
        "Deploy {} verified pak payload mapping(s) to {}.",
        plan.mappings.len(),
        join_human_list(&verified_routes)
    );
}

fn package_route_has_strong_evidence(
    profile: &GameProfile,
    scanned: &ScannedArchive,
    candidate: &InstallRouteCandidate,
) -> bool {
    if !validate_learned_route_shape(&candidate.adapter_id, &candidate.relative_path)
        || !route_has_safe_internal_root(profile, &candidate.relative_path, &candidate.adapter_id)
        || !archive_supports_adapter(scanned, &candidate.adapter_id)
        || !route_adapter_compatible(profile, &candidate.adapter_id)
    {
        return false;
    }

    verified_install_target_routes(profile, &candidate.adapter_id)
        .iter()
        .any(|route| route.eq_ignore_ascii_case(&candidate.relative_path))
}

fn archive_supports_adapter(scanned: &ScannedArchive, adapter_id: &str) -> bool {
    scanned.entries.iter().any(|entry| {
        if entry.is_directory {
            return false;
        }
        let path = entry.logical_path.to_lowercase();
        let name = basename(&path).to_lowercase();
        match adapter_id {
            "unreal-pak" => {
                path.ends_with(".pak") || path.ends_with(".ucas") || path.ends_with(".utoc")
            }
            "script-files" => path.ends_with(".as"),
            "ue4ss" => {
                path.ends_with(".lua")
                    || path.starts_with("mods/")
                    || path.starts_with("ue4ss/")
                    || is_ue4ss_root_runtime_file(&path)
            }
            "bepinex" => {
                path.contains("bepinex/")
                    || path.starts_with("plugins/")
                    || name.ends_with(".dll")
                    || is_bepinex_root_runtime_file(&path)
            }
            "reframework" => {
                path.starts_with("reframework/")
                    || path.ends_with(".lua")
                    || is_reframework_root_runtime_file(&path)
            }
            _ => false,
        }
    })
}

fn description_runtime_dependencies(
    profile: &GameProfile,
    text: &str,
    provided_runtime: Option<&str>,
) -> Vec<DependencySpec> {
    let searchable = ascii_requirement_text(text);
    if searchable.is_empty() {
        return Vec::new();
    }
    let mut dependencies = Vec::new();
    for definition in runtime_definitions() {
        if provided_runtime.is_some_and(|runtime| runtime.eq_ignore_ascii_case(&definition.id))
            || !runtime_definition_matches_profile(definition, profile)
            || !runtime_alias_is_required(&searchable, &runtime_requirement_aliases(&definition.id))
        {
            continue;
        }
        let dependency = known_runtime_dependency(profile, &definition.id);
        if !dependencies.iter().any(|existing: &DependencySpec| {
            dependency_key(existing) == dependency_key(&dependency)
        }) {
            dependencies.push(dependency);
        }
    }
    dependencies
}

fn runtime_definition_matches_profile(
    definition: &RuntimeDefinition,
    profile: &GameProfile,
) -> bool {
    profile.engine == "unknown"
        || definition
            .profile_engines
            .iter()
            .any(|engine| engine.eq_ignore_ascii_case(&profile.engine))
        || definition
            .profile_loaders
            .iter()
            .any(|loader| loader.eq_ignore_ascii_case(&profile.loader))
}

fn runtime_requirement_aliases(runtime_id: &str) -> Vec<&'static str> {
    match runtime_id {
        "enshrouded-eml" => vec!["enshrouded mod loader", "eml", "kfc parser"],
        "enshrouded-shroudtopia" => vec!["shroudtopia", "shroudweave"],
        "enshrouded-proxy" => vec!["modloader proxy", "modloaderproxy"],
        "bepinex" | "bepinex-il2cpp" => vec!["bepinex", "bep in ex"],
        "ue4ss" => vec!["ue4ss", "re ue4ss"],
        "reframework" => vec!["reframework", "re framework"],
        _ => Vec::new(),
    }
}

fn ascii_requirement_text(text: &str) -> String {
    text.chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() {
                character.to_ascii_lowercase()
            } else {
                ' '
            }
        })
        .collect::<String>()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

fn runtime_alias_is_required(searchable: &str, aliases: &[&str]) -> bool {
    const REQUIREMENT_WORDS: [&str; 10] = [
        "require",
        "requires",
        "required",
        "requirement",
        "requirements",
        "dependency",
        "dependencies",
        "prerequisite",
        "needs",
        "install first",
    ];
    aliases.iter().any(|alias| {
        let mut offset = 0usize;
        while let Some(relative_index) = searchable[offset..].find(alias) {
            let index = offset + relative_index;
            let alias_end = index + alias.len();
            let starts_on_boundary =
                index == 0 || !searchable.as_bytes()[index - 1].is_ascii_alphanumeric();
            let ends_on_boundary = alias_end == searchable.len()
                || !searchable.as_bytes()[alias_end].is_ascii_alphanumeric();
            if !starts_on_boundary || !ends_on_boundary {
                offset = index + 1;
                continue;
            }
            let start = index.saturating_sub(140);
            let end = (alias_end + 140).min(searchable.len());
            let local_start = index.saturating_sub(64);
            let local_end = (alias_end + 64).min(searchable.len());
            let local = &searchable[local_start..local_end];
            if !runtime_requirement_is_negated(local, alias)
                && REQUIREMENT_WORDS
                    .iter()
                    .any(|word| searchable[start..end].contains(word))
            {
                return true;
            }
            offset = alias_end;
        }
        false
    })
}

fn runtime_requirement_is_negated(context: &str, alias: &str) -> bool {
    [
        format!("does not require {alias}"),
        format!("doesnt require {alias}"),
        format!("do not require {alias}"),
        format!("not require {alias}"),
        format!("without {alias}"),
        format!("no need for {alias}"),
        format!("{alias} is not required"),
        format!("{alias} not required"),
        format!("{alias} is optional"),
        format!("{alias} optional"),
        format!("optional {alias}"),
    ]
    .iter()
    .any(|phrase| context.contains(phrase))
}

fn append_unique_dependencies(
    destination: &mut Vec<DependencySpec>,
    dependencies: impl IntoIterator<Item = DependencySpec>,
) {
    for dependency in dependencies {
        if !destination
            .iter()
            .any(|existing| dependency_key(existing) == dependency_key(&dependency))
        {
            destination.push(dependency);
        }
    }
}

fn runtime_id_for_provider_package(
    profile: &GameProfile,
    provider: &str,
    namespace: Option<&str>,
    package_name: &str,
) -> Option<String> {
    let engine_known = profile.engine != "unknown";
    let loader_known = profile.loader != "none";
    let mut candidates = runtime_definitions()
        .iter()
        .filter(|definition| {
            runtime_provider_package_matches(definition, provider, namespace, package_name)
        })
        .filter(|definition| {
            (!engine_known
                || definition
                    .profile_engines
                    .iter()
                    .any(|engine| engine.eq_ignore_ascii_case(&profile.engine)))
                && (!loader_known
                    || definition
                        .profile_loaders
                        .iter()
                        .any(|loader| loader.eq_ignore_ascii_case(&profile.loader)))
        })
        .map(|definition| definition.id.clone())
        .collect::<Vec<_>>();
    candidates.sort();
    candidates.dedup();
    (candidates.len() == 1).then(|| candidates.remove(0))
}

fn is_known_runtime_provider_package(
    provider: &str,
    namespace: Option<&str>,
    package_name: &str,
) -> bool {
    runtime_definitions().iter().any(|definition| {
        runtime_provider_package_matches(definition, provider, namespace, package_name)
    })
}

fn provider_slug_aliases(slug: &str) -> Vec<String> {
    match slug {
        "dragonwilds" | "rsdragonwilds" => vec!["runescapedragonwilds".to_string()],
        "mhwilds" => vec!["monsterhunterwilds".to_string()],
        _ => Vec::new(),
    }
}

fn provider_name_aliases(slug: &str) -> Vec<String> {
    match slug {
        "dragonwilds" | "rsdragonwilds" | "runescapedragonwilds" => {
            vec!["RuneScape: Dragonwilds".to_string()]
        }
        "mhwilds" | "monsterhunterwilds" => vec!["Monster Hunter Wilds".to_string()],
        _ => Vec::new(),
    }
}

fn push_provider_slug(candidates: &mut Vec<String>, seen: &mut HashSet<String>, value: String) {
    let trimmed = value.trim_matches('-').to_string();
    if trimmed.len() >= 2 && seen.insert(trimmed.clone()) {
        candidates.push(trimmed);
    }
}

fn push_unique_string(values: &mut Vec<String>, seen: &mut HashSet<String>, value: String) {
    let trimmed = value.trim().to_string();
    let key = trimmed.to_lowercase();
    if !trimmed.is_empty() && seen.insert(key) {
        values.push(trimmed);
    }
}

fn readable_provider_text(value: &str) -> String {
    let mut output = String::new();
    let characters = value.chars().collect::<Vec<_>>();

    for (index, character) in characters.iter().enumerate() {
        let previous = index
            .checked_sub(1)
            .and_then(|previous| characters.get(previous));
        let next = characters.get(index + 1);
        let should_split_camel = character.is_ascii_uppercase()
            && previous
                .map(|previous| previous.is_ascii_lowercase() || previous.is_ascii_digit())
                .unwrap_or(false)
            && next.map(|next| next.is_ascii_lowercase()).unwrap_or(false);

        if should_split_camel && !output.ends_with(' ') {
            output.push(' ');
        }

        if character.is_ascii_alphanumeric() {
            output.push(*character);
        } else if !output.ends_with(' ') {
            output.push(' ');
        }
    }

    output.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn compact_provider_slug(value: &str) -> String {
    value
        .chars()
        .filter(|character| character.is_ascii_alphanumeric())
        .flat_map(|character| character.to_lowercase())
        .collect::<String>()
}

fn hyphenated_provider_slug(value: &str) -> String {
    readable_provider_text(value)
        .split_whitespace()
        .map(|part| {
            part.chars()
                .filter(|character| character.is_ascii_alphanumeric())
                .flat_map(|character| character.to_lowercase())
                .collect::<String>()
        })
        .filter(|part| !part.is_empty())
        .collect::<Vec<_>>()
        .join("-")
}

fn discover_thunderstore_community_mods(
    store_root: &Path,
    profile: &GameProfile,
    community: &str,
    fetch: NexusDiscoveryFetch<'_>,
) -> Result<DiscoveryProviderBatch, String> {
    ensure_discovery_is_current(&profile.id, fetch.request_id)?;
    let mut packages = fetch_thunderstore_community_packages(community)?;
    ensure_discovery_is_current(&profile.id, fetch.request_id)?;
    let installed_keys = installed_package_identity_keys(store_root, &profile.id)?;
    let normalized_query = fetch.query.trim().to_ascii_lowercase();
    packages.retain(|package| {
        is_discoverable_thunderstore_package(package)
            && (normalized_query.is_empty()
                || package
                    .name
                    .to_ascii_lowercase()
                    .contains(&normalized_query)
                || package
                    .full_name
                    .to_ascii_lowercase()
                    .contains(&normalized_query))
    });
    packages.sort_by(|first, second| {
        let tie = || {
            first
                .full_name
                .to_ascii_lowercase()
                .cmp(&second.full_name.to_ascii_lowercase())
        };
        match fetch.sort {
            "newest" => thunderstore_package_timestamp(second)
                .cmp(thunderstore_package_timestamp(first))
                .then_with(tie),
            "oldest" => thunderstore_package_timestamp(first)
                .cmp(thunderstore_package_timestamp(second))
                .then_with(tie),
            _ => thunderstore_package_downloads(second)
                .cmp(&thunderstore_package_downloads(first))
                .then_with(|| second.rating_score.cmp(&first.rating_score))
                .then_with(tie),
        }
    });

    let raw_total = packages.len();
    let start_offset = fetch.start_offset.min(raw_total);
    let end_offset = start_offset
        .saturating_add(fetch.max_new_results)
        .min(raw_total);
    let mut records = Vec::new();
    let mut filtered_out = 0_usize;
    for package in packages
        .into_iter()
        .skip(start_offset)
        .take(end_offset.saturating_sub(start_offset))
    {
        ensure_discovery_is_current(&profile.id, fetch.request_id)?;
        match thunderstore_package_to_online_mod(profile, community, package, &installed_keys) {
            Some(record) if !is_external_mod_manager_listing(&record) => records.push(record),
            _ => filtered_out = filtered_out.saturating_add(1),
        }
    }

    Ok(DiscoveryProviderBatch {
        start_offset: fetch.start_offset,
        records,
        raw_total,
        next_offset: end_offset,
        filtered_out,
        complete: end_offset >= raw_total,
    })
}

fn thunderstore_package_downloads(package: &ThunderstoreCommunityPackage) -> u64 {
    package
        .versions
        .iter()
        .map(|version| version.downloads)
        .sum()
}

fn thunderstore_package_timestamp(package: &ThunderstoreCommunityPackage) -> &str {
    package
        .date_updated
        .as_deref()
        .or(package.date_created.as_deref())
        .unwrap_or_default()
}

fn fetch_thunderstore_community_packages(
    community: &str,
) -> Result<Vec<ThunderstoreCommunityPackage>, String> {
    let cache = THUNDERSTORE_CACHE.get_or_init(|| Mutex::new(HashMap::new()));
    let cached_packages = cache
        .lock()
        .ok()
        .and_then(|cache| cache.get(community).cloned())
        .filter(|entry| entry.fetched_at.elapsed() < Duration::from_secs(10 * 60));
    let packages = if let Some(entry) = cached_packages {
        entry.packages
    } else {
        let client = thunderstore_client()?;
        let url = format!(
            "{}/{}/api/v1/package/",
            THUNDERSTORE_COMMUNITY_API_BASE,
            sanitize_url_path_segment(community)
        );
        let packages = client
            .get(url)
            .send()
            .map_err(error_to_string)?
            .error_for_status()
            .map_err(error_to_string)?
            .json::<Vec<ThunderstoreCommunityPackage>>()
            .map_err(error_to_string)?;
        if let Ok(mut cache) = cache.lock() {
            let now = Instant::now();
            cache.retain(|_, entry| {
                now.duration_since(entry.fetched_at) < Duration::from_secs(10 * 60)
            });
            if cache.len() >= THUNDERSTORE_CACHE_MAX_ENTRIES && !cache.contains_key(community) {
                if let Some(oldest) = cache
                    .iter()
                    .min_by_key(|(_, entry)| entry.fetched_at)
                    .map(|(key, _)| key.clone())
                {
                    cache.remove(&oldest);
                }
            }
            cache.insert(
                community.to_string(),
                ThunderstoreCacheEntry {
                    fetched_at: now,
                    packages: packages.clone(),
                },
            );
        }
        packages
    };
    Ok(packages)
}

fn clear_thunderstore_community_cache(community: &str) {
    if let Ok(mut cache) = THUNDERSTORE_CACHE
        .get_or_init(|| Mutex::new(HashMap::new()))
        .lock()
    {
        cache.remove(community);
    }
}

fn is_discoverable_thunderstore_package(package: &ThunderstoreCommunityPackage) -> bool {
    if package.is_deprecated || package.has_nsfw_content || package.versions.is_empty() {
        return false;
    }

    if is_known_runtime_provider_package("thunderstore", Some(&package.owner), &package.name) {
        return false;
    }

    let lower_name = package.name.to_lowercase();
    let is_tool = package
        .categories
        .iter()
        .any(|category| category.eq_ignore_ascii_case("tools"))
        || matches!(lower_name.as_str(), "r2modman" | "thunderstore_mod_manager");

    !is_tool
}

fn thunderstore_package_to_online_mod(
    profile: &GameProfile,
    community: &str,
    package: ThunderstoreCommunityPackage,
    installed_keys: &HashSet<String>,
) -> Option<OnlineModRecord> {
    let latest = latest_active_thunderstore_version(&package)?.clone();
    let package_ref = ThunderstorePackageRef {
        namespace: package.owner.clone(),
        name: package.name.clone(),
        version: Some(latest.version_number.clone()),
    };
    let package_id = thunderstore_package_id(&package_ref);
    let dependency_string = thunderstore_dependency_string(&package_ref, &latest.version_number);
    let installed = installed_keys.contains(&format!("package:{}", package_id.to_lowercase()))
        || installed_keys.contains(&format!("dependency:{}", dependency_string.to_lowercase()));
    let total_downloads = package
        .versions
        .iter()
        .map(|version| version.downloads)
        .sum::<u64>();
    let created_at = package
        .date_created
        .clone()
        .or_else(|| latest.date_created.clone());
    let updated_at = package
        .date_updated
        .clone()
        .or_else(|| latest.date_created.clone());

    Some(OnlineModRecord {
        id: package_id,
        provider: "thunderstore".to_string(),
        provider_label: "Thunderstore".to_string(),
        game_id: profile.game_id.clone(),
        provider_game_id: Some(community.to_string()),
        name: humanize_mod_display_name(&package.full_name),
        owner: package.owner,
        version: latest.version_number,
        description: latest.description,
        categories: package.categories,
        downloads: total_downloads,
        rating_score: package.rating_score,
        dependency_count: latest.dependencies.len(),
        file_size: latest.file_size,
        icon_url: latest.icon,
        package_url: package.package_url,
        website_url: latest.website_url,
        installed,
        created_at,
        updated_at,
        install_supported: true,
        install_note: None,
    })
}

fn installed_package_identity_keys(
    store_root: &Path,
    profile_id: &str,
) -> Result<HashSet<String>, String> {
    let store = read_store::<InstalledModRecord>(&installed_mods_path(store_root))
        .map_err(error_to_string)?;
    let mut keys = HashSet::new();
    for record in store
        .items
        .iter()
        .filter(|record| record.profile_id == profile_id && record.enabled)
    {
        if let Some(package_id) = &record.package_id {
            keys.insert(format!("package:{}", package_id.to_lowercase()));
        }
        if let Some(dependency) = &record.dependency_string {
            keys.insert(format!("dependency:{}", dependency.to_lowercase()));
        }
    }
    Ok(keys)
}

fn discover_nexus_mods_for_profile(
    profile: &GameProfile,
    domain: &str,
    nexus_api_ready: bool,
    fetch: NexusDiscoveryFetch<'_>,
) -> Result<DiscoveryProviderBatch, String> {
    let client = provider_client()?;
    let mut records = Vec::new();
    let mut offset = fetch.start_offset;
    let mut total_count = usize::MAX;
    let mut filtered_out = 0usize;
    let mut complete = false;

    while offset < total_count && records.len() < fetch.max_new_results {
        ensure_discovery_is_current(&profile.id, fetch.request_id)?;
        let remaining = fetch.max_new_results.saturating_sub(records.len());
        let page_size = nexus_discovery_batch_size(remaining);
        if page_size == 0 {
            break;
        }

        let page = fetch_nexus_mod_page_sorted(
            &client,
            domain,
            offset,
            page_size,
            fetch.sort,
            fetch.query,
        )?;
        ensure_discovery_is_current(&profile.id, fetch.request_id)?;
        total_count = page.total_count;
        let returned_count = page.nodes.len();

        if returned_count == 0 {
            complete = true;
            break;
        }

        for node in page.nodes {
            if let Some(record) = nexus_mod_to_online_mod(profile, domain, node, nexus_api_ready) {
                if is_external_mod_manager_listing(&record) {
                    filtered_out = filtered_out.saturating_add(1);
                } else {
                    records.push(record);
                }
            } else {
                filtered_out = filtered_out.saturating_add(1);
            }
        }

        offset += returned_count;
        complete = offset >= total_count;
    }

    Ok(DiscoveryProviderBatch {
        start_offset: fetch.start_offset,
        records,
        raw_total: total_count.min(usize::MAX - 1),
        next_offset: offset,
        filtered_out,
        complete,
    })
}

fn nexus_discovery_batch_size(remaining: usize) -> usize {
    remaining.min(NEXUS_DISCOVERY_PAGE_SIZE)
}

fn fetch_nexus_mod_page_sorted(
    client: &Client,
    domain: &str,
    offset: usize,
    count: usize,
    sort: &str,
    query: &str,
) -> Result<NexusModPage, String> {
    fetch_nexus_mod_page_with_sort(client, domain, offset, count, sort, query)
}

fn fetch_nexus_mod_page(
    client: &Client,
    domain: &str,
    offset: usize,
    count: usize,
) -> Result<NexusModPage, String> {
    fetch_nexus_mod_page_with_sort(client, domain, offset, count, "downloads", "")
}

fn fetch_nexus_mod_page_with_sort(
    client: &Client,
    domain: &str,
    offset: usize,
    count: usize,
    sort: &str,
    query: &str,
) -> Result<NexusModPage, String> {
    const NEXUS_DISCOVERY_QUERY: &str = r#"
        query ModGarrisonDiscoverMods(
          $filter: ModsFilter,
          $sort: [ModsSort!],
          $offset: Int,
          $count: Int
        ) {
          mods(filter: $filter, sort: $sort, offset: $offset, count: $count) {
            totalCount
            nodes {
              id
              modId
              name
              summary
              author
              category
              version
              createdAt
              updatedAt
              downloads
              endorsements
              fileSize
              pictureUrl
              thumbnailUrl
              thumbnailLargeUrl
              directDownloadEnabled
              adultContent
              status
              modRequirements(skipDisabledRequirements: true) {
                nexusRequirements {
                  totalCount
                  nodes {
                    externalRequirement
                    gameId
                    modId
                    modName
                    notes
                    url
                  }
                }
              }
            }
          }
        }
    "#;

    let sort_value = match sort {
        "newest" => serde_json::json!({ "updatedAt": { "direction": "DESC" } }),
        "oldest" => serde_json::json!({ "createdAt": { "direction": "ASC" } }),
        _ => serde_json::json!({ "downloads": { "direction": "DESC" } }),
    };
    let mut filter = serde_json::json!({
        "op": "AND",
        "gameDomainName": [{ "value": domain, "op": "EQUALS" }],
        "adultContent": [{ "value": false, "op": "EQUALS" }],
        "status": [{ "value": "published", "op": "EQUALS" }]
    });
    if !query.trim().is_empty() {
        filter
            .as_object_mut()
            .expect("discovery filter is an object")
            .insert(
                "name".to_string(),
                serde_json::json!([{ "value": query.trim(), "op": "WILDCARD" }]),
            );
    }
    let body = serde_json::json!({
        "query": NEXUS_DISCOVERY_QUERY,
        "variables": {
            "filter": filter,
            "sort": [sort_value],
            "offset": offset,
            "count": count
        }
    });

    let response = client
        .post(NEXUS_GRAPHQL_API_BASE)
        .json(&body)
        .send()
        .map_err(error_to_string)?
        .error_for_status()
        .map_err(error_to_string)?
        .json::<NexusGraphqlResponse>()
        .map_err(error_to_string)?;

    if !response.errors.is_empty() {
        let messages = response
            .errors
            .into_iter()
            .map(|error| error.message)
            .collect::<Vec<_>>()
            .join("; ");
        return Err(messages);
    }

    response
        .data
        .map(|data| data.mods)
        .ok_or_else(|| "Nexus Mods returned no discovery data.".to_string())
}

fn fetch_nexus_games_by_name(client: &Client, name: &str) -> Option<Vec<NexusGameNode>> {
    fetch_nexus_games_by_name_result(client, name).ok()
}

fn fetch_nexus_games_by_name_result(
    client: &Client,
    name: &str,
) -> Result<Vec<NexusGameNode>, String> {
    const NEXUS_GAME_QUERY: &str = r#"
        query ModGarrisonDiscoverGame(
          $filter: GamesSearchFilter,
          $sort: [GamesSearchSort!],
          $offset: Int,
          $count: Int
        ) {
          games(filter: $filter, sort: $sort, offset: $offset, count: $count) {
            nodes {
              id
              name
              domainName
            }
          }
        }
    "#;

    let body = serde_json::json!({
        "query": NEXUS_GAME_QUERY,
        "variables": {
            "filter": {
                "name": [{ "value": name, "op": "MATCHES" }]
            },
            "sort": [{ "relevance": { "direction": "DESC" } }],
            "offset": 0,
            "count": 5
        }
    });

    let response = client
        .post(NEXUS_GRAPHQL_API_BASE)
        .json(&body)
        .send()
        .map_err(error_to_string)?
        .error_for_status()
        .map_err(error_to_string)?
        .json::<NexusGamesGraphqlResponse>()
        .map_err(error_to_string)?;

    if !response.errors.is_empty() {
        return Err(response
            .errors
            .into_iter()
            .map(|error| error.message)
            .collect::<Vec<_>>()
            .join("; "));
    }

    response
        .data
        .map(|data| data.games.nodes)
        .ok_or_else(|| "Nexus Mods returned no game catalogue data.".to_string())
}

fn nexus_game_lookup_names(profile: &GameProfile, domain: &str) -> Vec<String> {
    let mut names = Vec::new();
    let mut seen = HashSet::new();

    for alias in provider_name_aliases(&compact_provider_slug(domain)) {
        push_unique_string(&mut names, &mut seen, alias);
    }
    for name in provider_name_candidates(profile) {
        push_unique_string(&mut names, &mut seen, name);
    }
    push_unique_string(&mut names, &mut seen, profile.name.clone());
    push_unique_string(&mut names, &mut seen, readable_provider_text(domain));
    names
}

fn fetch_nexus_game_id_for_domain(
    client: &Client,
    profile: &GameProfile,
    domain: &str,
    api_key: Option<&str>,
) -> Result<u64, String> {
    let normalized_domain = compact_provider_slug(domain);
    if let Ok(mut cache) = NEXUS_GAME_ID_CACHE
        .get_or_init(|| Mutex::new(HashMap::new()))
        .lock()
    {
        if let Some(entry) = cache.get(&normalized_domain) {
            if entry.fetched_at.elapsed() < Duration::from_secs(NEXUS_GAME_ID_CACHE_HOURS * 60 * 60)
            {
                return Ok(entry.game_id);
            }
        }
        cache.remove(&normalized_domain);
    }

    if let Some(api_key) = api_key {
        let direct_url = format!(
            "https://api.nexusmods.com/v1/games/{}.json",
            sanitize_url_path_segment(domain)
        );
        if let Ok(response) = nexus_api_get(client, &direct_url, api_key).send() {
            if let Ok(response) = response.error_for_status() {
                if let Ok(details) = response.json::<NexusGameDetails>() {
                    let returned_domain = compact_provider_slug(&details.domain_name);
                    if returned_domain.is_empty() || returned_domain == normalized_domain {
                        cache_nexus_game_id(&normalized_domain, details.id);
                        return Ok(details.id);
                    }
                }
            }
        }
    }

    for name in nexus_game_lookup_names(profile, domain) {
        let Some(nodes) = fetch_nexus_games_by_name(client, &name) else {
            continue;
        };
        if let Some(game_id) = nodes
            .into_iter()
            .find(|node| compact_provider_slug(&node.domain_name) == normalized_domain)
            .and_then(|node| node.id)
        {
            cache_nexus_game_id(&normalized_domain, game_id);
            return Ok(game_id);
        }
    }

    Err(format!(
        "Nexus Mods could not resolve the game catalogue id for '{domain}'. Refresh Discovery and try again."
    ))
}

fn cache_nexus_game_id(domain: &str, game_id: u64) {
    if let Ok(mut cache) = NEXUS_GAME_ID_CACHE
        .get_or_init(|| Mutex::new(HashMap::new()))
        .lock()
    {
        let now = Instant::now();
        cache.retain(|_, entry| {
            now.duration_since(entry.fetched_at)
                < Duration::from_secs(NEXUS_GAME_ID_CACHE_HOURS * 60 * 60)
        });
        if cache.len() >= NEXUS_GAME_ID_CACHE_MAX_ENTRIES && !cache.contains_key(domain) {
            if let Some(oldest) = cache
                .iter()
                .min_by_key(|(_, entry)| entry.fetched_at)
                .map(|(key, _)| key.clone())
            {
                cache.remove(&oldest);
            }
        }
        cache.insert(
            domain.to_string(),
            NexusGameIdCacheEntry {
                fetched_at: now,
                game_id,
            },
        );
    }
}

fn fetch_nexus_mod_requirements(
    client: &Client,
    profile: &GameProfile,
    domain: &str,
    mod_id: u64,
    api_key: Option<&str>,
) -> Result<Vec<NexusRequirement>, String> {
    const NEXUS_REQUIREMENTS_QUERY: &str = r#"
        query ModGarrisonModRequirements($filter: ModsFilter, $count: Int) {
          mods(filter: $filter, count: $count) {
            nodes {
              modId
              modRequirements(skipDisabledRequirements: true) {
                nexusRequirements {
                  totalCount
                  nodes {
                    externalRequirement
                    gameId
                    modId
                    modName
                    notes
                    url
                  }
                }
              }
            }
          }
        }
    "#;
    let game_id = fetch_nexus_game_id_for_domain(client, profile, domain, api_key)?;
    let body = serde_json::json!({
        "query": NEXUS_REQUIREMENTS_QUERY,
        "variables": {
            "filter": {
                "op": "AND",
                "gameId": [{ "value": game_id.to_string(), "op": "EQUALS" }],
                "modId": [{ "value": mod_id.to_string(), "op": "EQUALS" }]
            },
            "count": 1
        }
    });
    let response = client
        .post(NEXUS_GRAPHQL_API_BASE)
        .json(&body)
        .send()
        .map_err(error_to_string)?
        .error_for_status()
        .map_err(error_to_string)?
        .json::<NexusGraphqlResponse>()
        .map_err(error_to_string)?;
    if !response.errors.is_empty() {
        return Err(response
            .errors
            .into_iter()
            .map(|error| error.message)
            .collect::<Vec<_>>()
            .join("; "));
    }

    Ok(response
        .data
        .and_then(|data| data.mods.nodes.into_iter().next())
        .and_then(|node| node.mod_requirements)
        .map(|requirements| requirements.nexus_requirements.nodes)
        .unwrap_or_default())
}

fn nexus_requirement_dependencies(
    profile: &GameProfile,
    parent_domain: &str,
    requirements: &[NexusRequirement],
) -> Vec<DependencySpec> {
    let mut dependencies = Vec::new();
    let mut seen = HashSet::new();

    for requirement in requirements {
        let required = !nexus_requirement_is_optional(requirement);
        let dependency =
            if let Some(runtime_id) = runtime_id_for_nexus_requirement(profile, requirement) {
                let mut dependency = known_runtime_dependency(profile, &runtime_id);
                dependency.required = required;
                dependency.notes = requirement.notes.clone().or(dependency.notes);
                dependency
            } else if !requirement.external_requirement {
                let domain = nexus_requirement_domain(requirement, parent_domain);
                let Ok(mod_id) = requirement.mod_id.trim().parse::<u64>() else {
                    continue;
                };
                DependencySpec {
                    id: format!("nexus:{domain}/{mod_id}"),
                    name: non_empty_string(requirement.mod_name.trim())
                        .unwrap_or_else(|| format!("Nexus mod {mod_id}")),
                    version: None,
                    provider: "nexus".to_string(),
                    required,
                    status: "missing".to_string(),
                    source: non_empty_string(requirement.url.trim()),
                    notes: requirement.notes.clone(),
                }
            } else {
                let source = non_empty_string(requirement.url.trim());
                let name = nexus_external_requirement_name(requirement);
                if name.is_none() && source.is_none() {
                    continue;
                }
                let identity = name
                    .as_deref()
                    .or(source.as_deref())
                    .unwrap_or("external-requirement");
                DependencySpec {
                    id: format!("external:{}", compact_provider_slug(identity)),
                    name: name.unwrap_or_else(|| "External requirement".to_string()),
                    version: None,
                    provider: "manual".to_string(),
                    required,
                    status: "missing".to_string(),
                    source,
                    notes: requirement.notes.clone(),
                }
            };
        if seen.insert(dependency_key(&dependency)) {
            dependencies.push(dependency);
        }
    }

    dependencies
}

fn runtime_id_for_nexus_requirement(
    profile: &GameProfile,
    requirement: &NexusRequirement,
) -> Option<String> {
    if let Some(runtime) =
        runtime_id_for_provider_package(profile, "nexus", None, &requirement.mod_name)
    {
        return Some(runtime);
    }

    let evidence = [
        requirement.mod_name.as_str(),
        requirement.notes.as_deref().unwrap_or_default(),
        requirement.url.as_str(),
    ]
    .into_iter()
    .filter(|value| !value.trim().is_empty())
    .collect::<Vec<_>>()
    .join(" ");
    let searchable = ascii_requirement_text(&minimal_url_decode(&evidence));
    if searchable.is_empty() {
        return None;
    }

    let mut candidates = runtime_definitions()
        .iter()
        .filter(|definition| runtime_definition_matches_profile(definition, profile))
        .filter(|definition| {
            runtime_definition_matches_requirement_evidence(definition, &searchable)
        })
        .map(|definition| definition.id.clone())
        .collect::<Vec<_>>();
    candidates.sort();
    candidates.dedup();
    (candidates.len() == 1).then(|| candidates.remove(0))
}

fn runtime_definition_matches_requirement_evidence(
    definition: &RuntimeDefinition,
    searchable: &str,
) -> bool {
    let mut aliases = vec![definition.id.clone(), definition.dependency.name.clone()];
    aliases.extend(
        runtime_requirement_aliases(&definition.id)
            .into_iter()
            .map(str::to_string),
    );
    for package in definition
        .provider_packages
        .iter()
        .filter(|package| package.provider.eq_ignore_ascii_case("nexus"))
    {
        aliases.extend(package.package_patterns.iter().cloned());
    }

    aliases.into_iter().any(|alias| {
        let normalized = ascii_requirement_text(alias.trim_matches(['*', '?', ' ']));
        !normalized.is_empty() && normalized_phrase_is_present(searchable, &normalized)
    })
}

fn normalized_phrase_is_present(searchable: &str, phrase: &str) -> bool {
    let haystack = format!(" {searchable} ");
    let needle = format!(" {phrase} ");
    haystack.contains(&needle)
}

fn nexus_external_requirement_name(requirement: &NexusRequirement) -> Option<String> {
    non_empty_string(requirement.mod_name.trim()).or_else(|| {
        let parsed = url::Url::parse(requirement.url.trim()).ok()?;
        let filename = parsed
            .path_segments()?
            .rfind(|segment| !segment.is_empty())?;
        let decoded = minimal_url_decode(filename);
        let stem = Path::new(&decoded)
            .file_stem()
            .and_then(|value| value.to_str())
            .unwrap_or(decoded.as_str());
        non_empty_string(humanize_mod_display_name(stem).trim())
    })
}

fn nexus_requirement_domain(requirement: &NexusRequirement, parent_domain: &str) -> String {
    if let Ok(url) = url::Url::parse(requirement.url.trim()) {
        let segments = url
            .path_segments()
            .map(|segments| {
                segments
                    .filter(|segment| !segment.is_empty())
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        let domain_index = usize::from(segments.first().is_some_and(|segment| *segment == "games"));
        if segments
            .get(domain_index + 1)
            .is_some_and(|segment| *segment == "mods")
        {
            if let Some(domain) = segments.get(domain_index) {
                return sanitize_url_path_segment(domain);
            }
        }
    }

    let provider_game_id = requirement.game_id.trim();
    if provider_game_id
        .chars()
        .any(|character| character.is_ascii_alphabetic())
    {
        return sanitize_url_path_segment(provider_game_id);
    }

    parent_domain.to_string()
}

fn nexus_requirement_is_optional(requirement: &NexusRequirement) -> bool {
    let text = format!(
        "{} {}",
        requirement.mod_name,
        requirement.notes.as_deref().unwrap_or_default()
    )
    .to_lowercase();
    [
        "optional",
        "not required",
        "alternative",
        "choose one",
        "only needed if",
        "only required if",
    ]
    .iter()
    .any(|marker| text.contains(marker))
}

fn nexus_mod_to_online_mod(
    profile: &GameProfile,
    domain: &str,
    node: NexusModNode,
    nexus_api_ready: bool,
) -> Option<OnlineModRecord> {
    if node.adult_content
        || !node
            .status
            .as_deref()
            .unwrap_or("published")
            .eq_ignore_ascii_case("published")
    {
        return None;
    }

    let mod_id = node.mod_id?;
    let name = node.name?.trim().to_string();
    if name.is_empty() {
        return None;
    }
    if is_known_runtime_provider_package("nexus", None, &name) {
        return None;
    }
    let dependency_count = node
        .mod_requirements
        .as_ref()
        .map(|requirements| {
            requirements
                .nexus_requirements
                .total_count
                .max(requirements.nexus_requirements.nodes.len())
        })
        .unwrap_or_default();

    let page_url = format!(
        "{}/{}/mods/{}",
        NEXUS_SITE_BASE,
        sanitize_url_path_segment(domain),
        mod_id
    );
    let category = node
        .category
        .and_then(|value| non_empty_string(value.trim()));
    let categories = category.into_iter().collect::<Vec<_>>();
    let icon_url = node
        .thumbnail_large_url
        .or(node.thumbnail_url)
        .or(node.picture_url);
    let install_note = if nexus_api_ready {
        "Choose a file to install it through Mod Garrison."
    } else if node.direct_download_enabled {
        "Add a Nexus API key in Settings to enable direct install for Nexus mods."
    } else {
        "Add a Nexus API key in Settings to enable Nexus installs."
    };

    Some(OnlineModRecord {
        id: format!("nexus:{}/{}", sanitize_url_path_segment(domain), mod_id),
        provider: "nexus".to_string(),
        provider_label: "Nexus Mods".to_string(),
        game_id: profile.game_id.clone(),
        provider_game_id: Some(domain.to_string()),
        name,
        owner: node
            .author
            .and_then(|value| non_empty_string(value.trim()))
            .unwrap_or_else(|| "Nexus Mods".to_string()),
        version: node
            .version
            .and_then(|value| non_empty_string(value.trim()))
            .unwrap_or_else(|| "latest".to_string()),
        description: clean_nexus_summary(node.summary),
        categories,
        downloads: node.downloads,
        rating_score: node.endorsements,
        dependency_count,
        file_size: node.file_size.map(|size_kb| size_kb.saturating_mul(1024)),
        icon_url,
        package_url: Some(page_url.clone()),
        website_url: Some(page_url),
        installed: false,
        created_at: node.created_at,
        updated_at: node.updated_at,
        install_supported: nexus_api_ready,
        install_note: Some(install_note.to_string()),
    })
}

fn clean_nexus_summary(summary: Option<String>) -> String {
    let Some(raw_summary) = summary else {
        return String::new();
    };

    let raw_summary = decode_provider_html_entities(&raw_summary);
    let mut cleaned = String::new();
    let mut skipping_html = false;
    let mut skipping_bbcode = false;

    for character in raw_summary.chars() {
        match character {
            '<' if !skipping_bbcode => skipping_html = true,
            '>' if skipping_html => skipping_html = false,
            '[' if !skipping_html => skipping_bbcode = true,
            ']' if skipping_bbcode => skipping_bbcode = false,
            _ if !skipping_html && !skipping_bbcode => cleaned.push(character),
            _ => {}
        }
    }

    cleaned.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn non_empty_string(value: &str) -> Option<String> {
    if value.is_empty() {
        None
    } else {
        Some(value.to_string())
    }
}

fn latest_active_thunderstore_version(
    package: &ThunderstoreCommunityPackage,
) -> Option<&ThunderstoreVersion> {
    package
        .versions
        .iter()
        .find(|version| version.is_active)
        .or_else(|| package.versions.first())
}

fn list_discovered_mod_files_impl(
    store_root: &Path,
    profile: &GameProfile,
    settings: &AppSettings,
    provider: &str,
    mod_id: &str,
    supplied_provider_game_id: Option<&str>,
) -> Result<Vec<OnlineModFileOption>, String> {
    match provider {
        "nexus" => list_nexus_mod_files(
            store_root,
            profile,
            settings,
            mod_id,
            supplied_provider_game_id,
        ),
        "thunderstore" => {
            list_thunderstore_mod_versions(store_root, profile, mod_id, supplied_provider_game_id)
        }
        "gamebanana" => {
            gamebanana::list_files(store_root, profile, mod_id, supplied_provider_game_id)
        }
        "modio" => {
            let api_key = settings.modio_api_key().ok_or_else(|| {
                "A mod.io application key is not configured in this Mod Garrison build or in Settings."
                    .to_string()
            })?;
            modio::list_files(
                store_root,
                profile,
                api_key,
                mod_id,
                supplied_provider_game_id,
            )
        }
        "steam-workshop" => {
            steam_workshop::list_files(store_root, profile, mod_id, supplied_provider_game_id)
        }
        _ => Err(format!(
            "{} does not expose selectable files in this build.",
            provider
        )),
    }
}

fn list_nexus_mod_files(
    store_root: &Path,
    profile: &GameProfile,
    settings: &AppSettings,
    mod_id: &str,
    supplied_provider_game_id: Option<&str>,
) -> Result<Vec<OnlineModFileOption>, String> {
    let api_key = settings.nexus_api_key().ok_or_else(|| {
        "Add your Nexus API key in Settings before loading this mod's files.".to_string()
    })?;
    let (domain, nexus_mod_id) = parse_nexus_online_mod_id(mod_id)?;
    verified_discovery_provider_game(
        store_root,
        profile,
        "nexus",
        supplied_provider_game_id,
        Some(&domain),
    )?;

    let client = provider_client()?;
    let account = validate_nexus_api_key(api_key)?;
    let mut files = fetch_nexus_mod_files(&client, api_key, &domain, nexus_mod_id)?;
    files.retain(nexus_file_supported);
    files.sort_by(|first, second| {
        nexus_file_category_score(second)
            .cmp(&nexus_file_category_score(first))
            .then_with(|| {
                second
                    .is_primary
                    .unwrap_or(false)
                    .cmp(&first.is_primary.unwrap_or(false))
            })
            .then_with(|| {
                second
                    .uploaded_timestamp
                    .unwrap_or_default()
                    .cmp(&first.uploaded_timestamp.unwrap_or_default())
            })
    });

    Ok(files
        .into_iter()
        .map(|file| OnlineModFileOption {
            id: file.file_id.to_string(),
            name: nexus_file_display_name(&file),
            version: file
                .version
                .as_deref()
                .and_then(|value| non_empty_string(value.trim())),
            category: file
                .category_name
                .as_deref()
                .and_then(|value| non_empty_string(value.trim())),
            description: file.description.clone().and_then(|description| {
                non_empty_string(clean_nexus_summary(Some(description)).trim())
            }),
            file_name: file.file_name.clone(),
            file_size: nexus_file_size(&file),
            uploaded_at: nexus_file_uploaded_at(&file),
            primary: file.is_primary.unwrap_or(false),
            action: if account.is_premium {
                "direct".to_string()
            } else {
                "browser".to_string()
            },
            download_page_url: Some(nexus_file_page_url(&domain, nexus_mod_id, file.file_id)),
        })
        .collect())
}

fn list_thunderstore_mod_versions(
    store_root: &Path,
    profile: &GameProfile,
    mod_id: &str,
    supplied_provider_game_id: Option<&str>,
) -> Result<Vec<OnlineModFileOption>, String> {
    let raw_id = mod_id
        .strip_prefix("thunderstore:")
        .ok_or_else(|| format!("Invalid Thunderstore mod id: {}", mod_id))?;
    let package_ref = parse_thunderstore_token(raw_id, None).ok_or_else(|| {
        format!(
            "Could not parse Thunderstore package reference from {}.",
            mod_id
        )
    })?;
    let community = verified_discovery_provider_game(
        store_root,
        profile,
        "thunderstore",
        supplied_provider_game_id,
        supplied_provider_game_id,
    )?;
    let packages = fetch_thunderstore_community_packages(&community)?;
    let package = packages
        .into_iter()
        .find(|package| {
            package.owner.eq_ignore_ascii_case(&package_ref.namespace)
                && package.name.eq_ignore_ascii_case(&package_ref.name)
        })
        .ok_or_else(|| {
            format!(
                "Thunderstore no longer lists {}/{} for this game.",
                package_ref.namespace, package_ref.name
            )
        })?;
    let primary_version =
        latest_active_thunderstore_version(&package).map(|version| version.version_number.clone());
    let package_url = package.package_url.clone();
    let mut versions = package.versions;
    versions.retain(|version| version.is_active);
    versions.sort_by(|first, second| {
        second
            .date_created
            .cmp(&first.date_created)
            .then_with(|| second.version_number.cmp(&first.version_number))
    });

    Ok(versions
        .into_iter()
        .map(|version| OnlineModFileOption {
            id: version.version_number.clone(),
            name: format!("Version {}", version.version_number),
            version: Some(version.version_number.clone()),
            category: Some("Release".to_string()),
            description: non_empty_string(version.description.trim()),
            file_name: Some(format!("{}.zip", version.full_name)),
            file_size: version.file_size,
            uploaded_at: version.date_created,
            primary: primary_version.as_deref() == Some(version.version_number.as_str()),
            action: "direct".to_string(),
            download_page_url: package_url.clone(),
        })
        .collect())
}

fn nexus_file_size(file: &NexusFileRecord) -> Option<u64> {
    file.size_in_bytes.or_else(|| {
        file.size_kb
            .or(file.size)
            .map(|size_kb| size_kb.saturating_mul(1024))
    })
}

fn verify_nexus_declared_file_size(path: &Path, file: &NexusFileRecord) -> Result<(), String> {
    if let Some(expected_bytes) = file.size_in_bytes.filter(|size| *size > 0) {
        return verify_declared_download_integrity(
            path,
            Some(expected_bytes),
            None,
            &format!("Nexus file {}", file.file_id),
        );
    }
    let Some(expected_kb) = file.size_kb.or(file.size).filter(|size| *size > 0) else {
        return Ok(());
    };
    let expected_bytes = expected_kb.saturating_mul(1024);
    let actual_bytes = path.metadata().map_err(error_to_string)?.len();
    // Nexus v1 reports both legacy size fields in whole kilobytes. Allow one
    // KiB for provider rounding while still detecting incomplete or substituted
    // downloads; use size_in_bytes strictly whenever the API supplies it.
    if actual_bytes.abs_diff(expected_bytes) > 1024 {
        return Err(format!(
            "Nexus file {} failed its provider size check (reported {} KB, received {} bytes). The downloaded file was removed.",
            file.file_id, expected_kb, actual_bytes
        ));
    }
    Ok(())
}

fn nexus_file_uploaded_at(file: &NexusFileRecord) -> Option<String> {
    file.uploaded_time.clone().or_else(|| {
        file.uploaded_timestamp.and_then(|timestamp| {
            chrono::DateTime::<Utc>::from_timestamp(timestamp as i64, 0)
                .map(|value| value.to_rfc3339())
        })
    })
}

fn nexus_file_page_url(domain: &str, mod_id: u64, file_id: u64) -> String {
    format!(
        "{}/{}/mods/{}?tab=files&file_id={}",
        NEXUS_SITE_BASE,
        sanitize_url_path_segment(domain),
        mod_id,
        file_id
    )
}

fn nexus_manager_download_page_url(domain: &str, mod_id: u64, file_id: u64) -> String {
    format!(
        "{}/{}/mods/{}?tab=files&file_id={}&nmm=1",
        NEXUS_SITE_BASE,
        sanitize_url_path_segment(domain),
        mod_id,
        file_id
    )
}

#[allow(clippy::too_many_arguments)]
fn install_nexus_discovered_mod(
    store_root: &Path,
    profile: &GameProfile,
    mod_id: &str,
    settings: &AppSettings,
    version: Option<String>,
    supplied_provider_game_id: Option<&str>,
    selected_file_id: Option<&str>,
    install_target_id: Option<&str>,
) -> Result<InstallResult, String> {
    let api_key = settings.nexus_api_key().ok_or_else(|| {
        "Add your Nexus API key in Settings before installing Nexus mods.".to_string()
    })?;
    let (domain, nexus_mod_id) = parse_nexus_online_mod_id(mod_id)?;
    let provider_game_id = verified_discovery_provider_game(
        store_root,
        profile,
        "nexus",
        supplied_provider_game_id,
        Some(&domain),
    )?;
    let client = provider_client()?;
    let account = validate_nexus_api_key(api_key)?;
    if !account.is_premium {
        return Err(
            "Your Nexus key is valid, but Nexus only gives direct API download links to Premium accounts. Open the selected file's Nexus download page and use its browser download instead."
                .to_string(),
        );
    }
    let files = fetch_nexus_mod_files(&client, api_key, &domain, nexus_mod_id)?;
    let file = choose_nexus_file_for_profile(profile, &files, selected_file_id)?.ok_or_else(|| {
        "Nexus returned no installable files for this mod. Open the mod page and download manually."
            .to_string()
    })?;
    let links = fetch_nexus_download_links(&client, api_key, &domain, nexus_mod_id, file.file_id)?;
    let download_url = nexus_http_download_url(&links).ok_or_else(|| {
        "Nexus did not return a direct HTTP download link for this file. It may require opening the Nexus page or using an NXM handler."
            .to_string()
    })?;

    let mut visited_dependencies = HashSet::new();
    install_resolved_nexus_file(
        store_root,
        profile,
        &client,
        api_key,
        &account,
        &domain,
        nexus_mod_id,
        &file,
        &download_url,
        version,
        provider_game_id,
        install_target_id,
        None,
        &mut visited_dependencies,
        0,
    )
}

#[allow(clippy::too_many_arguments)]
fn install_resolved_nexus_file(
    store_root: &Path,
    profile: &GameProfile,
    client: &Client,
    api_key: &str,
    account: &NexusUserValidation,
    domain: &str,
    nexus_mod_id: u64,
    file: &NexusFileRecord,
    download_url: &str,
    version: Option<String>,
    provider_game_id: String,
    install_target_id: Option<&str>,
    dependency_target: Option<&InstallTargetOption>,
    visited_dependencies: &mut HashSet<String>,
    dependency_depth: usize,
) -> Result<InstallResult, String> {
    let (mut result, warnings) = run_install_graph_transaction(store_root, profile, || {
        install_resolved_nexus_file_inner(
            store_root,
            profile,
            client,
            api_key,
            account,
            domain,
            nexus_mod_id,
            file,
            download_url,
            version,
            provider_game_id,
            install_target_id,
            dependency_target,
            visited_dependencies,
            dependency_depth,
        )
    })?;
    result.warnings.extend(warnings);
    Ok(result)
}

#[allow(clippy::too_many_arguments)]
fn install_resolved_nexus_file_inner(
    store_root: &Path,
    profile: &GameProfile,
    client: &Client,
    api_key: &str,
    account: &NexusUserValidation,
    domain: &str,
    nexus_mod_id: u64,
    file: &NexusFileRecord,
    download_url: &str,
    version: Option<String>,
    provider_game_id: String,
    install_target_id: Option<&str>,
    dependency_target: Option<&InstallTargetOption>,
    visited_dependencies: &mut HashSet<String>,
    dependency_depth: usize,
) -> Result<InstallResult, String> {
    if dependency_depth > MAX_DEPENDENCY_DEPTH {
        return Err("Nexus dependency chain is too deep to install safely.".to_string());
    }
    let visit_key = dependency_target_visit_key(
        &format!("nexus:{}/{}", domain.to_lowercase(), nexus_mod_id),
        dependency_target,
    );
    if !visited_dependencies.insert(visit_key) {
        return Err(
            "Nexus returned a circular dependency chain. No duplicate package was installed."
                .to_string(),
        );
    }

    let details =
        fetch_nexus_mod_details(client, api_key, domain, nexus_mod_id).unwrap_or_default();
    let icon_url = nexus_mod_details_icon_url(&details);
    let mod_name =
        non_empty_string(details.name.trim()).unwrap_or_else(|| nexus_file_display_name(file));
    let provider_document = ProviderRouteDocument {
        provider: "Nexus Mods".to_string(),
        mod_id: format!("nexus:{domain}/{nexus_mod_id}"),
        mod_name: mod_name.clone(),
        text: [
            details.summary.as_str(),
            details.description.as_str(),
            file.description.as_deref().unwrap_or_default(),
        ]
        .into_iter()
        .filter(|value| !value.trim().is_empty())
        .collect::<Vec<_>>()
        .join("\n"),
    };
    let provided_runtime = runtime_id_for_provider_package(profile, "nexus", None, &mod_name);
    let requirements =
        fetch_nexus_mod_requirements(client, profile, domain, nexus_mod_id, Some(api_key))?;
    let mut dependencies = nexus_requirement_dependencies(profile, domain, &requirements);
    append_unique_dependencies(
        &mut dependencies,
        description_runtime_dependencies(
            profile,
            &provider_document.text,
            provided_runtime.as_deref(),
        ),
    );
    let archive_path =
        download_nexus_file(store_root, client, domain, nexus_mod_id, file, download_url)?;
    let package_id = format!("nexus:{}/{}", domain, nexus_mod_id);
    let source_identity = provider_source_identity(
        "nexus",
        package_id.clone(),
        version,
        Some(provider_game_id),
        "Nexus Mods discovery result and file download",
    );
    let scanned = scan_import_source(store_root, &archive_path)?;
    let analysis =
        analyze_scanned_archive_with_identity(scanned.clone(), profile, Some(source_identity));
    let install_source_path = analysis.archive_path.clone();
    let package_identity = analysis.package_identity.clone();
    let mut plan = analysis
        .recommended_plan
        .ok_or_else(|| analysis.compatibility.reason.clone())?;
    let route_outcome = prepare_package_install_routes(
        store_root,
        profile,
        &scanned,
        &provider_document,
        &mut plan,
    );

    append_unique_dependencies(&mut plan.dependencies, dependencies.clone());
    plan.warnings.extend(route_outcome.warnings);
    let install_targets =
        provider_plan_install_target_options(store_root, profile, &provider_document, &plan);
    let selected_install_target_id = if dependency_target.is_some() {
        select_dependency_install_target_id(&plan, &install_targets, dependency_target)?
    } else {
        provider_selected_install_target_id(
            store_root,
            profile,
            &provider_document,
            &install_targets,
            install_target_id,
        )
    };
    let selected_install_target = selected_install_target_id
        .as_deref()
        .and_then(|selected| install_targets.iter().find(|target| target.id == selected));
    let dependency_warnings = install_nexus_requirement_dependencies(
        store_root,
        profile,
        client,
        api_key,
        account,
        &plan.dependencies,
        visited_dependencies,
        dependency_depth + 1,
        selected_install_target,
    )?;
    plan.warnings.extend(dependency_warnings);

    if plan.adapter_id == "loose-files" || plan.requires_confirmation {
        return Err(format!(
            "{} downloaded, but Mod Garrison could not identify a safe automatic install layout.",
            nexus_file_display_name(file)
        ));
    }

    let dependency_string = Some(format!("{}#{}", package_id, file.file_id));
    let install_result = install_archive_impl_with_metadata(
        store_root,
        profile,
        &install_source_path,
        &plan,
        InstallOptions {
            metadata: InstallMetadata {
                archive_name: file
                    .file_name
                    .clone()
                    .or_else(|| Some(nexus_file_display_name(file))),
                package_id: Some(package_id),
                dependency_string,
                package_provider: Some("nexus".to_string()),
                package_version: file.version.clone(),
                provider_file_id: Some(file.file_id.to_string()),
                provider_variant: Some(nexus_file_display_name(file)),
                display_name: Some(nexus_file_display_name(file)),
                package_identity: Some(package_identity),
                runtime_id: None,
                icon_url,
                install_targets,
                selected_install_target_id,
            },
            resolve_dependencies: true,
            visited_dependencies,
            dependency_depth,
        },
    );
    if install_result.is_ok() {
        cleanup_successful_provider_artifacts(
            store_root,
            &archive_path,
            Path::new(&install_source_path),
        );
    }
    install_result
}

#[allow(clippy::too_many_arguments)]
fn install_nexus_requirement_dependencies(
    store_root: &Path,
    profile: &GameProfile,
    client: &Client,
    api_key: &str,
    account: &NexusUserValidation,
    dependencies: &[DependencySpec],
    visited_dependencies: &mut HashSet<String>,
    dependency_depth: usize,
    target: Option<&InstallTargetOption>,
) -> Result<Vec<String>, String> {
    if dependency_depth > MAX_DEPENDENCY_DEPTH {
        return Err("Nexus dependency chain is too deep to install safely.".to_string());
    }
    let mut warnings = Vec::new();

    for dependency in dependencies.iter().filter(|dependency| dependency.required) {
        let dependency =
            refresh_dependency_status_for_target(store_root, profile, dependency, target);
        if dependency.status == "already-installed" {
            continue;
        }

        if dependency.provider != "nexus" {
            match install_dependency_by_provider_for_target(
                store_root,
                profile,
                &dependency,
                visited_dependencies,
                dependency_depth,
                target,
            ) {
                Ok(mut installed_warnings) => warnings.append(&mut installed_warnings),
                Err(error) => {
                    return Err(format!(
                        "{} requires {}. Mod Garrison checked the game folder first, but the requirement is missing: {}",
                        profile_game_label(profile), dependency.name, error
                    ));
                }
            }
            continue;
        }

        let (dependency_domain, dependency_mod_id) = parse_nexus_online_mod_id(&dependency.id)?;
        verified_discovery_provider_game(
            store_root,
            profile,
            "nexus",
            Some(&dependency_domain),
            Some(&dependency_domain),
        )?;
        let visit_key = dependency_target_visit_key(
            &format!(
                "nexus:{}/{}",
                dependency_domain.to_lowercase(),
                dependency_mod_id
            ),
            target,
        );
        if visited_dependencies.contains(&visit_key) {
            continue;
        }
        if !account.is_premium {
            return Err(format!(
                "Missing required Nexus mod: {}. Confirm this dependency in Mod Garrison, then authorize its Slow download on Nexus before installing the parent mod.",
                dependency.name
            ));
        }

        let files = fetch_nexus_mod_files(client, api_key, &dependency_domain, dependency_mod_id)?;
        let dependency_file =
            choose_nexus_file_for_profile(profile, &files, None)?.ok_or_else(|| {
                format!(
                    "{} is required, but Nexus returned no supported main archive for it.",
                    dependency.name
                )
            })?;
        let links = fetch_nexus_download_links(
            client,
            api_key,
            &dependency_domain,
            dependency_mod_id,
            dependency_file.file_id,
        )?;
        let download_url = nexus_http_download_url(&links).ok_or_else(|| {
            format!(
                "Nexus did not return a direct download server for required mod {}.",
                dependency.name
            )
        })?;
        let result = install_resolved_nexus_file(
            store_root,
            profile,
            client,
            api_key,
            account,
            &dependency_domain,
            dependency_mod_id,
            &dependency_file,
            &download_url,
            dependency_file.version.clone(),
            dependency_domain.clone(),
            None,
            target,
            visited_dependencies,
            dependency_depth,
        )?;
        warnings.extend(result.warnings);
        warnings.push(format!("Installed required Nexus mod {}.", dependency.name));
    }

    Ok(warnings)
}

fn parse_nexus_online_mod_id(mod_id: &str) -> Result<(String, u64), String> {
    let raw = mod_id
        .strip_prefix("nexus:")
        .ok_or_else(|| format!("Invalid Nexus mod id: {}", mod_id))?;
    let (domain, id) = raw
        .split_once('/')
        .ok_or_else(|| format!("Invalid Nexus mod id: {}", mod_id))?;
    let nexus_mod_id = id
        .parse::<u64>()
        .map_err(|_| format!("Invalid Nexus mod id: {}", mod_id))?;
    Ok((sanitize_url_path_segment(domain), nexus_mod_id))
}

fn parse_nexus_nxm_link(raw: &str) -> Result<NexusNxmLink, String> {
    let invalid = || {
        "Nexus sent an invalid download handoff. Return to the file page and click Slow download again.".to_string()
    };
    let parsed = url::Url::parse(raw).map_err(|_| invalid())?;
    if parsed.scheme() != "nxm"
        || !parsed.username().is_empty()
        || parsed.password().is_some()
        || parsed.port().is_some()
        || parsed.fragment().is_some()
    {
        return Err(invalid());
    }

    let domain = parsed.host_str().ok_or_else(invalid)?.to_ascii_lowercase();
    if domain.is_empty()
        || domain.len() > 100
        || !sanitize_url_path_segment(&domain).eq_ignore_ascii_case(&domain)
    {
        return Err(invalid());
    }

    let segments = parsed
        .path_segments()
        .ok_or_else(invalid)?
        .filter(|segment| !segment.is_empty())
        .collect::<Vec<_>>();
    if segments.len() != 4 || segments[0] != "mods" || segments[2] != "files" {
        return Err(invalid());
    }
    let mod_id = segments[1].parse::<u64>().map_err(|_| invalid())?;
    let file_id = segments[3].parse::<u64>().map_err(|_| invalid())?;
    if mod_id == 0 || file_id == 0 {
        return Err(invalid());
    }

    let mut key = None;
    let mut expires = None;
    let mut user_id = None;
    for (name, value) in parsed.query_pairs() {
        match name.as_ref() {
            "key" => {
                if key.is_some() {
                    return Err(invalid());
                }
                key = Some(value.into_owned());
            }
            "expires" => {
                if expires.is_some() {
                    return Err(invalid());
                }
                expires = Some(value.into_owned());
            }
            "user_id" => {
                if user_id.is_some() {
                    return Err(invalid());
                }
                user_id = Some(value.into_owned());
            }
            _ => {}
        }
    }

    let key = key.ok_or_else(invalid)?;
    if key.is_empty() || key.len() > 1024 || key.chars().any(char::is_whitespace) {
        return Err(invalid());
    }
    let expires = expires
        .ok_or_else(invalid)?
        .parse::<i64>()
        .map_err(|_| invalid())?;
    if expires < Utc::now().timestamp() - 30 {
        return Err("This Nexus download authorization expired. Return to the file page and click Slow download again.".to_string());
    }
    let user_id = user_id
        .ok_or_else(invalid)?
        .parse::<u64>()
        .map_err(|_| invalid())?;
    if user_id == 0 {
        return Err(invalid());
    }

    Ok(NexusNxmLink {
        domain,
        mod_id,
        file_id,
        key,
        expires,
        user_id,
    })
}

fn pending_nexus_download_is_fresh(pending: &PendingNexusDownload, now: i64) -> bool {
    pending.created_at <= now + 60
        && now.saturating_sub(pending.created_at)
            <= NEXUS_PENDING_DOWNLOAD_TTL_MINUTES.saturating_mul(60)
}

fn store_pending_nexus_download(
    store_root: &Path,
    pending: PendingNexusDownload,
    now: i64,
) -> Result<(), String> {
    let path = pending_nexus_downloads_path(store_root);
    let mut store = read_store::<PendingNexusDownload>(&path).map_err(error_to_string)?;
    store.items.retain(|existing| {
        pending_nexus_download_is_fresh(existing, now)
            && !(existing.domain.eq_ignore_ascii_case(&pending.domain)
                && existing.mod_id == pending.mod_id
                && existing.file_id == pending.file_id)
    });
    store.items.push(pending);
    write_store(&path, &store).map_err(error_to_string)
}

fn find_pending_nexus_download(
    store_root: &Path,
    nxm: &NexusNxmLink,
) -> Result<PendingNexusDownload, String> {
    let path = pending_nexus_downloads_path(store_root);
    let mut store = read_store::<PendingNexusDownload>(&path).map_err(error_to_string)?;
    let profiles =
        read_store::<GameProfile>(&profiles_path(store_root)).map_err(error_to_string)?;
    let profile_ids = profiles
        .items
        .iter()
        .map(|profile| profile.id.as_str())
        .collect::<HashSet<_>>();
    let now = Utc::now().timestamp();
    let original_len = store.items.len();
    store.items.retain(|pending| {
        pending_nexus_download_is_fresh(pending, now)
            && profile_ids.contains(pending.profile_id.as_str())
    });
    if store.items.len() != original_len {
        write_store(&path, &store).map_err(error_to_string)?;
    }

    store
        .items
        .into_iter()
        .filter(|pending| {
            pending.domain.eq_ignore_ascii_case(&nxm.domain)
                && pending.mod_id == nxm.mod_id
                && pending.file_id == nxm.file_id
        })
        .max_by_key(|pending| pending.created_at)
        .ok_or_else(|| {
            "Mod Garrison did not request this Nexus download, or the request expired. Start it again from Discovery."
                .to_string()
        })
}

fn remove_pending_nexus_downloads_for_profile(
    store_root: &Path,
    profile_id: &str,
) -> Result<(), String> {
    let path = pending_nexus_downloads_path(store_root);
    let mut store = read_store::<PendingNexusDownload>(&path).map_err(error_to_string)?;
    let original_len = store.items.len();
    store
        .items
        .retain(|pending| pending.profile_id != profile_id);
    if store.items.len() != original_len {
        write_store(&path, &store).map_err(error_to_string)?;
    }
    Ok(())
}

fn remove_pending_nexus_download(store_root: &Path, nxm: &NexusNxmLink) -> Result<(), String> {
    let path = pending_nexus_downloads_path(store_root);
    let mut store = read_store::<PendingNexusDownload>(&path).map_err(error_to_string)?;
    store.items.retain(|pending| {
        !(pending.domain.eq_ignore_ascii_case(&nxm.domain)
            && pending.mod_id == nxm.mod_id
            && pending.file_id == nxm.file_id)
    });
    write_store(&path, &store).map_err(error_to_string)
}

fn fetch_nexus_mod_files(
    client: &Client,
    api_key: &str,
    domain: &str,
    mod_id: u64,
) -> Result<Vec<NexusFileRecord>, String> {
    let url = format!(
        "https://api.nexusmods.com/v1/games/{}/mods/{}/files.json",
        sanitize_url_path_segment(domain),
        mod_id
    );
    let response = nexus_api_get(client, &url, api_key)
        .send()
        .map_err(error_to_string)?
        .error_for_status()
        .map_err(error_to_string)?
        .json::<NexusFilesResponse>()
        .map_err(error_to_string)?;

    Ok(response.files)
}

fn fetch_nexus_download_links(
    client: &Client,
    api_key: &str,
    domain: &str,
    mod_id: u64,
    file_id: u64,
) -> Result<Vec<NexusDownloadLink>, String> {
    let url = format!(
        "https://api.nexusmods.com/v1/games/{}/mods/{}/files/{}/download_link.json",
        sanitize_url_path_segment(domain),
        mod_id,
        file_id
    );
    let response = nexus_api_get(client, &url, api_key)
        .send()
        .map_err(error_to_string)?;
    if response.status().as_u16() == 403 {
        return Err(
            "Nexus requires this download to be started on its website. Choose the file and use the browser handoff."
                .to_string(),
        );
    }
    response
        .error_for_status()
        .map_err(error_to_string)?
        .json::<Vec<NexusDownloadLink>>()
        .map_err(error_to_string)
}

fn fetch_nexus_download_links_with_nxm(
    client: &Client,
    api_key: &str,
    nxm: &NexusNxmLink,
) -> Result<Vec<NexusDownloadLink>, String> {
    let url = format!(
        "https://api.nexusmods.com/v1/games/{}/mods/{}/files/{}/download_link.json",
        sanitize_url_path_segment(&nxm.domain),
        nxm.mod_id,
        nxm.file_id
    );
    let expires = nxm.expires.to_string();
    let user_id = nxm.user_id.to_string();
    let response = nexus_api_get(client, &url, api_key)
        .query(&[
            ("key", nxm.key.as_str()),
            ("expires", expires.as_str()),
            ("user_id", user_id.as_str()),
        ])
        .send()
        .map_err(|_| "Could not contact Nexus to finish the authorized download.".to_string())?;
    let status = response.status();
    if !status.is_success() {
        return Err(if status.as_u16() == 403 {
            "Nexus rejected this download authorization. Return to the file page and click Slow download again."
                .to_string()
        } else {
            format!(
                "Nexus could not finish the authorized download (HTTP {}). Try again.",
                status.as_u16()
            )
        });
    }

    response.json::<Vec<NexusDownloadLink>>().map_err(|_| {
        "Nexus returned invalid download-server data. Try the download again.".to_string()
    })
}

fn nexus_api_get(client: &Client, url: &str, api_key: &str) -> reqwest::blocking::RequestBuilder {
    client
        .get(url)
        .header("apikey", api_key)
        .header("Application-Name", "Mod Garrison")
        .header("Application-Version", env!("CARGO_PKG_VERSION"))
        .header("Accept", "application/json")
}

fn validate_nexus_api_key(api_key: &str) -> Result<NexusUserValidation, String> {
    let fingerprint = nexus_api_key_fingerprint(api_key);
    if let Ok(cache) = NEXUS_KEY_VALIDATION_CACHE
        .get_or_init(|| Mutex::new(None))
        .lock()
    {
        if let Some(entry) = cache.as_ref() {
            if entry.fingerprint == fingerprint
                && entry.fetched_at.elapsed()
                    < Duration::from_secs(NEXUS_KEY_VALIDATION_CACHE_MINUTES * 60)
            {
                return Ok(entry.account.clone());
            }
        }
    }

    let client = provider_client()?;
    let response = nexus_api_get(
        &client,
        "https://api.nexusmods.com/v1/users/validate.json",
        api_key,
    )
    .send()
    .map_err(|error| format!("Could not validate the Nexus API key: {error}"))?;

    if response.status().is_success() {
        let account = response.json::<NexusUserValidation>().map_err(|error| {
            format!("Nexus validated the key but returned invalid account data: {error}")
        })?;
        if let Ok(mut cache) = NEXUS_KEY_VALIDATION_CACHE
            .get_or_init(|| Mutex::new(None))
            .lock()
        {
            *cache = Some(NexusKeyValidationCacheEntry {
                fetched_at: Instant::now(),
                fingerprint,
                account: account.clone(),
            });
        }
        return Ok(account);
    }
    if response.status().as_u16() == 401 || response.status().as_u16() == 403 {
        return Err(
            "Nexus Mods rejected this API key. Request a personal API key and paste the full value."
                .to_string(),
        );
    }

    Err(format!(
        "Nexus Mods could not validate the API key right now (HTTP {}). Please try again.",
        response.status()
    ))
}

fn nexus_api_key_fingerprint(api_key: &str) -> String {
    hex::encode(Sha256::digest(api_key.trim().as_bytes()))
}

fn clear_stale_nexus_key_validation(value: Option<&str>) {
    let Ok(mut cache) = NEXUS_KEY_VALIDATION_CACHE
        .get_or_init(|| Mutex::new(None))
        .lock()
    else {
        return;
    };
    let expected = value.map(nexus_api_key_fingerprint);
    if cache
        .as_ref()
        .is_some_and(|entry| Some(entry.fingerprint.as_str()) != expected.as_deref())
        || value.is_none()
    {
        *cache = None;
    }
}

fn choose_nexus_file_for_profile(
    profile: &GameProfile,
    files: &[NexusFileRecord],
    selected_file_id: Option<&str>,
) -> Result<Option<NexusFileRecord>, String> {
    if !enshrouded::is_profile(profile) {
        return choose_requested_nexus_file(files, selected_file_id);
    }
    let server = !Path::new(&profile.game_path)
        .join("enshrouded.exe")
        .is_file();
    let file_scope = |file: &NexusFileRecord| {
        let title = format!(
            "{} {}",
            file.name,
            file.file_name.as_deref().unwrap_or_default()
        );
        let words = ascii_requirement_text(&title);
        if words
            .split_whitespace()
            .any(|word| matches!(word, "server" | "dedicated"))
        {
            Some(true)
        } else if words.split_whitespace().any(|word| word == "client") {
            Some(false)
        } else {
            None
        }
    };
    if selected_file_id.is_some() {
        let file = choose_requested_nexus_file(files, selected_file_id)?;
        if file
            .as_ref()
            .is_some_and(|file| file_scope(file).is_some_and(|scope| scope != server))
        {
            return Err("The selected Enshrouded file targets a different client/server installation. The game folder was not changed.".to_string());
        }
        return Ok(file);
    }
    let matching = files
        .iter()
        .filter(|file| file_scope(file) == Some(server))
        .cloned()
        .collect::<Vec<_>>();
    if let Some(file) = choose_nexus_file(&matching) {
        return Ok(Some(file));
    }
    let generic = files
        .iter()
        .filter(|file| file_scope(file).is_none())
        .cloned()
        .collect::<Vec<_>>();
    Ok(choose_nexus_file(&generic))
}

fn choose_requested_nexus_file(
    files: &[NexusFileRecord],
    selected_file_id: Option<&str>,
) -> Result<Option<NexusFileRecord>, String> {
    let Some(selected_file_id) = selected_file_id else {
        return Ok(choose_nexus_file(files));
    };
    let parsed_file_id = selected_file_id
        .parse::<u64>()
        .map_err(|_| "The selected Nexus file id is invalid.".to_string())?;
    let file = files
        .iter()
        .find(|file| file.file_id == parsed_file_id)
        .cloned()
        .ok_or_else(|| "The selected Nexus file is no longer available.".to_string())?;
    if !nexus_file_supported(&file) {
        return Err(
            "The selected Nexus file is not a ZIP, 7Z, or RAR archive that Mod Garrison can install."
                .to_string(),
        );
    }
    Ok(Some(file))
}

fn choose_nexus_file(files: &[NexusFileRecord]) -> Option<NexusFileRecord> {
    files
        .iter()
        .filter(|file| nexus_file_supported(file))
        .max_by_key(|file| {
            let category_score = nexus_file_category_score(file);
            let primary_score = if file.is_primary.unwrap_or(false) {
                1
            } else {
                0
            };
            let upload_time = file.uploaded_timestamp.unwrap_or(0);
            (category_score, primary_score, upload_time)
        })
        .cloned()
}

fn nexus_file_supported(file: &NexusFileRecord) -> bool {
    file.file_name
        .as_deref()
        .map(|name| {
            let lower = name.to_lowercase();
            lower.ends_with(".zip") || lower.ends_with(".7z") || lower.ends_with(".rar")
        })
        .unwrap_or(true)
}

fn nexus_file_category_score(file: &NexusFileRecord) -> u8 {
    let category = file
        .category_name
        .as_deref()
        .unwrap_or_default()
        .to_lowercase();
    if file.is_primary.unwrap_or(false) || category.contains("main") {
        3
    } else if category.contains("update") {
        2
    } else if category.contains("optional") {
        1
    } else if category.contains("old") {
        0
    } else {
        2
    }
}

fn nexus_http_download_url(links: &[NexusDownloadLink]) -> Option<String> {
    links.iter().find_map(|link| {
        let uri = link.uri.as_deref()?.trim();
        if uri.starts_with("http://") || uri.starts_with("https://") {
            Some(uri.to_string())
        } else {
            None
        }
    })
}

fn download_nexus_file(
    store_root: &Path,
    client: &Client,
    domain: &str,
    mod_id: u64,
    file: &NexusFileRecord,
    download_url: &str,
) -> Result<PathBuf, String> {
    let file_name = file
        .file_name
        .as_deref()
        .or_else(|| {
            let uri_name = download_url
                .split('/')
                .next_back()
                .and_then(|name| name.split('?').next());
            uri_name.filter(|name| !name.trim().is_empty())
        })
        .unwrap_or("nexus-mod.zip");
    let safe_name = sanitize_file_segment(file_name);
    let download_dir = store_root.join("downloads").join("nexus").join(format!(
        "{}-{}-{}",
        sanitize_file_segment(domain),
        mod_id,
        file.file_id
    ));
    fs::create_dir_all(&download_dir).map_err(error_to_string)?;
    let archive_path = download_dir.join(format!("{}-{}", Uuid::new_v4(), safe_name));
    download_url_to_file(client, download_url, &archive_path)?;
    if let Err(error) = verify_nexus_declared_file_size(&archive_path, file) {
        remove_download_artifact(&archive_path);
        return Err(error);
    }
    Ok(archive_path)
}

fn nexus_file_display_name(file: &NexusFileRecord) -> String {
    non_empty_string(file.name.trim())
        .or_else(|| {
            file.file_name
                .as_deref()
                .and_then(|name| non_empty_string(name.trim()))
        })
        .unwrap_or_else(|| format!("Nexus file {}", file.file_id))
}

fn install_thunderstore_discovered_mod(
    store_root: &Path,
    profile: &GameProfile,
    mod_id: &str,
    version: Option<String>,
    supplied_provider_game_id: Option<&str>,
    install_target_id: Option<&str>,
) -> Result<InstallResult, String> {
    let raw_id = mod_id
        .strip_prefix("thunderstore:")
        .ok_or_else(|| format!("Invalid Thunderstore mod id: {}", mod_id))?;
    let package_ref = parse_thunderstore_token(raw_id, version.as_deref()).ok_or_else(|| {
        format!(
            "Could not parse Thunderstore package reference from {}.",
            mod_id
        )
    })?;
    let provider_game_id = verified_discovery_provider_game(
        store_root,
        profile,
        "thunderstore",
        supplied_provider_game_id,
        supplied_provider_game_id,
    )?;
    let package_version = fetch_thunderstore_package_version(&package_ref)?;
    let resolved_ref = ThunderstorePackageRef {
        namespace: package_ref.namespace.clone(),
        name: package_ref.name.clone(),
        version: Some(package_version.version_number.clone()),
    };
    let package_id = thunderstore_package_id(&package_ref);
    let dependency_string =
        thunderstore_dependency_string(&package_ref, &package_version.version_number);
    let provider_document = thunderstore_route_document(&resolved_ref, &package_version);
    let provided_runtime = runtime_id_for_provider_package(
        profile,
        "thunderstore",
        Some(&package_ref.namespace),
        &package_ref.name,
    );

    if thunderstore_package_installed(
        store_root,
        profile,
        &package_id,
        Some(&dependency_string),
        Some(&package_version.version_number),
    ) {
        return Err(format!(
            "{} is already installed in this profile.",
            humanize_mod_display_name(&package_version.full_name)
        ));
    }

    let archive_path = download_thunderstore_package(store_root, &resolved_ref, &package_version)?;
    let source_identity = provider_source_identity(
        "thunderstore",
        package_id.clone(),
        Some(package_version.version_number.clone()),
        Some(provider_game_id),
        "Thunderstore community catalogue and package manifest",
    );
    let scanned = scan_zip_archive(&archive_path)?;
    let analysis =
        analyze_scanned_archive_with_identity(scanned.clone(), profile, Some(source_identity));
    let package_identity = analysis.package_identity.clone();
    let mut plan = analysis
        .recommended_plan
        .ok_or_else(|| analysis.compatibility.reason.clone())?;
    let route_outcome = prepare_package_install_routes(
        store_root,
        profile,
        &scanned,
        &provider_document,
        &mut plan,
    );

    for dependency_string in &package_version.dependencies {
        let parsed = parse_thunderstore_dependency(dependency_string);
        if !plan.dependencies.iter().any(|item| item.id == parsed.id) {
            plan.dependencies.push(parsed);
        }
    }
    append_unique_dependencies(
        &mut plan.dependencies,
        description_runtime_dependencies(
            profile,
            &provider_document.text,
            provided_runtime.as_deref(),
        ),
    );
    plan.warnings.extend(route_outcome.warnings);
    let install_targets =
        provider_plan_install_target_options(store_root, profile, &provider_document, &plan);
    let selected_install_target_id = provider_selected_install_target_id(
        store_root,
        profile,
        &provider_document,
        &install_targets,
        install_target_id,
    );

    if plan.adapter_id == "loose-files" || plan.requires_confirmation {
        return Err(format!(
            "{} downloaded, but Mod Garrison could not identify a safe automatic install layout.",
            package_version.full_name
        ));
    }

    let archive_path_string = archive_path.to_string_lossy().to_string();
    let mut visited_dependencies = HashSet::new();
    install_archive_impl_with_metadata(
        store_root,
        profile,
        &archive_path_string,
        &plan,
        InstallOptions {
            metadata: InstallMetadata {
                archive_name: Some(package_version.full_name.clone()),
                package_id: Some(package_id),
                dependency_string: Some(dependency_string),
                package_provider: Some("thunderstore".to_string()),
                package_version: Some(package_version.version_number.clone()),
                provider_file_id: None,
                provider_variant: Some(package_version.version_number.clone()),
                display_name: Some(package_version.full_name),
                package_identity: Some(package_identity),
                runtime_id: None,
                icon_url: package_version.icon.clone(),
                install_targets,
                selected_install_target_id,
            },
            resolve_dependencies: true,
            visited_dependencies: &mut visited_dependencies,
            dependency_depth: 0,
        },
    )
}

fn install_thunderstore_dependency(
    store_root: &Path,
    profile: &GameProfile,
    dependency: &DependencySpec,
    visited_dependencies: &mut HashSet<String>,
    dependency_depth: usize,
    target: Option<&InstallTargetOption>,
) -> Result<Vec<String>, String> {
    if dependency_depth > MAX_DEPENDENCY_DEPTH {
        return Err("Dependency chain is too deep to install safely.".to_string());
    }

    let package_ref = parse_thunderstore_ref(dependency)?;
    let visit_key = dependency_target_visit_key(&thunderstore_visit_key(&package_ref), target);
    if !visited_dependencies.insert(visit_key) {
        return Ok(Vec::new());
    }

    if dependency_already_available_for_target(store_root, profile, dependency, target) {
        return Ok(Vec::new());
    }

    let package_version = fetch_thunderstore_package_version(&package_ref)?;
    let resolved_ref = ThunderstorePackageRef {
        namespace: package_ref.namespace.clone(),
        name: package_ref.name.clone(),
        version: Some(package_version.version_number.clone()),
    };
    visited_dependencies.insert(dependency_target_visit_key(
        &thunderstore_visit_key(&resolved_ref),
        target,
    ));
    let package_id = thunderstore_package_id(&package_ref);
    let dependency_string =
        thunderstore_dependency_string(&package_ref, &package_version.version_number);
    let provider_document = thunderstore_route_document(&resolved_ref, &package_version);
    let provided_runtime = runtime_id_for_provider_package(
        profile,
        "thunderstore",
        Some(&package_ref.namespace),
        &package_ref.name,
    );

    let installed_records = read_store::<InstalledModRecord>(&installed_mods_path(store_root))
        .map_err(error_to_string)?;
    let replacement_id = match dependency_install_disposition_for_target(
        &installed_records.items,
        profile,
        dependency,
        &package_id,
        &package_version.version_number,
        target,
    )? {
        DependencyInstallDisposition::AlreadySatisfied => return Ok(Vec::new()),
        DependencyInstallDisposition::InstallNew => None,
        DependencyInstallDisposition::Replace(installed_mod_id) => Some(installed_mod_id),
    };

    let archive_path = download_thunderstore_package(store_root, &resolved_ref, &package_version)?;
    let scanned = scan_zip_archive(&archive_path)?;
    let analysis = analyze_scanned_archive(scanned.clone(), profile);
    let mut plan = analysis.recommended_plan.ok_or_else(|| {
        format!(
            "Could not find a safe install route for dependency {}.",
            dependency.name
        )
    })?;
    let route_outcome = prepare_package_install_routes(
        store_root,
        profile,
        &scanned,
        &provider_document,
        &mut plan,
    );

    for dependency_string in &package_version.dependencies {
        let parsed = parse_thunderstore_dependency(dependency_string);
        if !plan.dependencies.iter().any(|item| item.id == parsed.id) {
            plan.dependencies.push(parsed);
        }
    }
    append_unique_dependencies(
        &mut plan.dependencies,
        description_runtime_dependencies(
            profile,
            &provider_document.text,
            provided_runtime.as_deref(),
        ),
    );
    plan.warnings.extend(route_outcome.warnings);
    let install_targets =
        provider_plan_install_target_options(store_root, profile, &provider_document, &plan);
    let selected_install_target_id =
        select_dependency_install_target_id(&plan, &install_targets, target)?;

    if plan.adapter_id == "loose-files" || plan.requires_confirmation {
        return Err(format!(
            "Dependency {} downloaded, but Mod Garrison could not identify a safe automatic install layout.",
            dependency.name
        ));
    }

    let archive_path_string = archive_path.to_string_lossy().to_string();
    let result = replace_installed_mod_transaction(
        store_root,
        profile,
        replacement_id.as_deref(),
        &package_id,
        || {
            install_archive_impl_with_metadata(
                store_root,
                profile,
                &archive_path_string,
                &plan,
                InstallOptions {
                    metadata: InstallMetadata {
                        archive_name: Some(package_version.full_name.clone()),
                        package_id: Some(package_id.clone()),
                        dependency_string: Some(dependency_string),
                        package_provider: Some("thunderstore".to_string()),
                        package_version: Some(package_version.version_number.clone()),
                        display_name: Some(package_version.full_name.clone()),
                        package_identity: None,
                        runtime_id: runtime_id_for_dependency(profile, dependency),
                        icon_url: package_version.icon.clone(),
                        install_targets,
                        selected_install_target_id,
                        ..InstallMetadata::default()
                    },
                    resolve_dependencies: true,
                    visited_dependencies,
                    dependency_depth,
                },
            )
        },
    )?;

    let mut warnings = result.warnings;
    warnings.push(format!(
        "Installed dependency {} {}.",
        package_version.full_name, package_version.version_number
    ));
    Ok(warnings)
}

fn install_release_dependency(
    store_root: &Path,
    profile: &GameProfile,
    dependency: &DependencySpec,
    release_ref: ReleaseDependencyRef,
    visited_dependencies: &mut HashSet<String>,
    dependency_depth: usize,
    target: Option<&InstallTargetOption>,
) -> Result<Vec<String>, String> {
    if dependency_depth > MAX_DEPENDENCY_DEPTH {
        return Err("Dependency chain is too deep to install safely.".to_string());
    }

    let visit_key = dependency_target_visit_key(
        &format!("release:{}", release_ref.source_key.to_lowercase()),
        target,
    );
    if !visited_dependencies.insert(visit_key) {
        return Ok(Vec::new());
    }

    if dependency_already_available_for_target(store_root, profile, dependency, target) {
        return Ok(Vec::new());
    }

    let installed_records = read_store::<InstalledModRecord>(&installed_mods_path(store_root))
        .map_err(error_to_string)?;
    let replacement_id = match dependency_install_disposition_for_target(
        &installed_records.items,
        profile,
        dependency,
        &release_ref.source_key,
        &release_ref.version,
        target,
    )? {
        DependencyInstallDisposition::AlreadySatisfied => return Ok(Vec::new()),
        DependencyInstallDisposition::InstallNew => None,
        DependencyInstallDisposition::Replace(installed_mod_id) => Some(installed_mod_id),
    };

    let archive_path = download_release_archive(store_root, dependency, &release_ref)?;
    let scanned = scan_zip_archive(&archive_path)?;
    let analysis = analyze_scanned_archive(scanned, profile);
    let plan = analysis.recommended_plan.ok_or_else(|| {
        format!(
            "Could not find a safe install route for dependency {}.",
            dependency.name
        )
    })?;

    if plan.adapter_id == "loose-files" || plan.requires_confirmation {
        return Err(format!(
            "Dependency {} downloaded, but Mod Garrison could not identify a safe automatic install layout.",
            dependency.name
        ));
    }
    let install_targets = plan_install_target_options(profile, &plan);
    let selected_install_target_id =
        select_dependency_install_target_id(&plan, &install_targets, target)?;

    let archive_path_string = archive_path.to_string_lossy().to_string();
    let result = replace_installed_mod_transaction(
        store_root,
        profile,
        replacement_id.as_deref(),
        &release_ref.source_key,
        || {
            install_archive_impl_with_metadata(
                store_root,
                profile,
                &archive_path_string,
                &plan,
                InstallOptions {
                    metadata: InstallMetadata {
                        archive_name: Some(release_ref.display_name.clone()),
                        package_id: Some(release_ref.source_key.clone()),
                        dependency_string: Some(format!(
                            "{}@{}",
                            release_ref.source_key, release_ref.version
                        )),
                        package_provider: Some(dependency.provider.clone()),
                        package_version: Some(release_ref.version.clone()),
                        display_name: Some(release_ref.display_name.clone()),
                        package_identity: None,
                        runtime_id: runtime_id_for_dependency(profile, dependency),
                        icon_url: None,
                        install_targets,
                        selected_install_target_id,
                        ..InstallMetadata::default()
                    },
                    resolve_dependencies: true,
                    visited_dependencies,
                    dependency_depth,
                },
            )
        },
    )?;

    let mut warnings = result.warnings;
    warnings.push(format!(
        "Installed dependency {} {}.",
        release_ref.display_name, release_ref.version
    ));
    Ok(warnings)
}

fn refresh_dependency_status(
    store_root: &Path,
    profile: &GameProfile,
    dependency: &DependencySpec,
) -> DependencySpec {
    refresh_dependency_status_with_availability(
        dependency,
        dependency_availability(store_root, profile, dependency),
    )
}

fn refresh_dependency_status_for_target(
    store_root: &Path,
    profile: &GameProfile,
    dependency: &DependencySpec,
    target: Option<&InstallTargetOption>,
) -> DependencySpec {
    let availability = target
        .map(|target| dependency_availability_for_target(store_root, profile, dependency, target))
        .unwrap_or_else(|| dependency_availability(store_root, profile, dependency));
    refresh_dependency_status_with_availability(dependency, availability)
}

fn refresh_dependency_status_with_availability(
    dependency: &DependencySpec,
    availability: DependencyAvailability,
) -> DependencySpec {
    const UNVERIFIED_VERSION_NOTE: &str =
        "The component is present, but its installed version could not be verified.";
    let mut refreshed = dependency.clone();
    refreshed.notes = dependency
        .notes
        .as_deref()
        .and_then(|notes| non_empty_string(notes.replace(UNVERIFIED_VERSION_NOTE, "").trim()));
    if availability.available {
        refreshed.status = "already-installed".to_string();
        if dependency.version.is_some() && !availability.version_verified {
            refreshed.notes = Some(match refreshed.notes.take() {
                Some(existing) => format!("{existing} {UNVERIFIED_VERSION_NOTE}"),
                None => UNVERIFIED_VERSION_NOTE.to_string(),
            });
        }
    } else {
        refreshed.status = "missing".to_string();
    }
    refreshed
}

#[derive(Debug, Clone, Copy, Default)]
struct DependencyAvailability {
    available: bool,
    version_verified: bool,
}

fn dependency_already_available(
    store_root: &Path,
    profile: &GameProfile,
    dependency: &DependencySpec,
) -> bool {
    dependency_availability(store_root, profile, dependency).available
}

fn dependency_already_available_for_target(
    store_root: &Path,
    profile: &GameProfile,
    dependency: &DependencySpec,
    target: Option<&InstallTargetOption>,
) -> bool {
    target
        .map(|target| {
            dependency_availability_for_target(store_root, profile, dependency, target).available
        })
        .unwrap_or_else(|| dependency_already_available(store_root, profile, dependency))
}

fn dependency_availability(
    store_root: &Path,
    profile: &GameProfile,
    dependency: &DependencySpec,
) -> DependencyAvailability {
    let installed_store = read_store::<InstalledModRecord>(&installed_mods_path(store_root)).ok();
    if let Some(runtime) = runtime_from_dependency(dependency) {
        let records = installed_store
            .as_ref()
            .map(|store| {
                store
                    .items
                    .iter()
                    .filter(|record| {
                        record.profile_id == profile.id
                            && record.enabled
                            && record.last_status != "removed"
                            && runtime_record_matches(record, runtime)
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        if let Some(required) = dependency.version.as_deref() {
            if records.iter().any(|record| {
                record
                    .package_version
                    .as_deref()
                    .is_some_and(|installed| version_requirement_matches(required, installed))
            }) {
                return DependencyAvailability {
                    available: true,
                    version_verified: true,
                };
            }
            if records
                .iter()
                .any(|record| record.package_version.is_some())
            {
                return DependencyAvailability {
                    available: false,
                    version_verified: true,
                };
            }
        }
        if !records.is_empty() || runtime_installed(profile, runtime) {
            return DependencyAvailability {
                available: true,
                version_verified: dependency.version.is_none(),
            };
        }
    }

    if dependency.provider == "nexus" {
        let Some(store) = installed_store.as_ref() else {
            return DependencyAvailability::default();
        };
        return availability_from_records(
            store.items.iter().filter(|record| {
                record.profile_id == profile.id
                    && record.enabled
                    && record.last_status != "removed"
                    && record
                        .package_id
                        .as_deref()
                        .is_some_and(|package_id| package_id.eq_ignore_ascii_case(&dependency.id))
            }),
            dependency.version.as_deref(),
        );
    }

    if dependency.provider != "thunderstore" {
        if let Some(store) = installed_store.as_ref() {
            let installed = installed_dependency_match(&store.items, profile, dependency);
            if let Some(record) = installed.satisfying {
                return DependencyAvailability {
                    available: true,
                    version_verified: dependency.version.is_none()
                        || record.package_version.is_some(),
                };
            }
            if let Some(record) = installed.same_package {
                return DependencyAvailability {
                    available: false,
                    version_verified: record.package_version.is_some(),
                };
            }
        }
        return DependencyAvailability::default();
    }

    let Ok(package_ref) = parse_thunderstore_ref(dependency) else {
        return DependencyAvailability::default();
    };

    if thunderstore_runtime_available(profile, &package_ref) {
        return DependencyAvailability {
            available: true,
            version_verified: dependency.version.is_none(),
        };
    }

    let package_id = thunderstore_package_id(&package_ref);
    let dependency_string = package_ref
        .version
        .as_ref()
        .map(|version| thunderstore_dependency_string(&package_ref, version));

    let Some(store) = installed_store.as_ref() else {
        return DependencyAvailability::default();
    };
    availability_from_records(
        store.items.iter().filter(|record| {
            record.profile_id == profile.id
                && record.enabled
                && record.last_status != "removed"
                && (record
                    .package_id
                    .as_deref()
                    .is_some_and(|installed| installed.eq_ignore_ascii_case(&package_id))
                    || dependency_string.as_deref().is_some_and(|expected| {
                        record
                            .dependency_string
                            .as_deref()
                            .is_some_and(|installed| installed.eq_ignore_ascii_case(expected))
                    }))
        }),
        dependency.version.as_deref(),
    )
}

fn dependency_availability_for_target(
    store_root: &Path,
    profile: &GameProfile,
    dependency: &DependencySpec,
    target: &InstallTargetOption,
) -> DependencyAvailability {
    let installed_store = read_store::<InstalledModRecord>(&installed_mods_path(store_root)).ok();
    if let Some(runtime) = runtime_id_for_dependency(profile, dependency) {
        let records = installed_store
            .as_ref()
            .map(|store| {
                store
                    .items
                    .iter()
                    .filter(|record| {
                        record.profile_id == profile.id
                            && record.enabled
                            && record.last_status != "removed"
                            && runtime_record_matches(record, &runtime)
                            && record_payload_covers_install_target(record, target)
                    })
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        if let Some(required) = dependency.version.as_deref() {
            if records.iter().any(|record| {
                record
                    .package_version
                    .as_deref()
                    .is_some_and(|installed| version_requirement_matches(required, installed))
            }) {
                return DependencyAvailability {
                    available: true,
                    version_verified: true,
                };
            }
            if records
                .iter()
                .any(|record| record.package_version.is_some())
            {
                return DependencyAvailability {
                    available: false,
                    version_verified: true,
                };
            }
        }
        return DependencyAvailability {
            available: !records.is_empty()
                || runtime_installed_for_target(profile, &runtime, target),
            version_verified: dependency.version.is_none(),
        };
    }

    let Some(store) = installed_store.as_ref() else {
        return DependencyAvailability::default();
    };
    if dependency.provider == "nexus" {
        return availability_from_records(
            store.items.iter().filter(|record| {
                record.profile_id == profile.id
                    && record.enabled
                    && record.last_status != "removed"
                    && record
                        .package_id
                        .as_deref()
                        .is_some_and(|package_id| package_id.eq_ignore_ascii_case(&dependency.id))
                    && record_payload_covers_install_target(record, target)
            }),
            dependency.version.as_deref(),
        );
    }

    if dependency.provider != "thunderstore" {
        let installed =
            installed_dependency_match_for_target(&store.items, profile, dependency, Some(target));
        if let Some(record) = installed.satisfying {
            return DependencyAvailability {
                available: true,
                version_verified: dependency.version.is_none() || record.package_version.is_some(),
            };
        }
        if let Some(record) = installed.same_package {
            return DependencyAvailability {
                available: false,
                version_verified: record.package_version.is_some(),
            };
        }
        return DependencyAvailability::default();
    }

    let Ok(package_ref) = parse_thunderstore_ref(dependency) else {
        return DependencyAvailability::default();
    };
    let package_id = thunderstore_package_id(&package_ref);
    let dependency_string = package_ref
        .version
        .as_ref()
        .map(|version| thunderstore_dependency_string(&package_ref, version));
    availability_from_records(
        store.items.iter().filter(|record| {
            record.profile_id == profile.id
                && record.enabled
                && record.last_status != "removed"
                && (record
                    .package_id
                    .as_deref()
                    .is_some_and(|installed| installed.eq_ignore_ascii_case(&package_id))
                    || dependency_string.as_deref().is_some_and(|expected| {
                        record
                            .dependency_string
                            .as_deref()
                            .is_some_and(|installed| installed.eq_ignore_ascii_case(expected))
                    }))
                && record_payload_covers_install_target(record, target)
        }),
        dependency.version.as_deref(),
    )
}

fn availability_from_records<'a>(
    records: impl Iterator<Item = &'a InstalledModRecord>,
    required_version: Option<&str>,
) -> DependencyAvailability {
    let records = records.collect::<Vec<_>>();
    if records.is_empty() {
        return DependencyAvailability::default();
    }
    let Some(required) = required_version else {
        return DependencyAvailability {
            available: true,
            version_verified: true,
        };
    };
    if records.iter().any(|record| {
        record
            .package_version
            .as_deref()
            .is_some_and(|installed| version_requirement_matches(required, installed))
    }) {
        return DependencyAvailability {
            available: true,
            version_verified: true,
        };
    }
    DependencyAvailability {
        available: records
            .iter()
            .all(|record| record.package_version.is_none()),
        version_verified: records
            .iter()
            .any(|record| record.package_version.is_some()),
    }
}

fn version_requirement_matches(required: &str, installed: &str) -> bool {
    let required = required.trim();
    let installed = installed.trim();
    if required.is_empty() {
        return true;
    }
    let normalized_installed = installed.trim_start_matches(['v', 'V']);
    let Ok(installed_version) = Version::parse(normalized_installed) else {
        return required
            .trim_start_matches(['v', 'V'])
            .eq_ignore_ascii_case(normalized_installed);
    };
    let normalized_required = required.trim_start_matches(['v', 'V']);
    if normalized_required
        .chars()
        .next()
        .is_some_and(|character| matches!(character, '^' | '~' | '>' | '<' | '=' | '*'))
        || normalized_required.contains(',')
    {
        return VersionReq::parse(normalized_required)
            .map(|requirement| requirement.matches(&installed_version))
            .unwrap_or(false);
    }
    Version::parse(normalized_required)
        .map(|required_version| required_version == installed_version)
        .unwrap_or_else(|_| normalized_required.eq_ignore_ascii_case(normalized_installed))
}

#[derive(Debug, Clone, Copy, Default)]
struct InstalledDependencyMatch<'a> {
    satisfying: Option<&'a InstalledModRecord>,
    same_package: Option<&'a InstalledModRecord>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum DependencyInstallDisposition {
    AlreadySatisfied,
    InstallNew,
    Replace(String),
}

fn installed_dependency_match<'a>(
    records: &'a [InstalledModRecord],
    profile: &GameProfile,
    dependency: &DependencySpec,
) -> InstalledDependencyMatch<'a> {
    installed_dependency_match_for_target(records, profile, dependency, None)
}

fn installed_dependency_match_for_target<'a>(
    records: &'a [InstalledModRecord],
    profile: &GameProfile,
    dependency: &DependencySpec,
    target: Option<&InstallTargetOption>,
) -> InstalledDependencyMatch<'a> {
    let mut result = InstalledDependencyMatch::default();

    for record in records.iter().filter(|record| {
        record.profile_id == profile.id
            && record.last_status != "removed"
            && installed_record_matches_dependency_package(profile, record, dependency)
            && target.is_none_or(|target| record_payload_covers_install_target(record, target))
    }) {
        if result.same_package.is_none()
            || record.enabled
                && result
                    .same_package
                    .is_some_and(|existing| !existing.enabled)
        {
            result.same_package = Some(record);
        }
        if record.enabled
            && installed_record_satisfies_dependency(profile, record, dependency)
            && result.satisfying.is_none()
        {
            result.satisfying = Some(record);
        }
    }

    result
}

fn installed_record_matches_dependency_package(
    profile: &GameProfile,
    record: &InstalledModRecord,
    dependency: &DependencySpec,
) -> bool {
    if let Some(runtime) = runtime_id_for_dependency(profile, dependency) {
        return runtime_record_matches(record, &runtime);
    }

    if dependency.provider.eq_ignore_ascii_case("thunderstore") {
        let Ok(package_ref) = parse_thunderstore_ref(dependency) else {
            return false;
        };
        let expected_package_id = thunderstore_package_id(&package_ref);
        if record
            .package_id
            .as_deref()
            .is_some_and(|installed| installed.eq_ignore_ascii_case(&expected_package_id))
        {
            return true;
        }
        return record
            .dependency_string
            .as_deref()
            .and_then(|installed| parse_thunderstore_token(installed, None))
            .is_some_and(|installed| {
                installed
                    .namespace
                    .eq_ignore_ascii_case(&package_ref.namespace)
                    && installed.name.eq_ignore_ascii_case(&package_ref.name)
            });
    }

    let package_id_matches = |candidate: &str| {
        record
            .package_id
            .as_deref()
            .is_some_and(|installed| installed.eq_ignore_ascii_case(candidate))
    };
    if package_id_matches(&dependency.id)
        || dependency.source.as_deref().is_some_and(package_id_matches)
    {
        return true;
    }

    record
        .dependency_string
        .as_deref()
        .is_some_and(|installed| {
            [
                &dependency.id,
                dependency.source.as_deref().unwrap_or_default(),
            ]
            .into_iter()
            .filter(|candidate| !candidate.trim().is_empty())
            .any(|candidate| {
                installed.eq_ignore_ascii_case(candidate)
                    || installed
                        .strip_prefix(candidate)
                        .is_some_and(|suffix| suffix.starts_with('@'))
            })
        })
}

fn installed_record_satisfies_dependency(
    profile: &GameProfile,
    record: &InstalledModRecord,
    dependency: &DependencySpec,
) -> bool {
    installed_record_matches_dependency_package(profile, record, dependency)
        && dependency.version.as_deref().is_none_or(|required| {
            record
                .package_version
                .as_deref()
                .is_none_or(|installed| version_requirement_matches(required, installed))
        })
}

fn installed_record_definitely_satisfies_dependency(
    profile: &GameProfile,
    record: &InstalledModRecord,
    dependency: &DependencySpec,
) -> bool {
    installed_record_matches_dependency_package(profile, record, dependency)
        && dependency.version.as_deref().is_none_or(|required| {
            record
                .package_version
                .as_deref()
                .is_some_and(|installed| version_requirement_matches(required, installed))
        })
}

fn active_reverse_dependencies<'a>(
    profile: &GameProfile,
    records: &'a [InstalledModRecord],
    target: &'a InstalledModRecord,
) -> Vec<(&'a InstalledModRecord, &'a DependencySpec)> {
    if !target.enabled || target.runtime_id.is_some() {
        return Vec::new();
    }

    let mut reverse_dependencies = Vec::new();
    for dependent in records.iter().filter(|record| {
        record.profile_id == profile.id
            && record.id != target.id
            && record.enabled
            && record.last_status != "removed"
    }) {
        for dependency in dependent.dependencies.iter().filter(|item| item.required) {
            if !installed_record_satisfies_dependency(profile, target, dependency)
                || !record_payload_covers_dependent_target(target, dependent)
            {
                continue;
            }
            let has_alternative = records.iter().any(|candidate| {
                candidate.id != target.id
                    && candidate.id != dependent.id
                    && candidate.profile_id == profile.id
                    && candidate.enabled
                    && candidate.last_status != "removed"
                    && installed_record_definitely_satisfies_dependency(
                        profile, candidate, dependency,
                    )
                    && record_payload_covers_dependent_target(candidate, dependent)
            });
            if !has_alternative {
                reverse_dependencies.push((dependent, dependency));
            }
        }
    }
    reverse_dependencies
}

fn ensure_mod_has_no_active_reverse_dependencies(
    profile: &GameProfile,
    records: &[InstalledModRecord],
    target: &InstalledModRecord,
) -> Result<(), String> {
    let reverse_dependencies = active_reverse_dependencies(profile, records, target);
    if reverse_dependencies.is_empty() {
        return Ok(());
    }

    let mut dependents = reverse_dependencies
        .iter()
        .map(|(record, dependency)| {
            format!(
                "{} ({})",
                display_record_name(record),
                dependency.name.trim()
            )
        })
        .collect::<Vec<_>>();
    dependents.sort_by_key(|value| value.to_ascii_lowercase());
    dependents.dedup_by(|first, second| first.eq_ignore_ascii_case(second));
    Err(format!(
        "{} is still required by enabled mod{}: {}. Disable or remove the dependent mod{} first.",
        display_record_name(target),
        if dependents.len() == 1 { "" } else { "s" },
        dependents.join(", "),
        if dependents.len() == 1 { "" } else { "s" },
    ))
}

fn ensure_replacement_preserves_reverse_dependencies(
    profile: &GameProfile,
    records: &[InstalledModRecord],
    existing: &InstalledModRecord,
    replacement: &InstalledModRecord,
) -> Result<(), String> {
    let mut conflicts = Vec::new();
    for dependent in records.iter().filter(|record| {
        record.profile_id == profile.id
            && record.id != existing.id
            && record.enabled
            && record.last_status != "removed"
    }) {
        for requirement in dependent.dependencies.iter().filter(|item| item.required) {
            if !installed_record_matches_dependency_package(profile, existing, requirement)
                || !record_payload_covers_dependent_target(existing, dependent)
                || (installed_record_definitely_satisfies_dependency(
                    profile,
                    replacement,
                    requirement,
                ) && record_payload_covers_dependent_target(replacement, dependent))
            {
                continue;
            }
            let has_alternative = records.iter().any(|candidate| {
                candidate.id != existing.id
                    && candidate.id != dependent.id
                    && candidate.profile_id == profile.id
                    && candidate.enabled
                    && candidate.last_status != "removed"
                    && installed_record_definitely_satisfies_dependency(
                        profile,
                        candidate,
                        requirement,
                    )
                    && record_payload_covers_dependent_target(candidate, dependent)
            });
            if !has_alternative {
                conflicts.push(format!(
                    "{} requires {}",
                    display_record_name(dependent),
                    requirement
                        .version
                        .as_deref()
                        .unwrap_or("the installed version")
                ));
            }
        }
    }
    if conflicts.is_empty() {
        return Ok(());
    }

    conflicts.sort_by_key(|value| value.to_ascii_lowercase());
    conflicts.dedup_by(|first, second| first.eq_ignore_ascii_case(second));
    Err(format!(
        "Cannot replace {} with version {} because it would break enabled mod{}: {}.",
        display_record_name(existing),
        replacement
            .package_version
            .as_deref()
            .unwrap_or("an unverified version"),
        if conflicts.len() == 1 { "" } else { "s" },
        conflicts.join(", ")
    ))
}

#[cfg(test)]
fn dependency_install_disposition(
    records: &[InstalledModRecord],
    profile: &GameProfile,
    dependency: &DependencySpec,
    candidate_package_id: &str,
    candidate_version: &str,
) -> Result<DependencyInstallDisposition, String> {
    dependency_install_disposition_for_target(
        records,
        profile,
        dependency,
        candidate_package_id,
        candidate_version,
        None,
    )
}

fn dependency_install_disposition_for_target(
    records: &[InstalledModRecord],
    profile: &GameProfile,
    dependency: &DependencySpec,
    candidate_package_id: &str,
    candidate_version: &str,
    target: Option<&InstallTargetOption>,
) -> Result<DependencyInstallDisposition, String> {
    if dependency
        .version
        .as_deref()
        .is_some_and(|required| !version_requirement_matches(required, candidate_version))
    {
        return Err(format!(
            "{} returned version {}, which does not satisfy the required version {}.",
            dependency.name,
            candidate_version,
            dependency.version.as_deref().unwrap_or_default()
        ));
    }

    let installed = installed_dependency_match_for_target(records, profile, dependency, target);
    if installed.satisfying.is_some() {
        return Ok(DependencyInstallDisposition::AlreadySatisfied);
    }
    let Some(existing) = installed.same_package else {
        return Ok(DependencyInstallDisposition::InstallNew);
    };
    if existing.runtime_id.is_some() || existing.externally_managed {
        return Err(format!(
            "{} is present as a protected or externally managed component, but its version does not satisfy {}. Update that component before installing the dependent mod.",
            display_record_name(existing),
            dependency.name
        ));
    }
    if !existing
        .package_id
        .as_deref()
        .is_some_and(|installed| installed.eq_ignore_ascii_case(candidate_package_id))
    {
        return Err(format!(
            "{} appears to provide {}, but its provider identity is incomplete. Reinstall it through Mod Garrison before changing dependency versions.",
            display_record_name(existing),
            dependency.name
        ));
    }

    let mut conflicts = Vec::new();
    for dependent in records.iter().filter(|record| {
        record.profile_id == profile.id
            && record.id != existing.id
            && record.enabled
            && record.last_status != "removed"
    }) {
        for requirement in dependent.dependencies.iter().filter(|item| item.required) {
            if !installed_record_matches_dependency_package(profile, existing, requirement)
                || !record_payload_covers_dependent_target(existing, dependent)
                || requirement
                    .version
                    .as_deref()
                    .is_none_or(|required| version_requirement_matches(required, candidate_version))
            {
                continue;
            }
            let has_alternative = records.iter().any(|candidate| {
                candidate.id != existing.id
                    && candidate.id != dependent.id
                    && candidate.profile_id == profile.id
                    && candidate.enabled
                    && candidate.last_status != "removed"
                    && installed_record_definitely_satisfies_dependency(
                        profile,
                        candidate,
                        requirement,
                    )
                    && record_payload_covers_dependent_target(candidate, dependent)
            });
            if !has_alternative {
                conflicts.push(format!(
                    "{} requires {}",
                    display_record_name(dependent),
                    requirement
                        .version
                        .as_deref()
                        .unwrap_or("the installed version")
                ));
            }
        }
    }
    if !conflicts.is_empty() {
        conflicts.sort_by_key(|value| value.to_ascii_lowercase());
        conflicts.dedup_by(|first, second| first.eq_ignore_ascii_case(second));
        return Err(format!(
            "Cannot replace {} with version {} because it would break enabled mod{}: {}.",
            display_record_name(existing),
            candidate_version,
            if conflicts.len() == 1 { "" } else { "s" },
            conflicts.join(", ")
        ));
    }

    Ok(DependencyInstallDisposition::Replace(existing.id.clone()))
}

fn push_missing_dependency(
    missing_dependencies: &mut Vec<DependencySpec>,
    seen: &mut HashSet<String>,
    dependency: DependencySpec,
    target: Option<&InstallTargetOption>,
) {
    if !dependency.required || dependency.status == "already-installed" {
        return;
    }

    if seen.insert(dependency_key_for_target(&dependency, target)) {
        missing_dependencies.push(dependency);
    }
}

fn dependency_key(dependency: &DependencySpec) -> String {
    format!(
        "{}|{}|{}",
        dependency.provider,
        dependency.id,
        dependency.version.as_deref().unwrap_or_default()
    )
}

fn dependency_key_for_target(
    dependency: &DependencySpec,
    target: Option<&InstallTargetOption>,
) -> String {
    dependency_target_visit_key(&dependency_key(dependency), target)
}

fn mod_file_health_for_record(
    record: &InstalledModRecord,
    launch_suspension: &ProfileLaunchSuspension,
) -> ModFileHealth {
    let checked_files = if record.enabled {
        record.files_written.len()
    } else {
        0
    };
    let intentionally_suspended = record.enabled
        && launch_suspension
            .mods
            .iter()
            .any(|suspended| suspended.mod_id == record.id);
    let mut missing_files = Vec::new();
    let mut suspended_files = Vec::new();

    if record.enabled {
        for path in &record.files_written {
            if Path::new(path).exists() {
                continue;
            }
            if intentionally_suspended {
                suspended_files.push(path.clone());
            } else {
                missing_files.push(path.clone());
            }
        }
    }

    ModFileHealth {
        installed_mod_id: record.id.clone(),
        mod_name: record
            .display_name
            .as_deref()
            .map(humanize_mod_display_name)
            .unwrap_or_else(|| humanize_mod_display_name(&record.archive_name)),
        checked_files,
        missing_files,
        suspended_files,
    }
}

fn profile_refresh_warnings(
    detection: &GameDetectionResult,
    mod_file_health: &[ModFileHealth],
    missing_dependencies: &[DependencySpec],
) -> Vec<String> {
    let mut warnings = detection.warnings.clone();
    let missing_file_count = mod_file_health
        .iter()
        .map(|health| health.missing_files.len())
        .sum::<usize>();

    if missing_file_count > 0 {
        let affected_mod_count = mod_file_health
            .iter()
            .filter(|health| !health.missing_files.is_empty())
            .count();
        warnings.push(format!(
            "{} expected file(s) are missing across {} enabled mod(s).",
            missing_file_count, affected_mod_count
        ));
    }

    if !missing_dependencies.is_empty() {
        warnings.push(format!(
            "{} required dependenc{} still missing.",
            missing_dependencies.len(),
            if missing_dependencies.len() == 1 {
                "y is"
            } else {
                "ies are"
            }
        ));
    }

    warnings
}

fn runtime_from_dependency(dependency: &DependencySpec) -> Option<&str> {
    let (kind, runtime) = dependency.id.split_once(':')?;
    (kind.eq_ignore_ascii_case("runtime") && !runtime.trim().is_empty()).then_some(runtime)
}

fn runtime_installed(profile: &GameProfile, runtime: &str) -> bool {
    let game_path = Path::new(&profile.game_path);
    if !game_path.is_dir() {
        return false;
    }

    let entries = walk_game_folder(game_path);
    runtime_layout_matches(profile, &entries, runtime)
}

fn runtime_supplied_by_plan(profile: &GameProfile, plan: &InstallPlan) -> Option<String> {
    if profile.game_id.as_deref() == Some("enshrouded")
        && enshrouded_runtime::plan_supplies_eml(plan)
    {
        return Some("enshrouded-eml".to_string());
    }
    if profile.game_id.as_deref() == Some("enshrouded") {
        if enshrouded_loaders::plan_supplies_shroudtopia(plan) {
            return Some("enshrouded-shroudtopia".to_string());
        }
        if enshrouded_loaders::runtime_supplies_proxy(plan) {
            return Some("enshrouded-proxy".to_string());
        }
        // Installed loaders do not prove that this package supplies a loader.
        return None;
    }
    let mut entries = Vec::new();
    let mut seen_entries = HashSet::new();

    for mapping in plan
        .mappings
        .iter()
        .filter(|mapping| mapping.target_root.eq_ignore_ascii_case("game"))
    {
        let relative_path = normalize_archive_path(&mapping.target_relative_path);
        let segments = relative_path
            .split('/')
            .filter(|segment| !segment.is_empty())
            .collect::<Vec<_>>();
        if segments.is_empty() {
            continue;
        }

        for depth in 1..segments.len() {
            let directory = segments[..depth].join("/");
            if seen_entries.insert((directory.to_ascii_lowercase(), true)) {
                entries.push(ProbeEntry {
                    relative_path: directory.clone(),
                    name: basename(&directory),
                    is_directory: true,
                    depth,
                });
            }
        }

        if seen_entries.insert((relative_path.to_ascii_lowercase(), false)) {
            entries.push(ProbeEntry {
                relative_path: relative_path.clone(),
                name: basename(&relative_path),
                is_directory: false,
                depth: segments.len(),
            });
        }
    }

    profile_runtime_ids(profile)
        .into_iter()
        .find(|runtime| runtime_layout_matches(profile, &entries, runtime))
}

fn runtime_layout_matches(profile: &GameProfile, entries: &[ProbeEntry], runtime: &str) -> bool {
    match runtime {
        "enshrouded-eml" => enshrouded_runtime::installed_eml(profile),
        "enshrouded-shroudtopia" => enshrouded_loaders::installed_shroudtopia(profile),
        "enshrouded-proxy" => enshrouded_loaders::installed_proxy(profile),
        "bepinex" | "bepinex-il2cpp" => bepinex_runtime_layout_matches(entries, runtime),
        "ue4ss" => ue4ss_runtime_layout_matches(entries),
        "reframework" => reframework_runtime_layout_matches(entries),
        _ => runtime_definition_by_id(runtime).is_some_and(|definition| {
            definition
                .detection_rules
                .iter()
                .any(|rule| runtime_detection_rule_matches(profile, entries, rule))
        }),
    }
}

fn bepinex_runtime_layout_matches(entries: &[ProbeEntry], runtime: &str) -> bool {
    entries
        .iter()
        .filter(|entry| !entry.is_directory && runtime_core_file(runtime, &entry.relative_path))
        .filter_map(|entry| path_prefix_before_segments(&entry.relative_path, &["bepinex", "core"]))
        .any(|root| {
            runtime_root_is_executable_backed(entries, &root)
                && probe_root_has_any_file(entries, &root, &["winhttp.dll", "winhttp_il2cpp.dll"])
                && probe_root_has_any_file(
                    entries,
                    &root,
                    &["doorstop_config.ini", "doorstop_config_il2cpp.ini"],
                )
        })
}

fn ue4ss_runtime_layout_matches(entries: &[ProbeEntry]) -> bool {
    entries
        .iter()
        .filter(|entry| !entry.is_directory && runtime_core_file("ue4ss", &entry.relative_path))
        .map(|entry| {
            let parent = archive_path_parent(&entry.relative_path);
            if basename(&parent).eq_ignore_ascii_case("ue4ss") {
                archive_path_parent(&parent)
            } else {
                parent
            }
        })
        .any(|root| {
            runtime_root_is_executable_backed(entries, &root)
                && probe_root_has_any_file(
                    entries,
                    &root,
                    &["dwmapi.dll", "xinput1_3.dll", "version.dll"],
                )
        })
}

fn reframework_runtime_layout_matches(entries: &[ProbeEntry]) -> bool {
    entries
        .iter()
        .filter(|entry| !entry.is_directory && entry.name.eq_ignore_ascii_case("dinput8.dll"))
        .map(|entry| archive_path_parent(&entry.relative_path))
        .any(|root| {
            runtime_root_is_executable_backed(entries, &root)
                && (probe_root_has_any_file(entries, &root, &["reframework_revision.txt"])
                    || entries.iter().any(|entry| {
                        archive_path_is_within(
                            &entry.relative_path,
                            &join_install_route(&root, "reframework"),
                        )
                    }))
        })
}

fn runtime_root_is_executable_backed(entries: &[ProbeEntry], root: &str) -> bool {
    let executable_roots = entries
        .iter()
        .filter(|entry| !entry.is_directory && entry.name.to_ascii_lowercase().ends_with(".exe"))
        .map(|entry| archive_path_parent(&entry.relative_path))
        .collect::<Vec<_>>();
    executable_roots.is_empty()
        || executable_roots
            .iter()
            .any(|candidate| candidate.eq_ignore_ascii_case(root))
}

fn probe_root_has_any_file(entries: &[ProbeEntry], root: &str, names: &[&str]) -> bool {
    entries.iter().any(|entry| {
        !entry.is_directory
            && archive_path_parent(&entry.relative_path).eq_ignore_ascii_case(root)
            && names
                .iter()
                .any(|name| entry.name.eq_ignore_ascii_case(name))
    })
}

fn path_prefix_before_segments(path: &str, expected: &[&str]) -> Option<String> {
    let normalized = normalize_archive_path(path);
    let segments = normalized
        .split('/')
        .filter(|segment| !segment.is_empty())
        .collect::<Vec<_>>();
    if expected.is_empty() || segments.len() < expected.len() {
        return None;
    }
    segments
        .windows(expected.len())
        .position(|window| {
            window
                .iter()
                .zip(expected)
                .all(|(actual, expected)| actual.eq_ignore_ascii_case(expected))
        })
        .map(|index| segments[..index].join("/"))
}

fn runtime_detection_rule_matches(
    profile: &GameProfile,
    entries: &[ProbeEntry],
    rule: &RuntimeDetectionRule,
) -> bool {
    if rule.all.is_empty() && rule.any.is_empty() {
        return false;
    }

    rule.all
        .iter()
        .all(|marker| runtime_detection_marker_matches(profile, entries, marker))
        && (rule.any.is_empty()
            || rule
                .any
                .iter()
                .any(|marker| runtime_detection_marker_matches(profile, entries, marker)))
}

fn runtime_detection_marker_matches(
    profile: &GameProfile,
    entries: &[ProbeEntry],
    marker: &str,
) -> bool {
    let Some((kind, expected)) = marker.split_once(':') else {
        return false;
    };
    let expected = normalize_archive_path(expected.trim());

    match kind.trim().to_ascii_lowercase().as_str() {
        "profile-engine" => profile.engine.eq_ignore_ascii_case(&expected),
        "profile-loader" => profile.loader.eq_ignore_ascii_case(&expected),
        "file" => entries.iter().any(|entry| {
            !entry.is_directory
                && normalize_archive_path(&entry.relative_path).eq_ignore_ascii_case(&expected)
        }),
        "file-name" => entries
            .iter()
            .any(|entry| !entry.is_directory && entry.name.eq_ignore_ascii_case(&expected)),
        "dir" => entries.iter().any(|entry| {
            entry.is_directory
                && normalize_archive_path(&entry.relative_path).eq_ignore_ascii_case(&expected)
        }),
        "dir-prefix" => entries.iter().any(|entry| {
            entry.is_directory && path_matches_or_is_below(&entry.relative_path, expected.as_str())
        }),
        "path" => entries.iter().any(|entry| {
            normalize_archive_path(&entry.relative_path).eq_ignore_ascii_case(&expected)
        }),
        "path-prefix" => entries
            .iter()
            .any(|entry| path_matches_or_is_below(&entry.relative_path, expected.as_str())),
        _ => false,
    }
}

fn path_matches_or_is_below(path: &str, expected: &str) -> bool {
    let normalized_path = normalize_archive_path(path).to_ascii_lowercase();
    let normalized_expected = normalize_archive_path(expected).to_ascii_lowercase();
    normalized_path == normalized_expected
        || normalized_path.starts_with(&format!("{normalized_expected}/"))
}

fn thunderstore_runtime_available(
    profile: &GameProfile,
    package_ref: &ThunderstorePackageRef,
) -> bool {
    runtime_definitions().iter().any(|definition| {
        runtime_definition_applies_to_profile(definition, profile)
            && runtime_provider_package_matches(
                definition,
                "thunderstore",
                Some(&package_ref.namespace),
                &package_ref.name,
            )
            && runtime_installed(profile, &definition.id)
    })
}

fn runtime_definition_applies_to_profile(
    definition: &RuntimeDefinition,
    profile: &GameProfile,
) -> bool {
    if definition.profile_engines.is_empty() && definition.profile_loaders.is_empty() {
        return true;
    }

    definition
        .profile_engines
        .iter()
        .any(|engine| engine.eq_ignore_ascii_case(&profile.engine))
        || definition
            .profile_loaders
            .iter()
            .any(|loader| loader.eq_ignore_ascii_case(&profile.loader))
}

fn runtime_provider_package_matches(
    definition: &RuntimeDefinition,
    provider: &str,
    namespace: Option<&str>,
    package_name: &str,
) -> bool {
    definition.provider_packages.iter().any(|package| {
        package.provider.eq_ignore_ascii_case(provider)
            && (package.namespace_patterns.is_empty()
                || namespace.is_some_and(|value| {
                    package
                        .namespace_patterns
                        .iter()
                        .any(|pattern| wildcard_match(pattern, value))
                }))
            && package.package_patterns.iter().any(|pattern| {
                wildcard_match(pattern, package_name)
                    || game_qualified_runtime_name_matches(pattern, package_name)
            })
    })
}

fn game_qualified_runtime_name_matches(runtime_alias: &str, package_name: &str) -> bool {
    if runtime_alias.contains('*') || runtime_alias.contains('?') {
        return false;
    }

    let alias = normalized_runtime_package_name(runtime_alias);
    let package = normalized_runtime_package_name(package_name);
    if alias.is_empty() || package.len() <= alias.len() || !package.starts_with(&alias) {
        return false;
    }

    let suffix = package[alias.len()..].trim_start();
    suffix
        .strip_prefix("for ")
        .is_some_and(|game_name| !game_name.trim().is_empty())
}

fn normalized_runtime_package_name(value: &str) -> String {
    value
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() {
                character.to_ascii_lowercase()
            } else {
                ' '
            }
        })
        .collect::<String>()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

fn thunderstore_package_installed(
    store_root: &Path,
    profile: &GameProfile,
    package_id: &str,
    dependency_string: Option<&str>,
    required_version: Option<&str>,
) -> bool {
    let Ok(store) = read_store::<InstalledModRecord>(&installed_mods_path(store_root)) else {
        return false;
    };

    store.items.iter().any(|record| {
        record.profile_id == profile.id
            && record.enabled
            && record.last_status != "removed"
            && (record
                .package_id
                .as_deref()
                .map(|installed_id| installed_id.eq_ignore_ascii_case(package_id))
                .unwrap_or(false)
                || dependency_string
                    .and_then(|expected| {
                        record
                            .dependency_string
                            .as_deref()
                            .map(|installed| installed.eq_ignore_ascii_case(expected))
                    })
                    .unwrap_or(false))
            && required_version.is_none_or(|required| {
                record
                    .package_version
                    .as_deref()
                    .is_none_or(|installed| version_requirement_matches(required, installed))
            })
    })
}

fn parse_thunderstore_ref(dependency: &DependencySpec) -> Result<ThunderstorePackageRef, String> {
    if dependency.provider != "thunderstore" {
        return Err(format!(
            "{} is not a Thunderstore dependency.",
            dependency.name
        ));
    }

    if let Some((namespace, name)) = dependency.name.split_once('/') {
        return Ok(ThunderstorePackageRef {
            namespace: namespace.to_string(),
            name: name.to_string(),
            version: dependency.version.clone(),
        });
    }

    let raw = dependency
        .id
        .strip_prefix("thunderstore:")
        .unwrap_or(&dependency.id);
    parse_thunderstore_token(raw, dependency.version.as_deref()).ok_or_else(|| {
        format!(
            "Could not parse Thunderstore dependency: {}",
            dependency.name
        )
    })
}

fn parse_thunderstore_token(
    token: &str,
    version_hint: Option<&str>,
) -> Option<ThunderstorePackageRef> {
    let token = token
        .trim()
        .strip_prefix("thunderstore:")
        .unwrap_or(token.trim());
    if let Some((namespace, name)) = token.split_once('/') {
        return Some(ThunderstorePackageRef {
            namespace: namespace.to_string(),
            name: name.to_string(),
            version: version_hint.map(|value| value.to_string()),
        });
    }

    let mut package_token = token.to_string();
    let mut version = version_hint.map(|value| value.to_string());
    if version.is_none() {
        if let Some((without_version, possible_version)) = token.rsplit_once('-') {
            if looks_like_version(possible_version) {
                package_token = without_version.to_string();
                version = Some(possible_version.to_string());
            }
        }
    } else if let Some(version_value) = &version {
        let suffix = format!("-{}", version_value);
        if package_token.ends_with(&suffix) {
            package_token.truncate(package_token.len() - suffix.len());
        }
    }

    let parts = package_token.split('-').collect::<Vec<_>>();
    if parts.len() < 2 {
        return None;
    }

    let (namespace, name) = if version.is_some() {
        (
            parts[..parts.len() - 1].join("-"),
            parts[parts.len() - 1].to_string(),
        )
    } else {
        let (namespace, name) = package_token.split_once('-')?;
        (namespace.to_string(), name.to_string())
    };

    if namespace.is_empty() || name.is_empty() {
        None
    } else {
        Some(ThunderstorePackageRef {
            namespace,
            name,
            version,
        })
    }
}

fn looks_like_version(value: &str) -> bool {
    value
        .chars()
        .next()
        .map(|character| character.is_ascii_digit())
        .unwrap_or(false)
        && value.chars().all(|character| {
            character.is_ascii_alphanumeric() || matches!(character, '.' | '-' | '_')
        })
}

fn fetch_thunderstore_package_version(
    package_ref: &ThunderstorePackageRef,
) -> Result<ThunderstoreVersion, String> {
    thunderstore::fetch_package_version(package_ref)
}

fn thunderstore_package_version_url(package_ref: &ThunderstorePackageRef, version: &str) -> String {
    thunderstore::package_metadata_url(package_ref, Some(version))
}

fn download_thunderstore_package(
    store_root: &Path,
    package_ref: &ThunderstorePackageRef,
    package_version: &ThunderstoreVersion,
) -> Result<PathBuf, String> {
    let cache_dir = store_root
        .join("cache")
        .join("thunderstore")
        .join(sanitize_file_segment(&package_ref.namespace))
        .join(sanitize_file_segment(&package_ref.name));
    fs::create_dir_all(&cache_dir).map_err(error_to_string)?;

    let archive_path = cache_dir.join(format!(
        "{}-{}.zip",
        sanitize_file_segment(&package_version.full_name),
        sanitize_file_segment(&package_version.version_number)
    ));

    if cached_download_is_verified(&archive_path, &package_version.download_url)? {
        match verify_declared_download_integrity(
            &archive_path,
            package_version.file_size.filter(|size| *size > 0),
            None,
            "Thunderstore package",
        ) {
            Ok(()) => return Ok(archive_path),
            Err(_) => remove_download_artifact(&archive_path),
        }
    }

    let client = thunderstore_client()?;
    download_url_to_file(&client, &package_version.download_url, &archive_path)?;
    if let Err(error) = verify_declared_download_integrity(
        &archive_path,
        package_version.file_size.filter(|size| *size > 0),
        None,
        "Thunderstore package",
    ) {
        remove_download_artifact(&archive_path);
        return Err(error);
    }
    Ok(archive_path)
}

fn resolve_github_release_dependency(
    dependency: &DependencySpec,
) -> Result<ReleaseDependencyRef, String> {
    let source = dependency
        .source
        .as_deref()
        .ok_or_else(|| format!("{} is missing a GitHub release source.", dependency.name))?;
    let raw = source
        .strip_prefix("github-release:")
        .ok_or_else(|| format!("{} has an invalid GitHub release source.", dependency.name))?;
    let (repository_ref, asset_pattern) = raw.split_once('#').ok_or_else(|| {
        format!(
            "{} GitHub source must include an asset pattern.",
            dependency.name
        )
    })?;
    let (repo, release_tag) = repository_ref
        .split_once('@')
        .map(|(repo, tag)| (repo, Some(tag)))
        .unwrap_or((repository_ref, None));
    let (owner, repo_name) = repo
        .split_once('/')
        .ok_or_else(|| format!("{} GitHub source must use owner/repo.", dependency.name))?;

    let client = provider_client()?;
    if [owner, repo_name].iter().any(|part| {
        part.is_empty()
            || !part
                .bytes()
                .all(|byte| byte.is_ascii_alphanumeric() || b"-_.".contains(&byte))
    }) {
        return Err("A GitHub dependency has an invalid repository.".to_string());
    }
    // Some official repositories publish several products; `latest` is not
    // necessarily a release of the loader required by this mod.
    let endpoint = match release_tag {
        Some(tag)
            if !tag.is_empty()
                && tag.len() <= 128
                && tag
                    .bytes()
                    .all(|byte| byte.is_ascii_alphanumeric() || b"-_.".contains(&byte)) =>
        {
            format!("tags/{tag}")
        }
        Some(_) => return Err("A GitHub dependency has an invalid release tag.".to_string()),
        None => "latest".to_string(),
    };
    let url = format!("{GITHUB_API_BASE}/{owner}/{repo_name}/releases/{endpoint}");
    let release = client
        .get(url)
        .send()
        .map_err(error_to_string)?
        .error_for_status()
        .map_err(error_to_string)?
        .json::<GithubReleaseResponse>()
        .map_err(error_to_string)?;

    let asset = release
        .assets
        .into_iter()
        .find(|asset| wildcard_match(asset_pattern, &asset.name))
        .ok_or_else(|| {
            format!(
                "Latest GitHub release for {} does not include asset pattern {}.",
                repo, asset_pattern
            )
        })?;
    let expected_size = asset.size.filter(|size| *size > 0);
    let expected_sha256 = github_asset_declared_sha256(&asset)?;

    Ok(ReleaseDependencyRef {
        source_key: source.to_string(),
        display_name: format!("{} {}", dependency.name, asset.name),
        download_url: asset.browser_download_url,
        version: release.tag_name,
        expected_size,
        expected_sha256,
    })
}

fn resolve_bepinbuilds_dependency(
    dependency: &DependencySpec,
) -> Result<ReleaseDependencyRef, String> {
    let source = dependency
        .source
        .as_deref()
        .ok_or_else(|| format!("{} is missing a BepInBuilds source.", dependency.name))?;
    let raw = source
        .strip_prefix("bepinbuilds:")
        .ok_or_else(|| format!("{} has an invalid BepInBuilds source.", dependency.name))?;
    let (project, asset_pattern) = raw.split_once('#').ok_or_else(|| {
        format!(
            "{} BepInBuilds source must include an asset pattern.",
            dependency.name
        )
    })?;

    let project_url = match project {
        "bepinex_be" => BEPINBUILDS_BEPINEX_BE,
        _ => return Err(format!("Unsupported BepInBuilds project: {}", project)),
    };

    let client = provider_client()?;
    let html = client
        .get(project_url)
        .send()
        .map_err(error_to_string)?
        .error_for_status()
        .map_err(error_to_string)?
        .text()
        .map_err(error_to_string)?;

    for href in extract_href_values(&html) {
        if !href.to_lowercase().ends_with(".zip") {
            continue;
        }

        let file_name = href
            .rsplit('/')
            .next()
            .map(minimal_url_decode)
            .unwrap_or_else(|| href.clone());

        if !wildcard_match(asset_pattern, &file_name) {
            continue;
        }

        let download_url = if href.starts_with("http://") || href.starts_with("https://") {
            href
        } else {
            format!("{}{}", BEPINBUILDS_BASE, href)
        };

        return Ok(ReleaseDependencyRef {
            source_key: source.to_string(),
            display_name: format!("{} {}", dependency.name, file_name),
            download_url,
            version: file_name
                .strip_suffix(".zip")
                .unwrap_or(&file_name)
                .to_string(),
            expected_size: None,
            expected_sha256: None,
        });
    }

    Err(format!(
        "BepInBuilds project {} does not include asset pattern {}.",
        project, asset_pattern
    ))
}

fn download_release_archive(
    store_root: &Path,
    dependency: &DependencySpec,
    release_ref: &ReleaseDependencyRef,
) -> Result<PathBuf, String> {
    if enshrouded_runtime::is_eml_dependency(dependency) {
        return enshrouded_runtime::download_eml_archive(store_root, dependency, release_ref);
    }
    let cache_dir = store_root
        .join("cache")
        .join(sanitize_file_segment(&dependency.provider))
        .join(sanitize_file_segment(&release_ref.source_key))
        .join(sanitize_file_segment(&release_ref.version));
    fs::create_dir_all(&cache_dir).map_err(error_to_string)?;

    let file_name = release_ref
        .download_url
        .split('?')
        .next()
        .and_then(|path| path.rsplit('/').next())
        .map(minimal_url_decode)
        .filter(|name| name.to_lowercase().ends_with(".zip"))
        .unwrap_or_else(|| format!("{}.zip", sanitize_file_segment(&dependency.name)));
    let archive_path = cache_dir.join(sanitize_file_segment(&file_name));

    if cached_download_is_verified(&archive_path, &release_ref.download_url)? {
        match verify_declared_download_integrity(
            &archive_path,
            release_ref.expected_size,
            release_ref.expected_sha256.as_deref(),
            &release_ref.display_name,
        ) {
            Ok(()) => return Ok(archive_path),
            Err(_) => remove_download_artifact(&archive_path),
        }
    }

    let client = provider_client()?;
    download_url_to_file(&client, &release_ref.download_url, &archive_path)?;
    if let Err(error) = verify_declared_download_integrity(
        &archive_path,
        release_ref.expected_size,
        release_ref.expected_sha256.as_deref(),
        &release_ref.display_name,
    ) {
        remove_download_artifact(&archive_path);
        return Err(error);
    }
    Ok(archive_path)
}

fn verify_declared_download_integrity(
    path: &Path,
    expected_size: Option<u64>,
    expected_sha256: Option<&str>,
    label: &str,
) -> Result<(), String> {
    if let Some(expected_size) = expected_size.filter(|size| *size > 0) {
        let actual_size = path.metadata().map_err(error_to_string)?.len();
        if actual_size != expected_size {
            return Err(format!(
                "{label} failed its provider size check (expected {expected_size} bytes, received {actual_size} bytes). The downloaded file was removed."
            ));
        }
    }

    if let Some(expected_sha256) = expected_sha256
        .map(str::trim)
        .filter(|hash| !hash.is_empty())
    {
        if expected_sha256.len() != 64
            || !expected_sha256
                .chars()
                .all(|character| character.is_ascii_hexdigit())
        {
            return Err(format!(
                "{label} has an invalid provider SHA-256 digest, so Mod Garrison refused the download."
            ));
        }
        let actual_sha256 = sha256_file(path)?;
        if !actual_sha256.eq_ignore_ascii_case(expected_sha256) {
            return Err(format!(
                "{label} failed its provider SHA-256 check. The downloaded file was removed."
            ));
        }
    }

    Ok(())
}

fn download_url_to_file(client: &Client, url: &str, destination: &Path) -> Result<(), String> {
    download_url_to_file_with_source_identity(client, url, destination, url)
}

fn download_url_to_file_with_source_identity(
    client: &Client,
    url: &str,
    destination: &Path,
    artifact_source: &str,
) -> Result<(), String> {
    validate_https_url(url)?;
    if let Some(parent) = destination.parent() {
        fs::create_dir_all(parent).map_err(error_to_string)?;
    }

    let temp_name = format!(
        ".{}.{}.download",
        destination
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("mod-garrison"),
        Uuid::new_v4()
    );
    let temp_path = destination.with_file_name(temp_name);

    let mut response = request_download_with_retry(client, url)?;
    validate_remote_https_url(response.url())
        .map_err(|error| format!("The download ended at an unsafe redirected URL: {error}"))?;

    let archive_extension = destination
        .extension()
        .and_then(|extension| extension.to_str())
        .map(|extension| extension.to_ascii_lowercase())
        .filter(|extension| matches!(extension.as_str(), "zip" | "7z" | "rar"));
    if archive_extension.is_some() {
        let content_type = response
            .headers()
            .get(reqwest::header::CONTENT_TYPE)
            .and_then(|value| value.to_str().ok())
            .unwrap_or_default()
            .to_ascii_lowercase();
        if content_type.starts_with("text/")
            || content_type.contains("application/json")
            || content_type.contains("application/problem+json")
        {
            return Err(
                "The download provider returned a webpage or message instead of a mod archive. Start the download again."
                    .to_string(),
            );
        }
    }

    if let Some(content_length) = response.content_length() {
        if content_length > MAX_DOWNLOAD_BYTES {
            return Err(format!(
                "Download is too large: {} MB exceeds Mod Garrison's {} MB safety limit.",
                content_length / 1024 / 1024,
                MAX_DOWNLOAD_BYTES / 1024 / 1024
            ));
        }
    }

    let mut file = File::create(&temp_path).map_err(error_to_string)?;
    let bytes_written = match copy_with_limit(&mut response, &mut file, MAX_DOWNLOAD_BYTES) {
        Ok(bytes) => bytes,
        Err(error) => {
            let _ = fs::remove_file(&temp_path);
            return Err(error);
        }
    };
    if let Err(error) = file.sync_all() {
        drop(file);
        let _ = fs::remove_file(&temp_path);
        return Err(error_to_string(error));
    }
    drop(file);

    if bytes_written == 0 {
        let _ = fs::remove_file(&temp_path);
        return Err("Download completed, but the downloaded file was empty.".to_string());
    }

    if let Some(extension) = archive_extension.as_deref() {
        if let Err(error) = validate_downloaded_archive(&temp_path, extension) {
            let _ = fs::remove_file(&temp_path);
            return Err(error);
        }
    }

    let sha256 = match sha256_file(&temp_path) {
        Ok(sha256) => sha256,
        Err(error) => {
            let _ = fs::remove_file(&temp_path);
            return Err(error);
        }
    };
    let result = replace_file_from_path(&temp_path, destination);
    let _ = fs::remove_file(&temp_path);
    result?;

    let artifact_metadata = DownloadArtifactMetadata {
        source_url: artifact_source.to_string(),
        sha256,
        size: bytes_written,
        verified_at: now_string(),
    };
    let metadata_bytes = match serde_json::to_vec_pretty(&artifact_metadata) {
        Ok(metadata) => metadata,
        Err(error) => {
            let _ = fs::remove_file(destination);
            return Err(error_to_string(error));
        }
    };
    if let Err(error) = atomic_write(
        &download_artifact_metadata_path(destination),
        &metadata_bytes,
    ) {
        let _ = fs::remove_file(destination);
        return Err(format!(
            "Downloaded file could not be recorded safely and was removed: {error}"
        ));
    }

    Ok(())
}

fn download_artifact_metadata_path(destination: &Path) -> PathBuf {
    let file_name = destination
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("download");
    destination.with_file_name(format!("{file_name}.download.json"))
}

fn remove_download_artifact(destination: &Path) {
    let _ = fs::remove_file(destination);
    let _ = fs::remove_file(download_artifact_metadata_path(destination));
}

fn cleanup_successful_provider_artifacts(
    store_root: &Path,
    downloaded_path: &Path,
    prepared_path: &Path,
) {
    let downloads_root = store_root.join("downloads");
    if downloaded_path.is_file()
        && validate_deployment_containment(&downloads_root, downloaded_path).is_ok()
    {
        let parent = downloaded_path.parent().map(Path::to_path_buf);
        remove_download_artifact(downloaded_path);
        if let Some(parent) = parent {
            prune_empty_directories(&parent, &downloads_root);
        }
    }

    let imports_root = store_root.join("cache").join("imports");
    if !prepared_path.exists()
        || validate_deployment_containment(&imports_root, prepared_path).is_err()
    {
        return;
    }
    let Ok(relative_path) = prepared_path.strip_prefix(&imports_root) else {
        return;
    };
    let Some(session_name) = relative_path.components().next() else {
        return;
    };
    let session_path = imports_root.join(session_name.as_os_str());
    if session_path != imports_root
        && session_path.is_dir()
        && validate_deployment_containment(&imports_root, &session_path).is_ok()
    {
        let _ = fs::remove_dir_all(session_path);
    }
}

fn prune_empty_directories(start: &Path, stop: &Path) {
    let mut current = start.to_path_buf();
    while current != stop
        && validate_deployment_containment(stop, &current).is_ok()
        && fs::read_dir(&current)
            .ok()
            .and_then(|mut entries| entries.next())
            .is_none()
    {
        if fs::remove_dir(&current).is_err() {
            break;
        }
        let Some(parent) = current.parent() else {
            break;
        };
        current = parent.to_path_buf();
    }
}

fn cached_download_is_verified(destination: &Path, source_url: &str) -> Result<bool, String> {
    if !destination.is_file() {
        return Ok(false);
    }

    let metadata_path = download_artifact_metadata_path(destination);
    let artifact = fs::read(&metadata_path)
        .ok()
        .and_then(|content| serde_json::from_slice::<DownloadArtifactMetadata>(&content).ok());
    let valid = if let Some(artifact) = artifact {
        let actual_size = destination.metadata().map_err(error_to_string)?.len();
        artifact.source_url == source_url
            && artifact.size > 0
            && artifact.size == actual_size
            && sha256_file(destination)?.eq_ignore_ascii_case(artifact.sha256.trim())
    } else {
        false
    };

    if valid {
        return Ok(true);
    }

    fs::remove_file(destination).map_err(|error| {
        format!(
            "Could not discard an unverified cached download at {}: {error}",
            destination.to_string_lossy()
        )
    })?;
    if metadata_path.exists() {
        fs::remove_file(&metadata_path).map_err(|error| {
            format!(
                "Could not discard invalid download metadata at {}: {error}",
                metadata_path.to_string_lossy()
            )
        })?;
    }
    Ok(false)
}

fn request_download_with_retry(client: &Client, url: &str) -> Result<Response, String> {
    for attempt in 0..MAX_DOWNLOAD_ATTEMPTS {
        match client.get(url).send() {
            Ok(response) => {
                let status = response.status();
                if status.is_success() {
                    return Ok(response);
                }

                let should_retry =
                    is_transient_download_status(status) && attempt + 1 < MAX_DOWNLOAD_ATTEMPTS;
                if should_retry {
                    let delay = download_retry_delay(&response, attempt);
                    drop(response);
                    std::thread::sleep(delay);
                    continue;
                }

                return Err(format!(
                    "Download server returned HTTP {}.",
                    status.as_u16()
                ));
            }
            Err(error) => {
                let should_retry = (error.is_connect() || error.is_timeout())
                    && attempt + 1 < MAX_DOWNLOAD_ATTEMPTS;
                if should_retry {
                    std::thread::sleep(default_download_retry_delay(attempt));
                    continue;
                }

                return Err(format!("Download request failed: {}", error.without_url()));
            }
        }
    }

    Err("The download server did not respond after several attempts.".to_string())
}

fn is_transient_download_status(status: StatusCode) -> bool {
    status == StatusCode::TOO_MANY_REQUESTS || status.is_server_error()
}

fn download_retry_delay(response: &Response, attempt: usize) -> Duration {
    response
        .headers()
        .get(reqwest::header::RETRY_AFTER)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.trim().parse::<u64>().ok())
        .map(|seconds| Duration::from_secs(seconds.min(DOWNLOAD_RETRY_MAX_DELAY_SECS)))
        .unwrap_or_else(|| default_download_retry_delay(attempt))
}

fn default_download_retry_delay(attempt: usize) -> Duration {
    Duration::from_millis(DOWNLOAD_RETRY_BASE_DELAY_MS * (attempt as u64 + 1))
}

fn validate_downloaded_archive(path: &Path, extension: &str) -> Result<(), String> {
    match extension {
        "zip" => {
            let file = File::open(path).map_err(error_to_string)?;
            let archive = ZipArchive::new(file).map_err(|_| {
                "The download provider returned an incomplete or invalid ZIP archive. Start the download again."
                    .to_string()
            })?;
            if archive.is_empty() {
                return Err(
                    "The download provider returned an empty ZIP archive. Start the download again."
                        .to_string(),
                );
            }
            Ok(())
        }
        "7z" => validate_archive_signature(path, &[0x37, 0x7A, 0xBC, 0xAF, 0x27, 0x1C], "7Z"),
        "rar" => {
            let mut file = File::open(path).map_err(error_to_string)?;
            let mut header = [0_u8; 8];
            let read = file.read(&mut header).map_err(error_to_string)?;
            let rar4 = read >= 7 && header[..7] == [0x52, 0x61, 0x72, 0x21, 0x1A, 0x07, 0x00];
            let rar5 = read >= 8 && header == [0x52, 0x61, 0x72, 0x21, 0x1A, 0x07, 0x01, 0x00];
            if rar4 || rar5 {
                Ok(())
            } else {
                Err(
                    "The download provider returned an incomplete or invalid RAR archive. Start the download again."
                        .to_string(),
                )
            }
        }
        _ => Ok(()),
    }
}

fn validate_archive_signature(path: &Path, signature: &[u8], label: &str) -> Result<(), String> {
    let mut file = File::open(path).map_err(error_to_string)?;
    let mut header = vec![0_u8; signature.len()];
    let valid = file
        .read_exact(&mut header)
        .map(|_| header == signature)
        .unwrap_or(false);
    if valid {
        Ok(())
    } else {
        Err(format!(
            "The download provider returned an incomplete or invalid {label} archive. Start the download again."
        ))
    }
}

fn validate_https_url(value: &str) -> Result<url::Url, String> {
    let parsed =
        url::Url::parse(value).map_err(|error| format!("Invalid download URL: {error}"))?;
    validate_remote_https_url(&parsed)?;
    Ok(parsed)
}

fn validate_remote_https_url(parsed: &url::Url) -> Result<(), String> {
    if parsed.scheme() != "https" || parsed.host_str().is_none() {
        return Err("downloads must use a valid HTTPS URL".to_string());
    }
    if !parsed.username().is_empty() || parsed.password().is_some() {
        return Err("download URLs cannot contain embedded credentials".to_string());
    }

    let host = parsed
        .host_str()
        .ok_or_else(|| "download URL is missing a host".to_string())?
        .trim_end_matches('.')
        .to_ascii_lowercase();
    if host.is_empty() {
        return Err("download URL is missing a host".to_string());
    }
    if let Ok(ip) = host.parse::<std::net::IpAddr>() {
        if download_ip_is_local_or_private(ip) {
            return Err(
                "download URLs cannot target a local or private network address".to_string(),
            );
        }
        return Ok(());
    }

    if !host.contains('.')
        || host == "localhost"
        || host.ends_with(".localhost")
        || host.ends_with(".local")
        || host.ends_with(".lan")
        || host.ends_with(".internal")
        || host.ends_with(".home.arpa")
    {
        return Err("download URLs cannot target a local network host".to_string());
    }

    Ok(())
}

fn download_ip_is_local_or_private(ip: std::net::IpAddr) -> bool {
    match ip {
        std::net::IpAddr::V4(ip) => {
            let octets = ip.octets();
            ip.is_private()
                || ip.is_loopback()
                || ip.is_link_local()
                || ip.is_unspecified()
                || ip.is_broadcast()
                || octets[0] == 0
                || (octets[0] == 100 && (64..=127).contains(&octets[1]))
                || (octets[0] == 192 && octets[1] == 0 && (octets[2] == 0 || octets[2] == 2))
                || (octets[0] == 198 && (octets[1] == 18 || octets[1] == 19))
                || (octets[0] == 198 && octets[1] == 51 && octets[2] == 100)
                || (octets[0] == 203 && octets[1] == 0 && octets[2] == 113)
                || octets[0] >= 224
        }
        std::net::IpAddr::V6(ip) => {
            if let Some(ipv4) = ip.to_ipv4_mapped() {
                return download_ip_is_local_or_private(std::net::IpAddr::V4(ipv4));
            }
            let octets = ip.octets();
            ip.is_loopback()
                || ip.is_unspecified()
                || (octets[0] == 0x01 && octets[1..8].iter().all(|octet| *octet == 0))
                || (octets[0..8] == [0x20, 0x01, 0x0d, 0xb8, 0, 0, 0, 0])
                || (octets[0] & 0xfe) == 0xfc
                || (octets[0] == 0xfe && (octets[1] & 0xc0) >= 0x80)
                || octets[0] == 0xff
        }
    }
}

fn safe_download_redirect_policy() -> reqwest::redirect::Policy {
    reqwest::redirect::Policy::custom(|attempt| {
        if attempt.previous().len() >= 10 {
            return attempt.error("too many download redirects");
        }
        match validate_remote_https_url(attempt.url()) {
            Ok(()) => attempt.follow(),
            Err(error) => attempt.error(io::Error::new(io::ErrorKind::PermissionDenied, error)),
        }
    })
}

fn thunderstore_client() -> Result<Client, String> {
    provider_client()
}

fn provider_client() -> Result<Client, String> {
    Client::builder()
        .user_agent(format!("Mod Garrison/{}", env!("CARGO_PKG_VERSION")))
        .connect_timeout(Duration::from_secs(8))
        .timeout(Duration::from_secs(30))
        .redirect(safe_download_redirect_policy())
        .build()
        .map_err(error_to_string)
}

fn thunderstore_package_id(package_ref: &ThunderstorePackageRef) -> String {
    format!(
        "thunderstore:{}/{}",
        package_ref.namespace, package_ref.name
    )
}

fn thunderstore_dependency_string(package_ref: &ThunderstorePackageRef, version: &str) -> String {
    format!("{}-{}-{}", package_ref.namespace, package_ref.name, version)
}

fn thunderstore_visit_key(package_ref: &ThunderstorePackageRef) -> String {
    format!(
        "thunderstore:{}:{}:{}",
        package_ref.namespace.to_lowercase(),
        package_ref.name.to_lowercase(),
        package_ref.version.as_deref().unwrap_or("*").to_lowercase()
    )
}

fn extract_href_values(html: &str) -> Vec<String> {
    html.split("href=\"")
        .skip(1)
        .filter_map(|part| part.split('"').next())
        .map(|href| href.replace("&amp;", "&"))
        .collect()
}

fn wildcard_match(pattern: &str, value: &str) -> bool {
    let pattern = pattern.to_lowercase();
    let value = value.to_lowercase();

    if pattern == "*" {
        return true;
    }

    if !pattern.contains('*') {
        return pattern == value;
    }

    let parts = pattern.split('*').collect::<Vec<_>>();
    let mut remaining = value.as_str();
    let mut first = true;

    for part in &parts {
        if part.is_empty() {
            continue;
        }

        if first && !pattern.starts_with('*') {
            if !remaining.starts_with(part) {
                return false;
            }
            remaining = &remaining[part.len()..];
        } else if let Some(index) = remaining.find(part) {
            remaining = &remaining[index + part.len()..];
        } else {
            return false;
        }

        first = false;
    }

    if !pattern.ends_with('*') {
        if let Some(last_part) = parts.iter().rev().find(|part| !part.is_empty()) {
            return value.ends_with(last_part);
        }
    }

    true
}

fn minimal_url_decode(value: &str) -> String {
    value
        .replace("%2B", "+")
        .replace("%2b", "+")
        .replace("%20", " ")
        .replace("%5B", "[")
        .replace("%5b", "[")
        .replace("%5D", "]")
        .replace("%5d", "]")
}

fn sanitize_file_segment(value: &str) -> String {
    value
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() || matches!(character, '-' | '_' | '.') {
                character
            } else {
                '_'
            }
        })
        .collect()
}

fn is_safe_internal_storage_segment(value: &str) -> bool {
    !value.is_empty()
        && !matches!(value, "." | "..")
        && !value.ends_with('.')
        && !value.ends_with(' ')
        && sanitize_file_segment(value) == value
}

fn sanitize_url_path_segment(value: &str) -> String {
    sanitize_file_segment(value).replace('.', "")
}

fn materialize_import_source(
    store_root: &Path,
    profile: &GameProfile,
    install_id: &str,
    source_path: &Path,
) -> Result<PathBuf, String> {
    if !source_path.exists() {
        return Err(format!(
            "Import source no longer exists: {}",
            source_path.to_string_lossy()
        ));
    }

    let package_root = profile_package_dir(store_root, &profile.id, install_id);
    fs::create_dir_all(&package_root).map_err(error_to_string)?;

    if source_path.is_dir() {
        let destination = package_root.join("source");
        copy_dir_contents(source_path, &destination)?;
        return Ok(destination);
    }

    if !source_path.is_file() {
        return Err("Import source must be a file or folder.".to_string());
    }

    let file_name = source_path
        .file_name()
        .and_then(|name| name.to_str())
        .map(sanitize_file_segment)
        .filter(|name| !name.is_empty())
        .unwrap_or_else(|| "source.zip".to_string());
    let destination = package_root.join(file_name);
    fs::copy(source_path, &destination).map_err(error_to_string)?;
    Ok(destination)
}

fn copy_dir_contents(source_root: &Path, destination_root: &Path) -> Result<(), String> {
    fs::create_dir_all(destination_root).map_err(error_to_string)?;
    let mut queue = VecDeque::from([source_root.to_path_buf()]);

    while let Some(current_path) = queue.pop_front() {
        for entry in fs::read_dir(&current_path).map_err(error_to_string)? {
            let entry = entry.map_err(error_to_string)?;
            let file_type = entry.file_type().map_err(error_to_string)?;
            if file_type.is_symlink() {
                continue;
            }

            let source_path = entry.path();
            let relative_path = source_path
                .strip_prefix(source_root)
                .map_err(error_to_string)?;
            let destination_path = safe_join(destination_root, &to_portable_path(relative_path))?;

            if file_type.is_dir() {
                fs::create_dir_all(&destination_path).map_err(error_to_string)?;
                queue.push_back(source_path);
                continue;
            }

            if file_type.is_file() {
                if let Some(parent) = destination_path.parent() {
                    fs::create_dir_all(parent).map_err(error_to_string)?;
                }
                fs::copy(&source_path, &destination_path).map_err(error_to_string)?;
            }
        }
    }

    Ok(())
}

#[derive(Debug)]
struct PreparedDeploymentFile {
    staged_path: PathBuf,
    destination: PathBuf,
    containment_root: PathBuf,
    target_relative_path: String,
    is_game_file: bool,
}

fn deploy_plan_transaction(
    store_root: &Path,
    profile: &GameProfile,
    install_id: &str,
    source_path: &Path,
    plan: &InstallPlan,
    excluded_mod_id: Option<&str>,
) -> Result<DeploymentOutcome, String> {
    if plan.mappings.is_empty() {
        return Err("The selected install plan does not contain any files.".to_string());
    }
    if plan.mappings.len() > MAX_ARCHIVE_ENTRIES {
        return Err(format!(
            "The install plan contains too many files (maximum {}).",
            MAX_ARCHIVE_ENTRIES
        ));
    }

    let transaction_root = profile_dir(store_root, &profile.id)
        .join("transactions")
        .join(Uuid::new_v4().to_string());
    let stage_root = transaction_root.join("stage");
    let rollback_root = transaction_root.join("rollback");
    fs::create_dir_all(&stage_root).map_err(error_to_string)?;
    fs::create_dir_all(&rollback_root).map_err(error_to_string)?;

    let result = (|| -> Result<DeploymentOutcome, String> {
        let mut archive = if source_path.is_dir() {
            None
        } else {
            let archive_file = File::open(source_path).map_err(error_to_string)?;
            Some(ZipArchive::new(archive_file).map_err(error_to_string)?)
        };
        let archive_member_indices = if let Some(archive) = archive.as_mut() {
            let mut indices = HashMap::with_capacity(archive.len());
            for index in 0..archive.len() {
                let member = archive.by_index(index).map_err(error_to_string)?;
                let normalized = normalize_archive_path(member.name()).to_ascii_lowercase();
                if indices.insert(normalized.clone(), index).is_some() {
                    return Err(format!(
                        "The archive contains ambiguous duplicate paths after normalization: {normalized}"
                    ));
                }
            }
            Some(indices)
        } else {
            None
        };
        let profile_root = profile_dir(store_root, &profile.id);
        let mut prepared = Vec::with_capacity(plan.mappings.len());
        let mut destination_keys = HashSet::new();
        let mut expanded_bytes = 0_u64;

        for (index, mapping) in plan.mappings.iter().enumerate() {
            if mapping.generated_content.is_none() {
                validate_archive_relative_path(&mapping.source_path)?;
            }
            validate_archive_relative_path(&mapping.target_relative_path)?;

            let target_root = if mapping.target_root == "game" {
                PathBuf::from(&profile.game_path)
            } else {
                profile_root.clone()
            };
            let destination = safe_join(&target_root, &mapping.target_relative_path)?;
            validate_deployment_containment(&target_root, &destination)?;
            let destination_key =
                normalize_filesystem_identity(destination.to_string_lossy().as_ref());
            if !destination_keys.insert(destination_key.clone()) {
                return Err(format!(
                    "The install plan maps more than one file to {}.",
                    destination.to_string_lossy()
                ));
            }

            let existing_owner = if mapping.target_root == "game" {
                enabled_file_owner(store_root, &profile.id, &destination_key, excluded_mod_id)?
            } else {
                None
            };
            if let Some(owner) = existing_owner.as_ref() {
                if !(enshrouded::is_profile(profile)
                    && enshrouded_integration::is_native_alias(&destination))
                {
                    return Err(format!(
                        "File conflict: {} is already managed by {}. Disable or remove that mod first.",
                        mapping.target_relative_path,
                        display_record_name(owner)
                    ));
                }
            }

            let staged_path = stage_root.join(format!("{index}.bin"));
            let file_size = if let Some(content) = mapping.generated_content.as_deref() {
                let bytes = content.as_bytes();
                if bytes.len() as u64 > MAX_ARCHIVE_FILE_BYTES {
                    return Err(format!(
                        "Generated install content is too large: {}",
                        mapping.target_relative_path
                    ));
                }
                let mut output = File::create(&staged_path).map_err(error_to_string)?;
                output.write_all(bytes).map_err(error_to_string)?;
                output.sync_all().map_err(error_to_string)?;
                bytes.len() as u64
            } else if let Some(archive) = archive.as_mut() {
                let normalized_source =
                    normalize_archive_path(&mapping.source_path).to_ascii_lowercase();
                let member_index = archive_member_indices
                    .as_ref()
                    .and_then(|indices| indices.get(&normalized_source))
                    .copied()
                    .ok_or_else(|| format!("Archive entry is missing: {}", mapping.source_path))?;
                let mut zip_file = archive
                    .by_index(member_index)
                    .map_err(|_| format!("Archive entry is missing: {}", mapping.source_path))?;
                validate_archive_file_size(
                    &mapping.source_path,
                    zip_file.size(),
                    zip_file.compressed_size(),
                )?;
                let mut output = File::create(&staged_path).map_err(error_to_string)?;
                copy_with_limit(&mut zip_file, &mut output, MAX_ARCHIVE_FILE_BYTES)?
            } else {
                let source_file = safe_join(source_path, &mapping.source_path)?;
                if !source_file.is_file() {
                    return Err(format!("Folder entry is missing: {}", mapping.source_path));
                }
                let size = source_file.metadata().map_err(error_to_string)?.len();
                validate_archive_file_size(&mapping.source_path, size, size)?;
                let mut input = File::open(&source_file).map_err(error_to_string)?;
                let mut output = File::create(&staged_path).map_err(error_to_string)?;
                copy_with_limit(&mut input, &mut output, MAX_ARCHIVE_FILE_BYTES)?
            };
            if let Some(owner) = existing_owner.as_ref() {
                let expected =
                    managed_record_hash_for_path(owner, &destination).ok_or_else(|| {
                        "The shared native loader has no verified file receipt.".to_string()
                    })?;
                if sha256_file(&staged_path)? != expected || sha256_file(&destination)? != expected
                {
                    return Err("Shared Enshrouded loader content differs from its existing owner; no files were changed.".to_string());
                }
            }
            expanded_bytes = expanded_bytes
                .checked_add(file_size)
                .ok_or_else(|| "The expanded mod size overflowed its safety limit.".to_string())?;
            if expanded_bytes > MAX_ARCHIVE_EXPANDED_BYTES {
                return Err(format!(
                    "The mod expands beyond Mod Garrison's {} GB safety limit.",
                    MAX_ARCHIVE_EXPANDED_BYTES / 1024 / 1024 / 1024
                ));
            }

            prepared.push(PreparedDeploymentFile {
                staged_path,
                destination,
                containment_root: target_root,
                target_relative_path: mapping.target_relative_path.clone(),
                is_game_file: mapping.target_root == "game",
            });
        }

        let backup_root = profile_backup_dir(store_root, &profile.id, install_id);
        let mut files_written = Vec::with_capacity(prepared.len());
        let mut backups_written = Vec::new();
        let mut written_file_hashes = HashMap::new();
        let mut rollback_entries = Vec::new();
        let mut journal_entries = Vec::with_capacity(prepared.len());

        for (index, file) in prepared.iter().enumerate() {
            validate_deployment_containment(&file.containment_root, &file.destination)?;
            let immediate_backup = if file.destination.exists() {
                let backup = rollback_root.join(format!("{index}.bin"));
                copy_file_synced(&file.destination, &backup)?;
                Some(backup)
            } else {
                None
            };
            rollback_entries.push(DeploymentRollbackEntry {
                destination: file.destination.clone(),
                immediate_backup: immediate_backup.clone(),
            });

            let shared_owner = if file.is_game_file
                && enshrouded::is_profile(profile)
                && enshrouded_integration::is_native_alias(&file.destination)
            {
                enabled_file_owner(
                    store_root,
                    &profile.id,
                    &normalize_filesystem_identity(file.destination.to_string_lossy().as_ref()),
                    Some(install_id),
                )?
            } else {
                None
            };
            let shared_baseline = shared_owner.as_ref().map(|owner| {
                profile_backup_dir(store_root, &profile.id, &owner.id)
                    .join(&file.target_relative_path)
            });
            let preserved_owned_config = if enshrouded::is_profile(profile) {
                if let Some(previous_id) = excluded_mod_id {
                    let previous =
                        read_store::<InstalledModRecord>(&installed_mods_path(store_root))
                            .map_err(error_to_string)?;
                    previous
                        .items
                        .iter()
                        .find(|record| record.id == previous_id && record.profile_id == profile.id)
                        .is_some_and(|record| {
                            record.files_written.iter().any(|path| {
                                normalize_filesystem_identity(path)
                                    == normalize_filesystem_identity(
                                        file.destination.to_string_lossy().as_ref(),
                                    )
                            }) && !record.backups_written.iter().any(|path| {
                                Path::new(path)
                                    == profile_backup_dir(store_root, &profile.id, previous_id)
                                        .join(&file.target_relative_path)
                            })
                        })
                } else {
                    false
                }
            } else {
                false
            };
            if file.is_game_file
                && file.destination.exists()
                && !preserved_owned_config
                && (shared_owner.is_none()
                    || shared_baseline.as_ref().is_some_and(|path| path.is_file()))
            {
                let backup_path = safe_join(&backup_root, &file.target_relative_path)?;
                if !backup_path.exists() {
                    if let Some(parent) = backup_path.parent() {
                        fs::create_dir_all(parent).map_err(error_to_string)?;
                    }
                    let source = shared_baseline
                        .as_deref()
                        .filter(|path| path.is_file())
                        .unwrap_or(&file.destination);
                    copy_file_synced(source, &backup_path)?;
                }
                backups_written.push(backup_path.to_string_lossy().to_string());
            }

            journal_entries.push(DeploymentJournalEntry {
                target_root: if file.is_game_file {
                    "game".to_string()
                } else {
                    "profile".to_string()
                },
                target_relative_path: file.target_relative_path.clone(),
                staged_file: format!("stage/{index}.bin"),
                rollback_file: immediate_backup
                    .as_ref()
                    .map(|_| format!("rollback/{index}.bin")),
                expected_sha256: sha256_file(&file.staged_path)?,
            });
        }

        let journal = DeploymentJournal {
            version: DEPLOYMENT_JOURNAL_VERSION,
            profile_id: profile.id.clone(),
            install_id: install_id.to_string(),
            game_path: profile.game_path.clone(),
            phase: DeploymentJournalPhase::Applying,
            entries: journal_entries,
        };
        write_deployment_journal(&transaction_root, &journal)?;

        for (index, file) in prepared.iter().enumerate() {
            if let Err(error) = replace_file_from_path(&file.staged_path, &file.destination) {
                let outcome = DeploymentOutcome {
                    files_written,
                    backups_written,
                    written_file_hashes,
                    transaction_root: transaction_root.clone(),
                    rollback_entries,
                    journal,
                };
                return match outcome.rollback() {
                    Ok(()) => Err(error),
                    Err(rollback_error) => Err(format!("{error} {rollback_error}")),
                };
            }

            let destination_string = file.destination.to_string_lossy().to_string();
            let deployed_hash = match sha256_file(&file.destination) {
                Ok(hash) => hash,
                Err(error) => {
                    let outcome = DeploymentOutcome {
                        files_written,
                        backups_written,
                        written_file_hashes,
                        transaction_root: transaction_root.clone(),
                        rollback_entries,
                        journal,
                    };
                    return match outcome.rollback() {
                        Ok(()) => Err(format!(
                            "Could not verify deployed file {}: {error}",
                            file.target_relative_path
                        )),
                        Err(rollback_error) => Err(format!(
                            "Could not verify deployed file {}: {error} {rollback_error}",
                            file.target_relative_path
                        )),
                    };
                }
            };
            if deployed_hash != journal.entries[index].expected_sha256 {
                let outcome = DeploymentOutcome {
                    files_written,
                    backups_written,
                    written_file_hashes,
                    transaction_root: transaction_root.clone(),
                    rollback_entries,
                    journal,
                };
                let error = format!(
                    "Mod Garrison could not verify the deployed file: {}",
                    file.target_relative_path
                );
                return match outcome.rollback() {
                    Ok(()) => Err(error),
                    Err(rollback_error) => Err(format!("{error} {rollback_error}")),
                };
            }
            written_file_hashes.insert(destination_string.clone(), deployed_hash);
            files_written.push(destination_string);
        }

        Ok(DeploymentOutcome {
            files_written,
            backups_written,
            written_file_hashes,
            transaction_root: transaction_root.clone(),
            rollback_entries,
            journal,
        })
    })();

    if result.is_err()
        && transaction_root.exists()
        && !deployment_journal_path(&transaction_root).exists()
    {
        let _ = fs::remove_dir_all(&transaction_root);
    }
    result
}

fn validate_deployment_containment(root: &Path, candidate: &Path) -> Result<(), String> {
    if !root.is_dir() {
        return Err(format!(
            "Deployment root is unavailable: {}",
            root.to_string_lossy()
        ));
    }
    let root_canonical = fs::canonicalize(root).map_err(error_to_string)?;
    let root_identity = normalize_filesystem_identity(root.to_string_lossy().as_ref());
    let candidate_identity = normalize_filesystem_identity(candidate.to_string_lossy().as_ref());
    let root_prefix = format!("{}/", root_identity.trim_end_matches('/'));
    if candidate_identity != root_identity && !candidate_identity.starts_with(&root_prefix) {
        return Err("A deployment target is outside its approved root.".to_string());
    }

    let mut ancestor = candidate;
    while !ancestor.exists() {
        ancestor = ancestor
            .parent()
            .ok_or_else(|| "A deployment target has no valid parent directory.".to_string())?;
    }
    let ancestor_canonical = fs::canonicalize(ancestor).map_err(error_to_string)?;
    if !ancestor_canonical.starts_with(&root_canonical) {
        return Err(
            "A deployment target crosses a junction or symbolic link outside the game folder."
                .to_string(),
        );
    }
    if candidate.exists() {
        let candidate_canonical = fs::canonicalize(candidate).map_err(error_to_string)?;
        if !candidate_canonical.starts_with(&root_canonical) {
            return Err(
                "A deployment target resolves outside the approved game or profile folder."
                    .to_string(),
            );
        }
    }
    Ok(())
}

fn validate_managed_record_path(
    store_root: &Path,
    profile: &GameProfile,
    path: &Path,
) -> Result<(), String> {
    let game_root = Path::new(&profile.game_path);
    let profile_root = profile_dir(store_root, &profile.id);
    for root in [game_root, profile_root.as_path()] {
        if validate_deployment_containment(root, path).is_ok() {
            return Ok(());
        }
    }
    Err(format!(
        "Refused to modify a recorded path outside this profile: {}",
        path.to_string_lossy()
    ))
}

fn enabled_file_owner(
    store_root: &Path,
    profile_id: &str,
    destination_key: &str,
    excluded_mod_id: Option<&str>,
) -> Result<Option<InstalledModRecord>, String> {
    let store = read_store::<InstalledModRecord>(&installed_mods_path(store_root))
        .map_err(error_to_string)?;
    Ok(store.items.into_iter().find(|record| {
        record.profile_id == profile_id
            && record.enabled
            && excluded_mod_id != Some(record.id.as_str())
            && record
                .files_written
                .iter()
                .any(|path| normalize_filesystem_identity(path) == destination_key)
    }))
}

fn validate_archive_relative_path(path: &str) -> Result<(), String> {
    if path.is_empty() {
        return Err("Archive contains an empty path.".to_string());
    }
    if path.starts_with('/') || path.starts_with('\\') {
        return Err(format!("Archive path must be relative: {path}"));
    }
    if path.chars().any(char::is_control) {
        return Err(format!(
            "Archive path contains a control character: {path:?}"
        ));
    }

    let normalized = path.replace('\\', "/");
    if normalized.contains("//") {
        return Err(format!("Archive path contains repeated separators: {path}"));
    }
    let normalized = normalized.trim_end_matches('/');
    if normalized.is_empty() {
        return Err(format!("Archive path must name a file or folder: {path}"));
    }
    let components = normalized.split('/').collect::<Vec<_>>();
    if components.first().is_some_and(|component| {
        let bytes = component.as_bytes();
        bytes.len() >= 2 && bytes[0].is_ascii_alphabetic() && bytes[1] == b':'
    }) {
        return Err(format!(
            "Archive path must not contain a drive prefix: {path}"
        ));
    }
    for component in &components {
        if component.is_empty() || matches!(*component, "." | "..") {
            return Err(format!(
                "Archive path contains traversal or dot segments: {path}"
            ));
        }
        if component.len() > 255 {
            return Err(format!("Archive path component is too long: {path}"));
        }
        if component.ends_with('.') || component.ends_with(' ') {
            return Err(format!(
                "Archive path has a Windows-ambiguous trailing dot or space: {path}"
            ));
        }
        if component
            .chars()
            .any(|character| matches!(character, '<' | '>' | ':' | '"' | '|' | '?' | '*'))
        {
            return Err(format!(
                "Archive path contains a Windows-invalid character: {path}"
            ));
        }
        if is_windows_reserved_folder_name(component) {
            return Err(format!(
                "Archive path uses a reserved Windows device name: {path}"
            ));
        }
    }

    let depth = components.len();
    if depth > MAX_ARCHIVE_PATH_DEPTH {
        return Err(format!(
            "Archive path is nested too deeply (maximum {}): {}",
            MAX_ARCHIVE_PATH_DEPTH, path
        ));
    }
    if normalized.len() > 1024 {
        return Err("An archive path exceeds Mod Garrison's safety limit.".to_string());
    }
    Ok(())
}

fn normalized_archive_identity(path: &str) -> Result<String, String> {
    validate_archive_relative_path(path)?;
    Ok(path.replace('\\', "/").trim_end_matches('/').to_lowercase())
}

fn validate_archive_file_size(path: &str, size: u64, compressed_size: u64) -> Result<(), String> {
    if size > MAX_ARCHIVE_FILE_BYTES {
        return Err(format!("Archive file is too large: {path}"));
    }
    if compressed_size > 0 && size / compressed_size.max(1) > MAX_ARCHIVE_COMPRESSION_RATIO {
        return Err(format!(
            "Archive file has an unsafe compression ratio: {path}"
        ));
    }
    Ok(())
}

fn copy_with_limit<R: Read + ?Sized, W: Write>(
    reader: &mut R,
    writer: &mut W,
    limit: u64,
) -> Result<u64, String> {
    let mut limited = reader.take(limit.saturating_add(1));
    let copied = io::copy(&mut limited, writer).map_err(error_to_string)?;
    if copied > limit {
        return Err(format!(
            "A file exceeded Mod Garrison's {} MB safety limit.",
            limit / 1024 / 1024
        ));
    }
    Ok(copied)
}

fn replace_file_from_path(source: &Path, destination: &Path) -> Result<(), String> {
    if let Some(parent) = destination.parent() {
        fs::create_dir_all(parent).map_err(error_to_string)?;
    }
    let file_name = destination
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("mod-file");
    let temporary = destination.with_file_name(format!(".{file_name}.{}.tmp", Uuid::new_v4()));
    let result = (|| -> Result<(), String> {
        fs::copy(source, &temporary).map_err(|error| {
            format!(
                "Could not stage {} for {}: {error}",
                source.to_string_lossy(),
                destination.to_string_lossy()
            )
        })?;
        File::options()
            .read(true)
            .write(true)
            .open(&temporary)
            .and_then(|file| file.sync_all())
            .map_err(|error| format!("Could not flush {}: {error}", temporary.to_string_lossy()))?;
        replace_file_path_atomic(&temporary, destination).map_err(|error| {
            format!(
                "Could not activate {}: {error}",
                destination.to_string_lossy()
            )
        })
    })();
    if temporary.exists() {
        let _ = fs::remove_file(temporary);
    }
    result
}

fn sha256_file(path: &Path) -> Result<String, String> {
    let mut file = File::open(path).map_err(error_to_string)?;
    let mut hasher = Sha256::new();
    let mut buffer = [0_u8; 64 * 1024];
    loop {
        let read = file.read(&mut buffer).map_err(error_to_string)?;
        if read == 0 {
            break;
        }
        hasher.update(&buffer[..read]);
    }
    Ok(hex::encode(hasher.finalize()))
}

fn sha256_managed_source(path: &Path) -> Result<String, String> {
    if path.is_file() {
        return sha256_file(path);
    }
    if !path.is_dir() {
        return Err(format!(
            "Managed package source is missing: {}",
            path.to_string_lossy()
        ));
    }

    let mut relative_paths = collect_folder_relative_paths(path)?;
    relative_paths.sort_by_key(|relative| normalize_archive_path(relative).to_ascii_lowercase());
    let mut hasher = Sha256::new();
    hasher.update(b"mod-garrison-directory-v1\0");
    for relative_path in relative_paths {
        let normalized = normalize_archive_path(&relative_path);
        let path_bytes = normalized.as_bytes();
        hasher.update((path_bytes.len() as u64).to_le_bytes());
        hasher.update(path_bytes);
        let source_file = safe_join(path, &relative_path)?;
        let mut file = File::open(&source_file).map_err(error_to_string)?;
        let mut buffer = [0_u8; 64 * 1024];
        loop {
            let read = file.read(&mut buffer).map_err(error_to_string)?;
            if read == 0 {
                break;
            }
            hasher.update(&buffer[..read]);
        }
    }
    Ok(hex::encode(hasher.finalize()))
}

fn cleanup_install_data(store_root: &Path, profile_id: &str, install_id: &str) {
    let _ = fs::remove_dir_all(profile_package_dir(store_root, profile_id, install_id));
    let _ = fs::remove_dir_all(profile_backup_dir(store_root, profile_id, install_id));
    let receipt = profile_dir(store_root, profile_id)
        .join("receipts")
        .join(format!("{install_id}.json"));
    let _ = fs::remove_file(receipt);
}

fn restore_deactivated_mods(
    store_root: &Path,
    profile: &GameProfile,
    records: &[InstalledModRecord],
) -> Result<(), String> {
    let mut errors = Vec::new();
    for record in records {
        let Some(plan) = record.plan.clone() else {
            errors.push(format!(
                "{} has no saved install plan.",
                display_record_name(record)
            ));
            continue;
        };
        let mut restored = record.clone();
        let install_id = restored.id.clone();
        let archive_path = restored.archive_path.clone();
        if let Err(error) = deploy_mod_files(
            store_root,
            profile,
            &install_id,
            &archive_path,
            &plan,
            &mut restored,
        ) {
            errors.push(format!("{}: {error}", display_record_name(record)));
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(format!(
            "Mod Garrison could not fully restore deactivated mods: {}",
            errors.join(" ")
        ))
    }
}

fn restore_checkpoint_record(
    store_root: &Path,
    profile: &GameProfile,
    record: &InstalledModRecord,
) -> Result<(), String> {
    if !record.enabled || installed_record_files_match(record) {
        return commit_installed_mod_records(
            store_root,
            profile,
            std::slice::from_ref(record),
            &[],
        );
    }

    let plan = record.plan.clone().ok_or_else(|| {
        format!(
            "{} cannot be restored because its install plan is unavailable.",
            display_record_name(record)
        )
    })?;
    let mut restored = record.clone();
    let install_id = restored.id.clone();
    let archive_path = restored.archive_path.clone();
    let (_, deployment) = deploy_mod_files_pending(
        store_root,
        profile,
        &install_id,
        &archive_path,
        &plan,
        &mut restored,
    )?;
    if let Err(error) = commit_installed_mod_records(
        store_root,
        profile,
        std::slice::from_ref(&restored),
        &[&deployment],
    ) {
        let _ = deployment.rollback();
        return Err(error);
    }
    deployment.commit()
}

fn installed_record_files_match(record: &InstalledModRecord) -> bool {
    !record.files_written.is_empty()
        && record.files_written.iter().all(|file_path| {
            let Some(expected_hash) = record.written_file_hashes.get(file_path) else {
                return false;
            };
            let path = Path::new(file_path);
            path.is_file()
                && sha256_file(path)
                    .is_ok_and(|actual_hash| actual_hash.eq_ignore_ascii_case(expected_hash))
        })
}

fn validate_profile_migration_plans(
    profile: &GameProfile,
    records: &[InstalledModRecord],
) -> Result<(), String> {
    let mut destinations = HashMap::<String, String>::new();
    for record in records
        .iter()
        .filter(|record| record.profile_id == profile.id && record.enabled)
    {
        let plan = record.plan.as_ref().ok_or_else(|| {
            format!(
                "{} cannot be migrated because its install plan is unavailable.",
                display_record_name(record)
            )
        })?;
        if let Some(reason) = incompatible_install_plan_reason(profile, plan) {
            return Err(format!("{}: {reason}", display_record_name(record)));
        }
        for mapping in plan
            .mappings
            .iter()
            .filter(|mapping| mapping.target_root == "game")
        {
            let destination =
                safe_join(Path::new(&profile.game_path), &mapping.target_relative_path)?;
            let key = normalize_filesystem_identity(destination.to_string_lossy().as_ref());
            if let Some(owner) = destinations.insert(key, display_record_name(record)) {
                return Err(format!(
                    "{} and {} both target {}. Resolve this conflict before changing folders.",
                    owner,
                    display_record_name(record),
                    mapping.target_relative_path
                ));
            }
        }
    }
    Ok(())
}

#[allow(dead_code)]
fn rollback_profile_migration(
    store_root: &Path,
    old_profile: &GameProfile,
    new_profile: &GameProfile,
    migrated_records: &[InstalledModRecord],
    old_records: &[InstalledModRecord],
) {
    for record in migrated_records.iter().rev() {
        let _ = deactivate_mod_files(store_root, new_profile, record);
        let _ = fs::remove_dir_all(profile_backup_dir(store_root, &new_profile.id, &record.id));
    }
    let _ = restore_deactivated_mods(store_root, old_profile, old_records);
    for record in old_records {
        let _ = write_receipt(store_root, old_profile, record);
    }
}

fn prepare_profile_mod_launch(
    store_root: &Path,
    profile: &GameProfile,
    mods_enabled: bool,
) -> Result<usize, String> {
    if mods_enabled {
        resume_profile_mod_files(store_root, profile)
    } else {
        suspend_profile_mod_files(store_root, profile)
    }
}

fn persist_profile_launch_mode(
    store_root: &Path,
    profile_id: &str,
    mods_enabled: bool,
) -> Result<(), String> {
    let _commit = lock_mutations()?;
    let profiles_file = profiles_path(store_root);
    let mut profiles = read_store::<GameProfile>(&profiles_file).map_err(error_to_string)?;
    let profile = profiles
        .items
        .iter_mut()
        .find(|profile| profile.id == profile_id)
        .ok_or_else(|| format!("Profile not found: {profile_id}"))?;
    profile.mods_enabled = mods_enabled;
    profile.updated_at = now_string();
    write_store(&profiles_file, &profiles).map_err(error_to_string)
}

fn record_is_mod_garrison_owned(record: &InstalledModRecord) -> bool {
    if record.externally_managed {
        return false;
    }

    !record.package_id.as_deref().is_some_and(|package_id| {
        package_id.starts_with("external-script:") || package_id.starts_with("observed-runtime:")
    })
}

fn suspend_profile_mod_files(store_root: &Path, profile: &GameProfile) -> Result<usize, String> {
    let store = read_store::<InstalledModRecord>(&installed_mods_path(store_root))
        .map_err(error_to_string)?;
    let mut suspension = read_profile_launch_suspension(store_root, &profile.id)?;
    let original_suspension = suspension.clone();
    let mut suspended_records = Vec::<(InstalledModRecord, SuspendedLaunchMod)>::new();

    for record in store.items.iter().filter(|record| {
        record.profile_id == profile.id && record.enabled && record_is_mod_garrison_owned(record)
    }) {
        let has_active_files = record
            .files_written
            .iter()
            .any(|file_path| Path::new(file_path).is_file());
        if !has_active_files {
            continue;
        }

        let suspended = if let Some(existing) = suspension
            .mods
            .iter()
            .find(|item| item.mod_id == record.id)
            .cloned()
        {
            existing
        } else {
            let staged_files = if installed_record_can_redeploy(record) {
                Vec::new()
            } else {
                match stage_launch_mod_files(store_root, profile, record) {
                    Ok(files) => files,
                    Err(error) => {
                        rollback_launch_suspension(store_root, profile, &suspended_records);
                        cleanup_new_launch_snapshots(store_root, &original_suspension, &suspension);
                        return Err(format!(
                            "Could not prepare a clean launch for {}: {error}",
                            display_record_name(record)
                        ));
                    }
                }
            };
            let suspended = SuspendedLaunchMod {
                mod_id: record.id.clone(),
                staged_files,
            };
            suspension.mods.push(suspended.clone());
            suspended
        };

        if let Err(error) = deactivate_mod_files(store_root, profile, record) {
            rollback_launch_suspension(store_root, profile, &suspended_records);
            cleanup_new_launch_snapshots(store_root, &original_suspension, &suspension);
            return Err(format!(
                "Could not prepare a clean launch because {} could not be suspended: {error}",
                display_record_name(record)
            ));
        }
        suspended_records.push((record.clone(), suspended));
    }

    let rebase = if store.items.iter().any(|record| {
        record.profile_id == profile.id
            && record.enabled
            && enshrouded_patch_state::record_uses_eml(record)
    }) {
        match enshrouded_patch_state::rebase_mod_data(
            store_root,
            profile,
            "enshrouded-clean-launch",
        ) {
            Ok(deployment) => deployment,
            Err(error) => {
                rollback_launch_suspension(store_root, profile, &suspended_records);
                cleanup_new_launch_snapshots(store_root, &original_suspension, &suspension);
                return Err(error);
            }
        }
    } else {
        None
    };
    if let Err(error) = write_profile_launch_suspension(store_root, &suspension, rebase.as_ref()) {
        let rollback_error = rebase
            .as_ref()
            .and_then(|deployment| deployment.rollback().err());
        rollback_launch_suspension(store_root, profile, &suspended_records);
        cleanup_new_launch_snapshots(store_root, &original_suspension, &suspension);
        return Err(match rollback_error {
            Some(rollback) => format!("{error} {rollback}"),
            None => error,
        });
    }
    if let Some(deployment) = rebase {
        let _ = deployment.commit();
    }

    Ok(suspended_records.len())
}

fn resume_profile_mod_files(store_root: &Path, profile: &GameProfile) -> Result<usize, String> {
    let suspension = read_profile_launch_suspension(store_root, &profile.id)?;
    if suspension.mods.is_empty() {
        return Ok(0);
    }

    let store = read_store::<InstalledModRecord>(&installed_mods_path(store_root))
        .map_err(error_to_string)?;
    let mut restored_records = Vec::<InstalledModRecord>::new();

    for suspended in &suspension.mods {
        let Some(record) = store.items.iter().find(|record| {
            record.id == suspended.mod_id
                && record.profile_id == profile.id
                && record.enabled
                && record_is_mod_garrison_owned(record)
        }) else {
            continue;
        };

        if let Err(error) = restore_suspended_launch_mod(store_root, profile, record, suspended) {
            for restored in restored_records.iter().rev() {
                let _ = deactivate_mod_files(store_root, profile, restored);
            }
            return Err(format!(
                "Could not restore {} for this launch: {error}",
                display_record_name(record)
            ));
        }
        restored_records.push(record.clone());
    }

    if let Err(error) = clear_profile_launch_suspension(store_root, &profile.id) {
        for restored in restored_records.iter().rev() {
            let _ = deactivate_mod_files(store_root, profile, restored);
        }
        return Err(error);
    }

    Ok(restored_records.len())
}

fn installed_record_can_redeploy(record: &InstalledModRecord) -> bool {
    record.plan.is_some() && Path::new(&record.archive_path).exists()
}

fn stage_launch_mod_files(
    store_root: &Path,
    profile: &GameProfile,
    record: &InstalledModRecord,
) -> Result<Vec<SuspendedLaunchFile>, String> {
    let suspension_root = profile_launch_suspension_dir(store_root, &profile.id);
    let files_root = suspension_root.join("files");
    fs::create_dir_all(&files_root).map_err(error_to_string)?;
    let mut staged = Vec::new();

    let result = (|| -> Result<(), String> {
        for destination in &record.files_written {
            let destination_path = Path::new(destination);
            if !destination_path.exists() {
                continue;
            }
            if !destination_path.is_file()
                || fs::symlink_metadata(destination_path)
                    .map_err(error_to_string)?
                    .file_type()
                    .is_symlink()
                || !path_is_inside(destination_path, Path::new(&profile.game_path))
            {
                return Err(format!(
                    "Mod Garrison will not stage an unsafe mod path: {}",
                    destination_path.to_string_lossy()
                ));
            }

            let snapshot_relative_path = format!("files/{}.bin", Uuid::new_v4());
            let snapshot_path = safe_join(&suspension_root, &snapshot_relative_path)?;
            fs::copy(destination_path, &snapshot_path).map_err(|error| {
                format!(
                    "Could not stage {} for a clean launch: {error}",
                    destination_path.to_string_lossy()
                )
            })?;
            staged.push(SuspendedLaunchFile {
                destination: destination.clone(),
                snapshot_relative_path,
            });
        }
        Ok(())
    })();

    if let Err(error) = result {
        remove_staged_launch_files(store_root, &profile.id, &staged);
        return Err(error);
    }

    Ok(staged)
}

fn restore_suspended_launch_mod(
    store_root: &Path,
    profile: &GameProfile,
    record: &InstalledModRecord,
    suspended: &SuspendedLaunchMod,
) -> Result<(), String> {
    if suspended.staged_files.is_empty() {
        let plan = record.plan.clone().ok_or_else(|| {
            "The managed source and install plan are no longer available.".to_string()
        })?;
        if !Path::new(&record.archive_path).exists() {
            return Err("The managed mod source is no longer available.".to_string());
        }
        let mut restored = record.clone();
        let install_id = restored.id.clone();
        let archive_path = restored.archive_path.clone();
        deploy_mod_files(
            store_root,
            profile,
            &install_id,
            &archive_path,
            &plan,
            &mut restored,
        )?;
        return Ok(());
    }

    let suspension_root = profile_launch_suspension_dir(store_root, &profile.id);
    for staged in &suspended.staged_files {
        let snapshot_path = safe_join(&suspension_root, &staged.snapshot_relative_path)?;
        if !snapshot_path.is_file() {
            return Err(format!(
                "A staged mod file is missing: {}",
                snapshot_path.to_string_lossy()
            ));
        }
        let destination = PathBuf::from(&staged.destination);
        if !launch_destination_is_inside_game(&destination, Path::new(&profile.game_path)) {
            return Err(format!(
                "A staged destination is outside the game folder: {}",
                destination.to_string_lossy()
            ));
        }
        replace_file_from_path(&snapshot_path, &destination)?;
    }
    Ok(())
}

fn launch_destination_is_inside_game(destination: &Path, game_path: &Path) -> bool {
    if destination.exists() {
        return path_is_inside(destination, game_path);
    }
    destination
        .parent()
        .is_some_and(|parent| path_is_inside(parent, game_path))
}

fn rollback_launch_suspension(
    store_root: &Path,
    profile: &GameProfile,
    suspended_records: &[(InstalledModRecord, SuspendedLaunchMod)],
) {
    for (record, suspended) in suspended_records.iter().rev() {
        let _ = restore_suspended_launch_mod(store_root, profile, record, suspended);
    }
}

fn cleanup_new_launch_snapshots(
    store_root: &Path,
    original: &ProfileLaunchSuspension,
    current: &ProfileLaunchSuspension,
) {
    let original_paths = original
        .mods
        .iter()
        .flat_map(|item| item.staged_files.iter())
        .map(|file| file.snapshot_relative_path.as_str())
        .collect::<HashSet<_>>();
    let new_files = current
        .mods
        .iter()
        .flat_map(|item| item.staged_files.iter())
        .filter(|file| !original_paths.contains(file.snapshot_relative_path.as_str()))
        .cloned()
        .collect::<Vec<_>>();
    remove_staged_launch_files(store_root, &current.profile_id, &new_files);
}

fn remove_staged_launch_files(
    store_root: &Path,
    profile_id: &str,
    staged_files: &[SuspendedLaunchFile],
) {
    let suspension_root = profile_launch_suspension_dir(store_root, profile_id);
    for staged in staged_files {
        if let Ok(path) = safe_join(&suspension_root, &staged.snapshot_relative_path) {
            let _ = fs::remove_file(path);
        }
    }
}

fn read_profile_launch_suspension(
    store_root: &Path,
    profile_id: &str,
) -> Result<ProfileLaunchSuspension, String> {
    let path = profile_launch_suspension_manifest_path(store_root, profile_id);
    if !path.exists() {
        return Ok(ProfileLaunchSuspension {
            version: PROFILE_LAUNCH_SUSPENSION_VERSION,
            profile_id: profile_id.to_string(),
            mods: Vec::new(),
        });
    }

    let content = fs::read_to_string(&path).map_err(error_to_string)?;
    let suspension = parse_json_allow_bom::<ProfileLaunchSuspension>(&content)
        .map_err(|error| format!("Could not read the clean-launch state: {error}"))?;
    if suspension.version != PROFILE_LAUNCH_SUSPENSION_VERSION
        || suspension.profile_id != profile_id
    {
        return Err("The saved clean-launch state is not valid for this profile.".to_string());
    }
    Ok(suspension)
}

fn write_profile_launch_suspension(
    store_root: &Path,
    suspension: &ProfileLaunchSuspension,
    deployment: Option<&DeploymentOutcome>,
) -> Result<(), String> {
    if suspension.mods.is_empty() && deployment.is_none() {
        return Ok(());
    }
    let mut writes = Vec::new();
    if !suspension.mods.is_empty() {
        let path = profile_launch_suspension_manifest_path(store_root, &suspension.profile_id);
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent).map_err(error_to_string)?;
        }
        writes.push(StoreBatchWrite {
            target: path,
            content: serialize_json_line(suspension)?,
        });
    }
    if let Some(deployment) = deployment {
        let mut journal = deployment.journal.clone();
        journal.phase = DeploymentJournalPhase::StateCommitted;
        writes.push(StoreBatchWrite {
            target: deployment_journal_path(&deployment.transaction_root),
            content: serialize_json_line(&journal)?,
        });
    }
    let _commit = lock_mutations()?;
    commit_store_batch(store_root, writes).map_err(error_to_string)
}

fn clear_profile_launch_suspension(store_root: &Path, profile_id: &str) -> Result<(), String> {
    let suspension_root = profile_launch_suspension_dir(store_root, profile_id);
    if !suspension_root.exists() {
        return Ok(());
    }
    let cleared =
        suspension_root.with_file_name(format!("launch-suspension-cleared-{}", Uuid::new_v4()));
    fs::rename(&suspension_root, &cleared)
        .map_err(|error| format!("Could not finish restoring the selected mods: {error}"))?;
    let _ = fs::remove_dir_all(cleared);
    Ok(())
}

#[derive(Debug, Default)]
struct DeactivationOutcome {
    files_changed: Vec<String>,
    preserved_files: Vec<String>,
    warnings: Vec<String>,
    transaction_root: Option<PathBuf>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ModifiedFilePolicy {
    Reject,
    RequireRemovalConfirmation,
    Preserve,
    AllowConfigChanges,
    PreserveConfigChanges,
    RetireConfigsOnly,
}

fn deactivate_mod_files(
    store_root: &Path,
    profile: &GameProfile,
    record: &InstalledModRecord,
) -> Result<Vec<String>, String> {
    deactivate_mod_files_with_policy(store_root, profile, record, ModifiedFilePolicy::Reject)
        .map(|outcome| outcome.files_changed)
}

fn deactivation_journal_path(transaction_root: &Path) -> PathBuf {
    transaction_root.join("deactivation.json")
}

fn managed_path_journal_location(
    store_root: &Path,
    profile: &GameProfile,
    path: &Path,
) -> Result<(String, String), String> {
    let game_root = Path::new(&profile.game_path);
    if let Ok(relative) = path.strip_prefix(game_root) {
        return Ok(("game".to_string(), to_portable_path(relative)));
    }
    let profile_root = profile_dir(store_root, &profile.id);
    if let Ok(relative) = path.strip_prefix(&profile_root) {
        return Ok(("profile".to_string(), to_portable_path(relative)));
    }
    Err(format!(
        "Managed deactivation path is outside its game and profile roots: {}",
        path.to_string_lossy()
    ))
}

fn write_deactivation_journal(
    transaction_root: &Path,
    journal: &DeactivationJournal,
) -> Result<(), String> {
    atomic_write(
        &deactivation_journal_path(transaction_root),
        &serialize_json_line(journal)?,
    )
    .map_err(error_to_string)
}

fn deactivate_mod_files_with_policy(
    store_root: &Path,
    profile: &GameProfile,
    record: &InstalledModRecord,
    modified_file_policy: ModifiedFilePolicy,
) -> Result<DeactivationOutcome, String> {
    deactivate_mod_files_with_policy_and_paths(
        store_root,
        profile,
        record,
        modified_file_policy,
        &[],
    )
}

fn deactivate_mod_files_with_policy_and_paths(
    store_root: &Path,
    profile: &GameProfile,
    record: &InstalledModRecord,
    modified_file_policy: ModifiedFilePolicy,
    additional_config_paths: &[PathBuf],
) -> Result<DeactivationOutcome, String> {
    if !additional_config_paths.is_empty()
        && !matches!(
            modified_file_policy,
            ModifiedFilePolicy::AllowConfigChanges | ModifiedFilePolicy::RetireConfigsOnly
        )
    {
        return Err(
            "Additional configuration paths require a configuration-aware deactivation policy."
                .to_string(),
        );
    }
    let verified_config_identities = if additional_config_paths.is_empty() {
        HashSet::new()
    } else {
        verified_target_switch_config_paths(profile, record)?
            .into_iter()
            .map(|path| normalize_filesystem_identity(path.to_string_lossy().as_ref()))
            .collect::<HashSet<_>>()
    };
    for config_path in additional_config_paths {
        let identity = normalize_filesystem_identity(config_path.to_string_lossy().as_ref());
        if !is_user_editable_config_file(config_path)
            || !verified_config_identities.contains(&identity)
        {
            return Err(format!(
                "Refused to retire a configuration path that is not present in this mod's verified receipt or install plan: {}",
                config_path.to_string_lossy()
            ));
        }
    }

    let backup_root = profile_backup_dir(store_root, &profile.id, &record.id);
    let mut validated_backups = Vec::with_capacity(record.backups_written.len());
    for backup_path in &record.backups_written {
        let backup = PathBuf::from(backup_path);
        let relative_path = backup.strip_prefix(&backup_root).map_err(|_| {
            format!(
                "Refused to restore a managed overwrite backup outside this mod's backup folder: {}",
                backup.to_string_lossy()
            )
        })?;
        if !backup.is_file() {
            return Err(format!(
                "Cannot safely deactivate {} because its managed overwrite backup is missing or is not a regular file: {}",
                display_record_name(record),
                backup.to_string_lossy()
            ));
        }
        validate_deployment_containment(&backup_root, &backup).map_err(|error| {
            format!(
                "Cannot safely deactivate {} because its managed overwrite backup is invalid: {} ({error})",
                display_record_name(record),
                backup.to_string_lossy()
            )
        })?;
        let backup_hash = sha256_file(&backup).map_err(|error| {
            format!(
                "Cannot safely deactivate {} because its managed overwrite backup could not be verified: {} ({error})",
                display_record_name(record),
                backup.to_string_lossy()
            )
        })?;
        let target = safe_join(
            Path::new(&profile.game_path),
            &to_portable_path(relative_path),
        )?;
        validate_deployment_containment(Path::new(&profile.game_path), &target).map_err(
            |error| {
                format!(
                    "Cannot safely deactivate {} because its managed overwrite target is invalid: {} ({error})",
                    display_record_name(record),
                    target.to_string_lossy()
                )
            },
        )?;
        validated_backups.push((backup, target, backup_hash));
    }

    let transaction_root = profile_dir(store_root, &profile.id)
        .join("transactions")
        .join(Uuid::new_v4().to_string());
    fs::create_dir_all(&transaction_root).map_err(error_to_string)?;

    let mut managed_path_identities = HashSet::new();
    let mut managed_paths_to_remove = Vec::new();
    for path in record
        .files_written
        .iter()
        .map(PathBuf::from)
        .chain(additional_config_paths.iter().cloned())
    {
        let identity = normalize_filesystem_identity(path.to_string_lossy().as_ref());
        if managed_path_identities.insert(identity) {
            managed_paths_to_remove.push(path);
        }
    }
    let mut affected_paths = managed_paths_to_remove.clone();
    for (_, target, _) in &validated_backups {
        let identity = normalize_filesystem_identity(target.to_string_lossy().as_ref());
        if managed_path_identities.insert(identity) {
            affected_paths.push(target.clone());
        }
    }
    for path in &affected_paths {
        validate_managed_record_path(store_root, profile, path)?;
    }

    let mut preserved_identities = if modified_file_policy == ModifiedFilePolicy::RetireConfigsOnly
    {
        affected_paths
            .iter()
            .filter(|path| !is_user_editable_config_file(path))
            .map(|path| normalize_filesystem_identity(path.to_string_lossy().as_ref()))
            .collect::<HashSet<_>>()
    } else {
        HashSet::new()
    };
    let mut preserved_files = Vec::new();
    let mut warnings = Vec::new();
    for file_path in &record.files_written {
        let path = PathBuf::from(file_path);
        if !path.exists() {
            continue;
        }
        let identity = normalize_filesystem_identity(path.to_string_lossy().as_ref());
        if enshrouded_integration::shared_alias_is_retained(store_root, profile, record, &path)? {
            preserved_identities.insert(identity);
            continue;
        }
        if preserved_identities.contains(&identity) {
            continue;
        }
        if modified_file_policy == ModifiedFilePolicy::PreserveConfigChanges
            && is_user_editable_config_file(&path)
        {
            if preserved_identities.insert(identity) {
                preserved_files.push(path.to_string_lossy().to_string());
            }
            continue;
        }
        let expected_hash = managed_record_hash_for_path(record, &path);
        let matches_receipt = path.is_file()
            && expected_hash.is_none_or(|expected_hash| {
                sha256_file(&path)
                    .is_ok_and(|current_hash| current_hash.eq_ignore_ascii_case(expected_hash))
            });
        if matches_receipt {
            continue;
        }

        let message = format!(
            "Mod Garrison did not remove {} because it was modified after installation: {}",
            display_record_name(record),
            path.to_string_lossy()
        );
        match modified_file_policy {
            ModifiedFilePolicy::Reject => {
                let _ = fs::remove_dir_all(&transaction_root);
                return Err(message);
            }
            ModifiedFilePolicy::RequireRemovalConfirmation => {
                let _ = fs::remove_dir_all(&transaction_root);
                return Err(format!("{FORCE_REMOVAL_REQUIRED_PREFIX}{message}"));
            }
            ModifiedFilePolicy::Preserve => {
                let identity = normalize_filesystem_identity(path.to_string_lossy().as_ref());
                if preserved_identities.insert(identity) {
                    let display_path = path.to_string_lossy().to_string();
                    preserved_files.push(display_path.clone());
                    warnings.push(format!(
                        "Mod Garrison forgot the managed record but left this modified or unverified file untouched: {display_path}"
                    ));
                }
            }
            ModifiedFilePolicy::AllowConfigChanges if is_user_editable_config_file(&path) => {
                // Target switching snapshots these bytes before deactivation and
                // redeploys them through the new target's deployment journal.
            }
            ModifiedFilePolicy::AllowConfigChanges => {
                let _ = fs::remove_dir_all(&transaction_root);
                return Err(message);
            }
            ModifiedFilePolicy::PreserveConfigChanges => {
                let _ = fs::remove_dir_all(&transaction_root);
                return Err(message);
            }
            ModifiedFilePolicy::RetireConfigsOnly if is_user_editable_config_file(&path) => {}
            ModifiedFilePolicy::RetireConfigsOnly => {
                let _ = fs::remove_dir_all(&transaction_root);
                return Err(message);
            }
        }
    }

    let expected_post_hashes = validated_backups
        .iter()
        .map(|(_, target, hash)| {
            (
                normalize_filesystem_identity(target.to_string_lossy().as_ref()),
                hash.clone(),
            )
        })
        .collect::<HashMap<_, _>>();
    let mut journal_entries = Vec::with_capacity(affected_paths.len());
    for (index, path) in affected_paths.iter().enumerate() {
        let identity = normalize_filesystem_identity(path.to_string_lossy().as_ref());
        if preserved_identities.contains(&identity) {
            continue;
        }
        let snapshot_file = if path.exists() {
            if !path.is_file() {
                let _ = fs::remove_dir_all(&transaction_root);
                return Err(format!(
                    "Mod Garrison cannot safely replace a folder where a managed file was expected: {}",
                    path.to_string_lossy()
                ));
            }
            let snapshot_file = format!("{index}.bin");
            let snapshot = transaction_root.join(&snapshot_file);
            copy_file_synced(path, &snapshot)?;
            Some(snapshot_file)
        } else {
            None
        };
        let (target_root, target_relative_path) =
            managed_path_journal_location(store_root, profile, path)?;
        journal_entries.push(DeactivationJournalEntry {
            target_root,
            target_relative_path,
            snapshot_file,
            expected_deactivated_sha256: expected_post_hashes.get(&identity).cloned(),
        });
    }
    let journal = DeactivationJournal {
        version: DEACTIVATION_JOURNAL_VERSION,
        id: transaction_root
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or_default()
            .to_string(),
        profile_id: profile.id.clone(),
        record_id: record.id.clone(),
        game_path: profile.game_path.clone(),
        original_record: if enshrouded::is_profile(profile) {
            read_store::<InstalledModRecord>(&installed_mods_path(store_root))
                .map_err(error_to_string)?
                .items
                .into_iter()
                .find(|original| original.id == record.id && original.profile_id == profile.id)
                .unwrap_or_else(|| record.clone())
        } else {
            record.clone()
        },
        entries: journal_entries,
    };
    if let Err(error) = write_deactivation_journal(&transaction_root, &journal) {
        let _ = fs::remove_dir_all(&transaction_root);
        return Err(error);
    }

    let operation = (|| -> Result<Vec<String>, String> {
        let mut files_changed = Vec::new();
        for path in &managed_paths_to_remove {
            let identity = normalize_filesystem_identity(path.to_string_lossy().as_ref());
            if preserved_identities.contains(&identity) {
                continue;
            }
            if path.exists() {
                fs::remove_file(path).map_err(error_to_string)?;
                files_changed.push(path.to_string_lossy().to_string());
            }
        }

        for (backup, target, expected_hash) in &validated_backups {
            if sha256_file(backup)? != *expected_hash {
                return Err(format!(
                    "Cannot safely deactivate {} because its managed overwrite backup changed after verification: {}",
                    display_record_name(record),
                    backup.to_string_lossy()
                ));
            }
            let target_identity = normalize_filesystem_identity(target.to_string_lossy().as_ref());
            if preserved_identities.contains(&target_identity) {
                continue;
            }
            replace_file_from_path(backup, target)?;
            files_changed.push(target.to_string_lossy().to_string());
        }
        Ok(files_changed)
    })();

    match operation {
        Ok(mut files_changed) => {
            files_changed.sort_by_key(|path| normalize_filesystem_identity(path));
            files_changed.dedup_by(|first, second| {
                normalize_filesystem_identity(first) == normalize_filesystem_identity(second)
            });
            warnings.sort();
            warnings.dedup();
            Ok(DeactivationOutcome {
                files_changed,
                preserved_files,
                warnings,
                transaction_root: Some(transaction_root),
            })
        }
        Err(error) => {
            match restore_deactivation_journal(
                store_root,
                profile,
                &transaction_root,
                &journal,
            ) {
                Ok(true) => {
                    let _ = fs::remove_dir_all(transaction_root);
                    Err(error)
                }
                Ok(false) => Err(format!(
                    "{error} Deactivation rollback was deferred because the game path is unavailable. Recovery data was retained at {}.",
                    transaction_root.to_string_lossy()
                )),
                Err(restore_error) => Err(format!(
                    "{error} Deactivation rollback was incomplete and its recovery data was retained at {}: {restore_error}",
                    transaction_root.to_string_lossy()
                )),
            }
        }
    }
}

fn deploy_mod_files(
    store_root: &Path,
    profile: &GameProfile,
    install_id: &str,
    archive_path: &str,
    plan: &InstallPlan,
    record: &mut InstalledModRecord,
) -> Result<Vec<String>, String> {
    let (files_written, deployment) =
        deploy_mod_files_pending(store_root, profile, install_id, archive_path, plan, record)?;
    deployment.commit()?;
    Ok(files_written)
}

fn deploy_mod_files_pending(
    store_root: &Path,
    profile: &GameProfile,
    install_id: &str,
    archive_path: &str,
    plan: &InstallPlan,
    record: &mut InstalledModRecord,
) -> Result<(Vec<String>, DeploymentOutcome), String> {
    let source_path = Path::new(archive_path);
    verify_managed_source_integrity(record, source_path)?;
    let deployment = deploy_plan_transaction(
        store_root,
        profile,
        install_id,
        source_path,
        plan,
        Some(&record.id),
    )?;
    record.files_written = deployment.files_written.clone();
    record.backups_written = deployment.backups_written.clone();
    record.written_file_hashes = deployment.written_file_hashes.clone();
    let files_written = deployment.files_written.clone();
    Ok((files_written, deployment))
}

fn verify_managed_source_integrity(
    record: &InstalledModRecord,
    source_path: &Path,
) -> Result<(), String> {
    let Some(expected_hash) = record.source_archive_sha256.as_deref() else {
        return Ok(());
    };
    if !source_path.is_file() && !source_path.is_dir() {
        return Err(format!(
            "The managed source for {} is missing or is no longer a file or folder.",
            display_record_name(record)
        ));
    }
    let actual_hash = sha256_managed_source(source_path)?;
    if !actual_hash.eq_ignore_ascii_case(expected_hash.trim()) {
        return Err(format!(
            "The managed source for {} changed after installation. Reinstall the mod from its provider or original archive.",
            display_record_name(record)
        ));
    }
    Ok(())
}

fn adopt_existing_native_script_mods(
    store_root: &Path,
    profile: &GameProfile,
    store: &mut StoreFile<InstalledModRecord>,
) -> Result<usize, String> {
    let script_files = discover_native_script_files(profile);
    if script_files.is_empty() {
        return Ok(0);
    }

    let existing_targets = store
        .items
        .iter()
        .filter(|record| record.profile_id == profile.id && record.last_status != "removed")
        .flat_map(|record| record.files_written.iter())
        .map(|path| normalize_filesystem_identity(path))
        .collect::<HashSet<_>>();

    let mut adopted_count = 0;
    for script_file in script_files {
        let target_identity =
            normalize_filesystem_identity(script_file.absolute_path.to_string_lossy().as_ref());
        if existing_targets.contains(&target_identity) {
            continue;
        }

        let install_id = Uuid::new_v4().to_string();
        let source_root = profile_package_dir(store_root, &profile.id, &install_id).join("source");
        let managed_source_path = safe_join(&source_root, &script_file.source_relative_path)?;
        if let Some(parent) = managed_source_path.parent() {
            fs::create_dir_all(parent).map_err(error_to_string)?;
        }
        fs::copy(&script_file.absolute_path, &managed_source_path).map_err(error_to_string)?;

        let plan = InstallPlan {
            adapter_id: "script-files".to_string(),
            adapter_name: "Native Script Mods".to_string(),
            confidence: 1.0,
            summary: format!(
                "Track existing script mod at {}.",
                script_file.target_relative_path
            ),
            mappings: vec![mapping(
                &script_file.source_relative_path,
                "game",
                &script_file.target_relative_path,
                "Existing game-side script mod adopted by Mod Garrison.",
            )],
            dependencies: Vec::new(),
            warnings: Vec::new(),
            requires_confirmation: false,
        };
        let display_name = humanize_mod_display_name(&script_file.source_relative_path);
        let installed_at = now_string();
        let record = InstalledModRecord {
            id: install_id,
            profile_id: profile.id.clone(),
            archive_path: source_root.to_string_lossy().to_string(),
            archive_name: basename(&script_file.source_relative_path),
            display_name: Some(display_name),
            package_id: Some(format!(
                "external-script:{}",
                script_file.target_relative_path.to_lowercase()
            )),
            package_provider: Some("local".to_string()),
            package_version: None,
            provider_file_id: None,
            provider_variant: None,
            source_archive_sha256: None,
            dependency_string: None,
            icon_url: None,
            adapter_id: "script-files".to_string(),
            summary: format!(
                "Existing script mod tracked from {}.",
                script_file.target_relative_path
            ),
            installed_at,
            files_written: vec![script_file.absolute_path.to_string_lossy().to_string()],
            backups_written: Vec::new(),
            written_file_hashes: HashMap::from([(
                script_file.absolute_path.to_string_lossy().to_string(),
                sha256_file(&script_file.absolute_path)?,
            )]),
            dependencies: Vec::new(),
            config_files: Vec::new(),
            runtime_id: None,
            externally_managed: true,
            enabled: true,
            last_status: "installed".to_string(),
            plan: Some(plan),
            install_target_plan: None,
            install_targets: Vec::new(),
            selected_install_target_id: None,
        };

        store.items.push(record);
        adopted_count += 1;
    }

    Ok(adopted_count)
}

fn adopt_existing_profile_mods(
    store_root: &Path,
    profile: &GameProfile,
    store: &mut StoreFile<InstalledModRecord>,
) -> Result<usize, String> {
    let native_scripts = adopt_existing_native_script_mods(store_root, profile, store)?;
    let ue4ss_mods = adopt_existing_ue4ss_mods(store_root, profile, store)?;
    Ok(native_scripts + ue4ss_mods)
}

fn adopt_existing_ue4ss_mods(
    store_root: &Path,
    profile: &GameProfile,
    store: &mut StoreFile<InstalledModRecord>,
) -> Result<usize, String> {
    if !profile_runtime_ids(profile)
        .iter()
        .any(|runtime| runtime.eq_ignore_ascii_case("ue4ss"))
    {
        return Ok(0);
    }

    let game_path = Path::new(&profile.game_path);
    let existing_targets = store
        .items
        .iter()
        .filter(|record| record.profile_id == profile.id && record.last_status != "removed")
        .flat_map(|record| record.files_written.iter())
        .map(|path| normalize_filesystem_identity(path))
        .collect::<HashSet<_>>();
    let existing_packages = store
        .items
        .iter()
        .filter(|record| record.profile_id == profile.id && record.last_status != "removed")
        .filter_map(|record| record.package_id.as_deref())
        .map(str::to_ascii_lowercase)
        .collect::<HashSet<_>>();
    let mut seen_directories = HashSet::new();
    let mut adopted_count = 0;

    for route in ue4ss_install_targets(profile).1 {
        let Ok(mods_root) = safe_join(game_path, &route) else {
            continue;
        };
        let Ok(entries) = fs::read_dir(&mods_root) else {
            continue;
        };

        for entry in entries.flatten() {
            let Ok(file_type) = entry.file_type() else {
                continue;
            };
            if !file_type.is_dir() || file_type.is_symlink() {
                continue;
            }

            let mod_root = entry.path();
            let mod_identity = normalize_filesystem_identity(mod_root.to_string_lossy().as_ref());
            if !seen_directories.insert(mod_identity) {
                continue;
            }

            let folder_name = entry.file_name().to_string_lossy().to_string();
            let relative_files = collect_folder_relative_paths(&mod_root)?;
            if relative_files.is_empty() || !is_adoptable_ue4ss_mod_directory(&relative_files) {
                continue;
            }

            let target_root = join_install_route(&route, &folder_name);
            let package_id = format!(
                "external-ue4ss:{}",
                normalize_archive_path(&target_root).to_ascii_lowercase()
            );
            if existing_packages.contains(&package_id) {
                continue;
            }

            let target_files = relative_files
                .iter()
                .map(|relative_path| {
                    safe_join(game_path, &join_install_route(&target_root, relative_path))
                        .map(|path| path.to_string_lossy().to_string())
                })
                .collect::<Result<Vec<_>, _>>()?;
            if target_files
                .iter()
                .any(|path| existing_targets.contains(&normalize_filesystem_identity(path)))
            {
                continue;
            }

            let install_id = Uuid::new_v4().to_string();
            let source_root =
                profile_package_dir(store_root, &profile.id, &install_id).join("source");
            copy_dir_contents(&mod_root, &source_root)?;
            let mappings = relative_files
                .iter()
                .map(|relative_path| {
                    mapping(
                        relative_path,
                        "game",
                        &join_install_route(&target_root, relative_path),
                        "Existing UE4SS mod file adopted without changing the game folder.",
                    )
                })
                .collect::<Vec<_>>();
            let written_file_hashes = target_files
                .iter()
                .filter_map(|path| {
                    sha256_file(Path::new(path))
                        .ok()
                        .map(|hash| (path.clone(), hash))
                })
                .collect::<HashMap<_, _>>();
            let plan = InstallPlan {
                adapter_id: "ue4ss".to_string(),
                adapter_name: "UE4SS Mods".to_string(),
                confidence: 1.0,
                summary: format!("Track existing UE4SS mod folder at {target_root}."),
                mappings,
                dependencies: Vec::new(),
                warnings: Vec::new(),
                requires_confirmation: false,
            };
            let display_name = humanize_mod_display_name(&folder_name);
            let record = InstalledModRecord {
                id: install_id,
                profile_id: profile.id.clone(),
                archive_path: source_root.to_string_lossy().to_string(),
                archive_name: folder_name,
                display_name: Some(display_name),
                package_id: Some(package_id),
                package_provider: Some("local".to_string()),
                package_version: None,
                provider_file_id: None,
                provider_variant: None,
                source_archive_sha256: None,
                dependency_string: None,
                icon_url: None,
                adapter_id: "ue4ss".to_string(),
                summary: format!(
                    "Existing UE4SS mod tracked from {}.",
                    normalize_archive_path(&target_root)
                ),
                installed_at: now_string(),
                files_written: target_files,
                backups_written: Vec::new(),
                written_file_hashes,
                dependencies: Vec::new(),
                config_files: Vec::new(),
                runtime_id: None,
                externally_managed: true,
                enabled: true,
                last_status: "installed".to_string(),
                plan: Some(plan),
                install_target_plan: None,
                install_targets: Vec::new(),
                selected_install_target_id: None,
            };
            store.items.push(record);
            adopted_count += 1;
        }
    }

    Ok(adopted_count)
}

fn is_adoptable_ue4ss_mod_directory(relative_files: &[String]) -> bool {
    let has_enable_marker = relative_files
        .iter()
        .any(|path| basename(path).eq_ignore_ascii_case("enabled.txt"));
    let has_unreal_package = relative_files.iter().any(|path| {
        Path::new(path)
            .extension()
            .and_then(|extension| extension.to_str())
            .is_some_and(|extension| {
                matches!(
                    extension.to_ascii_lowercase().as_str(),
                    "pak" | "ucas" | "utoc"
                )
            })
    });
    has_enable_marker || has_unreal_package
}

fn ensure_visible_runtime_records(
    _store_root: &Path,
    profile: &GameProfile,
    store: &mut StoreFile<InstalledModRecord>,
) -> Result<usize, String> {
    let mut changed = 0;
    for runtime in profile_runtime_ids(profile) {
        if !runtime_installed(profile, &runtime) {
            continue;
        }

        if let Some(record) = store.items.iter_mut().find(|record| {
            record.profile_id == profile.id
                && record.last_status != "removed"
                && runtime_record_matches(record, &runtime)
        }) {
            let mut record_changed = false;
            if !record.externally_managed
                && runtime_record_has_divergent_live_layout(profile, &runtime, record)
            {
                adopt_detected_runtime_layout(profile, &runtime, record);
                record_changed = true;
            }
            if record.runtime_id.as_deref() != Some(runtime.as_str()) {
                record.runtime_id = Some(runtime.clone());
                record_changed = true;
            }
            let display_name = format_loader(&runtime);
            if record.display_name.as_deref() != Some(display_name) {
                record.display_name = Some(display_name.to_string());
                record_changed = true;
            }
            if record_changed {
                record.summary = format!(
                    "System runtime required by {} mods.",
                    profile_game_label(profile)
                );
                changed += 1;
            }
            continue;
        }

        let files_written = detected_runtime_signature_files(profile, &runtime);
        let installed_at = now_string();
        let record = InstalledModRecord {
            id: Uuid::new_v4().to_string(),
            profile_id: profile.id.clone(),
            archive_path: profile.game_path.clone(),
            archive_name: format_loader(&runtime).to_string(),
            display_name: Some(format_loader(&runtime).to_string()),
            package_id: Some(format!("observed-runtime:{runtime}")),
            package_provider: Some("detected-runtime".to_string()),
            package_version: None,
            provider_file_id: None,
            provider_variant: None,
            source_archive_sha256: None,
            dependency_string: None,
            icon_url: None,
            adapter_id: runtime_adapter_id(&runtime).to_string(),
            summary: format!(
                "System runtime detected in the {} game folder.",
                profile_game_label(profile)
            ),
            installed_at,
            files_written: files_written.clone(),
            backups_written: Vec::new(),
            written_file_hashes: files_written
                .iter()
                .filter_map(|path| {
                    sha256_file(Path::new(path))
                        .ok()
                        .map(|hash| (path.clone(), hash))
                })
                .collect(),
            dependencies: Vec::new(),
            config_files: Vec::new(),
            runtime_id: Some(runtime),
            externally_managed: true,
            enabled: true,
            last_status: "installed".to_string(),
            plan: None,
            install_target_plan: None,
            install_targets: Vec::new(),
            selected_install_target_id: None,
        };
        store.items.push(record);
        changed += 1;
    }
    Ok(changed)
}

fn runtime_record_has_divergent_live_layout(
    profile: &GameProfile,
    runtime: &str,
    record: &InstalledModRecord,
) -> bool {
    let detected_files = detected_runtime_signature_files(profile, runtime);
    if detected_files.is_empty() {
        return false;
    }

    let recorded_paths = record
        .files_written
        .iter()
        .map(|path| normalize_filesystem_identity(path))
        .collect::<HashSet<_>>();
    detected_files
        .iter()
        .any(|path| !recorded_paths.contains(&normalize_filesystem_identity(path)))
}

fn adopt_detected_runtime_layout(
    profile: &GameProfile,
    runtime: &str,
    record: &mut InstalledModRecord,
) {
    let files_written = detected_runtime_signature_files(profile, runtime);
    record.archive_path = profile.game_path.clone();
    record.archive_name = format_loader(runtime).to_string();
    record.package_id = Some(format!("observed-runtime:{runtime}"));
    record.package_provider = Some("detected-runtime".to_string());
    record.provider_file_id = None;
    record.provider_variant = None;
    record.source_archive_sha256 = None;
    record.dependency_string = None;
    record.files_written = files_written.clone();
    record.written_file_hashes = files_written
        .iter()
        .filter_map(|path| {
            sha256_file(Path::new(path))
                .ok()
                .map(|hash| (path.clone(), hash))
        })
        .collect();
    record.backups_written.clear();
    record.plan = None;
    record.install_target_plan = None;
    record.install_targets.clear();
    record.selected_install_target_id = None;
    record.externally_managed = true;
    record.enabled = true;
    record.last_status = "installed".to_string();
    record.summary = format!(
        "System runtime detected in the {} game folder.",
        profile_game_label(profile)
    );
}

fn runtime_record_matches(record: &InstalledModRecord, runtime: &str) -> bool {
    record
        .runtime_id
        .as_deref()
        .is_some_and(|record_runtime| record_runtime.eq_ignore_ascii_case(runtime))
        || record
            .files_written
            .iter()
            .any(|path| runtime_signature_file_matches(runtime, path))
}

fn detected_runtime_signature_files(profile: &GameProfile, runtime: &str) -> Vec<String> {
    let game_path = Path::new(&profile.game_path);
    let mut files = walk_game_folder(game_path)
        .into_iter()
        .filter(|entry| {
            !entry.is_directory && runtime_signature_file_matches(runtime, &entry.relative_path)
        })
        .map(|entry| {
            game_path
                .join(entry.relative_path)
                .to_string_lossy()
                .to_string()
        })
        .collect::<Vec<_>>();
    files.sort_by_key(|path| path.to_lowercase());
    files.dedup_by(|first, second| first.eq_ignore_ascii_case(second));
    files
}

fn runtime_signature_file_matches(runtime: &str, path: &str) -> bool {
    let normalized = normalize_archive_path(path).to_lowercase();
    let name = basename(&normalized).to_lowercase();
    match runtime {
        "bepinex" => {
            normalized.ends_with("bepinex/core/bepinex.dll")
                || normalized.ends_with("bepinex/core/bepinex.unity.mono.dll")
        }
        "bepinex-il2cpp" => {
            normalized.ends_with("bepinex/core/bepinex.dll")
                || normalized.ends_with("bepinex/core/bepinex.unity.il2cpp.dll")
        }
        "ue4ss" => matches!(name.as_str(), "ue4ss.dll" | "ue4ss-settings.ini"),
        "reframework" => matches!(name.as_str(), "dinput8.dll" | "reframework_revision.txt"),
        _ => false,
    }
}

fn runtime_adapter_id(runtime: &str) -> &str {
    match runtime {
        "enshrouded-eml" | "enshrouded-shroudtopia" | "enshrouded-proxy" => "enshrouded",
        "bepinex" | "bepinex-il2cpp" => "bepinex",
        "ue4ss" => "ue4ss",
        "reframework" => "reframework",
        _ => "loose-files",
    }
}

fn discover_native_script_files(profile: &GameProfile) -> Vec<NativeScriptFile> {
    let game_path = Path::new(&profile.game_path);
    let mut files = Vec::new();
    let mut seen = HashSet::new();

    for route in native_script_target_dirs(profile) {
        let Ok(root) = safe_join(game_path, &route) else {
            continue;
        };
        if root.is_dir() {
            discover_native_script_files_in_dir(&root, &route, 0, &mut files, &mut seen);
        }
    }

    files.sort_by_key(|file| file.target_relative_path.to_lowercase());
    files
}

fn discover_native_script_files_in_dir(
    root: &Path,
    route: &str,
    depth: usize,
    files: &mut Vec<NativeScriptFile>,
    seen: &mut HashSet<String>,
) {
    if depth > MAX_CONFIG_SCAN_DEPTH {
        return;
    }

    let Ok(entries) = fs::read_dir(root) else {
        return;
    };

    for entry in entries.flatten() {
        let path = entry.path();
        let Ok(file_type) = entry.file_type() else {
            continue;
        };

        if file_type.is_dir() {
            discover_native_script_files_in_dir(&path, route, depth + 1, files, seen);
            continue;
        }

        if !file_type.is_file()
            || !path
                .extension()
                .and_then(|extension| extension.to_str())
                .map(|extension| extension.eq_ignore_ascii_case("as"))
                .unwrap_or(false)
        {
            continue;
        }

        let Ok(relative_path) = path.strip_prefix(root) else {
            continue;
        };
        let source_relative_path = to_portable_path(relative_path);
        let target_relative_path =
            normalize_archive_path(&format!("{}/{}", route, source_relative_path));
        let identity = normalize_filesystem_identity(path.to_string_lossy().as_ref());
        if seen.insert(identity) {
            files.push(NativeScriptFile {
                absolute_path: path,
                target_relative_path,
                source_relative_path,
            });
        }
    }
}

fn normalize_filesystem_identity(path: &str) -> String {
    path.replace('\\', "/").to_lowercase()
}

fn normalize_profile_game_path(path: &str) -> String {
    let trimmed = path.trim();
    #[cfg(target_os = "windows")]
    {
        trimmed.replace('/', "\\")
    }
    #[cfg(not(target_os = "windows"))]
    {
        trimmed.to_string()
    }
}

fn discover_profile_config_files(profile: &GameProfile) -> Vec<String> {
    let mut files = Vec::new();
    let mut seen = HashSet::new();

    for root in profile_config_roots(profile) {
        if root.is_dir() {
            discover_config_files_in_dir(&root, 0, &mut files, &mut seen);
        } else if root.is_file() && is_user_editable_config_file(&root) {
            push_unique_config_path(&mut files, &mut seen, &root);
        }

        if files.len() >= MAX_PROFILE_CONFIG_FILES {
            break;
        }
    }

    files.sort_by_key(|path| path.to_lowercase());
    files
}

fn profile_config_roots(profile: &GameProfile) -> Vec<PathBuf> {
    let game_path = Path::new(&profile.game_path);
    let mut roots = vec![
        game_path.join("BepInEx").join("config"),
        game_path.join("MelonLoader").join("UserData"),
        game_path.join("UserData"),
        game_path.join("config"),
        game_path.join("Config"),
        game_path.join("Configs"),
        game_path.join("Mods"),
        game_path.join("mods"),
        game_path.join("UE4SS"),
        game_path.join("REFramework"),
        game_path.join("reframework"),
        game_path.join("doorstop_config.ini"),
        game_path.join("UE4SS-settings.ini"),
        game_path.join("REFramework.ini"),
        game_path.join("dinput8.ini"),
    ];

    if let Some(definition) = profile.game_id.as_deref().and_then(game_definition_by_id) {
        roots.extend(
            definition
                .config_roots
                .iter()
                .filter_map(|root| safe_join(game_path, root).ok()),
        );
    }

    roots
}

fn discover_config_files_in_dir(
    root: &Path,
    depth: usize,
    files: &mut Vec<String>,
    seen: &mut HashSet<String>,
) {
    if depth > MAX_CONFIG_SCAN_DEPTH || files.len() >= MAX_PROFILE_CONFIG_FILES {
        return;
    }

    let Ok(entries) = fs::read_dir(root) else {
        return;
    };

    for entry in entries.flatten() {
        if files.len() >= MAX_PROFILE_CONFIG_FILES {
            break;
        }

        let path = entry.path();
        let Ok(file_type) = entry.file_type() else {
            continue;
        };

        if file_type.is_file() {
            if is_user_editable_config_file(&path) {
                push_unique_config_path(files, seen, &path);
            }
        } else if file_type.is_dir() && should_descend_config_dir(&path) {
            discover_config_files_in_dir(&path, depth + 1, files, seen);
        }
    }
}

fn should_descend_config_dir(path: &Path) -> bool {
    let name = path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or_default()
        .to_lowercase();

    !matches!(
        name.as_str(),
        ".git" | "cache" | "core" | "logs" | "plugins" | "tmp" | "temp"
    ) && !is_localization_directory_name(&name)
}

fn push_unique_config_path(files: &mut Vec<String>, seen: &mut HashSet<String>, path: &Path) {
    let key = path
        .canonicalize()
        .unwrap_or_else(|_| path.to_path_buf())
        .to_string_lossy()
        .replace('\\', "/")
        .to_lowercase();

    if seen.insert(key) {
        files.push(path.to_string_lossy().to_string());
    }
}

fn is_supported_config_file(path: &Path) -> bool {
    if path.file_name().is_some_and(|name| {
        name.eq_ignore_ascii_case("config.txt") || name.eq_ignore_ascii_case("items.txt")
    }) {
        return true;
    }
    let Some(extension) = path
        .extension()
        .and_then(|extension| extension.to_str())
        .map(|extension| extension.to_lowercase())
    else {
        return false;
    };

    matches!(
        extension.as_str(),
        "cfg" | "conf" | "config" | "ini" | "json" | "toml" | "yaml" | "yml"
    )
}

fn is_user_editable_config_file(path: &Path) -> bool {
    if path
        .components()
        .any(|part| part.as_os_str().eq_ignore_ascii_case(".mod-garrison"))
        || path.file_name().is_some_and(|name| {
            name.eq_ignore_ascii_case("mod.json") || name.eq_ignore_ascii_case("flame.json")
        })
    {
        return false;
    }
    is_supported_config_file(path) && !is_localization_resource_path(path)
}

fn is_localization_resource_path(path: &Path) -> bool {
    let components = path
        .components()
        .filter_map(|component| component.as_os_str().to_str())
        .collect::<Vec<_>>();
    if components.len() > 1 {
        let directories = &components[..components.len() - 1];
        let subtree_start = directories
            .iter()
            .rposition(|component| is_config_tree_boundary(component))
            .map(|index| index + 1)
            .unwrap_or_else(|| directories.len().saturating_sub(3));
        if directories[subtree_start..]
            .iter()
            .any(|component| is_localization_directory_name(component))
        {
            return true;
        }
    }

    let stem = path
        .file_stem()
        .and_then(|stem| stem.to_str())
        .unwrap_or_default();
    let tokens = stem
        .split(|character: char| !character.is_ascii_alphanumeric())
        .filter(|token| !token.is_empty())
        .map(|token| token.to_ascii_lowercase())
        .collect::<Vec<_>>();

    tokens.iter().any(|token| is_language_resource_token(token))
}

fn is_config_tree_boundary(name: &str) -> bool {
    let compact = name
        .chars()
        .filter(|character| character.is_ascii_alphanumeric())
        .map(|character| character.to_ascii_lowercase())
        .collect::<String>();
    matches!(
        compact.as_str(),
        "config" | "configs" | "mods" | "userdata" | "ue4ss" | "reframework" | "melonloader"
    )
}

fn is_localization_directory_name(name: &str) -> bool {
    let compact = name
        .chars()
        .filter(|character| character.is_ascii_alphanumeric())
        .map(|character| character.to_ascii_lowercase())
        .collect::<String>();
    compact.contains("translation")
        || compact.contains("localization")
        || matches!(
            compact.as_str(),
            "i18n" | "l10n" | "lang" | "langs" | "language" | "languages" | "locale" | "locales"
        )
}

fn is_language_resource_token(token: &str) -> bool {
    matches!(
        token,
        "arabic"
            | "brazilian"
            | "chinese"
            | "czech"
            | "danish"
            | "dutch"
            | "english"
            | "finnish"
            | "french"
            | "german"
            | "hungarian"
            | "indonesian"
            | "italian"
            | "japanese"
            | "korean"
            | "norwegian"
            | "polish"
            | "portuguese"
            | "romanian"
            | "russian"
            | "spanish"
            | "swedish"
            | "thai"
            | "traditionalchinese"
            | "simplifiedchinese"
            | "turkish"
            | "ukrainian"
            | "vietnamese"
            | "en"
            | "enus"
            | "engb"
            | "zh"
            | "zhcn"
            | "zhtw"
            | "ja"
            | "jp"
            | "ko"
            | "kr"
            | "de"
            | "fr"
            | "es"
            | "it"
            | "pt"
            | "ptbr"
            | "ru"
            | "pl"
    )
}

#[cfg(test)]
fn resolved_config_files_for_record(
    profile: &GameProfile,
    record: &InstalledModRecord,
    discovered_config_files: &[String],
) -> Vec<String> {
    resolved_profile_config_files(
        profile,
        std::slice::from_ref(record),
        discovered_config_files,
    )
    .remove(&record.id)
    .unwrap_or_default()
}

fn resolved_profile_config_files(
    profile: &GameProfile,
    records: &[InstalledModRecord],
    discovered_config_files: &[String],
) -> HashMap<String, Vec<String>> {
    let game_root = Path::new(&profile.game_path);
    let mut claims = HashMap::<String, (String, HashSet<String>)>::new();

    for record in records
        .iter()
        .filter(|record| record.profile_id == profile.id)
    {
        let verified_paths =
            verified_target_switch_config_paths(profile, record).unwrap_or_default();
        let verified_identities = verified_paths
            .iter()
            .map(|path| normalize_filesystem_identity(path.to_string_lossy().as_ref()))
            .collect::<HashSet<_>>();
        for path in &verified_paths {
            claim_profile_config_path(&mut claims, game_root, &record.id, path);
        }
        for stored_path in &record.config_files {
            let path = Path::new(stored_path);
            let identity = normalize_filesystem_identity(path.to_string_lossy().as_ref());
            if verified_identities.contains(&identity)
                || config_file_matches_record(profile, record, stored_path)
            {
                claim_profile_config_path(&mut claims, game_root, &record.id, path);
            }
        }
    }

    for discovered_path in discovered_config_files {
        let path = Path::new(discovered_path);
        if !path.is_file()
            || !is_user_editable_config_file(path)
            || validate_deployment_containment(game_root, path).is_err()
        {
            continue;
        }
        let identity = normalize_filesystem_identity(discovered_path);
        if claims.contains_key(&identity) {
            continue;
        }
        let matching_records = records
            .iter()
            .filter(|record| {
                record.profile_id == profile.id
                    && config_file_matches_record(profile, record, discovered_path)
            })
            .collect::<Vec<_>>();
        if let [record] = matching_records.as_slice() {
            claim_profile_config_path(&mut claims, game_root, &record.id, path);
        }
    }

    let mut resolved = records
        .iter()
        .filter(|record| record.profile_id == profile.id)
        .map(|record| (record.id.clone(), Vec::new()))
        .collect::<HashMap<_, _>>();
    for (_, (path, owners)) in claims {
        if let Some(owner_id) = owners.iter().next().filter(|_| owners.len() == 1) {
            resolved.entry(owner_id.clone()).or_default().push(path);
        }
    }
    for files in resolved.values_mut() {
        files.sort_by_key(|path| path.to_lowercase());
    }
    resolved
}

fn claim_profile_config_path(
    claims: &mut HashMap<String, (String, HashSet<String>)>,
    game_root: &Path,
    record_id: &str,
    path: &Path,
) {
    if !path.is_file()
        || !is_user_editable_config_file(path)
        || validate_deployment_containment(game_root, path).is_err()
    {
        return;
    }
    let identity = normalize_filesystem_identity(path.to_string_lossy().as_ref());
    let entry = claims
        .entry(identity)
        .or_insert_with(|| (path.to_string_lossy().to_string(), HashSet::new()));
    entry.1.insert(record_id.to_string());
}

fn config_file_matches_record(
    profile: &GameProfile,
    record: &InstalledModRecord,
    config_path: &str,
) -> bool {
    let filename = Path::new(config_path)
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or(config_path);
    let lower_filename = filename.to_lowercase();

    if runtime_config_filename_matches(profile, record, &lower_filename) {
        return true;
    }

    let config_key = config_match_key(&file_stem_from_path(filename));
    if config_key.is_empty() {
        return false;
    }

    config_match_needles(record).iter().any(|needle| {
        needle.len() >= 4
            && (config_key == *needle
                || config_key.starts_with(needle)
                || config_key.ends_with(needle))
    })
}

fn runtime_config_filename_matches(
    profile: &GameProfile,
    record: &InstalledModRecord,
    lower_filename: &str,
) -> bool {
    if !record_is_runtime_package(profile, record) {
        return false;
    }

    if record.adapter_id.contains("bepinex") {
        return matches!(lower_filename, "bepinex.cfg" | "doorstop_config.ini");
    }

    if record.adapter_id == "ue4ss" {
        return lower_filename == "ue4ss-settings.ini";
    }

    if record.adapter_id == "reframework" {
        return matches!(lower_filename, "reframework.ini" | "dinput8.ini");
    }

    false
}

fn record_is_runtime_package(profile: &GameProfile, record: &InstalledModRecord) -> bool {
    let combined = [
        record.display_name.as_deref().unwrap_or_default(),
        &record.archive_name,
        record.package_id.as_deref().unwrap_or_default(),
        record.dependency_string.as_deref().unwrap_or_default(),
    ]
    .join(" ")
    .to_lowercase();

    combined.contains("bepinexpack")
        || combined.contains("bepinex pack")
        || combined.contains("reframework")
        || combined.contains("ue4ss")
        || profile.loader == record.adapter_id
            && record.files_written.iter().any(|path| {
                let lower = basename(&normalize_archive_path(path)).to_lowercase();
                matches!(
                    lower.as_str(),
                    "winhttp.dll"
                        | "doorstop_config.ini"
                        | "dinput8.dll"
                        | "ue4ss.dll"
                        | "reframework.dll"
                )
            })
}

fn config_match_needles(record: &InstalledModRecord) -> Vec<String> {
    let mut values = Vec::new();

    if let Some(display_name) = record.display_name.as_deref() {
        values.push(display_name.to_string());
    }
    values.push(record.archive_name.clone());

    if let Some(package_id) = record.package_id.as_deref() {
        values.extend(package_id.split([':', '/', '-']).map(str::to_string));
    }

    if let Some(dependency_string) = record.dependency_string.as_deref() {
        values.extend(dependency_string.split('-').map(str::to_string));
    }

    for path in &record.files_written {
        values.push(file_stem_from_path(path));
    }

    let mut needles = Vec::new();
    let mut seen = HashSet::new();
    for value in values {
        let key = config_match_key(&humanize_mod_display_name(&value));
        if key.len() >= 4 && !is_generic_config_needle(&key) && seen.insert(key.clone()) {
            needles.push(key);
        }
    }

    needles
}

fn file_stem_from_path(path: &str) -> String {
    let normalized_path = normalize_archive_path(path);
    let file_name = basename(&normalized_path);
    Path::new(&file_name)
        .file_stem()
        .and_then(|stem| stem.to_str())
        .unwrap_or(&file_name)
        .to_string()
}

fn config_match_key(value: &str) -> String {
    value
        .chars()
        .filter(|character| character.is_ascii_alphanumeric())
        .map(|character| character.to_ascii_lowercase())
        .collect()
}

fn is_generic_config_needle(needle: &str) -> bool {
    matches!(
        needle,
        "bepinex"
            | "config"
            | "cfg"
            | "game"
            | "main"
            | "manual"
            | "mod"
            | "mods"
            | "pack"
            | "plugin"
            | "plugins"
            | "release"
            | "unity"
            | "valheim"
            | "version"
    )
}

fn read_mod_config_file(
    store_root: &Path,
    profile: &GameProfile,
    file_path: &str,
) -> Result<ModConfigFile, String> {
    let path = PathBuf::from(file_path);
    let file_name = path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or(file_path)
        .to_string();

    let warning_file = |warning: String| ModConfigFile {
        path: file_path.to_string(),
        file_name: file_name.clone(),
        entries: Vec::new(),
        raw_preview: String::new(),
        warning: Some(warning),
    };

    if !path.exists() {
        return Ok(warning_file("Config file no longer exists.".to_string()));
    }

    if !path.is_file() {
        return Ok(warning_file(
            "Config path exists, but it is not a file.".to_string(),
        ));
    }

    if is_localization_resource_path(&path) {
        return Ok(warning_file(
            "This is a translation/localization resource, not a user setting.".to_string(),
        ));
    }

    let game_path = Path::new(&profile.game_path);
    if !path_is_inside(&path, game_path) && !path_is_inside(&path, store_root) {
        return Ok(warning_file(
            "Config file is outside the selected game/profile folders and was not read."
                .to_string(),
        ));
    }

    let metadata = fs::metadata(&path).map_err(error_to_string)?;
    if metadata.len() > MAX_CONFIG_READ_BYTES {
        return Ok(warning_file(format!(
            "Config file is larger than {} KB and was not read.",
            MAX_CONFIG_READ_BYTES / 1024
        )));
    }

    let content = fs::read_to_string(&path).map_err(error_to_string)?;
    Ok(ModConfigFile {
        path: file_path.to_string(),
        file_name,
        entries: parse_mod_config_entries(&path, &content),
        raw_preview: content.chars().take(6000).collect(),
        warning: None,
    })
}

fn path_is_inside(path: &Path, root: &Path) -> bool {
    let Ok(path) = path.canonicalize() else {
        return false;
    };
    let Ok(root) = root.canonicalize() else {
        return false;
    };

    path.starts_with(root)
}

fn validate_config_file_for_edit(
    store_root: &Path,
    profile: &GameProfile,
    path: &Path,
) -> Result<(), String> {
    if !path.exists() {
        return Err("Config file no longer exists.".to_string());
    }

    if !path.is_file() {
        return Err("Config path exists, but it is not a file.".to_string());
    }

    if fs::symlink_metadata(path)
        .map_err(error_to_string)?
        .file_type()
        .is_symlink()
    {
        return Err("Symbolic-link config files are not edited for safety.".to_string());
    }

    if !is_supported_config_file(path) {
        return Err("This file type is not editable as a config file yet.".to_string());
    }
    if is_localization_resource_path(path) {
        return Err(
            "Translation/localization resources are not exposed as user settings.".to_string(),
        );
    }

    let game_path = Path::new(&profile.game_path);
    if !path_is_inside(path, game_path) && !path_is_inside(path, store_root) {
        return Err(
            "Config file is outside the selected game/profile folders and was not changed."
                .to_string(),
        );
    }

    let metadata = fs::metadata(path).map_err(error_to_string)?;
    if metadata.len() > MAX_CONFIG_READ_BYTES {
        return Err(format!(
            "Config file is larger than {} KB and was not changed.",
            MAX_CONFIG_READ_BYTES / 1024
        ));
    }

    Ok(())
}

fn parse_mod_config_entries(path: &Path, content: &str) -> Vec<ModConfigEntry> {
    match path
        .extension()
        .and_then(|extension| extension.to_str())
        .map(|extension| extension.to_lowercase())
        .as_deref()
    {
        Some("json") => parse_json_config_entries(content),
        Some("toml") => parse_toml_config_entries(content),
        Some("yaml") | Some("yml") => parse_yaml_config_entries(content),
        _ => parse_key_value_config_entries(content),
    }
}

fn parse_json_config_entries(content: &str) -> Vec<ModConfigEntry> {
    let Ok(value) = serde_json::from_str::<serde_json::Value>(content) else {
        return parse_key_value_config_entries(content);
    };
    let mut entries = Vec::new();
    flatten_json_config_value(&value, Vec::new(), &mut entries);
    entries
}

fn flatten_json_config_value(
    value: &serde_json::Value,
    path: Vec<String>,
    entries: &mut Vec<ModConfigEntry>,
) {
    match value {
        serde_json::Value::Object(map) => {
            for (key, value) in map {
                let mut next_path = path.clone();
                next_path.push(key.clone());
                flatten_json_config_value(value, next_path, entries);
            }
        }
        _ => {
            let key = path.last().cloned().unwrap_or_else(|| "value".to_string());
            let section = if path.len() > 1 {
                Some(path[..path.len() - 1].join("."))
            } else {
                None
            };
            entries.push(ModConfigEntry {
                section,
                key,
                value: json_config_value_display(value),
                value_type: Some(json_config_value_type(value).to_string()),
                default_value: None,
                description: None,
            });
        }
    }
}

fn json_config_value_display(value: &serde_json::Value) -> String {
    match value {
        serde_json::Value::String(value) => value.clone(),
        _ => value.to_string(),
    }
}

fn json_config_value_type(value: &serde_json::Value) -> &'static str {
    match value {
        serde_json::Value::Null => "null",
        serde_json::Value::Bool(_) => "bool",
        serde_json::Value::Number(_) => "number",
        serde_json::Value::String(_) => "string",
        serde_json::Value::Array(_) => "array",
        serde_json::Value::Object(_) => "object",
    }
}

fn parse_toml_config_entries(content: &str) -> Vec<ModConfigEntry> {
    let Ok(document) = content.parse::<toml_edit::DocumentMut>() else {
        return Vec::new();
    };
    let mut entries = Vec::new();
    flatten_toml_table(document.as_table(), Vec::new(), &mut entries);
    entries
}

fn flatten_toml_table(
    table: &toml_edit::Table,
    path: Vec<String>,
    entries: &mut Vec<ModConfigEntry>,
) {
    for (key, item) in table.iter() {
        let mut next_path = path.clone();
        next_path.push(key.to_string());
        match item {
            toml_edit::Item::Table(nested) => {
                flatten_toml_table(nested, next_path, entries);
            }
            toml_edit::Item::Value(value) => {
                let section = if path.is_empty() {
                    None
                } else {
                    Some(path.join("."))
                };
                entries.push(ModConfigEntry {
                    section,
                    key: key.to_string(),
                    value: toml_config_value_display(value),
                    value_type: Some(value.type_name().to_string()),
                    default_value: None,
                    description: None,
                });
            }
            toml_edit::Item::ArrayOfTables(_) | toml_edit::Item::None => {}
        }
    }
}

fn toml_config_value_display(value: &toml_edit::Value) -> String {
    value
        .as_str()
        .map(str::to_string)
        .unwrap_or_else(|| value.to_string().trim().to_string())
}

fn update_toml_config_content(
    content: &str,
    section: Option<&str>,
    key: &str,
    next_value: &str,
) -> Result<String, String> {
    let mut document = content
        .parse::<toml_edit::DocumentMut>()
        .map_err(error_to_string)?;
    let mut current = document.as_item_mut();
    for part in section
        .unwrap_or_default()
        .split('.')
        .filter(|part| !part.trim().is_empty())
    {
        current = current
            .get_mut(part)
            .ok_or_else(|| format!("Config section not found: {part}"))?;
    }
    let target = current
        .get_mut(key)
        .and_then(toml_edit::Item::as_value_mut)
        .ok_or_else(|| format!("Setting not found: {key}"))?;
    *target = typed_toml_config_value(target, next_value)?;
    Ok(document.to_string())
}

fn typed_toml_config_value(
    current: &toml_edit::Value,
    next_value: &str,
) -> Result<toml_edit::Value, String> {
    if current.is_str() {
        return Ok(toml_edit::Value::from(next_value));
    }

    let candidate = format!("value = {}", next_value.trim())
        .parse::<toml_edit::DocumentMut>()
        .map_err(|error| format!("Invalid TOML value: {error}"))?
        .get("value")
        .and_then(toml_edit::Item::as_value)
        .cloned()
        .ok_or_else(|| "Invalid TOML value.".to_string())?;

    if candidate.type_name() != current.type_name() {
        return Err(format!(
            "This setting requires a {} value.",
            current.type_name()
        ));
    }
    Ok(candidate)
}

fn parse_yaml_config_entries(content: &str) -> Vec<ModConfigEntry> {
    let Ok(value) = serde_yaml::from_str::<serde_yaml::Value>(content) else {
        return Vec::new();
    };
    let mut entries = Vec::new();
    flatten_yaml_config_value(&value, Vec::new(), &mut entries);
    entries
}

fn flatten_yaml_config_value(
    value: &serde_yaml::Value,
    path: Vec<String>,
    entries: &mut Vec<ModConfigEntry>,
) {
    if let serde_yaml::Value::Mapping(map) = value {
        for (key, value) in map {
            let Some(key) = key.as_str() else {
                continue;
            };
            let mut next_path = path.clone();
            next_path.push(key.to_string());
            flatten_yaml_config_value(value, next_path, entries);
        }
        return;
    }

    let key = path.last().cloned().unwrap_or_else(|| "value".to_string());
    let section = if path.len() > 1 {
        Some(path[..path.len() - 1].join("."))
    } else {
        None
    };
    entries.push(ModConfigEntry {
        section,
        key,
        value: yaml_config_value_display(value),
        value_type: Some(yaml_config_value_type(value).to_string()),
        default_value: None,
        description: None,
    });
}

fn yaml_config_value_display(value: &serde_yaml::Value) -> String {
    match value {
        serde_yaml::Value::String(value) => value.clone(),
        _ => serde_yaml::to_string(value)
            .unwrap_or_default()
            .trim()
            .to_string(),
    }
}

fn yaml_config_value_type(value: &serde_yaml::Value) -> &'static str {
    match value {
        serde_yaml::Value::Null => "null",
        serde_yaml::Value::Bool(_) => "bool",
        serde_yaml::Value::Number(_) => "number",
        serde_yaml::Value::String(_) => "string",
        serde_yaml::Value::Sequence(_) => "array",
        serde_yaml::Value::Mapping(_) => "object",
        serde_yaml::Value::Tagged(_) => "tagged",
    }
}

fn update_yaml_config_content(
    content: &str,
    section: Option<&str>,
    key: &str,
    next_value: &str,
) -> Result<String, String> {
    let mut root = serde_yaml::from_str::<serde_yaml::Value>(content).map_err(error_to_string)?;
    let mut path = section
        .map(|section| {
            section
                .split('.')
                .filter(|part| !part.trim().is_empty())
                .map(str::to_string)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    path.push(key.to_string());

    let target = yaml_value_at_path_mut(&mut root, &path)
        .ok_or_else(|| format!("Setting not found: {key}"))?;
    let next_typed_value = typed_yaml_config_value(target, next_value)?;
    let replacement = yaml_scalar_replacement(&next_typed_value)?;
    replace_yaml_value_in_place(content, &path, &replacement)
}

fn yaml_scalar_replacement(value: &serde_yaml::Value) -> Result<String, String> {
    if matches!(
        value,
        serde_yaml::Value::Mapping(_) | serde_yaml::Value::Tagged(_)
    ) {
        return Err("Complex YAML objects cannot be edited safely in place.".to_string());
    }

    let serialized = serde_yaml::to_string(value).map_err(error_to_string)?;
    let value = serialized
        .trim()
        .strip_prefix("---")
        .unwrap_or(serialized.trim())
        .trim();
    if value.contains('\n') {
        return Err("Multi-line YAML values cannot be edited safely in place.".to_string());
    }
    Ok(value.to_string())
}

fn replace_yaml_value_in_place(
    content: &str,
    target_path: &[String],
    replacement: &str,
) -> Result<String, String> {
    let newline = if content.contains("\r\n") {
        "\r\n"
    } else {
        "\n"
    };
    let had_trailing_newline = content.ends_with('\n') || content.ends_with('\r');
    let mut mapping_path: Vec<(usize, String)> = Vec::new();
    let mut replaced = false;
    let mut output = Vec::new();

    for line in content.lines() {
        if replaced {
            output.push(line.to_string());
            continue;
        }

        let Some((indent, key, colon_index)) = yaml_mapping_line(line) else {
            output.push(line.to_string());
            continue;
        };

        while mapping_path
            .last()
            .map(|(parent_indent, _)| *parent_indent >= indent)
            .unwrap_or(false)
        {
            mapping_path.pop();
        }

        let mut current_path = mapping_path
            .iter()
            .map(|(_, part)| part.clone())
            .collect::<Vec<_>>();
        current_path.push(key.clone());

        let remainder = &line[colon_index + 1..];
        let value_without_comment = yaml_value_without_comment(remainder).trim();
        if current_path == target_path {
            if value_without_comment.is_empty() {
                return Err("Block-style YAML values cannot be edited safely in place.".to_string());
            }
            output.push(replace_yaml_line_value(line, colon_index, replacement));
            replaced = true;
            continue;
        }

        if value_without_comment.is_empty() {
            mapping_path.push((indent, key));
        }
        output.push(line.to_string());
    }

    if !replaced {
        return Err(format!(
            "Setting not found in a formatting-preserving YAML location: {}",
            target_path.join(".")
        ));
    }

    let mut updated = output.join(newline);
    if had_trailing_newline {
        updated.push_str(newline);
    }
    Ok(updated)
}

fn yaml_mapping_line(line: &str) -> Option<(usize, String, usize)> {
    let indent = line
        .len()
        .saturating_sub(line.trim_start_matches(' ').len());
    let trimmed = line.get(indent..)?;
    if trimmed.is_empty()
        || trimmed.starts_with('#')
        || trimmed.starts_with('-')
        || trimmed.starts_with("---")
        || trimmed.starts_with("...")
    {
        return None;
    }

    let colon_offset = yaml_unquoted_character_index(trimmed, ':')?;
    let raw_key = trimmed[..colon_offset].trim();
    if raw_key.is_empty() {
        return None;
    }
    let key = raw_key
        .strip_prefix('"')
        .and_then(|value| value.strip_suffix('"'))
        .or_else(|| {
            raw_key
                .strip_prefix('\'')
                .and_then(|value| value.strip_suffix('\''))
        })
        .unwrap_or(raw_key)
        .to_string();
    Some((indent, key, indent + colon_offset))
}

fn yaml_unquoted_character_index(value: &str, needle: char) -> Option<usize> {
    let mut single_quoted = false;
    let mut double_quoted = false;
    let mut escaped = false;
    for (index, character) in value.char_indices() {
        if escaped {
            escaped = false;
            continue;
        }
        if character == '\\' && double_quoted {
            escaped = true;
            continue;
        }
        match character {
            '\'' if !double_quoted => single_quoted = !single_quoted,
            '"' if !single_quoted => double_quoted = !double_quoted,
            _ if character == needle && !single_quoted && !double_quoted => return Some(index),
            _ => {}
        }
    }
    None
}

fn yaml_value_without_comment(value: &str) -> &str {
    let mut single_quoted = false;
    let mut double_quoted = false;
    let mut escaped = false;
    for (index, character) in value.char_indices() {
        if escaped {
            escaped = false;
            continue;
        }
        if character == '\\' && double_quoted {
            escaped = true;
            continue;
        }
        match character {
            '\'' if !double_quoted => single_quoted = !single_quoted,
            '"' if !single_quoted => double_quoted = !double_quoted,
            '#' if !single_quoted
                && !double_quoted
                && value[..index]
                    .chars()
                    .last()
                    .map(char::is_whitespace)
                    .unwrap_or(true) =>
            {
                return &value[..index];
            }
            _ => {}
        }
    }
    value
}

fn replace_yaml_line_value(line: &str, colon_index: usize, replacement: &str) -> String {
    let remainder = &line[colon_index + 1..];
    let spacing_len = remainder.len().saturating_sub(remainder.trim_start().len());
    let spacing = &remainder[..spacing_len];
    let value_and_comment = &remainder[spacing_len..];
    let value_without_comment = yaml_value_without_comment(value_and_comment);
    let suffix = &value_and_comment[value_without_comment.len()..];
    let trailing_spacing_len = value_without_comment
        .len()
        .saturating_sub(value_without_comment.trim_end().len());
    let trailing_spacing = &value_without_comment[value_without_comment
        .len()
        .saturating_sub(trailing_spacing_len)..];

    format!(
        "{}{}{}{}{}",
        &line[..colon_index + 1],
        spacing,
        replacement,
        trailing_spacing,
        suffix
    )
}

fn yaml_value_at_path_mut<'a>(
    value: &'a mut serde_yaml::Value,
    path: &[String],
) -> Option<&'a mut serde_yaml::Value> {
    let mut current = value;
    for part in path {
        let serde_yaml::Value::Mapping(map) = current else {
            return None;
        };
        current = map.get_mut(serde_yaml::Value::String(part.clone()))?;
    }
    Some(current)
}

fn typed_yaml_config_value(
    current: &serde_yaml::Value,
    next_value: &str,
) -> Result<serde_yaml::Value, String> {
    if matches!(current, serde_yaml::Value::String(_)) {
        return Ok(serde_yaml::Value::String(next_value.to_string()));
    }
    let candidate =
        serde_yaml::from_str::<serde_yaml::Value>(next_value).map_err(error_to_string)?;
    if yaml_config_value_type(&candidate) != yaml_config_value_type(current) {
        return Err(format!(
            "This setting requires a {} value.",
            yaml_config_value_type(current)
        ));
    }
    Ok(candidate)
}

fn validate_structured_config_content(
    extension: Option<&str>,
    content: &str,
) -> Result<(), String> {
    match extension {
        Some("json") => serde_json::from_str::<serde_json::Value>(content)
            .map(|_| ())
            .map_err(error_to_string),
        Some("toml") => content
            .parse::<toml_edit::DocumentMut>()
            .map(|_| ())
            .map_err(error_to_string),
        Some("yaml") | Some("yml") => serde_yaml::from_str::<serde_yaml::Value>(content)
            .map(|_| ())
            .map_err(error_to_string),
        _ => Ok(()),
    }
}

fn update_json_config_content(
    content: &str,
    section: Option<&str>,
    key: &str,
    next_value: &str,
) -> Result<String, String> {
    let mut root = serde_json::from_str::<serde_json::Value>(content).map_err(error_to_string)?;
    let mut path = section
        .map(|section| {
            section
                .split('.')
                .filter(|part| !part.trim().is_empty())
                .map(str::to_string)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    path.push(key.to_string());

    let Some(target) = json_value_at_path_mut(&mut root, &path) else {
        return Err(format!("Setting not found: {}", key));
    };
    *target = json_config_update_value(target, next_value)?;

    serde_json::to_string_pretty(&root).map_err(error_to_string)
}

fn json_value_at_path_mut<'a>(
    value: &'a mut serde_json::Value,
    path: &[String],
) -> Option<&'a mut serde_json::Value> {
    let mut current = value;
    for part in path {
        let serde_json::Value::Object(map) = current else {
            return None;
        };
        current = map.get_mut(part)?;
    }

    Some(current)
}

fn json_config_update_value(
    current_value: &serde_json::Value,
    next_value: &str,
) -> Result<serde_json::Value, String> {
    match current_value {
        serde_json::Value::Bool(_) => match next_value.trim().to_lowercase().as_str() {
            "true" => Ok(serde_json::Value::Bool(true)),
            "false" => Ok(serde_json::Value::Bool(false)),
            _ => Err("Boolean settings must be true or false.".to_string()),
        },
        serde_json::Value::Number(_) => serde_json::from_str::<serde_json::Value>(next_value)
            .map_err(error_to_string)
            .and_then(|value| {
                if value.is_number() {
                    Ok(value)
                } else {
                    Err("Number settings must be saved as a number.".to_string())
                }
            }),
        serde_json::Value::String(_) => Ok(serde_json::Value::String(next_value.to_string())),
        serde_json::Value::Null => Ok(serde_json::Value::String(next_value.to_string())),
        serde_json::Value::Array(_) | serde_json::Value::Object(_) => {
            serde_json::from_str::<serde_json::Value>(next_value).map_err(error_to_string)
        }
    }
}

fn update_max_stack_item_override(
    content: &str,
    section: Option<&str>,
    key: &str,
    value: &str,
) -> Result<String, String> {
    if section.is_some()
        || key.is_empty()
        || key.len() > 128
        || !key
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || b"_.-".contains(&byte))
    {
        return Err(
            "Enter an item ID using letters, numbers, underscores, dots or hyphens.".to_string(),
        );
    }
    let size = value
        .trim()
        .parse::<u32>()
        .ok()
        .filter(|size| *size > 0 && *size <= i32::MAX as u32)
        .ok_or_else(|| "Stack size must be a whole number between 1 and 2147483647.".to_string())?;
    if parse_key_value_config_entries(content)
        .iter()
        .any(|entry| entry.key.eq_ignore_ascii_case(key))
    {
        return update_key_value_config_content(content, None, key, &size.to_string());
    }
    let newline = if content.contains("\r\n") {
        "\r\n"
    } else {
        "\n"
    };
    let mut output = content.to_string();
    if !output.is_empty() && !output.ends_with('\n') {
        output.push_str(newline);
    }
    output.push_str(&format!("{key}={size}{newline}"));
    Ok(output)
}

fn update_key_value_config_content(
    content: &str,
    target_section: Option<&str>,
    target_key: &str,
    next_value: &str,
) -> Result<String, String> {
    let newline = if content.contains("\r\n") {
        "\r\n"
    } else {
        "\n"
    };
    let had_trailing_newline = content.ends_with('\n') || content.ends_with('\r');
    let normalized_target_section = target_section.map(normalized_config_label);
    let normalized_target_key = normalized_config_label(target_key);
    let mut current_section: Option<String> = None;
    let mut updated = false;
    let mut lines = Vec::new();

    for line in content.lines() {
        let trimmed = line.trim();
        if let Some(section) = config_section_name(trimmed) {
            current_section = Some(section);
            lines.push(line.to_string());
            continue;
        }

        if config_comment(trimmed).is_some() {
            lines.push(line.to_string());
            continue;
        }

        if !updated {
            if let Some(delimiter_index) = config_assignment_delimiter_index(line) {
                let key_part = line[..delimiter_index].trim().trim_matches('"');
                if normalized_config_label(key_part) == normalized_target_key
                    && config_section_matches(
                        current_section.as_deref(),
                        normalized_target_section.as_deref(),
                    )
                {
                    lines.push(replace_assignment_value(line, delimiter_index, next_value));
                    updated = true;
                    continue;
                }
            }
        }

        lines.push(line.to_string());
    }

    if !updated {
        return Err(format!("Setting not found: {}", target_key));
    }

    let mut output = lines.join(newline);
    if had_trailing_newline {
        output.push_str(newline);
    }

    Ok(output)
}

fn config_section_name(line: &str) -> Option<String> {
    if line.starts_with('[') && line.ends_with(']') {
        Some(
            line.trim_start_matches('[')
                .trim_end_matches(']')
                .trim()
                .to_string(),
        )
    } else {
        None
    }
}

fn config_assignment_delimiter_index(line: &str) -> Option<usize> {
    line.find('=').or_else(|| line.find(':'))
}

fn config_section_matches(current_section: Option<&str>, target_section: Option<&str>) -> bool {
    match target_section {
        Some(target_section) => current_section
            .map(normalized_config_label)
            .map(|current_section| current_section == target_section)
            .unwrap_or(false),
        None => current_section.is_none(),
    }
}

fn replace_assignment_value(line: &str, delimiter_index: usize, next_value: &str) -> String {
    let value_start = delimiter_index + 1;
    let whitespace_len = line[value_start..]
        .char_indices()
        .take_while(|(_, character)| character.is_whitespace())
        .map(|(index, character)| index + character.len_utf8())
        .last()
        .unwrap_or(0);
    let spacing = &line[value_start..value_start + whitespace_len];

    format!("{}{}{}", &line[..value_start], spacing, next_value.trim())
}

fn normalized_config_label(value: &str) -> String {
    value.trim().to_lowercase()
}

fn parse_key_value_config_entries(content: &str) -> Vec<ModConfigEntry> {
    let mut entries = Vec::new();
    let mut section = None;
    let mut pending_comments = Vec::new();

    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }

        if trimmed.starts_with('[') && trimmed.ends_with(']') {
            section = Some(
                trimmed
                    .trim_start_matches('[')
                    .trim_end_matches(']')
                    .trim()
                    .to_string(),
            );
            pending_comments.clear();
            continue;
        }

        if let Some(comment) = config_comment(trimmed) {
            if !comment.is_empty() {
                pending_comments.push(comment.to_string());
            }
            continue;
        }

        if let Some((key, value)) = split_config_assignment(trimmed) {
            let (value_type, default_value, description) =
                config_comment_metadata(&pending_comments);
            entries.push(ModConfigEntry {
                section: section.clone(),
                key: key.trim().trim_matches('"').to_string(),
                value: clean_config_value(value),
                value_type,
                default_value,
                description,
            });
            pending_comments.clear();
            continue;
        }

        pending_comments.clear();
    }

    entries
}

fn config_comment(line: &str) -> Option<&str> {
    line.strip_prefix("##")
        .or_else(|| line.strip_prefix('#'))
        .or_else(|| line.strip_prefix(';'))
        .map(str::trim)
}

fn split_config_assignment(line: &str) -> Option<(&str, &str)> {
    line.split_once('=').or_else(|| line.split_once(':'))
}

fn clean_config_value(value: &str) -> String {
    value
        .trim()
        .trim_matches('"')
        .trim_matches('\'')
        .to_string()
}

fn config_comment_metadata(
    comments: &[String],
) -> (Option<String>, Option<String>, Option<String>) {
    let mut value_type = None;
    let mut default_value = None;
    let mut description = Vec::new();

    for comment in comments {
        let trimmed = comment.trim();
        if let Some(value) = strip_prefix_ignore_ascii_case(trimmed, "Setting type:") {
            value_type = Some(value.trim().to_string());
        } else if let Some(value) = strip_prefix_ignore_ascii_case(trimmed, "Default value:") {
            default_value = Some(value.trim().to_string());
        } else if trimmed.starts_with("Settings file was created")
            || trimmed.starts_with("Plugin GUID:")
        {
            continue;
        } else if !trimmed.is_empty() {
            description.push(trimmed.to_string());
        }
    }

    let description = if description.is_empty() {
        None
    } else {
        Some(description.join(" "))
    };

    (value_type, default_value, description)
}

fn strip_prefix_ignore_ascii_case<'a>(value: &'a str, prefix: &str) -> Option<&'a str> {
    value
        .get(..prefix.len())
        .filter(|candidate| candidate.eq_ignore_ascii_case(prefix))
        .and_then(|_| value.get(prefix.len()..))
}

fn config_files_from_paths(paths: &[String]) -> Vec<String> {
    paths
        .iter()
        .filter(|path| {
            let lower_path = path.to_lowercase().replace('\\', "/");
            lower_path.contains("/config/")
                || lower_path.contains("/reframework/autorun/")
                || lower_path.ends_with(".cfg")
                || lower_path.ends_with(".ini")
                || lower_path.ends_with(".conf")
                || lower_path.ends_with(".config")
                || lower_path.ends_with(".json")
                || lower_path.ends_with(".toml")
                || lower_path.ends_with(".yaml")
                || lower_path.ends_with(".yml")
                || lower_path.ends_with("/config.txt")
                || lower_path.ends_with("/items.txt")
        })
        .filter(|path| is_user_editable_config_file(Path::new(path)))
        .cloned()
        .collect()
}

fn merged_config_files(existing: &[String], deployed_paths: &[String]) -> Vec<String> {
    let mut merged = Vec::new();
    let mut seen = HashSet::new();
    for path in existing
        .iter()
        .cloned()
        .chain(config_files_from_paths(deployed_paths))
    {
        if seen.insert(normalize_filesystem_identity(&path)) {
            merged.push(path);
        }
    }
    merged
}

fn install_display_name(
    store_root: &Path,
    archive_path: &str,
    plan: &InstallPlan,
    metadata: &InstallMetadata,
) -> String {
    if let Some(display_name) = metadata.display_name.as_deref() {
        return humanize_mod_display_name(display_name);
    }

    if let Some(manifest_name) = import_manifest_name(store_root, Path::new(archive_path)) {
        return humanize_mod_display_name(&manifest_name);
    }

    if let Some(primary_source) = primary_mapping_source(plan) {
        return humanize_mod_display_name(&primary_source);
    }

    if let Some(archive_name) = metadata.archive_name.as_deref() {
        return humanize_mod_display_name(archive_name);
    }

    humanize_mod_display_name(
        Path::new(archive_path)
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or(archive_path),
    )
}

fn import_manifest_name(store_root: &Path, source_path: &Path) -> Option<String> {
    let scanned = scan_import_source(store_root, source_path).ok()?;
    scanned.manifest.and_then(|manifest| {
        let trimmed = manifest.name.trim();
        if trimmed.is_empty() {
            None
        } else {
            Some(trimmed.to_string())
        }
    })
}

fn primary_mapping_source(plan: &InstallPlan) -> Option<String> {
    plan.mappings
        .iter()
        .find(|mapping| {
            let lower = mapping.source_path.to_lowercase();
            lower.ends_with(".pak")
                || lower.ends_with(".dll")
                || lower.ends_with(".lua")
                || lower.ends_with(".ucas")
                || lower.ends_with(".utoc")
        })
        .or_else(|| plan.mappings.first())
        .map(|mapping| basename(&mapping.source_path))
}

fn humanize_mod_display_name(raw_name: &str) -> String {
    let normalized_path = normalize_archive_path(raw_name);
    let file_name = basename(&normalized_path);
    let lower_file_name = file_name.to_lowercase();
    let without_extension = [".zip", ".7z", ".rar", ".pak", ".dll", ".lua", ".as"]
        .iter()
        .find_map(|extension| {
            lower_file_name
                .ends_with(extension)
                .then(|| &file_name[..file_name.len() - extension.len()])
        })
        .unwrap_or(&file_name);
    let without_unreal_suffix = without_extension
        .strip_suffix("_P")
        .or_else(|| without_extension.strip_suffix("-P"))
        .unwrap_or(without_extension);
    let spaced = without_unreal_suffix
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() {
                character
            } else {
                ' '
            }
        })
        .collect::<String>();
    let mut words = spaced
        .split_whitespace()
        .flat_map(split_readable_mod_words)
        .collect::<Vec<_>>();

    let mut removed_hosting_tail = false;
    while let Some(last_word) = words.last() {
        if is_strong_mod_hosting_noise_token(last_word) {
            words.pop();
            removed_hosting_tail = true;
            continue;
        }

        if removed_hosting_tail
            && last_word
                .chars()
                .all(|character| character.is_ascii_digit())
        {
            words.pop();
            continue;
        }

        break;
    }

    if words.is_empty() {
        return "Unknown Mod".to_string();
    }

    polish_mod_display_name(&words.join(" "))
}

fn split_readable_mod_words(word: &str) -> Vec<String> {
    let characters = word.chars().collect::<Vec<_>>();
    let mut parts = Vec::new();
    let mut current = String::new();

    for (index, character) in characters.iter().enumerate() {
        if index > 0 {
            let previous = characters[index - 1];
            let next = characters.get(index + 1).copied();
            let camel_boundary = character.is_ascii_uppercase()
                && (previous.is_ascii_lowercase()
                    || previous.is_ascii_digit()
                    || (previous.is_ascii_uppercase()
                        && next
                            .map(|next_character| next_character.is_ascii_lowercase())
                            .unwrap_or(false)));
            let alpha_to_digit = character.is_ascii_digit() && previous.is_ascii_alphabetic();

            if (camel_boundary || alpha_to_digit) && !current.is_empty() {
                parts.push(current);
                current = String::new();
            }
        }

        current.push(*character);
    }

    if !current.is_empty() {
        parts.push(current);
    }

    parts
}

fn is_strong_mod_hosting_noise_token(token: &str) -> bool {
    let lower = token.to_lowercase();
    let has_digit = lower.chars().any(|character| character.is_ascii_digit());
    let has_alpha = lower
        .chars()
        .any(|character| character.is_ascii_alphabetic());
    lower.len() >= 8 && lower.chars().all(|character| character.is_ascii_hexdigit())
        || lower.len() >= 8 && has_digit
        || matches!(
            lower.as_str(),
            "manual" | "main" | "latest" | "version" | "release" | "file" | "files"
        )
        || (has_digit && has_alpha && lower.len() >= 6)
}

fn polish_mod_display_name(name: &str) -> String {
    let mut words = name
        .split_whitespace()
        .map(|word| word.to_string())
        .collect::<Vec<_>>();

    trim_known_file_extension_tail(&mut words);

    if words.len() > 1 && looks_like_mod_author_prefix(&words[0]) {
        words.remove(0);
    }

    while words.len() >= 3
        && words[words.len() - 3..]
            .iter()
            .all(|word| is_number_word(word))
    {
        words.truncate(words.len() - 3);
    }

    let mut name = words.join(" ");
    name = replace_ascii_case_insensitive(&name, "Bep In Ex", "BepInEx");
    name = replace_ascii_case_insensitive(&name, "BepInExPack", "BepInEx Pack");
    name = replace_ascii_case_insensitive(&name, "Ue 4 Ss", "UE4SS");
    name = replace_ascii_case_insensitive(&name, "Re Framework", "REFramework");

    name.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn trim_known_file_extension_tail(words: &mut Vec<String>) {
    if words.len() <= 1 {
        return;
    }

    let Some(last_word) = words.last() else {
        return;
    };

    if is_known_file_extension_word(last_word) {
        words.pop();
    }
}

fn is_known_file_extension_word(word: &str) -> bool {
    matches!(
        word.to_lowercase().as_str(),
        "as" | "lua" | "dll" | "pak" | "zip" | "rar" | "7z"
    )
}

fn looks_like_mod_author_prefix(word: &str) -> bool {
    let lower = word.to_lowercase();
    matches!(
        lower.as_str(),
        "denikson" | "thunderstore" | "nexusmods" | "nexus" | "overwolf"
    )
}

fn is_number_word(word: &str) -> bool {
    word.chars().all(|character| character.is_ascii_digit())
}

fn replace_ascii_case_insensitive(value: &str, needle: &str, replacement: &str) -> String {
    let mut result = String::new();
    let mut remaining = value;

    loop {
        let lower_remaining = remaining.to_lowercase();
        let lower_needle = needle.to_lowercase();
        let Some(index) = lower_remaining.find(&lower_needle) else {
            result.push_str(remaining);
            break;
        };

        result.push_str(&remaining[..index]);
        result.push_str(replacement);
        remaining = &remaining[index + needle.len()..];
    }

    result
}

fn default_enabled() -> bool {
    true
}

fn default_profile_setup_status() -> String {
    "ready".to_string()
}

fn default_true() -> bool {
    true
}

fn apply_profile_setup_outcome(profile: &mut GameProfile, warnings: Vec<String>) {
    let needs_action = warnings.iter().any(|warning| {
        let warning = warning.to_ascii_lowercase();
        warning.contains("could not")
            || warning.contains("failed")
            || warning.contains("missing")
            || warning.contains("unsupported")
            || warning.contains("needs ")
    });
    profile.setup_status = if needs_action {
        "needs-action"
    } else {
        "ready"
    }
    .to_string();
    profile.setup_warnings = warnings;
    profile.setup_updated_at = Some(now_string());
    profile.updated_at = now_string();
}

fn default_last_status() -> String {
    "installed".to_string()
}

fn installable_files(entries: &[ArchiveEntry]) -> Vec<ArchiveEntry> {
    entries
        .iter()
        .filter(|entry| !entry.is_directory && !is_package_metadata(&entry.logical_path))
        .cloned()
        .collect()
}

fn is_package_metadata(path: &str) -> bool {
    let normalized = normalize_archive_path(path).to_ascii_lowercase();
    if normalized == "fomod" || normalized.starts_with("fomod/") || normalized.contains("/fomod/") {
        return true;
    }
    if matches!(
        normalized.as_str(),
        "manifest.json"
            | "readme.md"
            | "readme.txt"
            | "icon.png"
            | "changelog.md"
            | "license"
            | "license.txt"
    ) {
        return true;
    }

    let parts = normalized
        .split('/')
        .filter(|part| !part.is_empty())
        .collect::<Vec<_>>();
    if parts.is_empty() || parts.len() > 2 {
        return false;
    }
    if parts.len() == 2 && !matches!(parts[0], "doc" | "docs" | "documentation" | ".github") {
        return false;
    }
    let file_name = parts[parts.len() - 1];
    if matches!(
        file_name,
        ".gitattributes" | ".gitignore" | "authors" | "copying" | "license"
    ) {
        return true;
    }
    let (stem, extension) = file_name
        .rsplit_once('.')
        .map(|(stem, extension)| (stem, Some(extension)))
        .unwrap_or((file_name, None));
    let documentation_name = [
        "author",
        "authors",
        "changelog",
        "changes",
        "contributors",
        "copying",
        "credits",
        "license",
        "notice",
        "readme",
    ]
    .iter()
    .any(|prefix| {
        stem == *prefix
            || stem.starts_with(&format!("{prefix}-"))
            || stem.starts_with(&format!("{prefix}_"))
    });
    documentation_name
        && extension.is_none_or(|extension| matches!(extension, "html" | "md" | "rst" | "txt"))
}

fn mapping(
    source_path: &str,
    target_root: &str,
    target_relative_path: &str,
    reason: &str,
) -> InstallMapping {
    InstallMapping {
        source_path: normalize_archive_path(source_path),
        target_root: target_root.to_string(),
        target_relative_path: normalize_archive_path(target_relative_path),
        reason: reason.to_string(),
        generated_content: None,
    }
}

fn generated_mapping(
    source_id: &str,
    target_root: &str,
    target_relative_path: &str,
    reason: &str,
    content: &str,
) -> InstallMapping {
    InstallMapping {
        source_path: format!(
            ".mod-garrison/generated/{}",
            sanitize_file_segment(source_id)
        ),
        target_root: target_root.to_string(),
        target_relative_path: normalize_archive_path(target_relative_path),
        reason: reason.to_string(),
        generated_content: Some(content.to_string()),
    }
}

fn archive_path_parent(path: &str) -> String {
    normalize_archive_path(path)
        .rsplit_once('/')
        .map(|(parent, _)| parent.to_string())
        .unwrap_or_default()
}

fn archive_path_is_within(path: &str, prefix: &str) -> bool {
    let path = normalize_archive_path(path);
    let prefix = normalize_archive_path(prefix).trim_matches('/').to_string();
    prefix.is_empty()
        || path.eq_ignore_ascii_case(&prefix)
        || path
            .to_ascii_lowercase()
            .starts_with(&format!("{}/", prefix.to_ascii_lowercase()))
}

fn archive_path_relative_to(path: &str, prefix: &str) -> Option<String> {
    let path = normalize_archive_path(path);
    let prefix = normalize_archive_path(prefix).trim_matches('/').to_string();
    if prefix.is_empty() {
        return (!path.is_empty()).then_some(path);
    }
    if path.eq_ignore_ascii_case(&prefix) {
        return None;
    }
    strip_prefix_ignore_ascii_case(&path, &format!("{prefix}/")).map(str::to_string)
}

fn runtime_payload_prefix(files: &[ArchiveEntry], runtime: &str) -> Option<String> {
    let mut candidates = files
        .iter()
        .filter(|file| runtime_bootstrap_file(runtime, &file.logical_path))
        .map(|file| archive_path_parent(&file.logical_path))
        .filter(|prefix| {
            files.iter().any(|file| {
                runtime_core_file(runtime, &file.logical_path)
                    && archive_path_is_within(&file.logical_path, prefix)
            })
        })
        .collect::<Vec<_>>();
    candidates.sort_by(|left, right| {
        right
            .split('/')
            .count()
            .cmp(&left.split('/').count())
            .then(right.len().cmp(&left.len()))
    });
    candidates.dedup_by(|left, right| left.eq_ignore_ascii_case(right));
    candidates.into_iter().next()
}

fn runtime_bootstrap_file(runtime: &str, path: &str) -> bool {
    let name = basename(path).to_ascii_lowercase();
    match runtime {
        "bepinex" | "bepinex-il2cpp" => matches!(
            name.as_str(),
            "winhttp.dll"
                | "winhttp_il2cpp.dll"
                | "doorstop_config.ini"
                | "doorstop_config_il2cpp.ini"
        ),
        "ue4ss" => matches!(
            name.as_str(),
            "dwmapi.dll" | "xinput1_3.dll" | "version.dll"
        ),
        "reframework" => name == "dinput8.dll",
        _ => false,
    }
}

fn runtime_core_file(runtime: &str, path: &str) -> bool {
    let normalized = normalize_archive_path(path).to_ascii_lowercase();
    let name = basename(&normalized);
    match runtime {
        "bepinex" => {
            normalized.contains("bepinex/core/")
                && matches!(
                    name.as_str(),
                    "bepinex.dll" | "bepinex.core.dll" | "bepinex.unity.mono.dll"
                )
        }
        "bepinex-il2cpp" => {
            normalized.contains("bepinex/core/")
                && matches!(
                    name.as_str(),
                    "bepinex.dll" | "bepinex.core.dll" | "bepinex.unity.il2cpp.dll"
                )
        }
        "ue4ss" => name == "ue4ss.dll",
        "reframework" => {
            normalized.contains("reframework/")
                || matches!(name.as_str(), "reframework_revision.txt")
        }
        _ => false,
    }
}

fn common_installable_payload_prefix_from_paths(paths: &[String]) -> Option<String> {
    let prefix = common_top_folder(paths)?;
    let semantic_payload_root = matches!(
        basename(&prefix).to_ascii_lowercase().as_str(),
        "script"
            | "scripts"
            | "mod"
            | "mods"
            | "plugin"
            | "plugins"
            | "patch"
            | "patches"
            | "bepinex"
            | "ue4ss"
            | "reframework"
    );
    (!semantic_payload_root).then_some(prefix)
}

fn push_unique_mapping(mappings: &mut Vec<InstallMapping>, candidate: InstallMapping) {
    if mappings.iter().any(|mapping| {
        mapping
            .source_path
            .eq_ignore_ascii_case(&candidate.source_path)
            && mapping
                .target_root
                .eq_ignore_ascii_case(&candidate.target_root)
            && mapping
                .target_relative_path
                .eq_ignore_ascii_case(&candidate.target_relative_path)
    }) {
        return;
    }
    mappings.push(candidate);
}

fn read_manifest(
    archive_path: &Path,
    entries: &[ArchiveEntry],
) -> Result<(Option<ThunderstoreManifest>, Option<PackageIdentity>), String> {
    let Some(manifest_entry) = entries.iter().find(|entry| {
        !entry.is_directory && entry.logical_path.eq_ignore_ascii_case("manifest.json")
    }) else {
        return Ok((None, None));
    };

    let archive_file = File::open(archive_path).map_err(error_to_string)?;
    let mut archive = ZipArchive::new(archive_file).map_err(error_to_string)?;
    let mut manifest_file = archive
        .by_name(&manifest_entry.path)
        .map_err(error_to_string)?;
    let mut manifest_content = String::new();
    io::Read::read_to_string(&mut manifest_file, &mut manifest_content).map_err(error_to_string)?;

    parse_embedded_package_manifest(&manifest_content)
}

fn read_folder_manifest(
    folder_path: &Path,
    entries: &[ArchiveEntry],
) -> Result<(Option<ThunderstoreManifest>, Option<PackageIdentity>), String> {
    let Some(manifest_entry) = entries.iter().find(|entry| {
        !entry.is_directory && entry.logical_path.eq_ignore_ascii_case("manifest.json")
    }) else {
        return Ok((None, None));
    };

    let manifest_path = safe_join(folder_path, &manifest_entry.path)?;
    let manifest_content = fs::read_to_string(manifest_path).map_err(error_to_string)?;
    parse_embedded_package_manifest(&manifest_content)
}

fn parse_embedded_package_manifest(
    manifest_content: &str,
) -> Result<(Option<ThunderstoreManifest>, Option<PackageIdentity>), String> {
    let value = parse_json_allow_bom::<serde_json::Value>(manifest_content)
        .map_err(|error| format!("Could not read package manifest.json: {error}"))?;
    let object = value
        .as_object()
        .ok_or_else(|| "Package manifest.json must contain a JSON object.".to_string())?;

    let has_thunderstore_version =
        object.contains_key("version_number") || object.contains_key("versionNumber");
    if object.contains_key("name") && has_thunderstore_version {
        let manifest = serde_json::from_value::<ThunderstoreManifest>(value)
            .map_err(|error| format!("Invalid Thunderstore manifest.json: {error}"))?;
        let dependencies = manifest.dependencies.clone().unwrap_or_default();
        let identity = PackageIdentity {
            provider: "thunderstore".to_string(),
            package_id: Some(format!(
                "thunderstore-manifest:{}",
                compact_provider_slug(&manifest.name)
            )),
            version: Some(manifest.version_number.clone()),
            provider_game_id: None,
            mod_types: Vec::new(),
            dependencies,
            evidence: vec!["Thunderstore manifest.json".to_string()],
            confidence: 0.82,
        };
        return Ok((Some(manifest), Some(identity)));
    }

    let is_curseforge = object.contains_key("manifestType")
        || object.contains_key("manifestVersion")
        || (object.contains_key("minecraft") && object.contains_key("files"));
    if is_curseforge {
        let name = json_string_field(object, &["name"]);
        let version = json_string_field(object, &["version"]);
        let provider_game_id = if object.contains_key("minecraft") {
            Some("minecraft".to_string())
        } else {
            json_string_field(object, &["gameId", "game"])
        };
        let dependencies = object
            .get("files")
            .and_then(|files| files.as_array())
            .into_iter()
            .flatten()
            .filter_map(|file| {
                let project_id = file.get("projectID").or_else(|| file.get("projectId"))?;
                let file_id = file.get("fileID").or_else(|| file.get("fileId"));
                Some(match file_id {
                    Some(file_id) => format!("curseforge:{project_id}#{file_id}"),
                    None => format!("curseforge:{project_id}"),
                })
            })
            .collect::<Vec<_>>();
        let package_id = name
            .as_deref()
            .map(compact_provider_slug)
            .filter(|name| !name.is_empty())
            .map(|name| format!("curseforge-manifest:{name}"));
        return Ok((
            None,
            Some(PackageIdentity {
                provider: "curseforge".to_string(),
                package_id,
                version,
                provider_game_id,
                mod_types: Vec::new(),
                dependencies,
                evidence: vec!["CurseForge manifest.json".to_string()],
                confidence: 0.78,
            }),
        ));
    }

    Ok((None, None))
}

fn json_string_field(
    object: &serde_json::Map<String, serde_json::Value>,
    keys: &[&str],
) -> Option<String> {
    keys.iter().find_map(|key| {
        object.get(*key).and_then(|value| match value {
            serde_json::Value::String(value) => non_empty_string(value.trim()),
            serde_json::Value::Number(value) => Some(value.to_string()),
            _ => None,
        })
    })
}

fn normalize_archive_path(path: &str) -> String {
    path.replace('\\', "/").trim_start_matches('/').to_string()
}

fn common_top_folder(paths: &[String]) -> Option<String> {
    let file_paths = paths
        .iter()
        .filter(|path| !path.ends_with('/'))
        .collect::<Vec<_>>();
    if file_paths.is_empty() {
        return None;
    }

    let first_parts = file_paths[0].split('/').collect::<Vec<_>>();
    if first_parts.len() < 2 {
        return None;
    }

    let candidate = first_parts[0];
    if is_semantic_archive_root(candidate) {
        return None;
    }
    if file_paths
        .iter()
        .all(|path| path.starts_with(&format!("{}/", candidate)))
    {
        Some(candidate.to_string())
    } else {
        None
    }
}

fn is_semantic_archive_root(value: &str) -> bool {
    matches!(
        compact_provider_slug(value).as_str(),
        "autorun"
            | "bepinex"
            | "binaries"
            | "client"
            | "config"
            | "content"
            | "dedicatedserver"
            | "mods"
            | "natives"
            | "plugins"
            | "r5"
            | "reframework"
            | "script"
            | "scripts"
            | "server"
            | "ue4ss"
            | "windowsserver"
    )
}

fn to_logical_path(path: &str, common_top_folder: Option<&str>) -> String {
    if let Some(common_top_folder) = common_top_folder {
        let prefix = format!("{}/", common_top_folder);
        if path.starts_with(&prefix) {
            return path[prefix.len()..].to_string();
        }
    }

    path.to_string()
}

fn basename(path: &str) -> String {
    path.rsplit('/').next().unwrap_or(path).to_string()
}

fn folder_import_name(path: &Path) -> String {
    path.file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("mod-folder")
        .to_string()
}

fn path_after_named_segment(path: &str, segment: &str) -> Option<String> {
    let target = segment.to_lowercase();
    let parts = normalize_archive_path(path)
        .split('/')
        .map(|part| part.to_string())
        .collect::<Vec<_>>();

    parts
        .iter()
        .position(|part| part.eq_ignore_ascii_case(&target))
        .and_then(|index| {
            let remaining = parts
                .iter()
                .skip(index + 1)
                .filter(|part| !part.is_empty())
                .cloned()
                .collect::<Vec<_>>();

            if remaining.is_empty() {
                None
            } else {
                Some(remaining.join("/"))
            }
        })
}

fn is_bepinex_root_runtime_file(path: &str) -> bool {
    matches!(
        basename(path).to_lowercase().as_str(),
        "doorstop_config.ini"
            | "winhttp.dll"
            | "doorstop_config_il2cpp.ini"
            | "winhttp_il2cpp.dll"
            | "start_game_bepinex.sh"
            | "run_bepinex.sh"
    )
}

fn is_probable_bepinex_plugin_dll(path: &str, profile: &GameProfile) -> bool {
    let file_name = basename(path).to_lowercase();
    if !file_name.ends_with(".dll") || is_known_native_bootstrap_file(&file_name) {
        return false;
    }

    profile.engine.starts_with("unity") || profile.engine == "unknown"
}

