    #[test]
    fn store_reads_wait_for_atomic_replacements() {
        let root = temp_game_dir("store-read-lock");
        fs::create_dir_all(&root).unwrap();
        let path = root.join("records.json");
        write_store(
            &path,
            &StoreFile {
                version: 1,
                items: vec![DependencySpec {
                    id: "runtime:test".to_string(),
                    name: "Test Runtime".to_string(),
                    version: None,
                    provider: "test".to_string(),
                    required: true,
                    status: "installed".to_string(),
                    source: None,
                    notes: None,
                }],
            },
        )
        .unwrap();

        let guard = lock_store_io().unwrap();
        let reader_path = path.clone();
        let (sender, receiver) = std::sync::mpsc::channel();
        let reader = std::thread::spawn(move || {
            sender
                .send(read_store::<DependencySpec>(&reader_path))
                .unwrap();
        });

        assert!(receiver
            .recv_timeout(std::time::Duration::from_millis(40))
            .is_err());
        drop(guard);
        let store = receiver
            .recv_timeout(std::time::Duration::from_secs(2))
            .unwrap()
            .unwrap();
        reader.join().unwrap();
        assert_eq!(store.items.len(), 1);

        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn update_checker_prefers_setup_exe_assets() {
        let release = GithubReleaseResponse {
            tag_name: "v0.5".to_string(),
            html_url: Some("https://github.com/Chucksterboy/ModGarrison/releases/tag/v0.5".to_string()),
            assets: vec![
                GithubReleaseAsset {
                    name: "Mod.Garrison_0.5.0_x64_en-US.msi".to_string(),
                    browser_download_url:
                        "https://github.com/Chucksterboy/ModGarrison/releases/download/v0.5/Mod.Garrison_0.5.0_x64_en-US.msi"
                            .to_string(),
                    size: Some(42),
                    digest: None,
                },
                GithubReleaseAsset {
                    name: "Mod.Garrison_0.5.0_x64-setup.exe".to_string(),
                    browser_download_url:
                        "https://github.com/Chucksterboy/ModGarrison/releases/download/v0.5/Mod.Garrison_0.5.0_x64-setup.exe"
                            .to_string(),
                    size: Some(84),
                    digest: Some(format!("sha256:{}", "a".repeat(64))),
                },
            ],
        };

        let asset = select_update_installer_asset(&release).unwrap();
        assert_eq!(asset.name, "Mod.Garrison_0.5.0_x64-setup.exe");
        assert_eq!(asset.size, Some(84));
        assert_eq!(github_asset_sha256(asset), Some("a".repeat(64)));
        assert_eq!(
            github_asset_declared_sha256(asset).unwrap(),
            Some("a".repeat(64))
        );
    }

