    #[test]
    fn mound_definition_infers_ue4ss_from_provider_evidence_without_hardcoding_it() {
        let definition =
            game_definition_by_steam_app_id("2569760").expect("The Mound must be registered");
        assert_eq!(definition.id, "the-mound");
        assert_eq!(
            definition.nexus_game_domain.as_deref(),
            Some("themoundomenofcthulhu")
        );
        assert!(definition.bootstrap_runtimes.is_empty());

        let mut profile = test_profile("the-mound", "The Mound", "unreal", "none");
        profile.steam_app_id = Some("2569760".to_string());
        assert_eq!(
            bundled_nexus_domain_for_profile(&profile).as_deref(),
            Some("themoundomenofcthulhu")
        );
        assert!(profile_bootstrap_dependencies(&profile).is_empty());
        assert!(profile_supports_any_inferred_runtime(&profile));
        assert!(profile_supports_inferred_runtime(&profile, "ue4ss"));

        let nodes = serde_json::from_value::<Vec<NexusModNode>>(serde_json::json!([
            {
                "modId": 12,
                "name": "MiniMap Mod",
                "modRequirements": {
                    "nexusRequirements": {
                        "nodes": [{ "modName": "UE4SS for The Mound" }]
                    }
                }
            },
            {
                "modId": 11,
                "name": "Mod Settings",
                "modRequirements": {
                    "nexusRequirements": {
                        "nodes": [{ "modName": "UE4SS for The Mound" }]
                    }
                }
            }
        ]))
        .unwrap();
        let mut supporters = HashMap::new();
        let mut providers = HashMap::new();
        let sampled = collect_nexus_runtime_votes(
            &profile,
            "themoundomenofcthulhu",
            &nodes,
            &mut supporters,
            &mut providers,
        );
        retain_supported_runtime_inference_votes(&profile, &mut supporters, &mut providers);
        let inference = choose_runtime_inference(supporters, providers, sampled).unwrap();
        assert_eq!(inference.runtime_id, "ue4ss");
        assert_eq!(inference.supporting_mods, 2);

        profile.loader = inference.runtime_id;
        let dependencies = profile_bootstrap_dependencies(&profile);
        assert_eq!(dependencies.len(), 1);
        assert_eq!(dependencies[0].id, "runtime:ue4ss");
        assert_eq!(dependencies[0].provider, "github-release");
    }

    #[test]
    fn gamebanana_and_modio_documents_vote_without_counting_runtime_packages() {
        let profile = test_profile("the-mound", "The Mound", "unreal", "none");
        let documents = vec![
            ProviderRouteDocument {
                provider: "GameBanana".to_string(),
                mod_id: "gamebanana:12/101".to_string(),
                mod_name: "Better Inventory".to_string(),
                text: "UE4SS is required before installing this mod.".to_string(),
            },
            ProviderRouteDocument {
                provider: "mod.io".to_string(),
                mod_id: "modio:12/202".to_string(),
                mod_name: "Map Markers".to_string(),
                text: "Requires UE4SS as a dependency.".to_string(),
            },
            ProviderRouteDocument {
                provider: "GameBanana".to_string(),
                mod_id: "gamebanana:12/303".to_string(),
                mod_name: "UE4SS for The Mound".to_string(),
                text: "UE4SS is required.".to_string(),
            },
        ];
        let mut supporters = HashMap::new();
        let mut providers = HashMap::new();

        let sampled =
            collect_document_runtime_votes(&profile, &documents, &mut supporters, &mut providers);
        retain_supported_runtime_inference_votes(&profile, &mut supporters, &mut providers);
        let inference = choose_runtime_inference(supporters, providers, sampled).unwrap();

        assert_eq!(sampled, 2);
        assert_eq!(inference.runtime_id, "ue4ss");
        assert_eq!(inference.supporting_mods, 2);
        assert_eq!(
            inference.providers,
            vec!["GameBanana".to_string(), "mod.io".to_string()]
        );
    }

